void LLCleanRendererVK::releaseTlas(VkCommandBuffer cmd, VkPipelineStageFlags2 stages)
{
    if (mRT) mRT->releaseToConsumers(cmd, stages);   // no-op when nothing is owed
}

void LLCleanRendererVK::releaseParticles(VkCommandBuffer cmd)
{
    if (!mPartReleasePending) return;
    mPartReleasePending = false;
    // Sim / emit / sort / indirect (compute) -> the particle draws' indirect + VS reads.
    VkMemoryBarrier2 b{VK_STRUCTURE_TYPE_MEMORY_BARRIER_2};
    b.srcStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; b.srcAccessMask = VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    b.dstStageMask = VK_PIPELINE_STAGE_2_DRAW_INDIRECT_BIT | VK_PIPELINE_STAGE_2_VERTEX_SHADER_BIT;
    b.dstAccessMask = VK_ACCESS_2_INDIRECT_COMMAND_READ_BIT | VK_ACCESS_2_SHADER_STORAGE_READ_BIT;
    VkDependencyInfo d{VK_STRUCTURE_TYPE_DEPENDENCY_INFO}; d.memoryBarrierCount = 1; d.pMemoryBarriers = &b;
    vkCmdPipelineBarrier2(cmd, &d);
}

// ===========================================================================
// ASYNC COMPUTE (roadmap phase 3a). Fork / join segments on a second queue with two
// timeline semaphores; the design, the hazard rules and the frame diagram are in
// (async compute).
// ===========================================================================
bool LLCleanRendererVK::asyncDeferLightingWanted(const char** why) const
{
    S32 v = -1;
#if defined(LL_HAS_CLEAN_PIPELINE)
    static LLCachedControl<S32> s_adl(gSavedSettings, "RenderVKAsyncDeferredLighting", -1);
    v = s_adl;
#endif
    if (v >= 0)
    {
        if (why) *why = v > 0 ? "set to 1" : "set to 0";
        return v > 0;
    }
    // Auto: measured on a dedicated compute family (RTX 5090, 3840x2088: 14.4-14.6 ms GPU on
    // vs 15.3-15.8 off -- off, AO only overlaps the shadow + reflect resolves and the combine
    // waits for it). A second queue of the graphics family shares its hardware: no default.
    if (why) *why = !mAsyncAvail ? "auto: no async queue"
                  : (mAsyncComputeOnly ? "auto: dedicated compute family" : "auto: graphics-family queue");
    return mAsyncAvail && mAsyncComputeOnly;
}

// #845 / #917: the renderer whose async state the device-lost report prints (gVkAsyncLostHook).
namespace { LLCleanRendererVK* sAsyncLostRenderer = nullptr; }

bool LLCleanRendererVK::initAsync()
{
    static_assert(kAsyncSlots == kRingSlots, "async command pools are per frame-in-flight slot");
    mAsyncAvail = false;
    if (!mCtx || !mCtx->asyncComputeAvailable())
    {
        const char* why = "";
        const bool adl = asyncDeferLightingWanted(&why);
        LL_INFOS("Vulkan") << "VKAsync: deferred lighting on the async queue: no (" << why
                           << (adl ? "; no async queue" : "") << ")" << LL_ENDL;
        return false;
    }
    VkDevice dev = mCtx->device();
    VkSemaphoreTypeCreateInfo tci{VK_STRUCTURE_TYPE_SEMAPHORE_TYPE_CREATE_INFO};
    tci.semaphoreType = VK_SEMAPHORE_TYPE_TIMELINE;
    tci.initialValue = 0;
    VkSemaphoreCreateInfo sci{VK_STRUCTURE_TYPE_SEMAPHORE_CREATE_INFO};
    sci.pNext = &tci;
    if (vkCreateSemaphore(dev, &sci, nullptr, &mTlGfx) != VK_SUCCESS ||
        vkCreateSemaphore(dev, &sci, nullptr, &mTlComp) != VK_SUCCESS)
    {
        LL_WARNS("Vulkan") << "async compute: timeline semaphore creation failed; single queue" << LL_ENDL;
        destroyAsync();
        return false;
    }
    mCtx->setObjectName(VK_OBJECT_TYPE_SEMAPHORE, (uint64_t)mTlGfx, "tlGraphics");
    mCtx->setObjectName(VK_OBJECT_TYPE_SEMAPHORE, (uint64_t)mTlComp, "tlAsyncCompute");
    mTlGfxNext = mTlCompNext = 0;
    mPipeSignal = mPipeWait = 0;   // (P values belong to the old timeline)
    mAsyncComputeOnly = mCtx->computeQueueComputeOnly();
    mAsyncTs = mCtx->computeTimestamps();
    for (uint32_t s = 0; s < kAsyncSlots; ++s)
    {
        VkCommandPoolCreateInfo pci{VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO};
        pci.flags = VK_COMMAND_POOL_CREATE_TRANSIENT_BIT;   // reset whole, once per frame
        pci.queueFamilyIndex = mCtx->computeFamily();
        if (vkCreateCommandPool(dev, &pci, nullptr, &mAsyncCompPool[s]) != VK_SUCCESS)
        {
            destroyAsync();
            return false;
        }
        VkCommandBufferAllocateInfo ai{VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO};
        ai.commandPool = mAsyncCompPool[s];
        ai.level = VK_COMMAND_BUFFER_LEVEL_PRIMARY;
        ai.commandBufferCount = kAsyncCompPerSlot;
        if (vkAllocateCommandBuffers(dev, &ai, mAsyncCompCmds[s]) != VK_SUCCESS)
        {
            destroyAsync();
            return false;
        }
        for (VkCommandBuffer c : mAsyncCompCmds[s]) vkAsyncRegisterCmd(c, mAsyncComputeOnly);
        // Graphics continuations: the context's graphics pool (RESET_COMMAND_BUFFER: each
        // vkBeginCommandBuffer resets implicitly). Index 0 = the WSI pre-command buffer.
        ai.commandPool = mCtx->commandPool();
        ai.commandBufferCount = kAsyncGfxPerSlot;
        if (vkAllocateCommandBuffers(dev, &ai, mAsyncGfxCmds[s]) != VK_SUCCESS)
        {
            for (VkCommandBuffer& c : mAsyncGfxCmds[s]) c = VK_NULL_HANDLE;
            destroyAsync();
            return false;
        }
        mAsyncSlotCompLast[s] = 0;
    }
    mAsyncQueue = mCtx->computeQueue();
    mAsyncAvail = true;
    sAsyncLostRenderer = this;                                  // #845 / #917
    gVkAsyncLostHook = &LLCleanRendererVK::asyncLostHook;
    LL_INFOS("Vulkan") << "async compute: " << mCtx->asyncComputeStatus()
                       << (mAsyncComputeOnly ? " (compute-only: barriers sanitized, resources CONCURRENT)"
                                             : " (graphics-capable: no sanitizing, EXCLUSIVE)")
                       << ", timestamps " << (mAsyncTs ? "on" : "off") << LL_ENDL;
    {
        const char* why = "";
        const bool adl = asyncDeferLightingWanted(&why);
        char fam[24] = "";
        if (mAsyncComputeOnly) std::snprintf(fam, sizeof(fam), " %u", mCtx->computeFamily());
        LL_INFOS("Vulkan") << "VKAsync: deferred lighting on the async queue: " << (adl ? "yes" : "no")
                           << " (" << why << fam << "; RenderVKAsyncDeferredLighting, live)" << LL_ENDL;
    }
    return true;
}

void LLCleanRendererVK::destroyAsync()
{
    VkDevice dev = mCtx ? mCtx->device() : VK_NULL_HANDLE;
    if (!dev) return;
    for (uint32_t s = 0; s < kAsyncSlots; ++s)
    {
        for (VkCommandBuffer& c : mAsyncCompCmds[s]) { vkAsyncUnregisterCmd(c); c = VK_NULL_HANDLE; }
        if (mAsyncCompPool[s]) vkDestroyCommandPool(dev, mAsyncCompPool[s], nullptr);   // frees its buffers
        mAsyncCompPool[s] = VK_NULL_HANDLE;
        bool any = false;
        for (VkCommandBuffer c : mAsyncGfxCmds[s]) any |= c != VK_NULL_HANDLE;
        if (any) vkFreeCommandBuffers(dev, mCtx->commandPool(), kAsyncGfxPerSlot, mAsyncGfxCmds[s]);
        for (VkCommandBuffer& c : mAsyncGfxCmds[s]) c = VK_NULL_HANDLE;
    }
    if (mTlGfx) vkDestroySemaphore(dev, mTlGfx, nullptr);
    if (mTlComp) vkDestroySemaphore(dev, mTlComp, nullptr);
    mTlGfx = mTlComp = VK_NULL_HANDLE;
    mPipeSignal = mPipeWait = 0;
    mFeCmd = VK_NULL_HANDLE;
    mAsyncAvail = false;
    mAsyncOptIn = false;
    mAsyncQueue = VK_NULL_HANDLE;
    if (sAsyncLostRenderer == this) { sAsyncLostRenderer = nullptr; gVkAsyncLostHook = nullptr; }   // #845 / #917
}

VkCommandBuffer LLCleanRendererVK::asyncNextGfxCmd()
{
    // Index 0 is the WSI pre-command buffer (asyncWsiCmd).
    if (mAsyncGfxUsed < 1) mAsyncGfxUsed = 1;
    if (mAsyncGfxUsed >= kAsyncGfxPerSlot) return VK_NULL_HANDLE;
    VkCommandBuffer c = mAsyncGfxCmds[mAsyncSlot][mAsyncGfxUsed++];
    VkCommandBufferBeginInfo bi{VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};
    bi.flags = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;
    VK_CHECK(vkBeginCommandBuffer(c, &bi));
    // A graphics continuation starts with NO bound state. The frame-constant world streams
    // are re-bound here, so a draw recorded after a fork / join / split never runs without an
    // index buffer (B6 validation VUID-vkCmdDrawIndexedIndirectCount-None-07312: an unbound
    // index buffer is undefined behaviour -- a fault / device loss on drivers that do not
    // carry the binding across command buffers). Pipelines and sets are re-bound by every
    // pass; callers that need another stream still bind their own.
    if (mIbo.buffer) vkCmdBindIndexBuffer(c, mIbo.buffer, 0, VK_INDEX_TYPE_UINT16);
    if (mVbo.buffer)
    {
        const VkDeviceSize off = 0;
        vkCmdBindVertexBuffers(c, 0, 1, &mVbo.buffer, &off);
    }
    return c;
}

void LLCleanRendererVK::asyncBeginFrame(VkCommandBuffer cmd)
{
    mFrameOom = false;   // #697: a failed End of an earlier frame that was not dropped here must not drop this one
    mAsyncOptIn = false;
    mAsyncNow = AsyncFlags{};
    if (!mAsyncAvail || !cmd) return;
    VkDevice dev = mCtx->device();
    mAsyncSlot = mFrameSlot % kAsyncSlots;
    // This slot's previous async work (and, queue order, everything before it there):
    // its command buffers are about to be reset. Its graphics work was covered by the
    // in-flight fence acquire() waited; the compute work by this host wait (normally
    // long done: every segment but the post one was joined by that frame's graphics).
    if (mAsyncSlotCompLast[mAsyncSlot])
    {
        VkSemaphoreWaitInfo wi{VK_STRUCTURE_TYPE_SEMAPHORE_WAIT_INFO};
        wi.semaphoreCount = 1;
        wi.pSemaphores = &mTlComp;
        wi.pValues = &mAsyncSlotCompLast[mAsyncSlot];
        VK_HITCH_SCOPE("vk_asyncSlotWait");
        VK_CHECK(vkWaitSemaphores(dev, &wi, UINT64_MAX));
    }
    VK_CHECK(vkResetCommandPool(dev, mAsyncCompPool[mAsyncSlot], 0));
    mAsyncCompUsed = 0;
    mAsyncGfxUsed = 1;
    mAsyncWsi = VK_NULL_HANDLE;
    mAsyncSegs.clear();
    mAsyncGfx = cmd;
    mAsyncGfxOpen = AsyncSeg{};
    mAsyncGfxOpen.cmd = cmd;
    // CROSS-FRAME: every async segment of earlier frames happens-before this frame's
    // graphics work. All of them but the last frame's post segment were joined by that
    // frame's graphics already, so this wait is free; it makes cross-frame WAR / WAW
    // (stream copies over buffers last frame's async passes read, in-place TLAS refits,
    // ...) independent of barrier chains across queues.
    mAsyncGfxOpen.waitComp = mAsyncJoinedLast;
    mAsyncPostPrev = mAsyncPostNew;   // joined after this frame's front end (asyncJoin)
    mAsyncPostNew = 0;
    mAsyncOutstanding = 0;
    mAsyncForks = 0;
    mAsyncOptIn = true;
}

VkCommandBuffer LLCleanRendererVK::asyncWsiCmd()
{
    if (!mAsyncOptIn) return VK_NULL_HANDLE;
    if (!mAsyncWsi)
    {
        mAsyncWsi = mAsyncGfxCmds[mAsyncSlot][0];
        VkCommandBufferBeginInfo bi{VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};
        bi.flags = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;
        VK_CHECK(vkBeginCommandBuffer(mAsyncWsi, &bi));
    }
    return mAsyncWsi;
}

void LLCleanRendererVK::latchAsync()
{
    AsyncFlags f;
#if defined(LL_HAS_CLEAN_PIPELINE)
    // RenderVKAsyncCompute: -1 auto (the per-GPU default was applied at device selection: an
    // auto-off device has no async queue, so mAsyncAvail is false), 0 off (live), 1 on.
    static LLCachedControl<S32> s_on(gSavedSettings, "RenderVKAsyncCompute", -1);
    static LLCachedControl<bool> s_rt(gSavedSettings, "RenderVKAsyncRTBuild", true);
    static LLCachedControl<bool> s_ao(gSavedSettings, "RenderVKAsyncMaskAO", true);
    static LLCachedControl<bool> s_gr(gSavedSettings, "RenderVKAsyncGodRays", true);
    static LLCachedControl<bool> s_vol(gSavedSettings, "RenderVKAsyncVolumetrics", true);
    static LLCachedControl<bool> s_post(gSavedSettings, "RenderVKAsyncPost", true);
    static LLCachedControl<bool> s_prt(gSavedSettings, "RenderVKAsyncProbeRT", true);
    // Needs the phase-2 recording (precise barriers, deferred releases): the async split
    // points are its overlap points.
    static LLCachedControl<bool> s_precise(gSavedSettings, "RenderVKPreciseBarriers", true);
    f.on = mAsyncOptIn && mAsyncAvail && !mOffscreen && s_on != 0 && s_precise;
    if (f.on)
    {
        f.rt = s_rt;
        f.maskAo = s_ao;
        f.godRays = s_gr;
        // Volumetric fog (#718): compute only (any async family). The #845 RDNA2 default-off
        // of the async queue reaches it through mAsyncAvail (f.on).
        f.volumetrics = s_vol;
        // The probe filter's mip chain is vkCmdBlitImage: graphics-capable queues only.
        f.post = s_post && !mAsyncComputeOnly;
        // The ray-traced probe capture is compute only (any async family).
        f.probeRt = s_prt;
        // Frame pipelining (phase 3b): the next front end waits this recording's P, which
        // must follow every async segment of it -- the post segment would be forked after
        // P (and sit ahead of the next front end on the compute queue): filters on graphics.
        static LLCachedControl<bool> s_pipe(gSavedSettings, "RenderVKFramePipelining", false);
        f.pipe = s_pipe;
        if (f.pipe) f.post = false;
    }
#endif
    mAsyncNow = f;
}

// ---- FRAME PIPELINING (phase 3b) ----
VkCommandBuffer LLCleanRendererVK::asyncOpenCompute(uint64_t waitGfx, const char* label)
{
    // The join after the segment needs one graphics continuation: reserve it now (nothing
    // between the open and the join allocates one), or the front end would end up joined
    // only by the tail -- after graphics work that reads it.
    if (!mAsyncNow.on || !waitGfx || mAsyncCompUsed >= kAsyncCompPerSlot
        || std::max(mAsyncGfxUsed, 1u) >= kAsyncGfxPerSlot)
        return VK_NULL_HANDLE;
    mPipeSignal = 0;   // (as asyncFork: no segment may follow a published P)
    VkCommandBuffer cc = mAsyncCompCmds[mAsyncSlot][mAsyncCompUsed++];
    VkCommandBufferBeginInfo bi{VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};
    bi.flags = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;
    VK_CHECK(vkBeginCommandBuffer(cc, &bi));
    // Its submission waits `waitGfx` (asyncEndCompute records it with the segment) and
    // nothing else on the graphics timeline.
    mAsyncCompWaitGfx = waitGfx;
    ++mAsyncForks;
    mFeCmd = cc;
    vkAsyncSetCmdLabel(cc, label);   // #845 / #917
    // Timers: the segment's own pool, reset here (this segment may run before this
    // frame's graphics reset of the shared sub-mark pool).
    if (mTsOn && !mTsLean && mAsyncTs && mFePool)
    {
        vkCmdResetQueryPool(cc, mFePool, 0, kFeTs);
        mFeCount = 0;
        gpuSubMark(cc, "f_begin");
    }
    return cc;
}

uint64_t LLCleanRendererVK::asyncSplitGfx(VkCommandBuffer& cmd)
{
    // (asyncFork's graphics half: no compute segment.)
    if (!mAsyncNow.on || cmd != mAsyncGfx || std::max(mAsyncGfxUsed, 1u) >= kAsyncGfxPerSlot)
        return 0;
    vkEndOrNoteOom(cmd);   // #697 (out of memory: the frame is dropped at submit)
    AsyncSeg g = mAsyncGfxOpen;
    g.cmd = cmd;
    g.signal = ++mTlGfxNext;
    mAsyncSegs.push_back(g);
    cmd = asyncNextGfxCmd();
    mAsyncGfx = cmd;
    mAsyncGfxOpen = AsyncSeg{};
    mAsyncGfxOpen.cmd = cmd;
    return g.signal;
}

void LLCleanRendererVK::pipeSignal(VkCommandBuffer& cmd)
{
    // Only recordings latched for pipelining publish a P: their post segment is forced
    // onto graphics, so every async segment of this recording is joined before P and the
    // semaphore chain covers it too.
    if (!mAsyncNow.pipe) return;
    // Belt and braces: anything still unjoined (normally nothing -- A / B / C are joined
    // before the cascades / pass 1b / the god-ray composite) is joined before P, so P
    // always follows every async segment recorded so far.
    if (mAsyncOutstanding || mAsyncPostPrev) asyncJoin(cmd);
    if (const uint64_t v = asyncSplitGfx(cmd)) mPipeSignal = v;
}

VkCommandBuffer LLCleanRendererVK::asyncFork(VkCommandBuffer& cmd, const char* label)
{
    // (+1 graphics command buffer kept for this fork's join: a join never lacks one.)
    if (!mAsyncNow.on || cmd != mAsyncGfx || mAsyncCompUsed >= kAsyncCompPerSlot
        || mAsyncGfxUsed + 2 > kAsyncGfxPerSlot)
        return VK_NULL_HANDLE;   // caller records on the graphics queue
    // Frame pipelining (3b): a fork AFTER P would race the next front end (P must follow
    // every async segment of its recording): withdraw P -- the next front end goes serial.
    mPipeSignal = 0;
    // Close the graphics work recorded so far; it signals the fork value.
    vkEndOrNoteOom(cmd);   // #697 (out of memory: the frame is dropped at submit)
    AsyncSeg g = mAsyncGfxOpen;
    g.cmd = cmd;
    g.signal = ++mTlGfxNext;
    mAsyncSegs.push_back(g);
    cmd = asyncNextGfxCmd();
    mAsyncGfx = cmd;
    mAsyncGfxOpen = AsyncSeg{};
    mAsyncGfxOpen.cmd = cmd;
    // The compute segment: waits the fork value at ALL_COMMANDS.
    VkCommandBuffer cc = mAsyncCompCmds[mAsyncSlot][mAsyncCompUsed++];
    VkCommandBufferBeginInfo bi{VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};
    bi.flags = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;
    VK_CHECK(vkBeginCommandBuffer(cc, &bi));
    mAsyncCompWaitGfx = g.signal;
    ++mAsyncForks;
    vkAsyncSetCmdLabel(cc, label);   // #845 / #917
    mAsyncSegStart = true;
    gpuSubMark(cc, "a_begin");   // (opens the segment: no delta)
    mAsyncSegStart = false;
    return cc;
}

void LLCleanRendererVK::asyncEndCompute(VkCommandBuffer cc, const char* mark)
{
    if (!cc) return;
    mAsyncSegEnd = true;
    gpuSubMark(cc, mark);        // q_*: the segment's total on the async queue
    mAsyncSegEnd = false;
    vkEndOrNoteOom(cc);   // #697
    AsyncSeg c;
    c.cmd = cc;
    c.compute = true;
    c.waitGfx = mAsyncCompWaitGfx;
    c.signal = ++mTlCompNext;
    c.name = mark;   // (#845 / #917 device-lost log)
    mAsyncSegs.push_back(c);
    mAsyncOutstanding = c.signal;
    mAsyncSlotCompLast[mAsyncSlot] = c.signal;
}

void LLCleanRendererVK::asyncJoin(VkCommandBuffer& cmd)
{
    // Everything handed to the async queue so far (this frame's open segments, last
    // frame's post segment: its value is lower, queue order) -> what follows on graphics.
    const uint64_t v = std::max(mAsyncOutstanding, mAsyncPostPrev);
    if (!v || !mAsyncOptIn || cmd != mAsyncGfx || mAsyncGfxUsed >= kAsyncGfxPerSlot) return;
    vkEndOrNoteOom(cmd);   // #697 (out of memory: the frame is dropped at submit)
    AsyncSeg g = mAsyncGfxOpen;
    g.cmd = cmd;
    mAsyncSegs.push_back(g);
    cmd = asyncNextGfxCmd();
    mAsyncGfx = cmd;
    mAsyncGfxOpen = AsyncSeg{};
    mAsyncGfxOpen.cmd = cmd;
    mAsyncGfxOpen.waitComp = v;
    mAsyncGfxOpen.waitCompStage = VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT;
    if (mAsyncOutstanding) mAsyncJoinedLast = std::max(mAsyncJoinedLast, mAsyncOutstanding);
    if (mAsyncPostPrev) mAsyncJoinedLast = std::max(mAsyncJoinedLast, mAsyncPostPrev);
    mAsyncOutstanding = 0;
    mAsyncPostPrev = 0;
}

void LLCleanRendererVK::asyncJoinUpTo(VkCommandBuffer& cmd, uint64_t v)
{
    // (asyncJoin's mechanics with a chosen wait value: everything on the compute queue up to
    // and including the segment that signalled `v` -> what follows on graphics. Values are
    // handed out in queue order, so earlier segments are covered; later ones stay outstanding.)
    if (!v || v <= mAsyncJoinedLast || !mAsyncOptIn || cmd != mAsyncGfx || mAsyncGfxUsed >= kAsyncGfxPerSlot) return;
    vkEndOrNoteOom(cmd);   // #697 (out of memory: the frame is dropped at submit)
    AsyncSeg g = mAsyncGfxOpen;
    g.cmd = cmd;
    mAsyncSegs.push_back(g);
    cmd = asyncNextGfxCmd();
    mAsyncGfx = cmd;
    mAsyncGfxOpen = AsyncSeg{};
    mAsyncGfxOpen.cmd = cmd;
    mAsyncGfxOpen.waitComp = v;
    mAsyncGfxOpen.waitCompStage = VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT;
    mAsyncJoinedLast = std::max(mAsyncJoinedLast, v);
    if (mAsyncOutstanding && mAsyncOutstanding <= v) mAsyncOutstanding = 0;
    if (mAsyncPostPrev && mAsyncPostPrev <= v) mAsyncPostPrev = 0;
}

// ---- VOLUMETRIC FOG (#718; llcleanvolfogvk.h) ----
void LLCleanRendererVK::writeVolFogBinding(VkImageView view)
{
    if (!mDsetDraw0 || !view || !mVolFogSampler) return;
    VkDescriptorImageInfo di{mVolFogSampler, view, VK_IMAGE_LAYOUT_GENERAL};
    VkWriteDescriptorSet wd{VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET};
    wd.dstSet = mDsetDraw0; wd.dstBinding = 45; wd.dstArrayElement = 0;
    wd.descriptorCount = 1; wd.descriptorType = VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER;
    wd.pImageInfo = &di;
    vkUpdateDescriptorSets(mCtx->device(), 1, &wd, 0, nullptr);
    mVolFogBoundView = view;
}

void LLCleanRendererVK::createVolFogStub()
{
    VkDevice dev = mCtx->device();
    if (!mVolFogSampler)
    {
        VkSamplerCreateInfo sci{VK_STRUCTURE_TYPE_SAMPLER_CREATE_INFO};
        sci.magFilter = sci.minFilter = VK_FILTER_LINEAR;
        sci.mipmapMode = VK_SAMPLER_MIPMAP_MODE_NEAREST;
        sci.addressModeU = sci.addressModeV = sci.addressModeW = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
        VK_CHECK(vkCreateSampler(dev, &sci, nullptr, &mVolFogSampler));
    }
    if (!mVolFogStub.image)
    {
        VkMemScope memcat(VKMEM_TARGET);   // #407
        mVolFogStub = mCtx->createImage3D(1, 1, 1, VK_FORMAT_R16G16B16A16_SFLOAT,
                                          VK_IMAGE_USAGE_SAMPLED_BIT | VK_IMAGE_USAGE_TRANSFER_DST_BIT);
        if (!mVolFogStub.image)
        {
            LL_WARNS("VKVolFog") << "volumetric fog identity stub failed to allocate" << LL_ENDL;
            return;
        }
        const VkImage img = mVolFogStub.image;
        mCtx->submitImmediate([img](VkCommandBuffer c)
        {
            VkImageMemoryBarrier2 ib{VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER_2};
            ib.dstStageMask = VK_PIPELINE_STAGE_2_CLEAR_BIT; ib.dstAccessMask = VK_ACCESS_2_TRANSFER_WRITE_BIT;
            ib.oldLayout = VK_IMAGE_LAYOUT_UNDEFINED; ib.newLayout = VK_IMAGE_LAYOUT_GENERAL;
            ib.image = img; ib.subresourceRange = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 1};
            VkDependencyInfo d{VK_STRUCTURE_TYPE_DEPENDENCY_INFO}; d.imageMemoryBarrierCount = 1; d.pImageMemoryBarriers = &ib;
            vkCmdPipelineBarrier2(c, &d);
            VkClearColorValue ident{};
            ident.float32[3] = 1.f;   // no in-scatter, transmittance 1
            const VkImageSubresourceRange rng{VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 1};
            vkCmdClearColorImage(c, img, VK_IMAGE_LAYOUT_GENERAL, &ident, 1, &rng);
            VkMemoryBarrier2 mb{VK_STRUCTURE_TYPE_MEMORY_BARRIER_2};
            mb.srcStageMask = VK_PIPELINE_STAGE_2_CLEAR_BIT; mb.srcAccessMask = VK_ACCESS_2_TRANSFER_WRITE_BIT;
            mb.dstStageMask = VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT | VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
            mb.dstAccessMask = VK_ACCESS_2_SHADER_SAMPLED_READ_BIT;
            VkDependencyInfo d2{VK_STRUCTURE_TYPE_DEPENDENCY_INFO}; d2.memoryBarrierCount = 1; d2.pMemoryBarriers = &mb;
            vkCmdPipelineBarrier2(c, &d2);
        });
    }
    writeVolFogBinding(mVolFogStub.view);
    writeWeatherAccumBinding(VK_NULL_HANDLE, VK_NULL_HANDLE);   // #901: 50 / 51 -> the stubs
}

// (#819) SKY-VIEW LUT: the table (GENERAL for good: the bake's storage writes and the consumers'
// samples), its linear / clamp sampler, the bake's set, draw set 0 binding 52. A refused
// allocation (#697) leaves the analytic sky (mSkyLut stays null: never baked, never flagged;
// binding 52 unwritten -- PARTIALLY_BOUND, never read).
void LLCleanRendererVK::initSkyLut()
{
    if (!mCtx || !mDsetDraw0 || mSkyLutSampler) return;
    VkDevice dev = mCtx->device();
    VkSamplerCreateInfo sci{VK_STRUCTURE_TYPE_SAMPLER_CREATE_INFO};
    sci.magFilter = sci.minFilter = VK_FILTER_LINEAR;
    sci.mipmapMode = VK_SAMPLER_MIPMAP_MODE_NEAREST;
    sci.addressModeU = sci.addressModeV = sci.addressModeW = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
    VK_CHECK(vkCreateSampler(dev, &sci, nullptr, &mSkyLutSampler));
    {
        VkMemScope memcat(VKMEM_TARGET);   // #407
        mSkyLut = mCtx->createImage2D(kSkyLutW, kSkyLutH, VK_FORMAT_R16G16B16A16_SFLOAT,
                                      VK_IMAGE_USAGE_SAMPLED_BIT | VK_IMAGE_USAGE_STORAGE_BIT, VK_IMAGE_ASPECT_COLOR_BIT);
    }
    VkImageView view = mSkyLut.view;
    if (mSkyLut.image)
    {
        const VkImage img = mSkyLut.image;
        mCtx->submitImmediate([img](VkCommandBuffer c)
        {
            VkImageMemoryBarrier2 ib{VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER_2};
            ib.dstStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; ib.dstAccessMask = VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
            ib.oldLayout = VK_IMAGE_LAYOUT_UNDEFINED; ib.newLayout = VK_IMAGE_LAYOUT_GENERAL;
            ib.image = img; ib.subresourceRange = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 1};
            VkDependencyInfo d{VK_STRUCTURE_TYPE_DEPENDENCY_INFO}; d.imageMemoryBarrierCount = 1; d.pImageMemoryBarriers = &ib;
            vkCmdPipelineBarrier2(c, &d);
        });
        VkDescriptorSetLayoutBinding b{};
        b.binding = 0; b.descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_IMAGE; b.descriptorCount = 1;
        b.stageFlags = VK_SHADER_STAGE_COMPUTE_BIT;
        VkDescriptorSetLayoutCreateInfo li{VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO};
        li.bindingCount = 1; li.pBindings = &b;
        VK_CHECK(vkdCreateSetLayout(dev, &li, &mDslSkyLut, "mDslSkyLut"));
        VK_CHECK(mSkyLutPool.create(dev, "sky LUT", {{mDslSkyLut, 1}}));
        VK_CHECK(mSkyLutPool.allocate(mDslSkyLut, &mDsetSkyLut));
        VkDescriptorImageInfo si{VK_NULL_HANDLE, mSkyLut.view, VK_IMAGE_LAYOUT_GENERAL};
        VkWriteDescriptorSet w{VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET};
        w.dstSet = mDsetSkyLut; w.dstBinding = 0; w.descriptorCount = 1;
        w.descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_IMAGE; w.pImageInfo = &si;
        vkUpdateDescriptorSets(dev, 1, &w, 0, nullptr);
    }
    else
    {
        // (binding 52 stays unwritten: PARTIALLY_BOUND, and never read -- ao_up.z stays 0)
        LL_WARNS("Vulkan") << "VKSkyLut: the sky-view table was refused (VRAM): the analytic sky stays" << LL_ENDL;
        return;
    }
    VkDescriptorImageInfo di{mSkyLutSampler, view, VK_IMAGE_LAYOUT_GENERAL};
    VkWriteDescriptorSet wd{VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET};
    wd.dstSet = mDsetDraw0; wd.dstBinding = 52; wd.descriptorCount = 1;
    wd.descriptorType = VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER; wd.pImageInfo = &di;
    vkUpdateDescriptorSets(dev, 1, &wd, 0, nullptr);
}

// (#819) The bake, right after this recording's frame-info upload (it reads the atmosphere) and
// before any consumer: WAR on the earlier frames' samples, RAW on the upload, then the table ->
// every fragment / compute sampler of this recording.
void LLCleanRendererVK::recordSkyLut(VkCommandBuffer cmd)
{
    if (!mSkyLutNow) return;
    VkMemoryBarrier2 mb{VK_STRUCTURE_TYPE_MEMORY_BARRIER_2};
    mb.srcStageMask = VK_PIPELINE_STAGE_2_COPY_BIT | VK_PIPELINE_STAGE_2_CLEAR_BIT; mb.srcAccessMask = VK_ACCESS_2_TRANSFER_WRITE_BIT;
    mb.dstStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; mb.dstAccessMask = VK_ACCESS_2_UNIFORM_READ_BIT;
    VkImageMemoryBarrier2 ib{VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER_2};
    ib.srcStageMask = VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT | VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
    ib.dstStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; ib.dstAccessMask = VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    ib.oldLayout = ib.newLayout = VK_IMAGE_LAYOUT_GENERAL;
    ib.image = mSkyLut.image; ib.subresourceRange = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 1};
    VkDependencyInfo d{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
    d.memoryBarrierCount = 1; d.pMemoryBarriers = &mb; d.imageMemoryBarrierCount = 1; d.pImageMemoryBarriers = &ib;
    vkCmdPipelineBarrier2(cmd, &d);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mSkyLutPipe);
    const VkDescriptorSet sets[2] = {mDsetDraw0, mDsetSkyLut};
    vkCmdBindDescriptorSets(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mSkyLutLayout, 0, 2, sets, 0, nullptr);
    vkCmdDispatch(cmd, (kSkyLutW + 7) / 8, (kSkyLutH + 7) / 8, 1);
    ib.srcStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; ib.srcAccessMask = VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    ib.dstStageMask = VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT | VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
    ib.dstAccessMask = VK_ACCESS_2_SHADER_SAMPLED_READ_BIT;
    d.memoryBarrierCount = 0;
    vkCmdPipelineBarrier2(cmd, &d);
    gpuSubMark(cmd, "c_sky_lut");
    if (!mSkyLutLogged)
    {
        mSkyLutLogged = true;
        LL_INFOS("Vulkan") << "VKSkyLut: sky-view table " << kSkyLutW << "x" << kSkyLutH
                           << " RGBA16F baked per frame (RenderVKSkyLUT): skyColor() reads it" << LL_ENDL;
    }
}

void LLCleanRendererVK::ensureVolFog(VkCommandBuffer cmd, const float* camTime, uint32_t rw, uint32_t rh)
{
    mVolFogNow = false;
    mVolFogRecorded = false;
    mVolFogAsyncValue = 0;
#if defined(LL_HAS_CLEAN_PIPELINE)
    static LLCachedControl<U32> s_vf(gSavedSettings, "RenderVKVolumetricFog", 0);
    if ((s_vf == 0 && !mVolFog) || !mDsetDraw0 || !mDslDraw1) return;
    if (!mVolFog) mVolFog = new LLCleanVolFogVK();
    LLCleanVolFogVK::Frame f;
    f.ctx = mCtx; f.dslDraw0 = mDslDraw0; f.dslDraw1 = mDslDraw1;
    f.hdrFormat = mHdrFormat; f.glowFormat = mGlowFormat; f.reactFormat = kReactFormat; f.depthFormat = mDepthFormat;
    f.rw = rw; f.rh = rh;
    f.frameSlot = mFrameSlot;
    f.viewProjRel = mViewProjRel; f.camTime = camTime; f.atmos = mAtmos;
    f.waterHeight = mWater[15];
    f.drawDistance = mLightInfoCPU.zinfo[1];
    f.shadowMode = mShadowParams[3];   // (last known; the light pass gets the final one)
    f.underwater = mWater[23] > 0.5f;
    f.offscreen = mOffscreen;
    f.snapSample = mOffscreen ? snapSample() : 0u;
    // The renderer's temporal reset (teleport / region crossing / origin shift / camera cut);
    // without the temporal state the fog's own camera-jump test covers it.
    f.cameraCut = mTemporalOn && (mTemporalReset || !mTaaPrevValid);
    // Ray-traced projector shadows in the fog (RenderVKVolumetricFogLocalShadows): the RT
    // consumer layout for its light-pass variant, wanted while projector shadows are traced.
    if (mRT && mDslDraw1)
    {
        f.rtLayout = mRT->consumerLayout();
        f.rtWanted = mProjMode == 2u;
    }
    // Volumetric particles (#721, RenderVKVolumetricParticles): the GPU particle pool, and
    // whether the main view's particle draw takes the lit VS (the one that fades injected
    // sprites; RenderVKParticleLighting 0 keeps the per-pixel FS: sprites stay whole).
    {
        static LLCachedControl<U32> s_plit(gSavedSettings, "RenderVKParticleLighting", 1);
        f.partPool = (mPartPool.buffer && mPartMax > 0) ? mPartPool.buffer : VK_NULL_HANDLE;
        f.partMax = f.partPool ? mPartMax : 0u;
        f.partSpriteFade = s_plit != 0;
    }
    mVolFogNow = mVolFog->prepare(cmd, f);
    const bool dirty = mVolFog->takeBindingDirty();
    if (!mVolFogNow && s_vf == 0 && mVolFog->idle()) { delete mVolFog; mVolFog = nullptr; }
    // Binding 45: the integrated volume while it exists, else the identity stub. A change
    // happens only right after the fog re-created / freed its images behind a device wait,
    // before anything in this recording bound draw set 0 (the target-ensure step).
    const VkImageView want = (mVolFog && mVolFog->volumeView()) ? mVolFog->volumeView() : mVolFogStub.view;
    if (want && (dirty || want != mVolFogBoundView))
    {
        vkDeviceWaitIdle(mCtx->device());   // (already idle when the fog re-created; cheap otherwise)
        writeVolFogBinding(want);
    }
#endif
}

// ---- PARTICLE FOG (#1003; llcleanpartfogvk.h) ----
void LLCleanRendererVK::ensurePartFog(VkCommandBuffer cmd, const float* camTime, uint32_t rw, uint32_t rh)
{
    mPartFogNow = false;
#if defined(LL_HAS_CLEAN_PIPELINE)
    static LLCachedControl<U32> s_pf(gSavedSettings, "RenderVKParticleFog", 0);
    if ((s_pf == 0 && !mPartFog) || !mDsetDraw0 || !mDslDraw1) return;
    if (!mPartFog) mPartFog = new LLCleanPartFogVK();
    static LLCachedControl<U32> s_plit(gSavedSettings, "RenderVKParticleLighting", 1);
    LLCleanPartFogVK::Frame f;
    f.ctx = mCtx; f.dslDraw0 = mDslDraw0; f.dslDraw1 = mDslDraw1;
    f.hdrFormat = mHdrFormat; f.glowFormat = mGlowFormat; f.reactFormat = kReactFormat; f.depthFormat = mDepthFormat;
    f.rw = rw; f.rh = rh;
    f.frameSlot = mFrameSlot;
    f.viewProjRel = mViewProjRel; f.camTime = camTime;
    f.depthView = mDepth.view; f.depthGen = mDepthGen;
    f.partPool = (mPartPool.buffer && mPartMax > 0) ? mPartPool.buffer : VK_NULL_HANDLE;
    f.partLight = mPartLight.buffer;
    f.partMax = f.partPool ? mPartMax : 0u;
    f.volFogNow = mVolFogNow;
    f.particlesOn = mPartOn && gPipeline.hasRenderType(LLPipeline::RENDER_TYPE_PARTICLES);
    f.partLighting = s_plit != 0;
    f.underwater = mWater[23] > 0.5f;
    f.offscreen = mOffscreen;
    f.cameraCut = mTemporalOn && (mTemporalReset || !mTaaPrevValid);
    f.pressured = mBudget.engaged() > 0u || mBudget.mode() != 0u;
    f.tanHalfFovY = mLightInfoCPU.grid[3];
    f.maxImageDim3D = mCtx ? mCtx->limits().maxImageDimension3D : 2048u;
    f.texIndex = [this](const LLUUID& id) -> int32_t
    {
        auto it = mPartTexIndex.find(id);
        return it != mPartTexIndex.end() ? it->second : -1;
    };
    mPartFogNow = mPartFog->prepare(cmd, f);
    if (!mPartFogNow && s_pf == 0 && mPartFog->idle()) { delete mPartFog; mPartFog = nullptr; }
#endif
}

void LLCleanRendererVK::recordPartFogCompute(VkCommandBuffer cmd)
{
    if (!mPartFogNow || !mPartFog) return;
    const VkDescriptorSet sets[2] = {mDsetDraw0, mDsetDraw1};
    mPartFog->recordCompute(cmd, sets, mPartLitNow, mShadowParams[3], (uint32_t)mLightsCPU.size(),
                            [this](VkCommandBuffer c, const char* n) { gpuSubMark(c, n); });
}

void LLCleanRendererVK::recordVolFogCompute(VkCommandBuffer& cmd, bool allowAsync)
{
    if (!mVolFogNow || mVolFogRecorded || !mVolFog) return;
    mVolFogRecorded = true;
    bool async = false;
#if defined(LL_HAS_CLEAN_PIPELINE)
    async = allowAsync && mAsyncNow.volumetrics;
#endif
    // The light pass may trace projector shadows: the deferred TLAS release (a no-op when
    // already recorded -- every call site but the single-scope fallback has it) on graphics,
    // before the async fork.
    releaseTlas(cmd, VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT | VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT);
    // ASYNC (RenderVKAsyncVolumetrics): its own segment, joined up to its value right before
    // the apply -- the probe-face traces queued behind it on the compute queue stay unjoined.
    VkCommandBuffer vc = async ? asyncFork(cmd, "q_volumetrics") : VK_NULL_HANDLE;
    VkCommandBuffer rc = vc ? vc : cmd;
    // The passes' layout {draw 0, draw 1, own}: the module binds all three (draw 1 = this
    // frame's bindless set: the light pass's projector gobos).
    const VkDescriptorSet sets[2] = {mDsetDraw0, mDsetDraw1};
    // Ray-traced projector records (mProjMode 2) imply this frame's TLAS; the TLAS release
    // to compute was recorded right before every call site.
    const VkDescriptorSet rtSet = (mRT && mRT->tlasValid()) ? mRT->consumerSet() : VK_NULL_HANDLE;
    // Volumetric particles (#721): only from a pool this frame's particle compute advanced
    // (recorded before every call site) and while particles are shown.
    bool partLive = mPartOn;
#if defined(LL_HAS_CLEAN_PIPELINE)
    partLive = partLive && gPipeline.hasRenderType(LLPipeline::RENDER_TYPE_PARTICLES);
#endif
    // (mGiNow: the light pass's giDecide ran earlier in this recording -- the fog's ambient then
    //  takes the per-cell sky visibility, RenderVKVolumetricFogAmbientOcclusion)
    mVolFog->recordCompute(rc, mShadowParams[3], (uint32_t)mLightsCPU.size(), sets, mProjMode, rtSet, partLive, mGiNow,
                           [this](VkCommandBuffer c, const char* n) { gpuSubMark(c, n); });
    if (vc)
    {
        asyncEndCompute(vc, "q_volumetrics");
        mVolFogAsyncValue = mAsyncOutstanding;
    }
}

// ---- WEATHER (#783; slweather.h, llcleanweathervk.h) ----
void LLCleanRendererVK::ensureWeather(VkCommandBuffer cmd, const VKDrawPush& dp, uint32_t rw, uint32_t rh)
{
    mWeatherNow = false;
    mWeatherMeshNow = false;
#if defined(LL_HAS_CLEAN_PIPELINE)
    // The state's frame step (transitions, wetness) -- live recordings only (a snapshot's extra
    // recordings must not advance it).
    SLWeather& wx = SLWeather::instance();
    if (!mOffscreen) wx.update();
    // #895 REGION CROSSING: LL's agent frame moved (llcleaningest.cpp shiftOrigin, both world-frame
    // modes) -- the module's agent-space maps / grids / ring move with it instead of being dropped
    // (the snow lies on across the border). No module: nothing to move.
    {
        extern float gVKWeatherShift[3];
        if (gVKWeatherShift[0] != 0.f || gVKWeatherShift[1] != 0.f || gVKWeatherShift[2] != 0.f)
        {
            if (mWeather) mWeather->shiftOrigin(gVKWeatherShift);
            gVKWeatherShift[0] = gVKWeatherShift[1] = gVKWeatherShift[2] = 0.f;
        }
    }
    // #895 NEW PLACE (a teleport, slweather.h PLACES): the ground maps start over at the
    // destination; the module (avatar snow / wetness, shelter atlas) stays.
    if (wx.placeSerial() != mWeatherPlaceSeen && !mOffscreen)
    {
        mWeatherPlaceSeen = wx.placeSerial();
        if (mWeather) mWeather->resetGround("teleport");
    }
    // #904 CLEAN SLATE (master off): the module and everything it holds -- the snow grids and
    // outer ring, tracks / footprints / drifts, the per-instance and avatar snow, the #901 shelter
    // maps and mesh snow, run-off flow and drips, particles and splashes, the occlusion maps -- go
    // NOW. Binding 49 falls back to the stand-ins below (the views differ from the bound ones).
    if (wx.clearSerial() != mWeatherResetSeen && !mOffscreen)
    {
        mWeatherResetSeen = wx.clearSerial();
        if (mWeather)
        {
            LL_INFOS("Weather") << "weather reset: the renderer's weather module is freed" << LL_ENDL;
            mWeather->destroy(mCtx->device());
            delete mWeather;
            mWeather = nullptr;
        }
    }
    if ((!wx.state().visible() && !LLCleanWeatherVK::avatarsWetHold() && !mWeather) || !mDsetDraw0) return;   // (#901: wet avatars dry on)
    if (!mWeather) mWeather = new LLCleanWeatherVK();
    LLCleanWeatherVK::Frame f;
    f.ctx = mCtx;
    f.hdrFormat = mHdrFormat; f.glowFormat = mGlowFormat; f.reactFormat = kReactFormat; f.depthFormat = mDepthFormat;
    f.reverseZ = kReverseZ;   // (pass 2b: the main view's depth)
    f.rw = rw; f.rh = rh;
    f.frameSlot = mFrameSlot;
    f.camTime = dp.cam_time;
    f.sunDir = dp.sun_dir; f.sunColor = dp.sun_color; f.ambient = dp.ambient_color;
    f.waterHeight = mWater[15];
    f.underwater = mWater[23] > 0.5f;
    f.offscreen = mOffscreen;
    f.snapSample = mOffscreen ? snapSample() : 0u;
    // A camera cut forces the weather's roof maps and clears its run-off drips (#895: the snow grids
    // and the outer ring are NOT dropped -- crossings re-base them, teleports reset them above): only for the LIVE view. Inside a snapshot sequence the
    // temporal camera can "cut" without the world moving -- each face of a 360 capture turns
    // 90 degrees (> the 60 degree cut test), a snapshot at another size restarts the motion
    // history -- and a snapshot must neither lose the grid (the snow mesh is built from the
    // published grid: an unpublished one drew no mesh in the snapshot) nor reset it for the live
    // view afterwards (endOffscreen restores the renderer's temporal state, not the weather's).
    // Teleports / region crossings / origin shifts cannot happen inside the synchronous sequence.
    f.cameraCut = !mOffscreen && mTemporalOn && (mTemporalReset || !mTaaPrevValid);
    f.dslDraw0 = mDslDraw0;               // (M2 persistent snow: its compute reads draw set 0)
    f.instanceCount = mInstanceCount;
    f.vramMode = mBudget.mode(); f.vramRung = mBudget.engaged();   // (#901: the shelter atlas's tiers)
    f.vramCapacity = mBudget.capacity();                             // (#946: the weather's VRAM tier)
    f.volFogOn = mVolFogNow;                                         // (#954: the fog carries the precipitation medium)
    // M3 snow mesh: the main view (world-space view-projection: dp's origin is zero), the world
    // draw layout and the deferred G-buffer / sun cascade pipeline templates.
    f.viewProj = dp.view_proj;
    f.drawLayout = mDrawLayout;
    f.gbufDesc = mGbufDescValid ? &mGbufDesc : nullptr;
    f.shadowDesc = mShadowDescClValid ? &mShadowDescCl : nullptr;
    // (forward frames -- a supersampled snapshot with RT shadows goes forward -- draw the mesh in
    // the forward lit pass 1: its LIT_RIG template and the RT draw layout for the ray-query twin)
    f.fwdDesc = mFwdDescClValid ? &mFwdDescCl : nullptr;
    f.drawLayoutRt = mDrawLayoutRt;
    // (the depth pre-pass templates: the mesh joins pass 1a, RenderVKWeatherSnowMeshPrepass)
    for (uint32_t v = 0; v < 4u; ++v) f.preDesc[v] = mPreDescClValid ? &mPreDescCl[v] : nullptr;
    mWeatherNow = mWeather->prepare(cmd, f);
    const bool dirty = mWeather->takeBindingDirty();
    if (!mWeatherNow && mWeather->idle()) { delete mWeather; mWeather = nullptr; }
    // Binding 49: the module's maps while they exist (each null slot: the stand-in). A change
    // happens only right after the module (re)created / freed maps behind a device wait,
    // before anything in this recording bound draw set 0 (the target-ensure step).
    static_assert(kWeatherOcclSlots == LLCleanWeatherVK::kBindingSlots, "binding 49 = the weather module's slots");
    VkImageView want[kWeatherOcclSlots] = {};
    VkImageLayout lay[kWeatherOcclSlots] = {};
    bool differ = false;
    for (uint32_t i = 0; i < kWeatherOcclSlots; ++i)
    {
        lay[i] = VK_IMAGE_LAYOUT_DEPTH_READ_ONLY_OPTIMAL;
        want[i] = mWeather ? mWeather->bindingView(i, lay[i]) : VK_NULL_HANDLE;
        const VkImageView eff = want[i] ? want[i] : mProjDummyDepth.view;
        differ = differ || eff != mWeatherBoundViews[i];
    }
    if (mProjDummyDepth.view && (dirty || differ))
    {
        // (#946: timed and counted into the weather's "weather sync" line -- a rewrite every
        // recording would show there as a run of waits)
        const auto t0 = std::chrono::steady_clock::now();
        vkDeviceWaitIdle(mCtx->device());   // (already idle when the module re-created; cheap otherwise)
        LLCleanWeatherVK::noteRendererWait(
            std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t0).count(), "binding 49 rewrite");
        writeWeatherOcclBinding(want, lay);
    }
    {
        // #901 REST-POSE ACCUMULATION: bindings 50 / 51 follow the module's grid pool (re-created /
        // freed behind a device wait in prepare(), before anything in this recording bound set 0).
        const VkBuffer ar = mWeather ? mWeather->accumRecord() : VK_NULL_HANDLE;
        const VkImageView av = mWeather ? mWeather->accumView() : VK_NULL_HANDLE;
        const VkBuffer effR = ar ? ar : mWxAccumStub.buffer;
        const VkImageView effV = av ? av : mVolFogStub.view;
        if (effR && effV && (effR != mWxAccumBoundRec || effV != mWxAccumBoundView))
        {
            const auto t0 = std::chrono::steady_clock::now();
            vkDeviceWaitIdle(mCtx->device());
            LLCleanWeatherVK::noteRendererWait(
                std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t0).count(), "binding 50/51 rewrite");
            writeWeatherAccumBinding(ar, av);
        }
    }
#endif
}

// The weather occlusion map (#783): the projector tiles' static path (recordProjShadows) for
// one orthographic view straight down -- reset the shared shadow buckets, cull the statics
// into them against the map's box (cascade 4: no sun caster planes; no sub-texel caster cull),
// draw them depth-only, two-sided, with the projector depth pipelines. Alpha-blend casters are
// alpha-tested exactly as the projector tiles draw them: fully transparent prims (phantom
// barriers, invisible platforms, security prims) must not become roofs; a glass roof below
// the shadow alpha cutoff lets the rain through (M2: a weather-specific low-cutoff test).
// Rigged / avatars, worn attachments and moving objects: not drawn (M2: static casters only).
void LLCleanRendererVK::recordWeatherOcclusion(VkCommandBuffer cmd, const VKCullPush& cullBase, const VKDrawPush& dp)
{
    if (!mWeather || !mWeather->occlusionDue()) return;
    if (!mDsetCullShadow || !mShadowCmd[0].buffer || !mShadowCounters.buffer
        || !mProjPipe || !mProjMaskPipe || !mProjDsPipe || !mProjMaskDsPipe)
        return;   // (not ready: the map stays unpublished; retried next recording)
    VK_HITCH_SCOPE("vk_weatherOccl");
    const VkImage img = mWeather->occlusionImage();
    const VkImageView view = mWeather->occlusionAttachView();
    const uint32_t res = mWeather->occlusionRes();
    if (!img || !view) return;

    // Prior readers of the shared shadow buckets / counters (the projector tiles' indirect
    // draws) -> counter reset + cull.
    {
        VkMemoryBarrier2 mb{VK_STRUCTURE_TYPE_MEMORY_BARRIER_2};
        mb.srcStageMask=VK_PIPELINE_STAGE_2_DRAW_INDIRECT_BIT|VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
        mb.srcAccessMask=VK_ACCESS_2_INDIRECT_COMMAND_READ_BIT|VK_ACCESS_2_SHADER_STORAGE_READ_BIT|VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
        mb.dstStageMask=VK_PIPELINE_STAGE_2_CLEAR_BIT|VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
        mb.dstAccessMask=VK_ACCESS_2_TRANSFER_WRITE_BIT|VK_ACCESS_2_SHADER_STORAGE_READ_BIT|VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
        VkDependencyInfo dp0{VK_STRUCTURE_TYPE_DEPENDENCY_INFO}; dp0.memoryBarrierCount=1; dp0.pMemoryBarriers=&mb;
        vkCmdPipelineBarrier2(cmd,&dp0);
    }
    vkCmdFillBuffer(cmd, mShadowCounters.buffer, 0, NUM_COUNTERS*sizeof(uint32_t), 0);
    {
        VkMemoryBarrier2 fb{VK_STRUCTURE_TYPE_MEMORY_BARRIER_2};
        fb.srcStageMask=VK_PIPELINE_STAGE_2_CLEAR_BIT; fb.srcAccessMask=VK_ACCESS_2_TRANSFER_WRITE_BIT;
        fb.dstStageMask=VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
        fb.dstAccessMask=VK_ACCESS_2_SHADER_STORAGE_READ_BIT|VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
        VkDependencyInfo fd{VK_STRUCTURE_TYPE_DEPENDENCY_INFO}; fd.memoryBarrierCount=1; fd.pMemoryBarriers=&fb;
        vkCmdPipelineBarrier2(cmd,&fd);
    }
    VKCullPush cp = cullBase;
    cp.hud_pass = 3; cp.skin_count = 0;
    cp.cascade = 4;   // projector-style view: its own frustum is the cull, no sun caster planes
    // M2: STATIC casters only (clean_cull.comp SHADOW_SPLIT_STATIC): a moving object (the
    // ingest's mover tracker, instance bit21 -- kept running while the weather is, see
    // gVKProjShadowsUsed) or a worn rigid attachment (bit9) never stamps a moving shelter onto
    // the map (it would leave a dry / bare trail, and the persistent snow cover would read its
    // arrival as a new roof). Once a mover settles it is static again and the next render
    // takes it in.
    cp.flags |= kShadowSplitStatic;
    // Sub-texel casters (clean_cull.comp casterOk, cascade 4: extent >= k x distance from the
    // apex): an apex far above the box makes k x distance ~ one map texel everywhere in it, so
    // leaf-sized objects that cannot cover a texel are not drawn.
    {
        float apex[3], k = 0.f;
        mWeather->occlusionApex(apex, k);
        cp.probe_near = apex[0]; cp.probe_far = apex[1]; cp.probe_lod_scale = apex[2];
        std::memcpy(&cp.probe_face, &k, sizeof(k));
    }
    mWeather->occlusionPlanes(cp.frustum_planes);
    dispatchCull(cmd, cp, mDsetCullShadow);
    {
        VkMemoryBarrier2 ib{VK_STRUCTURE_TYPE_MEMORY_BARRIER_2};
        ib.srcStageMask=VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; ib.srcAccessMask=VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
        ib.dstStageMask=VK_PIPELINE_STAGE_2_DRAW_INDIRECT_BIT; ib.dstAccessMask=VK_ACCESS_2_INDIRECT_COMMAND_READ_BIT;
        VkDependencyInfo idp{VK_STRUCTURE_TYPE_DEPENDENCY_INFO}; idp.memoryBarrierCount=1; idp.pMemoryBarriers=&ib;
        vkCmdPipelineBarrier2(cmd,&idp);
    }
    const VkPipelineStageFlags2 kDepthStages = VK_PIPELINE_STAGE_2_EARLY_FRAGMENT_TESTS_BIT|VK_PIPELINE_STAGE_2_LATE_FRAGMENT_TESTS_BIT;
    auto imgBarrier = [&](VkImageLayout from, VkImageLayout to, VkPipelineStageFlags2 ss, VkAccessFlags2 sa,
                          VkPipelineStageFlags2 ds, VkAccessFlags2 da) {
        VkImageMemoryBarrier2 b{VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER_2};
        b.srcStageMask=ss; b.srcAccessMask=sa; b.dstStageMask=ds; b.dstAccessMask=da;
        b.oldLayout=from; b.newLayout=to;
        b.image=img; b.subresourceRange={VK_IMAGE_ASPECT_DEPTH_BIT,0,1,0,1};
        VkDependencyInfo d{VK_STRUCTURE_TYPE_DEPENDENCY_INFO}; d.imageMemoryBarrierCount=1; d.pImageMemoryBarriers=&b;
        vkCmdPipelineBarrier2(cmd,&d);
    };
    // The target map (not the published one) was last sampled by earlier frames' lit FS /
    // deferred compute / simulation -> depth attachment (contents cleared below).
    imgBarrier(VK_IMAGE_LAYOUT_DEPTH_READ_ONLY_OPTIMAL, VK_IMAGE_LAYOUT_DEPTH_ATTACHMENT_OPTIMAL,
               VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT|VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT, 0,
               kDepthStages, VK_ACCESS_2_DEPTH_STENCIL_ATTACHMENT_WRITE_BIT|VK_ACCESS_2_DEPTH_STENCIL_ATTACHMENT_READ_BIT);
    {
        VkRenderingAttachmentInfo da{VK_STRUCTURE_TYPE_RENDERING_ATTACHMENT_INFO};
        da.imageView=view; da.imageLayout=VK_IMAGE_LAYOUT_DEPTH_ATTACHMENT_OPTIMAL;
        da.loadOp=VK_ATTACHMENT_LOAD_OP_CLEAR; da.storeOp=VK_ATTACHMENT_STORE_OP_STORE;
        da.clearValue.depthStencil={1.0f,0};   // 1 = the box's bottom: open sky
        VkRenderingInfo ri{VK_STRUCTURE_TYPE_RENDERING_INFO};
        ri.renderArea={{0,0},{res,res}}; ri.layerCount=1; ri.colorAttachmentCount=0;
        ri.pDepthAttachment=&da;
        vkCmdBeginRendering(cmd,&ri);
        VkViewport vp{0.f,0.f,(float)res,(float)res,0.f,1.f};
        VkRect2D sc{{0,0},{res,res}};
        vkCmdSetViewport(cmd,0,1,&vp); vkCmdSetScissor(cmd,0,1,&sc);
    }
    VKDrawPush pp = dp;
    {
        // Camera-relative casters (#555): the world matrix rebased onto the eye.
        static const float kWorldOrigin[3] = {0.f, 0.f, 0.f};
        float vp_rel[16];
        vkRebaseOrigin(mWeather->occlusionViewProj(), kWorldOrigin, dp.cam_time, vp_rel);
        vkSetDrawOrigin(pp, vp_rel, dp.cam_time);
    }
    const VkDescriptorSet dsets[2] = {mDsetDraw0, mDsetDraw1};
    const VkDeviceSize off = 0;
    bindDrawSets(cmd, dsets);
    pushDrawView(cmd, mDrawLayout, pp);
    vkCmdBindVertexBuffers(cmd,0,1,&mVbo.buffer,&off);
    vkCmdBindIndexBuffer(cmd, mIbo.buffer, 0, VK_INDEX_TYPE_UINT16);
    auto draw = [&](VkPipeline pipe, const GpuBuffer& buf, uint32_t b) {
        bindGraphicsPipeline(cmd, pipe);
        bucketDraw(cmd, buf.buffer, 0, mShadowCounters.buffer, counterSlot(b)*sizeof(uint32_t),
                   mdiMaxSlot(counterSlot(b)), sizeof(DrawCmd));
    };
    // <GMDX> cull-none pipelines (the Ds ones) for the single-sided buckets too: the projector pipes
    // cull back faces since 246a510a75 (LL's spot shadows), and this map's matrix has no y-flip, so
    // its winding is reversed -- every upward single-sided face (terrain, prim tops) was culled, the
    // near cascade's cover read the undersides as tops, and the ground under the camera stayed bare.
    draw(mProjDsPipe,     mShadowCmd[0], 0);   // opaque
    draw(mProjMaskDsPipe, mShadowCmd[1], 1);   // alpha-mask (foliage: the alpha test keeps its gaps)
    // </GMDX>
    draw(mProjMaskDsPipe, mShadowCmd[2], 2);   // alpha-blend, alpha-tested as the projector tiles (invisible prims stay open)
    draw(mProjDsPipe,     mShadowCmd[3], 6);   // double-sided opaque
    draw(mProjMaskDsPipe, mShadowCmd[4], 7);   // double-sided mask
    vkCmdEndRendering(cmd);
    // -> the lit FS / deferred compute / the simulation (from the next recording on: it is
    // published then).
    imgBarrier(VK_IMAGE_LAYOUT_DEPTH_ATTACHMENT_OPTIMAL, VK_IMAGE_LAYOUT_DEPTH_READ_ONLY_OPTIMAL,
               kDepthStages, VK_ACCESS_2_DEPTH_STENCIL_ATTACHMENT_WRITE_BIT,
               VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT|VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT,
               VK_ACCESS_2_SHADER_SAMPLED_READ_BIT);
    mWeather->occlusionRendered();
}

bool LLCleanRendererVK::asyncSubmitFrame(VkQueue gfxQueue, const AsyncWsi& wsi)
{
    if (!mAsyncOptIn) return false;
    mAsyncOptIn = false;
    // Tail = the open graphics command buffer (ended by the caller).
    AsyncSeg tail = mAsyncGfxOpen;
    tail.cmd = mAsyncGfx;
    // recordWorld joins everything it forks (the post segment aside); a frame that never
    // reached its join points (early out) still orders its graphics after the async work.
    if (mAsyncOutstanding)
    {
        tail.waitComp = std::max(tail.waitComp, mAsyncOutstanding);
        mAsyncJoinedLast = std::max(mAsyncJoinedLast, mAsyncOutstanding);
        mAsyncOutstanding = 0;
    }
    // (#978 phase 2) the one-frame-latency GI segment, when giLagJoin could not record its join: the tail
    // (and so the in-flight fence) waits it.
    if (mGiLagValue && mGiLagValue > mAsyncJoinedLast)
    {
        tail.waitComp = std::max(tail.waitComp, mGiLagValue);
        mAsyncJoinedLast = std::max(mAsyncJoinedLast, mGiLagValue);
    }
    mGiLagValue = 0;
    std::vector<AsyncSeg> segs;
    segs.reserve(mAsyncSegs.size() + 1);
    segs = mAsyncSegs;
    segs.push_back(tail);
    // Last frame's post segment not joined during recording (no split this frame): the
    // FIRST graphics submission waits it.
    if (mAsyncPostPrev)
    {
        for (AsyncSeg& g : segs)
            if (!g.compute) { g.waitComp2 = mAsyncPostPrev; break; }
        mAsyncJoinedLast = std::max(mAsyncJoinedLast, mAsyncPostPrev);
        mAsyncPostPrev = 0;
    }
    mAsyncSegs.clear();

    // Storage that must outlive the vkQueueSubmit2 calls.
    std::vector<VkSemaphoreSubmitInfo> waits, sigs;
    std::vector<VkCommandBufferSubmitInfo> cbs;
    waits.reserve(segs.size() * 3 + 1);
    sigs.reserve(segs.size() * 2 + 1);
    cbs.reserve(segs.size() + 1);
    std::vector<VkSubmitInfo2> batch;
    batch.reserve(segs.size() + 1);
    auto semInfo = [](VkSemaphore s, uint64_t v, VkPipelineStageFlags2 st)
    {
        VkSemaphoreSubmitInfo i{VK_STRUCTURE_TYPE_SEMAPHORE_SUBMIT_INFO};
        i.semaphore = s; i.value = v; i.stageMask = st;
        return i;
    };
    bool batchCompute = false;
    // #697: a segment that could not be ended -> nothing of this frame is submitted
    if (mFrameOom)
    {
        dropAsyncFrame(gfxQueue, wsi, false);
        return true;
    }
    bool acquireInBatch = false, acquireConsumed = false, submitFailed = false;
    auto flush = [&](bool withFence)
    {
        if (batch.empty() || submitFailed) return;
        const VkResult r = vkInjectOomTake() ? VK_ERROR_OUT_OF_HOST_MEMORY
                         : vkQueueSubmit2(batchCompute ? mAsyncQueue : gfxQueue, (uint32_t)batch.size(), batch.data(),
                                          withFence ? wsi.fence : VK_NULL_HANDLE);
        if (vkIsOom(r)) { submitFailed = true; return; }   // #697: dropped below
        VK_CHECK(r);
        if (acquireInBatch) acquireConsumed = true;
        acquireInBatch = false;
        batch.clear();
    };
    auto addSubmit = [&](bool compute, VkCommandBuffer cmd, size_t w0, size_t s0)
    {
        if (!batch.empty() && batchCompute != compute) flush(false);
        batchCompute = compute;
        cbs.push_back(VkCommandBufferSubmitInfo{VK_STRUCTURE_TYPE_COMMAND_BUFFER_SUBMIT_INFO});
        cbs.back().commandBuffer = cmd;
        VkSubmitInfo2 si{VK_STRUCTURE_TYPE_SUBMIT_INFO_2};
        si.waitSemaphoreInfoCount = (uint32_t)(waits.size() - w0);
        si.pWaitSemaphoreInfos = si.waitSemaphoreInfoCount ? &waits[w0] : nullptr;
        si.commandBufferInfoCount = 1;
        si.pCommandBufferInfos = &cbs.back();
        si.signalSemaphoreInfoCount = (uint32_t)(sigs.size() - s0);
        si.pSignalSemaphoreInfos = si.signalSemaphoreInfoCount ? &sigs[s0] : nullptr;
        batch.push_back(si);
    };
    // WSI pre-command buffer (swapchain clear): the only submission waiting the acquire
    // semaphore, so image acquisition never holds the front end / async work back. The
    // world's later swap-image accesses chain on its final COLOR_ATTACHMENT barrier
    // (same queue, submission order).
    bool acquireUsed = false;
    if (mAsyncWsi)
    {
        const size_t w0 = waits.size(), s0 = sigs.size();
        if (wsi.acquire) { waits.push_back(semInfo(wsi.acquire, 0, wsi.acquireStage)); acquireUsed = true; acquireInBatch = true; }
        addSubmit(false, mAsyncWsi, w0, s0);
        mAsyncWsi = VK_NULL_HANDLE;
    }
    for (size_t i = 0; i < segs.size(); ++i)
    {
        const AsyncSeg& g = segs[i];
        const bool last = (i + 1 == segs.size());
        const size_t w0 = waits.size(), s0 = sigs.size();
        if (g.compute)
        {
            if (g.waitGfx) waits.push_back(semInfo(mTlGfx, g.waitGfx, VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT));
            if (g.signal)  sigs.push_back(semInfo(mTlComp, g.signal, VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT));
        }
        else
        {
            if (!acquireUsed && wsi.acquire)
            {
                waits.push_back(semInfo(wsi.acquire, 0, wsi.acquireStage));
                acquireUsed = true;
                acquireInBatch = true;
            }
            if (g.waitComp)  waits.push_back(semInfo(mTlComp, g.waitComp, g.waitCompStage));
            if (g.waitComp2) waits.push_back(semInfo(mTlComp, g.waitComp2, VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT));
            if (g.signal)    sigs.push_back(semInfo(mTlGfx, g.signal, VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT));
            if (last && wsi.renderFinished)
                sigs.push_back(semInfo(wsi.renderFinished, 0, VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT));
        }
        addSubmit(g.compute, g.cmd, w0, s0);
    }
    flush(true);   // the tail is graphics: the in-flight fence goes on its batch
    if (submitFailed)
    {
        // (acquireInBatch: the failed batch held the acquire wait -- not consumed)
        dropAsyncFrame(gfxQueue, wsi, acquireConsumed);
        return true;
    }
    LLVKHitch::count("asyncForks", mAsyncForks);
    // #845 / #917: what this frame handed to the two queues (device-lost report).
    {
        AsyncFrameRec& fr = mAsyncFrameLog[mAsyncFrameLogN++ % kAsyncFrameLog];
        fr.frame = vkAddrCurrentFrame();
        fr.slot = mAsyncSlot;
        fr.n = 0;
        for (const AsyncSeg& g : segs)
        {
            if (fr.n >= sizeof(fr.seg) / sizeof(fr.seg[0])) break;
            fr.seg[fr.n++] = AsyncFrameRec::Seg{g.compute, g.name, g.waitGfx, g.waitComp, g.waitComp2, g.signal};
        }
    }
    return true;
}

// ---- #845 / #917 device-lost report: the async queue's recent frames ----
void LLCleanRendererVK::asyncLostHook()
{
    const LLCleanRendererVK* r = sAsyncLostRenderer;
    if (!r) return;
    char line[512];
    std::snprintf(line, sizeof(line), "[vktest] async compute: compute-only family %d, handed out graphics timeline %llu / "
                  "compute timeline %llu, joined %llu, slot waits %llu %llu, frame slot %u, RenderVKAsyncLayoutsOnGraphics "
                  "transitions left on the compute queue so far %u",
                  r->mAsyncComputeOnly ? 1 : 0, (unsigned long long)r->mTlGfxNext, (unsigned long long)r->mTlCompNext,
                  (unsigned long long)r->mAsyncJoinedLast, (unsigned long long)r->mAsyncSlotCompLast[0],
                  (unsigned long long)r->mAsyncSlotCompLast[1], r->mFrameSlot, vkAsyncAttachTransitions());
    vkFaultLogLine(line);
    std::snprintf(line, sizeof(line), "[vktest] texture retire guard: slot repairs %llu, duplicate records dropped %llu, "
                  "registry-owned dropped %llu, deferred %llu, compute waits %llu, forced %llu, late now %u",
                  (unsigned long long)r->mGuardSlotRepairs, (unsigned long long)r->mGuardDupDrops,
                  (unsigned long long)r->mGuardOwnedDrops, (unsigned long long)r->mGuardDeferred,
                  (unsigned long long)r->mGuardCompWaits, (unsigned long long)r->mGuardForced,
                  (unsigned)r->mRetireLate.size());
    vkFaultLogLine(line);
    // (#1049) the RT reflection hang guard (lit guard words kLgRt..) of the last frames whose readback
    // copy ran (host-visible ring: a hung frame's own copy never does; idle words stay 0)
    for (uint32_t k = 0; k < 3; ++k)
    {
        if (!r->mLgRb[k].mapped) continue;
        const uint32_t* w = static_cast<const uint32_t*>(r->mLgRb[k].mapped);
        std::snprintf(line, sizeof(line), "[vktest] RT reflection hang guard (#1049), lit guard ring %u (guard frame %llu): "
                      "query budget cut %u rays, rtRaySane refused %u rays, candidate budget hit %u walks",
                      k, (unsigned long long)r->mLgRbFrame[k], w[kLgRt], w[kLgRt + 1], w[kLgRt + 2]);
        vkFaultLogLine(line);
    }
    const uint32_t have = std::min(r->mAsyncFrameLogN, kAsyncFrameLog);
    for (uint32_t k = 0; k < have; ++k)
    {
        const AsyncFrameRec& fr = r->mAsyncFrameLog[(r->mAsyncFrameLogN - have + k) % kAsyncFrameLog];
        std::snprintf(line, sizeof(line), "[vktest] async frame (registry frame %u, slot %u): %u segments in submission order",
                      fr.frame, fr.slot, fr.n);
        vkFaultLogLine(line);
        for (uint32_t i = 0; i < fr.n; ++i)
        {
            const AsyncFrameRec::Seg& g = fr.seg[i];
            if (g.compute)
                std::snprintf(line, sizeof(line), "[vktest]   %2u compute  %-16s wait gfx %llu -> signal comp %llu", i,
                              g.name ? g.name : "?", (unsigned long long)g.waitGfx, (unsigned long long)g.signal);
            else
                std::snprintf(line, sizeof(line), "[vktest]   %2u graphics %-16s wait comp %llu (+ %llu) -> signal gfx %llu", i,
                              "", (unsigned long long)g.waitComp, (unsigned long long)g.waitComp2,
                              (unsigned long long)g.signal);
            vkFaultLogLine(line);
        }
    }
}

// ---- #697 dropped frames (see the header) ----
bool LLCleanRendererVK::vkEndOrNoteOom(VkCommandBuffer cmd)
{
    const VkResult r = vkInjectOomTake() ? VK_ERROR_OUT_OF_HOST_MEMORY : vkEndCommandBuffer(cmd);
    if (vkIsOom(r))
    {
        mFrameOom = true;
        return false;
    }
    VK_CHECK(r);
    return true;
}

bool LLCleanRendererVK::submitEmptyFrame(VkQueue q, const AsyncWsi& wsi, bool waitAcquire)
{
    VkSemaphoreSubmitInfo w{VK_STRUCTURE_TYPE_SEMAPHORE_SUBMIT_INFO};
    w.semaphore = wsi.acquire;
    w.stageMask = wsi.acquireStage ? wsi.acquireStage : VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT;
    VkSemaphoreSubmitInfo sg{VK_STRUCTURE_TYPE_SEMAPHORE_SUBMIT_INFO};
    sg.semaphore = wsi.renderFinished;
    sg.stageMask = VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT;
    VkSubmitInfo2 si{VK_STRUCTURE_TYPE_SUBMIT_INFO_2};
    si.waitSemaphoreInfoCount = (waitAcquire && wsi.acquire) ? 1u : 0u;
    si.pWaitSemaphoreInfos = si.waitSemaphoreInfoCount ? &w : nullptr;
    si.signalSemaphoreInfoCount = wsi.renderFinished ? 1u : 0u;
    si.pSignalSemaphoreInfos = si.signalSemaphoreInfoCount ? &sg : nullptr;
    const VkResult r = vkQueueSubmit2(q, 1, &si, wsi.fence);   // (no command buffers)
    if (r == VK_SUCCESS) return true;
    // Not even an empty submission: the queue cannot make progress. The graceful lost-device
    // path (message, logout, clean exit) instead of LL_ERRS.
    LL_WARNS("Vulkan") << "dropped frame: the empty replacement submission failed too (" << vkResultString(r)
                       << "); treating the device as lost" << LL_ENDL;
    vkDeviceLostRaise("vkQueueSubmit2 (dropped-frame replacement)", r, nullptr, __FILE__, __LINE__);
    return false;
}

void LLCleanRendererVK::dropAsyncFrame(VkQueue gfxQueue, const AsyncWsi& wsi, bool acquireConsumed)
{
    VkDevice dev = mCtx->device();
    // 1. Whatever was submitted finishes (its signals land; nothing pending past them).
    vkDeviceWaitIdle(dev);
    // 2. Every timeline value handed out this frame (fork / segment ends, pipelining P)
    //    is reached from the host: the next frame's waits on them must not hang.
    for (const std::pair<VkSemaphore, uint64_t>& t : {std::make_pair(mTlGfx, mTlGfxNext), std::make_pair(mTlComp, mTlCompNext)})
    {
        if (!t.first) continue;
        uint64_t cur = 0;
        if (vkGetSemaphoreCounterValue(dev, t.first, &cur) != VK_SUCCESS || cur >= t.second) continue;
        VkSemaphoreSignalInfo ssi{VK_STRUCTURE_TYPE_SEMAPHORE_SIGNAL_INFO};
        ssi.semaphore = t.first;
        ssi.value = t.second;
        vkSignalSemaphore(dev, &ssi);
    }
    mAsyncSegs.clear();
    mAsyncOutstanding = 0;
    mAsyncPostPrev = 0;
    mGiLagValue = 0;   // (#978 phase 2: host-signalled above)
    mPipeSignal = 0;
    mAsyncWsi = VK_NULL_HANDLE;
    // 3. The swapchain contract (acquire consumed, render-finished + fence signalled).
    submitEmptyFrame(gfxQueue, wsi, !acquireConsumed);
    onFrameDropped();
}

void LLCleanRendererVK::onFrameDropped()
{
    mFrameOom = false;
    ++mFramesDropped;
    // Cluster LOD (#749): none of the lost recording's page copies / table writes / zero fills
    // may have run -- residency restarts (no page flips resident without its copy).
    if (mCluster) mCluster->frameDropped();
    if (mLiveSnap) mLiveSnap->frameDropped();   // #873: the shot's recording never ran
    vkLowMemNote(VKLM_FRAME, true);
    // Everything the lost recording streamed / copied is re-sent from the CPU mirrors.
    mInstFullUpload = true;
    mStageRetrySlots = mStageRetryGroups = mStageRetryMat = true;
    mJointRowsFull = true;
    mSkinMetaFull = true;
    mAnimArenaFull = true;
    mAnimTopoUpload = true;
    mGeomStreamAll = true;   // (a grow copy recorded in the lost frame never ran)
    mMatUVDirty = mTerrainDirty = true;
    mPrevMatUV.clear();
    mPrevTerrain.clear();
    mTemporalReset = true;
    mGiLagLast.have = false;   // (#978 phase 2: the lost recording's GI trace never ran)
    if (mRT) mRT->dropAfterLostFrame();
    static double s_last = -1.0e9;
    const double now = LLFrameTimer::getElapsedSeconds();
    if (now - s_last >= 5.0)
    {
        s_last = now;
        LL_WARNS("Vulkan") << "frame DROPPED: out of memory ending / submitting its command buffers ("
                           << mFramesDropped << " so far); the next frame re-streams the scene tables. "
                           << "VRAM soft-fails: " << mCtx->softFailSummary() << LL_ENDL;
    }
    mVramOomKick = true;   // the ladder answers at the next texture pass (fast step)
}

// Probe filter now, or (faces recorded early) at the frame end: the filter writes the
// probe arrays the main view samples, so running it before pass 1 would show this
// frame's capture one frame sooner than before -- a visual change. Deferred, the main
// view samples last frame's filtered probes exactly as with the capture at the end.
void LLCleanRendererVK::probeFilterOrDefer(VkCommandBuffer cmd, VkImage capImage,
                                           const std::vector<VkDescriptorSet>& sets, uint32_t slot,
                                           const char* markMips, const char* markFilter, uint32_t tsQuery,
                                           uint32_t traced, int gpuJob)
{
    const VkDeviceSize jobOff = prbJobOff();   // (this frame slot's job records, kept for a deferred filter)
    if (mProbeDeferFilter)
    {
        // The PR stats' end timestamp can't bracket a filter recorded a whole frame later:
        // write it now (the stat then skips the filter, see the caller) and leave the
        // filter's cost to its pr_mips / pr_filter sub-marks.
        if (tsQuery != ~0u && mPrTsPool)
            vkCmdWriteTimestamp2(cmd, VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT, mPrTsPool, tsQuery);
        mProbeFilterPending.push_back({capImage, &sets, slot, markMips, markFilter, ~0u, traced, gpuJob, jobOff});
        return;
    }
    recordProbeFilter(cmd, capImage, sets, slot, markMips, markFilter, traced, gpuJob, jobOff);
    if (tsQuery != ~0u && mPrTsPool)
        vkCmdWriteTimestamp2(cmd, VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT, mPrTsPool, tsQuery);
}

void LLCleanRendererVK::flushProbeFilters(VkCommandBuffer cmd)
{
    mProbeDeferFilter = false;
    for (const ProbeFilterJob& j : mProbeFilterPending)
    {
        // The capture cube's faces were left in GENERAL by the early faces (recordProbeFace)
        // and the traced ones (joined / flushed before this); recordProbeFilter's first
        // barrier takes them from there.
        recordProbeFilter(cmd, j.image, *j.sets, j.slot, j.markMips, j.markFilter, j.traced, j.gpuJob, j.jobOff);
        if (j.tsQuery != ~0u && mPrTsPool)
            vkCmdWriteTimestamp2(cmd, VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT, mPrTsPool, j.tsQuery);
    }
    mProbeFilterPending.clear();
}

// ---- OPAQUE VARIABLE-RATE SHADING (VRS tier 2; clean_vrs_rate.comp) ----
bool LLCleanRendererVK::ensureVrs(VkCommandBuffer cmd, uint32_t rw, uint32_t rh)
{
    VkMemScope memcat(VKMEM_TARGET);   // #407
    if (!mVrsPipe || !mDsetVrs[0] || !mCtx->shadingRateImageEnabled()) return false;
    if (!mDepth.view || !mPrevColor.view || !mExposureImg.view) return false;
    const uint32_t t = mCtx->shadingRateTexel();
    const uint32_t w = (rw + t - 1) / t, h = (rh + t - 1) / t;
    VkDevice dev = mCtx->device();
    if (!mVrsRate.image || w != mVrsW || h != mVrsH)
    {
        vkDeviceWaitIdle(dev);   // the old image / sets may be in use by frames in flight
        destroyVrs();
        mVrsRate = mCtx->createImage2D(w, h, VK_FORMAT_R8_UINT,
            VK_IMAGE_USAGE_STORAGE_BIT | VK_IMAGE_USAGE_FRAGMENT_SHADING_RATE_ATTACHMENT_BIT_KHR
            | VK_IMAGE_USAGE_TRANSFER_DST_BIT, VK_IMAGE_ASPECT_COLOR_BIT);
        if (!mVrsRate.image) return false;
        mCtx->setObjectName(VK_OBJECT_TYPE_IMAGE, (uint64_t)mVrsRate.image, "vrsRate");
        mVrsW = w; mVrsH = h;
        // GENERAL for life, cleared to 1x1 (0).
        VkImageMemoryBarrier2 b{VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER_2};
        b.dstStageMask=VK_PIPELINE_STAGE_2_CLEAR_BIT; b.dstAccessMask=VK_ACCESS_2_TRANSFER_WRITE_BIT;
        b.oldLayout=VK_IMAGE_LAYOUT_UNDEFINED; b.newLayout=VK_IMAGE_LAYOUT_GENERAL;
        b.image=mVrsRate.image; b.subresourceRange={VK_IMAGE_ASPECT_COLOR_BIT,0,1,0,1};
        VkDependencyInfo d{VK_STRUCTURE_TYPE_DEPENDENCY_INFO}; d.imageMemoryBarrierCount=1; d.pImageMemoryBarriers=&b;
        vkCmdPipelineBarrier2(cmd,&d);
        const VkClearColorValue zero{};
        const VkImageSubresourceRange rng{VK_IMAGE_ASPECT_COLOR_BIT,0,1,0,1};
        vkCmdClearColorImage(cmd, mVrsRate.image, VK_IMAGE_LAYOUT_GENERAL, &zero, 1, &rng);
        b.srcStageMask=VK_PIPELINE_STAGE_2_CLEAR_BIT; b.srcAccessMask=VK_ACCESS_2_TRANSFER_WRITE_BIT;
        b.dstStageMask=VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT|VK_PIPELINE_STAGE_2_FRAGMENT_SHADING_RATE_ATTACHMENT_BIT_KHR;
        b.dstAccessMask=VK_ACCESS_2_SHADER_STORAGE_READ_BIT|VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT
                       |VK_ACCESS_2_FRAGMENT_SHADING_RATE_ATTACHMENT_READ_BIT_KHR;
        b.oldLayout=VK_IMAGE_LAYOUT_GENERAL;
        vkCmdPipelineBarrier2(cmd,&d);
        mVrsHistOk = false;
        for (VkImageView& v : mVrsViews) v = VK_NULL_HANDLE;
        if (!mVrsLogged)
        {
            mVrsLogged = true;
            LL_INFOS("Vulkan") << "VRS: opaque shading-rate image " << w << "x" << h << " texels of "
                               << t << "x" << t << " px" << LL_ENDL;
        }
    }
    // Motion target: when it doesn't exist set [1] (and [0]) point b2 at the previous
    // colour, a valid sampled image the shader never reads (push flag).
    const VkImageView motion = mMotion.view ? mMotion.view : mPrevColor.view;
    const VkImageView views[5] = {mPrevColor.view, mDepth.view, motion, mVrsRate.view, mExposureImg.view};
    if (std::memcmp(views, mVrsViews, sizeof(views)) != 0 || mVrsGen != mTargetGen)   // (gen: recycled handles)
    {
        if (mVrsViews[0]) vkDeviceWaitIdle(dev);   // rewrite of sets frames in flight may use
        for (int s = 0; s < 2; ++s)
        {
            const VkDescriptorImageInfo ii[5] = {
                {mGlowSampler,  mPrevColor.view, VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL},   // linear clamp
                {mDepthSampler, mDepth.view,     VK_IMAGE_LAYOUT_DEPTH_READ_ONLY_OPTIMAL},
                {mDepthSampler, s == 0 ? motion : mPrevColor.view, VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL},
                {VK_NULL_HANDLE, mVrsRate.view,  VK_IMAGE_LAYOUT_GENERAL},
                {VK_NULL_HANDLE, mExposureImg.view, VK_IMAGE_LAYOUT_GENERAL}};
            VkWriteDescriptorSet wr[5]{};
            for (int b = 0; b < 5; ++b)
            {
                wr[b].sType=VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET; wr[b].dstSet=mDsetVrs[s]; wr[b].dstBinding=b;
                wr[b].descriptorCount=1; wr[b].pImageInfo=&ii[b];
                wr[b].descriptorType = b >= 3 ? VK_DESCRIPTOR_TYPE_STORAGE_IMAGE : VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER;
            }
            vkUpdateDescriptorSets(dev, 5, wr, 0, nullptr);
        }
        std::memcpy(mVrsViews, views, sizeof(views));
        mVrsGen = mTargetGen;
    }
    return true;
}

void LLCleanRendererVK::destroyVrs()
{
    if (mVrsRate.image) mCtx->destroyImage(mVrsRate);
    mVrsRate = GpuImage{};
    mVrsW = mVrsH = 0;
    mVrsHistOk = false;
    for (VkImageView& v : mVrsViews) v = VK_NULL_HANDLE;
}

void LLCleanRendererVK::recordVrsRate(VkCommandBuffer cmd, uint32_t rw, uint32_t rh, bool motion, uint32_t forceMode)
{
    // In: depth DEPTH_ATTACHMENT_OPTIMAL (pre-pass written), the motion target sampled
    // (motion frames), last frame's colour sampled, the rate image GENERAL (last read as
    // the attachment of the previous pass 1b). Out: depth back to DEPTH_ATTACHMENT, the
    // rate image visible to the shading-rate stage.
    VkImageMemoryBarrier2 db{VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER_2};
    db.srcStageMask=VK_PIPELINE_STAGE_2_EARLY_FRAGMENT_TESTS_BIT|VK_PIPELINE_STAGE_2_LATE_FRAGMENT_TESTS_BIT;
    db.srcAccessMask=VK_ACCESS_2_DEPTH_STENCIL_ATTACHMENT_WRITE_BIT;
    db.dstStageMask=VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; db.dstAccessMask=VK_ACCESS_2_SHADER_SAMPLED_READ_BIT;
    db.oldLayout=VK_IMAGE_LAYOUT_DEPTH_ATTACHMENT_OPTIMAL; db.newLayout=VK_IMAGE_LAYOUT_DEPTH_READ_ONLY_OPTIMAL;
    db.image=mDepth.image; db.subresourceRange={VK_IMAGE_ASPECT_DEPTH_BIT,0,1,0,1};
    VkMemoryBarrier2 mb{VK_STRUCTURE_TYPE_MEMORY_BARRIER_2};   // last frame's attachment read / rate write -> this write
    mb.srcStageMask=VK_PIPELINE_STAGE_2_FRAGMENT_SHADING_RATE_ATTACHMENT_BIT_KHR|VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
    mb.srcAccessMask=VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    mb.dstStageMask=VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
    mb.dstAccessMask=VK_ACCESS_2_SHADER_STORAGE_READ_BIT|VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    VkDependencyInfo dep{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
    dep.memoryBarrierCount=1; dep.pMemoryBarriers=&mb;
    dep.imageMemoryBarrierCount=1; dep.pImageMemoryBarriers=&db;
    vkCmdPipelineBarrier2(cmd,&dep);

    struct { float size[4]; float params[4]; float flags[4]; float mode[4]; } p{};
    static_assert(sizeof(p) == 64, "VrsPush layout");
    F32 thr = 0.05f, mrelax = 0.15f, edge = 0.5f;
#if defined(LL_HAS_CLEAN_PIPELINE)
    static LLCachedControl<F32> s_thr(gSavedSettings, "RenderVKOpaqueShadingRateThreshold", 0.05f);
    static LLCachedControl<F32> s_mot(gSavedSettings, "RenderVKOpaqueShadingRateMotion", 0.15f);
    static LLCachedControl<F32> s_edge(gSavedSettings, "RenderVKOpaqueShadingRateEdge", 0.5f);
    thr = llmax((F32)s_thr, 0.f); mrelax = llmax((F32)s_mot, 0.f); edge = llmax((F32)s_edge, 0.f);
#endif
    p.size[0] = (float)rw; p.size[1] = (float)rh; p.size[2] = 1.f / (float)rw; p.size[3] = 1.f / (float)rh;
    p.params[0] = thr; p.params[1] = mrelax; p.params[2] = edge;
    p.params[3] = mAtmos[13 * 4 + 0];   // RenderExposure (as the tonemap / TAA)
    // History: last frame's colour exists at this size and the camera didn't cut.
    // (mTaaResolveReset stays true while the temporal state is off: gate it.)
    p.flags[0] = (mPrevValid && !(mTemporalOn && mTaaResolveReset)) ? 1.f : 0.f;
    p.flags[1] = motion ? 1.f : 0.f;
    p.flags[2] = (mAtmos[15 * 4 + 2] > 0.5f && mExposurePipe) ? 1.f : 0.f;   // dynamic exposure
    p.flags[3] = kReverseZ ? 1.f : 0.f;
    p.mode[0] = (float)forceMode;
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mVrsPipe);
    vkCmdBindDescriptorSets(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mVrsLayout, 0, 1, &mDsetVrs[motion ? 0 : 1], 0, nullptr);
    VK_PUSH_BUDGET_CHECK(p);
    vkCmdPushConstants(cmd, mVrsLayout, VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(p), &p);
    vkCmdDispatch(cmd, mVrsW, mVrsH, 1);
    mVrsHistOk = true;   // the texels now hold a decision (next frame's hysteresis)

    db.srcStageMask=VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; db.srcAccessMask=0;
    db.dstStageMask=VK_PIPELINE_STAGE_2_EARLY_FRAGMENT_TESTS_BIT|VK_PIPELINE_STAGE_2_LATE_FRAGMENT_TESTS_BIT;
    db.dstAccessMask=VK_ACCESS_2_DEPTH_STENCIL_ATTACHMENT_READ_BIT|VK_ACCESS_2_DEPTH_STENCIL_ATTACHMENT_WRITE_BIT;
    db.oldLayout=VK_IMAGE_LAYOUT_DEPTH_READ_ONLY_OPTIMAL; db.newLayout=VK_IMAGE_LAYOUT_DEPTH_ATTACHMENT_OPTIMAL;
    mb.srcStageMask=VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; mb.srcAccessMask=VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    mb.dstStageMask=VK_PIPELINE_STAGE_2_FRAGMENT_SHADING_RATE_ATTACHMENT_BIT_KHR;
    mb.dstAccessMask=VK_ACCESS_2_FRAGMENT_SHADING_RATE_ATTACHMENT_READ_BIT_KHR;
    vkCmdPipelineBarrier2(cmd,&dep);
}

// ---- DEFERRED LIGHTING (RenderVKDeferredLighting; phase 5.2) ----
bool LLCleanRendererVK::deferredWanted(bool prepass, bool od, const char** why) const
{
    auto no = [&](const char* w) { if (why) *why = w; return false; };
    bool on = true, hl = false, snap = true;
    U32 dbg = 0, litdbg = 0;
#if defined(LL_HAS_CLEAN_PIPELINE)
    static LLCachedControl<bool> s_on(gSavedSettings, "RenderVKDeferredLighting", true);
    static LLCachedControl<bool> s_snap(gSavedSettings, "RenderVKSnapshotDeferred", true);
    snap = s_snap;
    static LLCachedControl<U32> s_dbgview(gSavedSettings, "RenderVKDebugView", 0);
    static LLCachedControl<U32> s_litdbg(gSavedSettings, "RenderVKLitDebugMask", 0);
    on = s_on; dbg = s_dbgview; litdbg = s_litdbg;
    hl = LLPipeline::sShowDebugAlpha;
#endif
    if (!on) return no("RenderVKDeferredLighting off");
    if (!mDeferPipe || !mDsetDefer || !mGbufPipe[0] || !mGbufPipe[1] || !mGbufPipe[2] || !mGbufPipe[3])
        return no("pipelines unavailable");
    // Offscreen snapshots light like the main view (RenderVKSnapshotDeferred): the forward
    // fallback is a path the user never sees on screen, so a snapshot of a deferred main
    // view must not take it. Safe since #snapcrash: ensureDeferred re-creates the G-buffer
    // at the snapshot size (++mTargetGen) and rewrites its set on the generation, and the
    // next on-screen frame re-creates it back. (The async lighting split is main-view only:
    // mAsyncNow.on is false offscreen, so the lighting records inline.)
    if (mOffscreen && !snap) return no("offscreen render (RenderVKSnapshotDeferred off)");
    if (!prepass) return no("no depth pre-pass");
    if (od) return no("overdraw stats");
    // (#195 + #85: a frame predicted to run the MERGED RT shadow pass has no mask by design -- the
    // deferred SHADOW kernel reads the merged sun; recordWorld goes forward here after all if the
    // prediction is withdrawn without a mask to fall back on)
    if (mLitRt && !mRtMaskOn && !mShadowMergeTry) return no("ray-query lit pass (RT shadows without the RT mask)");
    // 13-15, 18: RT overlays, not a lit-FS term (as the frame-info fill maps it); 28: the RT
    // reflection ray density, drawn by the split's combine (it needs the split).
    if (dbg != 0u && !((dbg >= 13u && dbg <= 15u) || dbg == 18u || dbg == 28u)) return no("debug view");
    if (hl) return no("Highlight Transparent");
    if ((litdbg & 4096u) != 0u) return no("shading-rate overlay (RenderVKLitDebugMask 4096)");
    if (!kReverseZ || !mSkyDepthPipe) return no("no depth-tested sky");
    if (why) *why = "";
    return true;
}

// #615: one line per aliased (re)creation -- what the render targets would take without
// aliasing, what they take, and what is shared -- or why a set was not aliased.
void LLCleanRendererVK::logAlias(const char* who, bool ok)
{
    if (!mCtx) return;
    auto mb = [](uint64_t b) { return (unsigned long long)((b + (1ull << 19)) >> 20); };
    if (!ok)
    {
        static std::string s_last;
        const std::string why = mAlias.lastFail();
        if (why == s_last) return;   // (once per reason)
        s_last = why;
        LL_INFOS("Vulkan") << "render target aliasing: " << who << " not aliased ("
                           << (why.empty() ? "unknown" : why) << "); separate allocations" << LL_ENDL;
        return;
    }
    uint32_t imgs = 0, phases = 0, blocks = 0;
    uint64_t member = 0, block = 0, allBlocks = 0;
    mAlias.stats(*mCtx, imgs, member, block, phases);
    mCtx->aliasBlockStats(blocks, allBlocks);
    const VkDeviceContext::MemStats ms = mCtx->memStats();
    const uint64_t now = ms.catDev[VKMEM_TARGET] + ms.catHost[VKMEM_TARGET];
    const uint64_t saved = member > block ? member - block : 0;
    std::ostringstream o;
    o << "render targets: " << mb(now + saved) << " MB -> " << mb(now) << " MB (aliased " << imgs << " images in "
      << phases << " groups: " << mb(member) << " MB in a " << mb(block) << " MB block; " << who << ")";
    if (blocks > 1) o << " [+" << (blocks - 1) << " retiring block(s), " << mb(allBlocks - block) << " MB]";
    LL_INFOS("Vulkan") << o.str() << LL_ENDL;
}

void LLCleanRendererVK::destroyDeferredTargets()
{
    for (GpuImage& g : mGbuf)
        if (g.image) { mCtx->destroyImage(g); g = GpuImage{}; }   // (aliased: drops its block reference)
    mGbufAliased = false;
    mGbufW = mGbufH = 0;
    // (the light grid lives with the G-buffer: ensureDeferred re-creates it and set 2 binding 8)
    if (mLightGrid.buffer) { mCtx->destroyBuffer(mLightGrid); mLightGrid = GpuBuffer{}; }
    mLightGridTiles = 0;
    for (VkImageView& v : mDeferViews) v = VK_NULL_HANDLE;
    mDeferGen = 0;
    // (the G-buffer AO sets name G1: rewritten before their next use. Every caller has waited
    // for the device first, which is why ensureAoGbufSets skips its wait after a null-out.)
    mAoGbufView = VK_NULL_HANDLE;
}

bool LLCleanRendererVK::ensureDeferred(VkCommandBuffer cmd, uint32_t rw, uint32_t rh)
{
    VkMemScope memcat(VKMEM_TARGET);   // #407
    (void)cmd;
    if (!mDeferPipe || !mDsetDefer || !mDepth.view || !mGlowTarget.view || !sceneHdr().view) return false;
    VkDevice dev = mCtx->device();
    // #615: a set left on a retired alias block (or created before RenderVKAliasTargets
    // moved) is re-created like a resize.
    if (!mGbuf[0].image || mGbufW != rw || mGbufH != rh || aliasStale(mGbufAliasEpoch))
    {
        vkDeviceWaitIdle(dev);   // the old targets / set may be in use by frames in flight
        destroyDeferredTargets();
        static const char* names[kGbufCount] = {"gbufAlbedo", "gbufNormal", "gbufMaterial", "gbufEmissive"};
        const VkImageUsageFlags gu = VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT | VK_IMAGE_USAGE_SAMPLED_BIT;
        // ALIASED (#615): phase 0 of mAlias, sharing memory with the bloom pyramid.
        if (!mOffscreen && mAlias.enabled())
        {
            VkAliasArena::Desc ad[kGbufCount];
            for (uint32_t i = 0; i < kGbufCount; ++i)
            {
                ad[i].slot = AS_GBUF0 + i; ad[i].w = rw; ad[i].h = rh;
                ad[i].format = kGbufFormats[i]; ad[i].usage = gu; ad[i].aspect = VK_IMAGE_ASPECT_COLOR_BIT;
            }
            mGbufAliased = mAlias.create(*mCtx, ad, kGbufCount, mGbuf);
            logAlias("G-buffer", mGbufAliased);
        }
        for (uint32_t i = 0; i < kGbufCount; ++i)
        {
            if (!mGbufAliased)
                mGbuf[i] = mCtx->createImage2D(rw, rh, kGbufFormats[i], gu, VK_IMAGE_ASPECT_COLOR_BIT);
            if (!mGbuf[i].image) { destroyDeferredTargets(); return false; }
            mCtx->setObjectName(VK_OBJECT_TYPE_IMAGE, (uint64_t)mGbuf[i].image, names[i]);
        }
        mGbufW = rw; mGbufH = rh;
        mGbufAliasEpoch = mAlias.epoch();
        ++mTargetGen;
    }
    // The light grid (set 2 binding 8): one record per 16 px tile of the render extent, re-created
    // only when the tile count changes. Refused (#697): no deferred lighting this frame (the
    // forward path), retried on the next -- the lit kernels declare the binding, so it must hold
    // a live buffer whichever path RenderVKLightCulling picks.
    const uint32_t gridTiles = ((rw + 15u) / 16u) * ((rh + 15u) / 16u);
    if (!mLightGrid.buffer || mLightGridTiles != gridTiles)
    {
        vkDeviceWaitIdle(dev);   // the buffer / set may be in use by frames in flight
        if (mLightGrid.buffer) { mCtx->destroyBuffer(mLightGrid); mLightGrid = GpuBuffer{}; }
        mLightGridTiles = 0;
        mLightGrid = mCtx->createBuffer((VkDeviceSize)gridTiles * kLightGridWords * sizeof(uint32_t),
                                        VK_BUFFER_USAGE_STORAGE_BUFFER_BIT, VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);
        if (!mLightGrid.buffer)
        {
            static uint32_t s_fails = 0;
            if (s_fails++ == 0)
                LL_WARNS("Vulkan") << "deferred lighting: light grid buffer (" << gridTiles << " tiles) refused (VRAM);"
                                      " forward lighting until a retry succeeds" << LL_ENDL;
            return false;
        }
        mCtx->setObjectName(VK_OBJECT_TYPE_BUFFER, (uint64_t)mLightGrid.buffer, "deferLightGrid");
        mLightGridTiles = gridTiles;
        VkDescriptorBufferInfo bi{mLightGrid.buffer, 0, VK_WHOLE_SIZE};
        VkWriteDescriptorSet w{VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET};
        w.dstSet = mDsetDefer; w.dstBinding = 8; w.descriptorCount = 1;
        w.descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_BUFFER; w.pBufferInfo = &bi;
        vkUpdateDescriptorSets(dev, 1, &w, 0, nullptr);
    }
    const VkImageView views[7] = {mGbuf[0].view, mGbuf[1].view, mGbuf[2].view, mGbuf[3].view,
                                  mDepth.view, sceneHdr().view, mGlowTarget.view};
    // #snapcrash ROOT CAUSE: a handle compare alone is NOT enough. An offscreen snapshot
    // re-creates depth / HDR / glow (other size) and the next main frame re-creates them
    // again (back to the window size) while the G-buffer keeps its size; the driver hands
    // the freed views' handles straight back, every view compared equal, and the deferred
    // lighting compute kept writing HDR + glow (storage) and sampling depth through
    // descriptors of destroyed images: scene wash-out (the real HDR never lit) and, once
    // the freed memory was reused, VK_ERROR_DEVICE_LOST. mTargetGen moves on every
    // screen-target re-creation (see its declaration).
    bool same = mDeferGen == mTargetGen;
    for (int i = 0; i < 7; ++i) same = same && views[i] == mDeferViews[i];
    if (!same)
    {
        vkDeviceWaitIdle(dev);   // the set may be bound by frames in flight
        VkDescriptorImageInfo ii[7]{};
        VkWriteDescriptorSet wr[7]{};
        for (int i = 0; i < 7; ++i)
        {
            ii[i].imageView = views[i];
            ii[i].imageLayout = i < 4 ? VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL
                              : i == 4 ? VK_IMAGE_LAYOUT_DEPTH_READ_ONLY_OPTIMAL : VK_IMAGE_LAYOUT_GENERAL;
            wr[i].sType=VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET; wr[i].dstSet=mDsetDefer; wr[i].dstBinding=(uint32_t)i;
            wr[i].descriptorCount=1; wr[i].pImageInfo=&ii[i];
            wr[i].descriptorType = i >= 5 ? VK_DESCRIPTOR_TYPE_STORAGE_IMAGE : VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE;
        }
        vkUpdateDescriptorSets(dev, 7, wr, 0, nullptr);
        for (int i = 0; i < 7; ++i) mDeferViews[i] = views[i];
        mDeferGen = mTargetGen;
    }
    return true;
}

// ---- FROXEL LIGHT MASKS (RenderVKLightCulling 2; clean_light_froxel.comp) ----
// This extent's froxel grid into the light info (uploaded with it; the build and the deferred
// lighting's lookup read the same words): tile = the power of two nearest rh / 32 (16 .. 128 px:
// ~32 tile rows at any resolution, 64 px at 4K), kFroxelSlices slices -- slice 0 up to
// max(kFroxelNear, the cluster near), then log-spaced to the draw distance (the last open:
// beyond it too) -- and the main view's JITTERED P * rotation-only V + draw origin, the very
// matrix / origin the deferred lighting reconstructs its positions with. Returns the cells.
uint32_t LLCleanRendererVK::froxelSetup(uint32_t rw, uint32_t rh, const float viewProjRelJit[16], const float eye[3])
{
    VKLightInfo& li = mLightInfoCPU;
    rw = std::max(rw, 1u); rh = std::max(rh, 1u);
    const int lg = (int)std::lround(std::log2(std::max(1.0, (double)rh / 32.0)));
    const uint32_t shift = (uint32_t)std::clamp(lg, 4, 7);
    const uint32_t tile = 1u << shift;
    const uint32_t tx = (rw + tile - 1u) >> shift, ty = (rh + tile - 1u) >> shift;
    std::memcpy(li.fx_vp, viewProjRelJit, sizeof(li.fx_vp));
    li.fx_eye[0] = eye[0]; li.fx_eye[1] = eye[1]; li.fx_eye[2] = eye[2]; li.fx_eye[3] = 0.f;
    const float zn = std::max(kFroxelNear, li.zinfo[0]);
    const float zf = std::max(li.zinfo[1], zn * 2.f);
    li.fx_slices[0] = zn;
    li.fx_slices[1] = (float)(kFroxelSlices - 1u) / std::log(zf / zn);
    li.fx_slices[2] = zf;
    li.fx_slices[3] = 0.f;
    li.fx_dims[0] = tx; li.fx_dims[1] = ty; li.fx_dims[2] = kFroxelSlices; li.fx_dims[3] = shift;
    li.fx_extent[0] = (float)rw; li.fx_extent[1] = (float)rh;
    li.fx_extent[2] = 1.f / (float)rw; li.fx_extent[3] = 1.f / (float)rh;
    return tx * ty * kFroxelSlices;
}

// mFroxel -> the build's set (binding 2) and the deferred set (binding 9), whichever exist. The
// deferred kernels declare binding 9 statically, so until the masks exist it names a placeholder
// (the cluster counts: never read, the flag needs this recording's build).
void LLCleanRendererVK::writeFroxelDescriptors()
{
    if (!mCtx) return;
    const VkDescriptorBufferInfo fbi{mFroxel.buffer, 0, VK_WHOLE_SIZE};
    const VkDescriptorBufferInfo dbi{mFroxel.buffer ? mFroxel.buffer : mClusterCount.buffer, 0, VK_WHOLE_SIZE};
    VkWriteDescriptorSet w[2]{};
    uint32_t n = 0;
    if (mDsetFroxel && mFroxel.buffer)
    {
        w[n].sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET; w[n].dstSet = mDsetFroxel; w[n].dstBinding = 2;
        w[n].descriptorCount = 1; w[n].descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_BUFFER; w[n].pBufferInfo = &fbi;
        ++n;
    }
    if (mDsetDefer && dbi.buffer)
    {
        w[n].sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET; w[n].dstSet = mDsetDefer; w[n].dstBinding = 9;
        w[n].descriptorCount = 1; w[n].descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_BUFFER; w[n].pBufferInfo = &dbi;
        ++n;
    }
    if (n) vkUpdateDescriptorSets(mCtx->device(), n, w, 0, nullptr);
}

// Grow-only (high-water + 25 %: a window drag re-creates it a few times, a snapshot at another
// extent at most once). Behind a device wait: both sets may be bound by frames in flight (the
// light pass records it before either set is bound in this recording). Refused (#697): false --
// this frame lights with the tile test, the next one retries.
bool LLCleanRendererVK::ensureFroxelBuffer(uint32_t cells)
{
    if (mFroxel.buffer && cells <= mFroxelCapCells) return true;
    if (!mCtx || !cells) return false;
    const uint32_t cap = cells + cells / 4u;
    GpuBuffer nb;
    {
        VkMemScope memcat(VKMEM_SCENE);   // #407 (lights + clusters)
        // (device address: the forward lit FS reads the masks through LightInfo.fwd.xy)
        nb = mCtx->createBuffer((VkDeviceSize)cap * kFroxelWords * sizeof(uint32_t),
                                VK_BUFFER_USAGE_STORAGE_BUFFER_BIT | VK_BUFFER_USAGE_TRANSFER_DST_BIT,
                                VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT, true);
    }
    if (!nb.buffer)
    {
        static uint32_t s_fails = 0;
        if (s_fails++ == 0)
            LL_WARNS("Vulkan") << "froxel light masks: buffer (" << cap << " cells, "
                               << ((uint64_t)cap * kFroxelWords * 4u + (1u << 19)) / (1u << 20)
                               << " MB) refused (VRAM); tile light tests until a retry succeeds" << LL_ENDL;
        return false;
    }
    mCtx->setObjectName(VK_OBJECT_TYPE_BUFFER, (uint64_t)nb.buffer, "lightFroxels");
    vkDeviceWaitIdle(mCtx->device());   // the old buffer / both sets may be in use by frames in flight
    if (mFroxel.buffer) mCtx->destroyBuffer(mFroxel);
    mFroxel = nb;
    mFroxelCapCells = cap;
    writeFroxelDescriptors();
    LL_INFOS("Vulkan") << "froxel light masks: " << cap << " cells ("
                       << ((uint64_t)cap * kFroxelWords * 4u + (1u << 19)) / (1u << 20) << " MB)" << LL_ENDL;
    return true;
}

// ---- WORLD-SPACE LIGHT RESERVOIR GRID (#869, RenderVKLightGrid; clean_regir.glsl) ----
// mRegir -> the build's set (binding 2) and the deferred set (binding 12). The RT kernels declare
// binding 12 statically, so until the grid exists it names a placeholder (the cluster counts:
// never read -- the kernels touch it only under push rtr.y bit 4, set only when this recording
// built the grid).
void LLCleanRendererVK::writeRegirDescriptors()
{
    if (!mCtx) return;
    const VkDescriptorBufferInfo gbi{mRegir.buffer, 0, VK_WHOLE_SIZE};
    const VkDescriptorBufferInfo dbi{mRegir.buffer ? mRegir.buffer : mClusterCount.buffer, 0, VK_WHOLE_SIZE};
    VkWriteDescriptorSet w[2]{};
    uint32_t n = 0;
    if (mDsetRegir && mRegir.buffer)
    {
        w[n].sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET; w[n].dstSet = mDsetRegir; w[n].dstBinding = 2;
        w[n].descriptorCount = 1; w[n].descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_BUFFER; w[n].pBufferInfo = &gbi;
        ++n;
    }
    if (mDsetDefer && dbi.buffer)
    {
        w[n].sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET; w[n].dstSet = mDsetDefer; w[n].dstBinding = 12;
        w[n].descriptorCount = 1; w[n].descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_BUFFER; w[n].pBufferInfo = &dbi;
        ++n;
    }
    if (n) vkUpdateDescriptorSets(mCtx->device(), n, w, 0, nullptr);
}

// ONE allocation at the cap (kRegirBytes: 48 MiB with the #91 emissive lights, the #869 occlusion cache and the
// #1006 cell cache + its scratch), on the first frame that wants the grid; never
// grown or re-created, so the settings change only how much of it a frame uses. Behind a device
// wait (both sets may be bound by frames in flight). Refused (#697): logged once, the grid stays
// off this session (RenderVKLightGrid acts as 0; the hits keep the exact walk).
bool LLCleanRendererVK::ensureRegirBuffer()
{
    if (mRegir.buffer) return true;
    if (!mCtx || mRegirAllocFailed || !mDsetRegir || !mDsetDefer) return false;
    GpuBuffer nb;
    {
        VkMemScope memcat(VKMEM_SCENE);   // #407 (lights + clusters)
        VkDeviceContext::SoftAllocScope soft(mCtx);
        // (#1006: + INDIRECT -- the emissive cell build's dispatch is counted on the GPU, clean_regir.glsl
        //  INCREMENTAL CELLS)
        nb = mCtx->createBuffer(kRegirBytes, VK_BUFFER_USAGE_STORAGE_BUFFER_BIT | VK_BUFFER_USAGE_TRANSFER_DST_BIT
                                             | VK_BUFFER_USAGE_TRANSFER_SRC_BIT | VK_BUFFER_USAGE_INDIRECT_BUFFER_BIT,
                                VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);
    }
    if (!nb.buffer)
    {
        mRegirAllocFailed = true;
        LL_WARNS("Vulkan") << "light reservoir grid: buffer (" << ((kRegirBytes + (1u << 19)) >> 20)
                           << " MB) refused (VRAM); RT reflection hits keep the exact light walk this session"
                              " (RenderVKLightGrid acts as 0)" << LL_ENDL;
        return false;
    }
    mCtx->setObjectName(VK_OBJECT_TYPE_BUFFER, (uint64_t)nb.buffer, "lightRegir");
    vkDeviceWaitIdle(mCtx->device());   // both sets may be in use by frames in flight
    mRegir = nb;
    mRsOccClear = true;   // (#869: the occlusion cache's region starts undefined)
    mRsEmCellsValid = false;   // (#1006: so does the emissive cell cache -- the first build is FULL)
    writeRegirDescriptors();
    LL_INFOS("Vulkan") << "light reservoir grid: " << kRegirLevelsMax << " levels x " << kRegirCellsPerLevel
                       << " cells x up to " << kRegirResMax << " reservoirs, fixed buffer "
                       << ((kRegirBytes + (1u << 19)) >> 20) << " MB (allocated once)" << LL_ENDL;
    return true;
}

// This recording's grid settings (all live: read every frame) + whether to build it: the master
// switch, the RT reflections running (their hits are the only consumer today) and the pipeline.
bool LLCleanRendererVK::regirWanted()
{
    bool on = false;
    U32 rtMode = 0;
#if defined(LL_HAS_CLEAN_PIPELINE)
    static LLCachedControl<bool> s_on(gSavedSettings, "RenderVKLightGrid", false);
    static LLCachedControl<U32>  s_picks(gSavedSettings, "RenderVKLightGridPicks", 2);
    static LLCachedControl<F32>  s_cell(gSavedSettings, "RenderVKLightGridCellSize", 1.f);
    static LLCachedControl<U32>  s_levels(gSavedSettings, "RenderVKLightGridLevels", 4);
    static LLCachedControl<U32>  s_res(gSavedSettings, "RenderVKLightGridReservoirs", 8);
    static LLCachedControl<F32>  s_foot(gSavedSettings, "RenderVKLightGridFootprintCm", 2.f);
    static LLCachedControl<U32>  s_rt(gSavedSettings, "RenderVKRTReflections", 1);
    on = s_on;
    rtMode = s_rt;
    mRegirPicks = llclamp((U32)s_picks, 1u, kRegirPicksMax);
    mRegirCell = llclamp((F32)s_cell, 0.125f, 16.f);
    mRegirLevels = llclamp((U32)s_levels, 1u, kRegirLevelsMax);
    mRegirRes = llclamp((U32)s_res, 2u, kRegirResMax);
    mRegirFootCm = llclamp((F32)s_foot, 0.f, 1000.f);
#endif
    if (on)
    {
        const uint32_t key[5] = {mRegirPicks, mRegirLevels, mRegirRes, (uint32_t)(mRegirCell * 1000.f + 0.5f),
                                 (uint32_t)(mRegirFootCm * 100.f + 0.5f)};
        if (!mRegirLogged || std::memcmp(key, mRegirLogKey, sizeof(key)) != 0)
        {
            mRegirLogged = true;
            std::memcpy(mRegirLogKey, key, sizeof(key));
            const float outer = mRegirCell * (float)(1u << (mRegirLevels - 1u));
            LL_INFOS("Vulkan") << "light reservoir grid ON (RenderVKLightGrid): " << mRegirLevels << " levels, cell "
                               << mRegirCell << " .. " << outer << " m, outermost +-" << outer * 16.f << " m across / +-"
                               << outer * 8.f << " m up-down; " << mRegirRes << " reservoirs per cell, "
                               << mRegirPicks << " picks per RT reflection hit; hits whose reflected-pixel footprint is"
                                  " below " << mRegirFootCm << " cm keep the exact light walk" << LL_ENDL;
        }
    }
    else if (mRegirLogged)
    {
        mRegirLogged = false;
        LL_INFOS("Vulkan") << "light reservoir grid OFF (RenderVKLightGrid 0): RT reflection hits walk every light"
                              " in range" << LL_ENDL;
    }
    // (#87) the GI trace's hits take their local lights from the grid too (RenderVKGIHitLightGrid)
    mRegirReflOn = on && rtMode == 1u && mRT && !mRtReflStandDown;
    bool giGrid = true;
#if defined(LL_HAS_CLEAN_PIPELINE)
    static LLCachedControl<bool> s_giGrid(gSavedSettings, "RenderVKGIHitLightGrid", true);
    giGrid = s_giGrid;
#endif
    return (mRegirReflOn || (mGiNow && giGrid)) && mRegirPipe && mDsetRegir && mDsetDefer;
}

// The per-frame header: level origins snapped to each level's cell edge around the camera (a cell
// is a fixed world box while the camera moves inside it), R / N / seed, the footprint threshold,
// the changed-light mask; the reach mask and the GPU counters zeroed.
void LLCleanRendererVK::regirHeaderFill(RegirHeader& h)
{
    h = RegirHeader{};
    const double dims[3] = {32.0, 32.0, 16.0};   // = clean_regir.glsl REGIR_DIM_X / Y / Z
    for (uint32_t l = 0; l < kRegirLevelsMax; ++l)
    {
        const double cs = (double)mRegirCell * (double)(1u << std::min(l, mRegirLevels - 1u));
        for (int a = 0; a < 3; ++a)
            h.origin[l][a] = (float)(std::floor((double)mLightInfoCPU.cam_pos[a] / cs) * cs - 0.5 * dims[a] * cs);
        h.origin[l][3] = (float)cs;
    }
    h.cfg[0] = mRegirLevels;
    h.cfg[1] = mRegirRes;
    h.cfg[2] = mRegirPicks;
    h.cfg[3] = ++mRegirFrame;
    h.params[0] = mRegirFootCm * 0.01f;   // cm -> m (rt_surf_foot's unit)
    std::memcpy(h.changed, mRegirChanged, sizeof(h.changed));
    // (#869 Phase 5) ReSTIR DI: population 1's set, slots, reuse parameters, the light remap
    // (clean_regir.glsl RS_F_*; the flags are this recording's decision: regirGo's caller)
    U32 slots = 16, cand = 8, mcap = 20, taps = 3, radius = 12;
    F32 pointR = 0.03f, fixture = 1.5f, projR = 0.01f, bias = 0.f, wcut = 0.25f;
#if defined(LL_HAS_CLEAN_PIPELINE)
    static LLCachedControl<U32> s_slots(gSavedSettings, "RenderVKReSTIRCellSamples", 16U);
    static LLCachedControl<U32> s_cand(gSavedSettings, "RenderVKReSTIRCandidates", 8U);
    static LLCachedControl<U32> s_mcap(gSavedSettings, "RenderVKReSTIRMCap", 20U);
    static LLCachedControl<U32> s_taps(gSavedSettings, "RenderVKReSTIRSpatialTaps", 3U);
    static LLCachedControl<U32> s_rad(gSavedSettings, "RenderVKReSTIRSpatialRadius", 12U);
    static LLCachedControl<F32> s_pr(gSavedSettings, "RenderVKReSTIRPointRadius", 0.03f);
    static LLCachedControl<F32> s_fix(gSavedSettings, "RenderVKReSTIRFixtureSize", 1.5f);
    static LLCachedControl<F32> s_soft(gSavedSettings, "RenderVKRTShadowSoftness", 0.01f);
    static LLCachedControl<F32> s_bias(gSavedSettings, "RenderVKRTShadowBias", 0.f);
    static LLCachedControl<F32> s_wcut(gSavedSettings, "RenderVKDenoiseLightChange", 0.25f);
    slots = s_slots; cand = s_cand; mcap = s_mcap; taps = s_taps; radius = s_rad;
    pointR = s_pr; fixture = s_fix; projR = s_soft; bias = s_bias; wcut = s_wcut;
#endif
    h.rs_cfg[0] = std::clamp<U32>(slots, 1u, kRegirResMax);
    h.rs_cfg[1] = std::min<U32>(cand, kRegirResMax);
    h.rs_cfg[2] = (mRegirNow ? 256u : 0u) | (mRsNow ? 1u : 0u) | (mRsExt ? 2u : 0u) | (mRsAttached ? 4u : 0u)
                | (mRsNow && mRsMode >= 2u ? 8u : 0u) | (mRsNow && mRsMode >= 3u && taps > 0u ? 16u : 0u);
    {   // (RS_F_WCUT: the old cell-target-sum light-set cut, A/B only)
        bool wcut = false;
#if defined(LL_HAS_CLEAN_PIPELINE)
        static LLCachedControl<bool> s_wcut(gSavedSettings, "RenderVKReSTIRLightCut", false);
        wcut = s_wcut;
#endif
        if (wcut) h.rs_cfg[2] |= 32u;
    }
    {   // (RS_F_STRIDE: evenly spaced candidate / dense windows, RenderVKReSTIRStridedWindow)
        U32 stride = 1;
#if defined(LL_HAS_CLEAN_PIPELINE)
        static LLCachedControl<U32> s_stride(gSavedSettings, "RenderVKReSTIRStridedWindow", 1U);
        stride = s_stride;
#endif
        if (stride != 0u) h.rs_cfg[2] |= 64u;
    }
    {   // (#869 RS_F_OCC: the OCCLUSION CULL, RenderVKReSTIROcclusionCull; clean_deferred_light.comp)
        U32 occ = 1;
#if defined(LL_HAS_CLEAN_PIPELINE)
        static LLCachedControl<U32> s_occ(gSavedSettings, "RenderVKReSTIROcclusionCull", 1U);
        occ = s_occ;
#endif
        // (the resolve -- mode 8 of the emissive build kernel -- carries the counts to this frame's light
        //  indices: without it the counts would name other lights, so no cache)
        mRsOccNow = mRsNow && occ != 0u && mRsEmPipe != VK_NULL_HANDLE;
        if (mRsOccNow && !mRsOccPrev) mRsOccClear = true;   // (re-enabled: no verdict from before)
        mRsOccPrev = mRsOccNow;
        if (mRsOccNow) h.rs_cfg[2] |= 512u;
        // (#1052) 1 = the soft cull (evidence filter, 12 frames, a weight dithered / blended across patches);
        // 2 = the first cull's hard rules (RS_F_OCC_HARD, A/B). The counts mean the same: no clear on a switch.
        if (mRsOccNow && occ >= 2u) h.rs_cfg[2] |= 1024u;
    }
    {   // (#1052 RS_F_CONV_ANY, RenderVKReSTIRConvMultiLight: A/B) the denoiser's converged shortcut for any
        // reused reservoir (the old rule) instead of only where one light dominates the texel
        bool convAny = false;
#if defined(LL_HAS_CLEAN_PIPELINE)
        static LLCachedControl<bool> s_convAny(gSavedSettings, "RenderVKReSTIRConvMultiLight", false);
        convAny = s_convAny;
#endif
        if (convAny) h.rs_cfg[2] |= 2048u;
    }
    h.rs_cfg2[0] = std::clamp<U32>(mcap, 1u, 64u);
    h.rs_cfg2[1] = std::min<U32>(taps, 5u);
    h.rs_cfg2[2] = std::clamp<U32>(radius, 1u, 64u);
    h.rs_cfg2[3] = (U32)(std::clamp(wcut, 0.f, 4.f) * 1000.f + 0.5f);
    h.rs_params[0] = std::clamp(pointR, 0.f, 2.f);
    h.rs_params[1] = std::clamp(fixture, 0.f, 16.f);
    h.rs_params[2] = std::max(projR, 0.f);
    h.rs_params[3] = std::max(bias, 0.f);
    std::memcpy(h.rs_set, mRsSet, sizeof(h.rs_set));
    std::memcpy(h.rs_remap, mRsRemap, sizeof(h.rs_remap));
    {   // (#869) the MOVING-LIGHT shadow rule (RenderVKReSTIRMoveCut; clean_regir.glsl RS_MOVE_*):
        // rs_cfg.w bit 0 on, bits 4-7 the disc rays a moved light's sample traces; rs_moved the mask
        // bits 8-11 the candidate lights a moved texel evaluates densely (0 = the one pick)
        U32 moveCut = 1, moveRays = 4, moveLights = 4;
#if defined(LL_HAS_CLEAN_PIPELINE)
        static LLCachedControl<U32> s_mcut(gSavedSettings, "RenderVKReSTIRMoveCut", 1U);
        static LLCachedControl<U32> s_mrays(gSavedSettings, "RenderVKReSTIRMoveRays", 4U);
        static LLCachedControl<U32> s_mlights(gSavedSettings, "RenderVKReSTIRMoveLights", 4U);
        moveCut = s_mcut; moveRays = s_mrays; moveLights = s_mlights;
#endif
        if (moveCut != 0u)
        {
            h.rs_cfg[3] = 1u | (std::clamp<U32>(moveRays, 1u, 15u) << 4u)
                        | (std::min<U32>(moveLights, kRegirResMax - 1u) << 8u);
            std::memcpy(h.rs_moved, mRsMoved, sizeof(h.rs_moved));
            std::memcpy(h.rs_flick, mRsFlick, sizeof(h.rs_flick));   // (empty with RenderVKReSTIRFlickerCut 0)
        }
    }
    // (#91) the emissive lights (clean_regir.glsl EMISSIVE LIGHTS): the triangle cap while wanted (0 = the
    // build writes nothing), mode 1 = they light (EM_F_LIT | EM_F_GI_SPLIT), mode 2 = records + cells only
    {
        U32 em = 0, emSlots = 8, emTris = kRsEmCap, emTake = 1;
        F32 emMin = 0.1f, emGlow = 1.f, emCut = 0.004f, emRange = 32.f, emPbr = 1.f;
        bool emGiSplit = true, emReuse = true, emLists = true, emLong = true, emCluster = true, emSkip = false;
#if defined(LL_HAS_CLEAN_PIPELINE)
        static LLCachedControl<U32> s_em(gSavedSettings, "RenderVKReSTIREmissive", 1U);
        static LLCachedControl<F32> s_emMin(gSavedSettings, "RenderVKReSTIREmissiveMin", 0.1f);
        static LLCachedControl<F32> s_emGlow(gSavedSettings, "RenderVKReSTIREmissiveGlowScale", 1.f);
        static LLCachedControl<F32> s_emCut(gSavedSettings, "RenderVKReSTIREmissiveCutoff", 0.004f);
        static LLCachedControl<F32> s_emRange(gSavedSettings, "RenderVKReSTIREmissiveRange", 32.f);
        static LLCachedControl<U32> s_emSlots(gSavedSettings, "RenderVKReSTIREmissiveSlots", 8U);
        static LLCachedControl<bool> s_emGi(gSavedSettings, "RenderVKReSTIREmissiveGISplit", true);
        static LLCachedControl<U32> s_emTris(gSavedSettings, "RenderVKReSTIREmissiveTriangles", kRsEmCap);
        static LLCachedControl<F32> s_emPbr(gSavedSettings, "RenderVKReSTIREmissivePbrScale", 1.f);
        static LLCachedControl<U32> s_emTake(gSavedSettings, "RenderVKReSTIREmissiveLightTakeover", 1U);
        static LLCachedControl<bool> s_emReuse(gSavedSettings, "RenderVKReSTIREmissiveReuse", true);
        static LLCachedControl<bool> s_emLists(gSavedSettings, "RenderVKReSTIREmissiveCellLists", true);
        static LLCachedControl<bool> s_emLong(gSavedSettings, "RenderVKReSTIREmissiveLongCells", true);
        static LLCachedControl<bool> s_emCluster(gSavedSettings, "RenderVKReSTIREmissiveClusterStatic", true);
        static LLCachedControl<bool> s_emSkip(gSavedSettings, "RenderVKReSTIREmissiveSkipStats", false);
        emCluster = s_emCluster; emSkip = s_emSkip;
        em = s_em; emMin = s_emMin; emGlow = s_emGlow; emCut = s_emCut; emRange = s_emRange; emSlots = s_emSlots;
        emGiSplit = s_emGi; emTris = s_emTris; emPbr = s_emPbr; emTake = s_emTake;
        emReuse = s_emReuse; emLists = s_emLists; emLong = s_emLong;
#endif
        mRsEmMode = std::min<U32>(em, 2u);
        mRsEmNow = mRsNow && mRsEmMode != 0u && mRsEmPipe != VK_NULL_HANDLE;
        h.rs_em[2] = mRsEmNow ? std::clamp<U32>(emTris, 256u, kRsEmCap) : 0u;
        h.rs_em_params[0] = std::max(emMin, 1e-4f);
        h.rs_em_params[1] = std::max(emGlow, 0.f);
        h.rs_em_params[2] = std::isfinite(emPbr) ? std::clamp(emPbr, 0.f, 1000.f) : 1.f;
        h.rs_em_cfg[0] = std::clamp<U32>(emSlots, 1u, kRsEmSlotsMax);
        h.rs_em_cfg[2] = (mRsEmNow && mRsEmMode == 1u) ? (1u | (emGiSplit ? 2u : 0u)) : 0u;
        // (#986) RECORD REUSE once a build has filled the other parity (EM_F_REUSE), the CELL LISTS unless
        // RenderVKReSTIREmissiveCellLists 0 asks for the gather (EM_F_GATHER; recordProjStoch then skips them)
        mRsEmListsNow = mRsEmNow && emLists;
        if (mRsEmNow && emReuse && mRsEmBuiltOnce) h.rs_em_cfg[2] |= 8u;   // EM_F_REUSE
        if (mRsEmNow && !emLists) h.rs_em_cfg[2] |= 16u;                   // EM_F_GATHER
        // (#986 LONG CELLS) a cell with a long list gets a workgroup (mode 9; with the lists only)
        mRsEmLongNow = mRsEmListsNow && emLong;
        if (mRsEmLongNow) h.rs_em_cfg[2] |= 32u;                           // EM_F_LONG
        // (#1009 CLUSTER STATICS, clean_regir.glsl) a static traced on its cluster RT cut emits through the legacy
        // row clean_rt_instances.comp records beside it (RenderVKReSTIREmissiveClusterStatic 0: the A/B -- such
        // statics stay out, as before)
        if (mRsEmNow && emCluster) h.rs_em_cfg[2] |= 2048u;                // EM_F_CLUSTER
        // (#1009 SKIP DIAGNOSTIC) the emitting instances mode 0 leaves out, by why (with the lists: the counters
        // are per-build words of the cell cache header, zeroed and read back with them)
        mRsEmSkipNow = mRsEmListsNow && emSkip;
        if (mRsEmSkipNow) h.rs_em_cfg[2] |= 4096u;                         // EM_F_SKIPSTAT
        h.rs_em_params2[0] = std::isfinite(emCut) ? std::clamp(emCut, 1e-5f, 1.f) : 0.004f;
        h.rs_em_params2[1] = std::isfinite(emRange) ? std::clamp(emRange, 0.5f, 128.f) : 32.f;
        h.rs_em_params2[2] = 0.f;     // (#1006 below: the cell budget; was the own-box pad -- unused)
        // (LIGHT TAKEOVER, clean_regir.glsl) the table's rows reserve the first emitter entries: the entry
        // counter starts past them (recordProjStoch clears them with the hash); only while the emitters light
        mRsEmTakeNow = (mRsEmNow && mRsEmMode == 1u && emTake != 0u)
                     ? std::min<U32>(mRsEmTakeRows, kRsEmTakeN) : 0u;
        if (mRsEmTakeNow != 0u)
        {
            h.rs_em_cfg[2] |= 4u;   // EM_F_TAKE
            h.rs_em_cfg[3] = mRsEmTakeNow;
            h.rs_em_take_cfg[0] = mRsEmTakeNow;
        }
        // (#1006, clean_regir.glsl INCREMENTAL CELLS + WEAK OVERLAY; with the cell lists only -- a gather build
        // re-gathers everything and lists every emitter at level 0)
        U32 emInc = 1, emBudget = 2048, emRestRefresh = 1;
        F32 emWeak = 0.05f;
        bool wcutOn = false;
#if defined(LL_HAS_CLEAN_PIPELINE)
        static LLCachedControl<U32> s_emInc(gSavedSettings, "RenderVKReSTIREmissiveIncremental", 1U);
        static LLCachedControl<U32> s_emBudget(gSavedSettings, "RenderVKReSTIREmissiveCellBudget", 2048U);
        static LLCachedControl<U32> s_emRest(gSavedSettings, "RenderVKReSTIREmissiveRestRefresh", 1U);
        static LLCachedControl<F32> s_emWeak(gSavedSettings, "RenderVKReSTIREmissiveWeakPower", 0.05f);
        static LLCachedControl<bool> s_wcutOn(gSavedSettings, "RenderVKReSTIRLightCut", false);
        emInc = s_emInc; emBudget = s_emBudget; emRestRefresh = s_emRest; emWeak = s_emWeak; wcutOn = s_wcutOn;
#endif
        mRsEmShiftNow = false;
        if (mRsEmListsNow)
        {
            const float weakThr = std::isfinite(emWeak) ? std::clamp(emWeak, 0.f, 1.0e6f) : 0.f;
            if (weakThr > 0.f)
            {
                h.rs_em_cfg[2] |= 256u;                                        // EM_F_WEAK
                h.rs_em_params[3] = weakThr;
            }
            if (mRsEmBuiltOnce) h.rs_em_cfg[2] |= 1024u;                       // EM_F_LAST
            h.rs_em_params2[2] = (float)std::min<U32>(emBudget, kRsEmNCellsAll);   // (0: no cap)
            h.rs_em_params2[3] = (float)std::clamp<U32>(emRestRefresh, 1u, 4096u);
            // everything the cells' content is made of besides the records: a change re-gathers every cell
            auto floatBitsU = [](float f) { uint32_t u; std::memcpy(&u, &f, sizeof(u)); return u; };
            const uint32_t key[12] = {
                mRegirLevels, h.rs_em_cfg[0], (uint32_t)(h.rs_em_cfg[2] & (1u | 4u | 32u | 256u | 2048u)), h.rs_em[2],
                floatBitsU(h.rs_em_params[0]), floatBitsU(h.rs_em_params[1]), floatBitsU(h.rs_em_params[2]),
                floatBitsU(h.rs_em_params[3]), floatBitsU(h.rs_em_params2[0]), floatBitsU(h.rs_em_params2[1]),
                floatBitsU(h.origin[0][3]), mRsEmMode};
            bool full = emInc == 0u || !mRsEmCellsValid || wcutOn || std::memcmp(key, mRsEmCellKey, sizeof(key)) != 0;
            // the ORIGIN SHIFT: every level moved by whole cells (same edges) and not too far (a teleport, a region
            // crossing: everything at once instead) -> mode 12 moves the cells; else FULL
            if (!full)
            {
                bool moved = false;
                for (uint32_t l = 0; l < kRegirLevelsMax && !full; ++l)
                {
                    if (h.origin[l][3] != mRsEmCellOrigin[l][3]) { full = true; break; }
                    for (int a = 0; a < 3; ++a)
                    {
                        if (h.origin[l][a] == mRsEmCellOrigin[l][a]) continue;
                        moved = true;
                        const double d = ((double)h.origin[l][a] - (double)mRsEmCellOrigin[l][a]) / (double)h.origin[l][3];
                        if (!(std::fabs(d) <= 8.0)) full = true;
                    }
                }
                mRsEmShiftNow = moved && !full;
            }
            if (full) h.rs_em_cfg[2] |= 128u;                                   // EM_F_FULL
            if (mRsEmShiftNow) h.rs_em_cfg[2] |= 512u;                          // EM_F_SHIFT
            std::memcpy(mRsEmCellKey, key, sizeof(key));
            std::memcpy(mRsEmCellOrigin, h.origin, sizeof(mRsEmCellOrigin));
            mRsEmCellsValid = true;   // (this build fills the cache -- a gather build makes the GPU's VALID 0)
        }
        else mRsEmCellsValid = false;   // (no lists build this frame: the next one starts over)
    }
}

// (#869 Phase 5) setLights, after the projector records were chosen: pass 15's LIGHT SET (the
// ray-traced projector records; + with RenderVKReSTIRLights 1 every other projector and every point
// light, attached ones only with RenderVKReSTIRAttachedLights) -- the ONE mask the grid's build and
// the lit kernels' ratio rule read (clean_regir.glsl rsInSet) -- and the light REMAP for the
// reservoirs (the list is re-sorted by importance every frame: last frame's index -> this frame's,
// by the light's key; 0xFF = gone).
void LLCleanRendererVK::rsLightSet(const LLVKWorldFrame& wf)
{
    U32 mode = 0, lightsMode = 1;
    bool attached = false;
#if defined(LL_HAS_CLEAN_PIPELINE)
    static LLCachedControl<U32>  s_mode(gSavedSettings, "RenderVKReSTIRDI", 0U);
    static LLCachedControl<U32>  s_lights(gSavedSettings, "RenderVKReSTIRLights", 1U);
    static LLCachedControl<bool> s_att(gSavedSettings, "RenderVKReSTIRAttachedLights", false);
    mode = s_mode; lightsMode = s_lights; attached = s_att;
#endif
    mRsMode = std::min<U32>(mode, 3u);
    mRsExt = lightsMode != 0u;
    mRsAttached = attached;
    std::memset(mRsSet, 0, sizeof(mRsSet));
    mRsSetN = mRsPointN = mRsExtProjN = 0;
    const size_t n = std::min<size_t>(mLightsCPU.size(), std::min<size_t>(wf.lights.size(), 256));
    for (size_t i = 0; i < n; ++i)
    {
        const VKLightGPU& g = mLightsCPU[i];
        if (!(g.pos_radius[3] > 0.f) || g.pos_radius[2] < -1.0e8f) continue;   // (an inert record)
        const bool proj = g.proj_origin[3] >= 0.5f;
        bool in = false;
        if (proj && g.tex[2] != 0u && g.tex[2] <= kMaxProjRecords && mProjShadowCPU[g.tex[2] - 1u].params[2] > 1.5f)
            in = true;   // a ray-traced record (projStochEligible)
        else if (mRsExt && proj) { in = true; ++mRsExtProjN; }
        else if (mRsExt && !proj && (wf.lights[i].proj_axis[1] < 0.5f || mRsAttached)) { in = true; ++mRsPointN; }
        if (!in) continue;
        mRsSet[i >> 5] |= 1u << (i & 31u);
        ++mRsSetN;
    }
    // REMAP (bounded: one key per light of the last frame)
    std::vector<std::pair<uint64_t, uint32_t>> cur;
    cur.reserve(n);
    for (size_t i = 0; i < n && i < 255; ++i)
        if (wf.lights[i].key != 0) cur.emplace_back(wf.lights[i].key, (uint32_t)i);
    std::sort(cur.begin(), cur.end());
    std::memset(mRsRemap, 0xFF, sizeof(mRsRemap));
    for (size_t p = 0; p < mRsPrevKeys.size() && p < 256; ++p)
    {
        const uint64_t k = mRsPrevKeys[p];
        if (k == 0) continue;
        const auto it = std::lower_bound(cur.begin(), cur.end(), std::make_pair(k, (uint32_t)0));
        if (it != cur.end() && it->first == k) mRsRemap[p] = (uint8_t)it->second;
    }
    mRsPrevKeys.clear();
    for (size_t i = 0; i < n; ++i) mRsPrevKeys.push_back(wf.lights[i].key);
}

// This recording builds population 1 (the light pass): the setting, a light set, the stochastic
// projector path able to run (ray-traced projector mode, a valid TLAS, the generic-core kernels:
// pass 15's ReSTIR code is theirs) and the grid's own pipeline / sets. Logs its settings on change.
bool LLCleanRendererVK::rsWanted()
{
    U32 stoch = 0;
#if defined(LL_HAS_CLEAN_PIPELINE)
    static LLCachedControl<U32> s_stoch(gSavedSettings, "RenderVKProjStochastic", 0U);
    stoch = s_stoch;
#endif
    // (Decided in the light pass, BEFORE this frame's TLAS build: tlasValid() is false there by
    // construction -- it wants this frame's slot -- so the decision takes last frame's build;
    // pass 15 itself only runs when this frame's TLAS is valid, pdnFrame.)
    const bool tlas = mRT && (mRT->tlasValid() || mRT->tlasBuiltLast());
    uint32_t why = 0u;
    if (stoch == 0u) why |= 1u;
    if (mOffscreen) why |= 2u;
    // (#91) with the emissive lights on, a scene without a light in the set still samples: its emitters
    // are found on the GPU (the records), the host cannot know whether there are any
    if (mRsSetN == 0u && !rsEmLightWanted()) why |= 4u;
    if (mProjMode != 2u) why |= 8u;
    if (!mRT) why |= 16u;
    else if (!tlas) why |= 32u;
    if (!mPdnSampleCorePipe || !mPdnMergeCorePipe) why |= 64u;
    if (!mRegirPipe || !mDsetRegir || !mDsetDefer) why |= 128u;
    const bool on = mRsMode != 0u && why == 0u;
    const uint32_t key[4] = {mRsMode | (stoch != 0u ? 8u : 0u), mRsExt ? 1u : 0u, mRsAttached ? 1u : 0u, why};
    if (mRsMode != 0u && (!mRsLogged || std::memcmp(key, mRsLogKey, sizeof(key)) != 0))
    {
        mRsLogged = true;
        std::memcpy(mRsLogKey, key, sizeof(key));
        static const char* const kMode[4] = {"off", "grid candidates (5a)", "+ temporal reuse (5b)",
                                             "+ temporal and spatial reuse (5c)"};
        LL_INFOS("VKShadow") << "ReSTIR DI (RenderVKReSTIRDI " << mRsMode << "): " << kMode[mRsMode] << "; light set = "
                             << (mRsExt ? "every projector + point light" : "ray-traced projector records only")
                             << (mRsExt ? (mRsAttached ? " (attached lights too)" : " (attached lights unshadowed)") : "")
                             << " (RenderVKReSTIRLights / _AttachedLights); ";
        if (on) LL_CONT << "ACTIVE (" << mRsSetN << " lights in the set, " << mRsPointN << " point)";
        else
        {
            LL_CONT << "waiting on:";
            if (why & 1u)   LL_CONT << " RenderVKProjStochastic is 0;";
            if (why & 2u)   LL_CONT << " an offscreen (snapshot) recording;";
            if (why & 4u)   LL_CONT << " no light in the set (no ray-traced projector record / point light in view);";
            if (why & 8u)   LL_CONT << " projector shadows are not ray traced this frame (mode " << mProjMode
                                    << "; RenderVKProjectorShadows 2 + RT up);";
            if (why & 16u)  LL_CONT << " no ray tracing;";
            if (why & 32u)  LL_CONT << " no TLAS built last frame;";
            if (why & 64u)  LL_CONT << " the generic-core pass-15 kernels still compiling;";
            if (why & 128u) LL_CONT << " the light grid's pipeline / sets missing;";
        }
        LL_CONT << LL_ENDL;
    }
    else if (mRsMode == 0u && mRsLogged)
    {
        mRsLogged = false;
        LL_INFOS("VKShadow") << "ReSTIR DI off (RenderVKReSTIRDI 0): pass 15 walks the cluster's projector records"
                             << LL_ENDL;
    }
    return on;
}

// The split kernels' combine (#978: also recordDeferTail's, after the GI early trace's join).
void LLCleanRendererVK::recordDeferCombine(VkCommandBuffer cmd, bool feat, uint32_t rw, uint32_t rh, bool onAsync)
{
    if (feat)
    {
        // Producers -> BASE (+ the tile list -> LOCAL's indirect read, two barriers on).
        VkMemoryBarrier2 m{VK_STRUCTURE_TYPE_MEMORY_BARRIER_2};
        m.srcStageMask=VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; m.srcAccessMask=VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
        m.dstStageMask=VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT | VK_PIPELINE_STAGE_2_DRAW_INDIRECT_BIT;
        m.dstAccessMask=VK_ACCESS_2_SHADER_STORAGE_READ_BIT | VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT
                       | VK_ACCESS_2_INDIRECT_COMMAND_READ_BIT;
        VkDependencyInfo mdep{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
        mdep.memoryBarrierCount=1; mdep.pMemoryBarriers=&m;
        vkCmdPipelineBarrier2(cmd,&mdep);
        vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, deferFeatPipe(DFP_BASE));
        vkCmdDispatch(cmd, (rw + 7) / 8, (rh + 7) / 8, 1);       // 8x8, every pixel
        gpuSubMark(cmd, onAsync ? "c_defer_base" : "g_defer_base");
        // BASE's HDR / glow / gain -> LOCAL's read-modify-write (same images, GENERAL).
        vkCmdPipelineBarrier2(cmd,&mdep);
        vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, deferFeatPipe(DFP_LOCAL));
        vkCmdDispatchIndirect(cmd, mDsTileList.buffer, 0);       // one 16x16 workgroup per listed tile
        gpuSubMark(cmd, onAsync ? "c_defer_local" : "g_defer_local");
    }
    else
    {
        VkMemoryBarrier2 m{VK_STRUCTURE_TYPE_MEMORY_BARRIER_2};
        m.srcStageMask=VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; m.srcAccessMask=VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
        m.dstStageMask=VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
        m.dstAccessMask=VK_ACCESS_2_SHADER_STORAGE_READ_BIT | VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
        VkDependencyInfo mdep{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
        mdep.memoryBarrierCount=1; mdep.pMemoryBarriers=&m;
        vkCmdPipelineBarrier2(cmd,&mdep);
        vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, deferSplitPipe(DSP_COMBINE));
        vkCmdDispatch(cmd, (rw + 15) / 16, (rh + 15) / 16, 1);   // one 16x16 tile per workgroup
    }
    recordLitGuardEnd(cmd);
    recordShaderClockEnd(cmd);
}

// In: the G-buffer SHADER_READ_ONLY, depth DEPTH_READ_ONLY, scene HDR + glow GENERAL (the
// caller's barriers). Writes every pixel of HDR + glow (no-surface pixels: black, no glow).
void LLCleanRendererVK::recordDeferredLighting(VkCommandBuffer& cmd, uint32_t rw, uint32_t rh, uint32_t viewIndex,
                                               const float viewProjRel[16],
                                               const std::function<void(VkCommandBuffer&)>* beforeCombine)
{
    VKDeferPush p{};
    p.view = viewIndex;
    p.flags = 0u;
    p.width = rw; p.height = rh;
    vkInvert4(viewProjRel, p.inv_vp_rel);
    // (#860) RT MIRROR: the hero mirror's image, before every kernel that taps it (its own layout,
    // sets and push: every path below binds its own after it).
    if (mRtMirrorNow) recordRtMirror(cmd, p, deferViewOffset(p.view));
    // LIGHT CULLING (RenderVKLightCulling, live):
    //   2 FROXEL MASKS: the light pass built this extent's froxel masks (clean_light_froxel.comp,
    //     mFroxelNow) -- DEFER_FLAG_LIGHT_FROXEL: the uber / combine read each pixel's cell, no
    //     tile test, no barrier, no extra dispatch here.
    //   1 LIGHT GRID: the tile masks from their own kernel (CLEAN_DEFER_PASS 6, the lit kernels'
    //     16x16 tile grid) -- DEFER_FLAG_LIGHT_GRID.
    //   0 (or the chosen path's pipeline / buffer missing): the in-kernel tile test.
    uint32_t culling = 2;
#if defined(LL_HAS_CLEAN_PIPELINE)
    static LLCachedControl<U32> s_culling(gSavedSettings, "RenderVKLightCulling", 0);
    culling = s_culling;
#endif
    const bool froxel = culling == 2 && mFroxelNow && mFroxelW == rw && mFroxelH == rh && mFroxel.buffer;
    const uint32_t tilesX = (rw + 15) / 16, tilesY = (rh + 15) / 16;
    const bool grid = culling == 1 && mLightGrid.buffer && mLightGridTiles == tilesX * tilesY
        && mLightGridPipe[mDeferSplitNow ? 1 : 0] != VK_NULL_HANDLE;
    constexpr uint32_t kDeferFlagLightGrid = 16u;     // clean_deferred_light.comp DEFER_FLAG_LIGHT_GRID
    constexpr uint32_t kDeferFlagLightFroxel = 32u;   // ... DEFER_FLAG_LIGHT_FROXEL
    constexpr uint32_t kDeferFlagLightStage = 64u;    // ... DEFER_FLAG_LIGHT_STAGE (#815)
    // LIGHT STAGING (#815, RenderVKLightStage, live): with a workgroup-uniform tile mask (culling
    // 0 / 1, not the per-pixel froxel cells) the uber / combine kernels copy each tile's lights'
    // point part (pos_radius, color_falloff, projector bit) into shared memory once and walk
    // that. Lossless (bit copies); 0 = every pixel loads them from the light buffer (A/B).
    bool lightStage = true;
#if defined(LL_HAS_CLEAN_PIPELINE)
    static LLCachedControl<bool> s_light_stage(gSavedSettings, "RenderVKLightStage", false);
    lightStage = s_light_stage;
#endif
    const uint32_t stageFlag = (lightStage && !froxel) ? kDeferFlagLightStage : 0u;
    // FEATURE SPLIT (#827, RenderVKDeferredFeatureSplit; deferSplitFrame: kernels + targets exist):
    // the split's combine replaced by TILE CLASSIFY (beside SHADOW / REFLECT) -> BASE -> LOCAL over
    // the listed tiles (clean_deferred_light.comp FEATURE SPLIT). The classification builds the
    // light grid itself (culling 0 / 1 alike: the grid test is lossless + bit-identical), so it needs
    // the grid buffer at this extent; froxel frames (culling 2) walk the cells as before.
    const bool feat = mDeferSplitNow && mDeferFeatNow && mLightGrid.buffer && mLightGridTiles == tilesX * tilesY
                   && mDsFeatFull && mDsW == rw && mDsH == rh;
    if (feat)
    {
        // Pass timers: the queue's prefix (the lighting may run on the async compute queue).
        const bool onAsync = mAsyncAvail && vkAsyncIsAsyncCmd(cmd);
        p.flags = mDeferSplitFlags | (froxel ? kDeferFlagLightFroxel : kDeferFlagLightGrid) | stageFlag;
        // The intermediates (+ the gain) start UNDEFINED every frame, as in the plain split below.
        constexpr uint32_t nIb = DS_ALIASED + 2u;   // mDsImg, mDsVisProj, mDsGain
        VkImageMemoryBarrier2 ib[nIb]{};
        for (uint32_t k = 0; k < nIb; ++k)
        {
            const bool own = k >= DS_ALIASED;   // (dedicated images: never on the alias arena)
            ib[k].sType=VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER_2;
            ib[k].srcStageMask=VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
            if (mDsAliased && !own)
            {
                ib[k].srcStageMask=kAliasSrcStages;
                ib[k].srcAccessMask=VK_ACCESS_2_COLOR_ATTACHMENT_WRITE_BIT | VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
            }
            ib[k].dstStageMask=VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
            ib[k].dstAccessMask=VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
            ib[k].oldLayout=VK_IMAGE_LAYOUT_UNDEFINED; ib[k].newLayout=VK_IMAGE_LAYOUT_GENERAL;
            ib[k].image=k == DS_ALIASED ? mDsVisProj.image : (k == DS_ALIASED + 1u ? mDsGain.image : mDsImg[k].image);
            ib[k].subresourceRange={VK_IMAGE_ASPECT_COLOR_BIT,0,1,0,VK_REMAINING_ARRAY_LAYERS};
        }
        // The tile list's header is rewritten below: after the previous frame's LOCAL read it as
        // its indirect arguments and its CLASSIFY appended to it (WAR: an execution dependency).
        VkMemoryBarrier2 tw{VK_STRUCTURE_TYPE_MEMORY_BARRIER_2};
        tw.srcStageMask=VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT | VK_PIPELINE_STAGE_2_DRAW_INDIRECT_BIT;
        tw.dstStageMask=VK_PIPELINE_STAGE_2_ALL_TRANSFER_BIT; tw.dstAccessMask=VK_ACCESS_2_TRANSFER_WRITE_BIT;
        VkDependencyInfo idep{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
        idep.memoryBarrierCount=1; idep.pMemoryBarriers=&tw;
        idep.imageMemoryBarrierCount=nIb; idep.pImageMemoryBarriers=ib;
        vkCmdPipelineBarrier2(cmd,&idep);
        // Header = VkDispatchIndirectCommand (0, 1, 1) + pad: CLASSIFY counts x up (compute-queue
        // legal, as the lit guards' fills; no graphics-only command anywhere in this segment).
        const uint32_t hdr[4] = {0u, 1u, 1u, 0u};
        vkCmdUpdateBuffer(cmd, mDsTileList.buffer, 0, sizeof(hdr), hdr);
        VkMemoryBarrier2 tr{VK_STRUCTURE_TYPE_MEMORY_BARRIER_2};
        tr.srcStageMask=VK_PIPELINE_STAGE_2_ALL_TRANSFER_BIT; tr.srcAccessMask=VK_ACCESS_2_TRANSFER_WRITE_BIT;
        tr.dstStageMask=VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
        tr.dstAccessMask=VK_ACCESS_2_SHADER_STORAGE_READ_BIT | VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
        VkDependencyInfo tdep{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
        tdep.memoryBarrierCount=1; tdep.pMemoryBarriers=&tr;
        vkCmdPipelineBarrier2(cmd,&tdep);
        const VkDescriptorSet sets[4] = {mDsetDraw0, mDsetDraw1, mDsetDefer, mDsetDeferSplit};
        const uint32_t viewOff = deferViewOffset(p.view);   // set 2 b10: the main view's entry (#814)
        vkCmdBindDescriptorSets(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mDeferSplitLayout, 0, 4, sets, 1, &viewOff);
        VK_PUSH_BUDGET_CHECK(p);
        vkCmdPushConstants(cmd, mDeferSplitLayout, VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(p), &p);
        recordLitGuardBegin(cmd);      // (transfer only: the binds / push above stay bound)
        recordShaderClockBegin(cmd);   // (RenderVKShaderClockLighting; transfer only too)
        recordRtMarkInit(cmd);         // (#859: the RT reflection mark -> GENERAL, contents discarded)
        // (#831) The barriers + header fill above, timed apart: the first dispatch's mark no longer
        // absorbs their drain.
        gpuSubMark(cmd, onAsync ? "c_defer_prep" : "g_defer_prep");
        // LIT-GUARD CLUSTER SCAN (#831): its own small dispatch of the CLASSIFY kernel
        // (DEFER_FLAG_SCAN_ONLY: the scan alone, no tile build / grid / list write) on every
        // kLgScanEvery-th guarded frame -- instead of inside every tile build of every frame.
        // readLitGuardStats scales the scan words by the frames that scanned (mLgScanNow).
        constexpr uint32_t kDeferFlagScanOnly = 128u;   // clean_deferred_light.comp DEFER_FLAG_SCAN_ONLY
        constexpr uint32_t kScanGroups = 256u;          // (lgClusterScan strides the ~3.5k clusters over them)
        mLgScanNow = mLgActive && (mLgFrame % kLgScanEvery) == 0u;
        if (mLgScanNow)
        {
            VKDeferPush ps = p;
            ps.flags |= kDeferFlagScanOnly;
            vkCmdPushConstants(cmd, mDeferSplitLayout, VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(ps), &ps);
            vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, deferFeatPipe(DFP_CLASSIFY));
            vkCmdDispatch(cmd, kScanGroups, 1, 1);
            vkCmdPushConstants(cmd, mDeferSplitLayout, VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(p), &p);
        }
        // CLASSIFY FOLDED INTO SHADOW (#831, RenderVKDeferClassifyFused, live): SHADOW_CLS runs the
        // tile classification (the same gridTileBuild: identical grid words / tile list) as the
        // prologue of the shadow resolve, one 16 px tile per workgroup -- the separate full-screen
        // CLASSIFY pass (its own G2 + depth fetch + position per pixel) is gone. Off, or the kernel
        // missing: CLASSIFY beside SHADOW as #827 recorded it. Both pipelines exist from init (and
        // per spec set): the toggle only changes which ones this recording binds (#809).
        bool fused = true;
#if defined(LL_HAS_CLEAN_PIPELINE)
        static LLCachedControl<bool> s_cls_fused(gSavedSettings, "RenderVKDeferClassifyFused", true);
        fused = s_cls_fused;
#endif
        // (#823) Nothing casts (mDeferShadowSkip): no SHADOW pass -- the classification alone.
        const VkPipeline shadowCls = (fused && !mDeferShadowSkip) ? deferFeatPipe(DFP_SHADOW_CLS) : VK_NULL_HANDLE;
        // (#195 + #85) MERGED RT SHADOWS: the merged pass + the denoiser FIRST -- the SHADOW kernel
        // below reads the denoised sun / moon (re-binds the split layout's sets + push after itself).
        if (mShadowMergeNow) recordShadowMergeFirst(cmd, p, viewOff, onAsync);
        if (shadowCls != VK_NULL_HANDLE)
        {
            vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, shadowCls);
            vkCmdDispatch(cmd, tilesX, tilesY, 1);                // one 16 px tile per workgroup
            gpuSubMark(cmd, onAsync ? "c_defer_shadow_cls" : "g_defer_shadow_cls");
        }
        else
        {
            // TILE CLASSIFY first (the grid masks / froxel verdicts + the tile list): independent of
            // SHADOW / REFLECT, which overlap it.
            vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, deferFeatPipe(DFP_CLASSIFY));
            vkCmdDispatch(cmd, tilesX, tilesY, 1);                // one 16 px tile per workgroup
            gpuSubMark(cmd, onAsync ? "c_defer_classify" : "g_defer_classify");
            if (!mDeferShadowSkip)
            {
                vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, deferSplitPipe(DSP_SHADOW));
                vkCmdDispatch(cmd, (rw + 7) / 8, (rh + 7) / 8, 1);   // 8x8
            }
            gpuSubMark(cmd, onAsync ? "c_defer_shadow" : "g_defer_shadow");   // (#823: ~0 when skipped)
        }
        if (mDsReflHalf)
        {
            const uint32_t hw = (rw + 1) / 2, hh = (rh + 1) / 2;
            vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, deferSplitPipe(DSP_REFLECT_HALF));
            vkCmdDispatch(cmd, (hw + 7) / 8, (hh + 7) / 8, 1);   // 8x8 blocks
            vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, deferSplitPipe(DSP_REFLECT_SHARP));
            vkCmdDispatch(cmd, (rw + 7) / 8, (rh + 7) / 8, 1);   // 8x8 (soft pixels leave at once)
        }
        else
        {
            vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, deferSplitPipe(DSP_REFLECT));
            vkCmdDispatch(cmd, (rw + 7) / 8, (rh + 7) / 8, 1);   // 8x8
        }
        // (the timestamps land as each pass's predecessors finish: the three overlap, so shadow /
        // refl are completion points, not exclusive costs)
        gpuSubMark(cmd, onAsync ? "c_defer_refl" : "g_defer_refl");
        // (#859) Hybrid RT reflections: the SSR-miss smooth pixels' rays, spliced into the words
        // BASE reads (re-binds the split layout's sets + push after itself).
        recordRtReflect(cmd, p, viewOff, onAsync);
        // (#85 phase 2) the projector stochastic sampler + the diffuse / specular denoiser: LOCAL
        // remodulates its result (re-binds the split layout's sets + push after itself).
        // (Merged RT shadows: it already ran, before SHADOW.)
        if (!mShadowMergeNow) recordProjStoch(cmd, p, viewOff, onAsync);
        // (#87: the GI trace + its denoiser; BASE reads the result. #978 phase 2, GI_F_LAG: BASE reads LAST
        //  frame's -- this frame's trace follows the combine: giLagRecord after the stash, else below.)
        if (!mGiLagNow) recordGI(cmd, p, viewOff, onAsync);
        // (#978 GI EARLY TRACE) the async chain ends here: BASE + LOCAL stashed for pass 1b, on
        // graphics after a join up to this segment (recordDeferTail; no beforeCombine on an async chain).
        if (deferStashCombine(true, p, viewOff, rw, rh)) return;
        // The async AO's join (as the plain split's): BASE is the AO reader.
        if (beforeCombine && *beforeCombine)
        {
            (*beforeCombine)(cmd);
            vkCmdBindDescriptorSets(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mDeferSplitLayout, 0, 4, sets, 1, &viewOff);
            vkCmdPushConstants(cmd, mDeferSplitLayout, VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(p), &p);
        }
        recordDeferCombine(cmd, true, rw, rh, onAsync);
        // (#978 phase 2, GI_F_LAG, the chain not stashed: the trace right after the combine, same queue --
        //  recordGI's leading barrier orders it after BASE / LOCAL's reads of the GI images / state)
        if (mGiLagNow) recordGI(cmd, p, viewOff, mAsyncAvail && vkAsyncIsAsyncCmd(cmd));
        return;
    }
    if (mDeferSplitNow)
    {
        // SPLIT (deferSplitFrame: pipelines + intermediates exist): shadow resolve
        // and reflection resolve (independent: no barrier between them) -> the combine.
        // The intermediates start UNDEFINED every frame (contents discarded; the previous
        // frame's combine read them -- an execution dependency on that compute is enough;
        // #615 aliased: the memory was last the bloom pyramid / cross filter's, as the
        // G-buffer's in beginGbuffer. A compute-only segment's sanitizer drops the
        // graphics stages, whose producers ran before the fork).
        p.flags = mDeferSplitFlags | (grid ? kDeferFlagLightGrid : 0u) | (froxel ? kDeferFlagLightFroxel : 0u) | stageFlag;
        constexpr uint32_t nIb = DS_ALIASED + 1u;
        VkImageMemoryBarrier2 ib[nIb]{};
        for (uint32_t k = 0; k < nIb; ++k)
        {
            const bool proj = k == DS_ALIASED;
            ib[k].sType=VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER_2;
            ib[k].srcStageMask=VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
            if (mDsAliased && !proj)
            {
                ib[k].srcStageMask=kAliasSrcStages;
                ib[k].srcAccessMask=VK_ACCESS_2_COLOR_ATTACHMENT_WRITE_BIT | VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
            }
            ib[k].dstStageMask=VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
            ib[k].dstAccessMask=VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
            ib[k].oldLayout=VK_IMAGE_LAYOUT_UNDEFINED; ib[k].newLayout=VK_IMAGE_LAYOUT_GENERAL;
            ib[k].image=proj ? mDsVisProj.image : mDsImg[k].image;
            ib[k].subresourceRange={VK_IMAGE_ASPECT_COLOR_BIT,0,1,0,VK_REMAINING_ARRAY_LAYERS};
        }
        VkDependencyInfo idep{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
        idep.imageMemoryBarrierCount=nIb; idep.pImageMemoryBarriers=ib;
        vkCmdPipelineBarrier2(cmd,&idep);
        const VkDescriptorSet sets[4] = {mDsetDraw0, mDsetDraw1, mDsetDefer, mDsetDeferSplit};
        const uint32_t viewOff = deferViewOffset(p.view);   // set 2 b10: the main view's entry (#814)
        vkCmdBindDescriptorSets(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mDeferSplitLayout, 0, 4, sets, 1, &viewOff);
        VK_PUSH_BUDGET_CHECK(p);
        vkCmdPushConstants(cmd, mDeferSplitLayout, VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(p), &p);
        recordLitGuardBegin(cmd);   // (transfer only: the binds / push above stay bound)
        recordShaderClockBegin(cmd);   // (RenderVKShaderClockLighting; transfer only too)
        recordRtMarkInit(cmd);         // (#859: the RT reflection mark -> GENERAL, contents discarded)
        // (#195 + #85) MERGED RT SHADOWS: the merged pass + the denoiser before SHADOW (above).
        if (mShadowMergeNow) recordShadowMergeFirst(cmd, p, viewOff, mAsyncAvail && vkAsyncIsAsyncCmd(cmd));
        if (grid)
        {
            // The light grid first: independent of SHADOW / REFLECT (it writes only the grid +
            // the lit-guard words), so they overlap it; the barrier before COMBINE covers it.
            vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mLightGridPipe[1]);
            vkCmdDispatch(cmd, tilesX, tilesY, 1);   // one 16x16 tile per workgroup
        }
        if (!mDeferShadowSkip)   // (#823: nothing casts -- the combine takes the cloud layer itself)
        {
            vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, deferSplitPipe(DSP_SHADOW));
            vkCmdDispatch(cmd, (rw + 7) / 8, (rh + 7) / 8, 1);       // 8x8
        }
        if (mDsReflHalf)
        {
            // Half-resolution reflections: one invocation per 2 x 2 block, then the sharp
            // pixels at full resolution (independent of each other and of the shadow pass).
            const uint32_t hw = (rw + 1) / 2, hh = (rh + 1) / 2;
            vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, deferSplitPipe(DSP_REFLECT_HALF));
            vkCmdDispatch(cmd, (hw + 7) / 8, (hh + 7) / 8, 1);   // 8x8 blocks
            vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, deferSplitPipe(DSP_REFLECT_SHARP));
            vkCmdDispatch(cmd, (rw + 7) / 8, (rh + 7) / 8, 1);   // 8x8 (soft pixels leave at once)
        }
        else
        {
            vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, deferSplitPipe(DSP_REFLECT));
            vkCmdDispatch(cmd, (rw + 7) / 8, (rh + 7) / 8, 1);   // 8x8
        }
        // (#859) Hybrid RT reflections between REFLECT and COMBINE (re-binds the split layout after).
        recordRtReflect(cmd, p, viewOff, mAsyncAvail && vkAsyncIsAsyncCmd(cmd));
        // (#85 phase 2) the projector stochastic sampler + denoiser: the combine remodulates it.
        // (Merged RT shadows: it already ran, before SHADOW.)
        if (!mShadowMergeNow) recordProjStoch(cmd, p, viewOff, mAsyncAvail && vkAsyncIsAsyncCmd(cmd));
        // (#87: the combine reads it. #978 phase 2, GI_F_LAG: last frame's -- as the feature split above)
        if (!mGiLagNow) recordGI(cmd, p, viewOff, mAsyncAvail && vkAsyncIsAsyncCmd(cmd));
        // (#978 GI EARLY TRACE: as the feature split above -- COMBINE stashed)
        if (deferStashCombine(false, p, viewOff, rw, rh)) return;
        // The async AO's join (aoPost + RenderVKAOAsync): only COMBINE reads AO, so the shadow /
        // reflection resolves above overlapped it. The join continues in a new graphics command
        // buffer: re-bind the sets + push (the pipeline is bound below).
        if (beforeCombine && *beforeCombine)
        {
            gpuSubMark(cmd, "g_defer_sr");   // shadow + reflection resolves (the AO overlap window)
            (*beforeCombine)(cmd);
            vkCmdBindDescriptorSets(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mDeferSplitLayout, 0, 4, sets, 1, &viewOff);
            vkCmdPushConstants(cmd, mDeferSplitLayout, VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(p), &p);
        }
        recordDeferCombine(cmd, false, rw, rh, mAsyncAvail && vkAsyncIsAsyncCmd(cmd));
        if (mGiLagNow) recordGI(cmd, p, viewOff, mAsyncAvail && vkAsyncIsAsyncCmd(cmd));   // (#978 phase 2: as above)
        return;
    }
    // (debug twin while a RenderVKLitDebugMask cost switch is set: mDeferDbgNow)
    const VkPipeline litPipe = (mDeferDbgNow && mDeferPipeDbg) ? mDeferPipeDbg : deferPipe();
    // (#859) RT PRE-TRACE for the uber kernel: its own layout and dispatch first (the uber binds
    // its sets / push after it), then DEFER_FLAG_RT_IN. (+ a stale forward-reflection target
    // cleared: the forward FS reads it on uber frames too.)
    recordRtMarkInit(cmd);
    if (mRtUberNow)
    {
        recordRtPreTrace(cmd, p, deferViewOffset(p.view));
        p.flags |= (1u << 17);   // (clean_deferred_light.comp DEFER_FLAG_RT_IN)
    }
    if (grid) p.flags |= kDeferFlagLightGrid;
    if (froxel) p.flags |= kDeferFlagLightFroxel;
    p.flags |= stageFlag;   // (#815; the grid build ignores it)
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, grid ? mLightGridPipe[0] : litPipe);
    const VkDescriptorSet sets[3] = {mDsetDraw0, mDsetDraw1, mDsetDefer};
    const uint32_t viewOff = deferViewOffset(p.view);   // set 2 b10: the main view's entry (#814)
    vkCmdBindDescriptorSets(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mDeferLayout, 0, 3, sets, 1, &viewOff);
    VK_PUSH_BUDGET_CHECK(p);
    vkCmdPushConstants(cmd, mDeferLayout, VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(p), &p);
    recordLitGuardBegin(cmd);   // (transfer only: the compute bind / push above stay bound)
    recordShaderClockBegin(cmd);
    if (grid)
    {
        // The light grid, then the uber kernel behind one barrier (grid writes -> its reads).
        vkCmdDispatch(cmd, tilesX, tilesY, 1);   // one 16x16 tile per workgroup
        gpuSubMark(cmd, "g_light_grid");
        VkMemoryBarrier2 m{VK_STRUCTURE_TYPE_MEMORY_BARRIER_2};
        m.srcStageMask=VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; m.srcAccessMask=VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
        m.dstStageMask=VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
        m.dstAccessMask=VK_ACCESS_2_SHADER_STORAGE_READ_BIT | VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
        VkDependencyInfo mdep{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
        mdep.memoryBarrierCount=1; mdep.pMemoryBarriers=&m;
        vkCmdPipelineBarrier2(cmd,&mdep);
        vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, litPipe);
    }
    vkCmdDispatch(cmd, tilesX, tilesY, 1);   // one 16x16 tile per workgroup
    recordLitGuardEnd(cmd);
    recordShaderClockEnd(cmd);
}

// ---- LIT GUARDS (clean_draw_common.glsl lgFinite; clean_deferred_light.comp lgClusterScan) ----
// Words [kLgFirstWord, + kLgWords) of mOdCounter, as the deferred compute writes them:
//   0 local-light term non-finite / out of range, 1 probe blend, 2 SSR hit, 3 final colour,
//   4 / 5 (unused: list-index trips are per-pixel flags only), 6 light clusters over
//   CLUSTER_CAP, 7 max light candidates in one cluster, 8 clusters whose SHADOWED
//   projectors alone overflowed the cap, 9 light list entries past the light count,
//   10 probe clusters over PROBE_CLUSTER_CAP, 11 max probe candidates, 12 probe list
//   entries past the probe count; 13.. the PROBE TEXEL GUARD (kLgPt*, clean_draw_common.glsl
//   lgProbeTexel): bad texels per store, value range, bad lookup inputs, a sample, the
//   bad slots -- litGuardProbeHeal logs them and heals the slots; kLgRt.. (#1049) the RT
//   reflection hang guard (clean_deferred_light.comp rtrStatsGuard): rays the per-ray query
//   budget cut, rays rtRaySane refused, walks over the candidate budget.
// The deferred segment may run on the async queue (resources are CONCURRENT then); the
// readback ring is read 3 frames later, after the frame fences that cover it.
void LLCleanRendererVK::recordLitGuardBegin(VkCommandBuffer cmd)
{
    // Main view only: offscreen renders (snapshots) would turn the ring faster than the
    // 3-frame latency it relies on. Their trips just aren't counted.
    mLgActive = false;
    mLgScanNow = true;   // (#831: every path scans every frame but the feature split, which overrides)
    if (mOffscreen || !mOdCounter.buffer || mOdCounter.size < kOdCounterBytes) return;
    readLitGuardStats();   // harvest this ring slot (3 frames old) before reusing it
    const uint32_t slot = (uint32_t)(mLgFrame % 3u);
    if (!mLgRb[slot].buffer)
    {
        VkMemScope memcat(VKMEM_READBACK);
        mLgRb[slot] = mCtx->createBuffer(kLgWords * sizeof(uint32_t), VK_BUFFER_USAGE_TRANSFER_DST_BIT,
                                         VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT |
                                         VK_MEMORY_PROPERTY_HOST_CACHED_BIT);
        if (mLgRb[slot].mapped) std::memset(mLgRb[slot].mapped, 0, kLgWords * sizeof(uint32_t));
    }
    // WAR: an earlier frame's guard atomics + readback copy -> this zero fill.
    VkBufferMemoryBarrier2 b{VK_STRUCTURE_TYPE_BUFFER_MEMORY_BARRIER_2};
    b.srcStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT | VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT
                   | VK_PIPELINE_STAGE_2_COPY_BIT;
    b.srcAccessMask = VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    b.dstStageMask = VK_PIPELINE_STAGE_2_CLEAR_BIT;
    b.dstAccessMask = VK_ACCESS_2_TRANSFER_WRITE_BIT;
    b.buffer = mOdCounter.buffer; b.offset = kLgFirstWord * sizeof(uint32_t); b.size = kLgWords * sizeof(uint32_t);
    VkDependencyInfo d{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
    d.bufferMemoryBarrierCount = 1; d.pBufferMemoryBarriers = &b;
    vkCmdPipelineBarrier2(cmd, &d);
    vkCmdFillBuffer(cmd, mOdCounter.buffer, kLgFirstWord * sizeof(uint32_t), kLgWords * sizeof(uint32_t), 0u);
    b.srcStageMask = VK_PIPELINE_STAGE_2_CLEAR_BIT; b.srcAccessMask = VK_ACCESS_2_TRANSFER_WRITE_BIT;
    b.dstStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
    b.dstAccessMask = VK_ACCESS_2_SHADER_STORAGE_READ_BIT | VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    vkCmdPipelineBarrier2(cmd, &d);
    mLgActive = true;
}

void LLCleanRendererVK::recordLitGuardEnd(VkCommandBuffer cmd)
{
    if (!mLgActive) return;
    mLgActive = false;
    const uint32_t slot = (uint32_t)(mLgFrame % 3u);
    if (!mLgRb[slot].buffer || !mLgRb[slot].mapped) return;
    VkBufferMemoryBarrier2 b{VK_STRUCTURE_TYPE_BUFFER_MEMORY_BARRIER_2};
    b.srcStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; b.srcAccessMask = VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    b.dstStageMask = VK_PIPELINE_STAGE_2_COPY_BIT; b.dstAccessMask = VK_ACCESS_2_TRANSFER_READ_BIT;
    b.buffer = mOdCounter.buffer; b.offset = kLgFirstWord * sizeof(uint32_t); b.size = kLgWords * sizeof(uint32_t);
    VkDependencyInfo d{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
    d.bufferMemoryBarrierCount = 1; d.pBufferMemoryBarriers = &b;
    vkCmdPipelineBarrier2(cmd, &d);
    const VkBufferCopy cp{kLgFirstWord * sizeof(uint32_t), 0, kLgWords * sizeof(uint32_t)};
    vkCmdCopyBuffer(cmd, mOdCounter.buffer, mLgRb[slot].buffer, 1, &cp);
    // While probe texels trip: the GPU slot table beside the counters (same frame), so the
    // log can name what each bad slot holds. RANK_D's writes (this frame) -> the copy; the
    // copy -> the next frame's slot writes (WAR, execution only).
    const double now = std::chrono::duration<double>(std::chrono::steady_clock::now().time_since_epoch()).count();
    mLgSlotRbValid[slot] = false;
    const VkDeviceSize slotBytes = (VkDeviceSize)kPrbSlotCap * kPrbSlotBytes;
    if (now < mLgSlotsUntil && mPrbActive && mPrbSlots.buffer)
    {
        if (!mLgSlotRb[slot].buffer)
        {
            VkMemScope memcat(VKMEM_READBACK);
            mLgSlotRb[slot] = mCtx->createBuffer(slotBytes, VK_BUFFER_USAGE_TRANSFER_DST_BIT,
                                                 VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT |
                                                 VK_MEMORY_PROPERTY_HOST_CACHED_BIT);
        }
        if (mLgSlotRb[slot].buffer && mLgSlotRb[slot].mapped)
        {
            VkBufferMemoryBarrier2 s{VK_STRUCTURE_TYPE_BUFFER_MEMORY_BARRIER_2};
            s.srcStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; s.srcAccessMask = VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
            s.dstStageMask = VK_PIPELINE_STAGE_2_COPY_BIT; s.dstAccessMask = VK_ACCESS_2_TRANSFER_READ_BIT;
            s.buffer = mPrbSlots.buffer; s.offset = 0; s.size = slotBytes;
            d.pBufferMemoryBarriers = &s;
            vkCmdPipelineBarrier2(cmd, &d);
            const VkBufferCopy sc{0, 0, slotBytes};
            vkCmdCopyBuffer(cmd, mPrbSlots.buffer, mLgSlotRb[slot].buffer, 1, &sc);
            s.srcStageMask = VK_PIPELINE_STAGE_2_COPY_BIT; s.srcAccessMask = 0;
            s.dstStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; s.dstAccessMask = 0;
            vkCmdPipelineBarrier2(cmd, &d);
            mLgSlotRbValid[slot] = true;
        }
    }
    VkBufferMemoryBarrier2 h[2]{};
    for (VkBufferMemoryBarrier2& x : h)
    {
        x.sType = VK_STRUCTURE_TYPE_BUFFER_MEMORY_BARRIER_2;
        x.srcStageMask = VK_PIPELINE_STAGE_2_COPY_BIT; x.srcAccessMask = VK_ACCESS_2_TRANSFER_WRITE_BIT;
        x.dstStageMask = VK_PIPELINE_STAGE_2_HOST_BIT; x.dstAccessMask = VK_ACCESS_2_HOST_READ_BIT;
        x.offset = 0; x.size = VK_WHOLE_SIZE;
    }
    h[0].buffer = mLgRb[slot].buffer;
    h[1].buffer = mLgSlotRb[slot].buffer;
    d.bufferMemoryBarrierCount = mLgSlotRbValid[slot] ? 2u : 1u;
    d.pBufferMemoryBarriers = h;
    vkCmdPipelineBarrier2(cmd, &d);
    mLgRbValid[slot] = true;
    mLgRbFrame[slot] = mLgFrame;
    mLgRbScan[slot] = mLgScanNow;   // (#831: did this frame's dispatches run the cluster scan)
    ++mLgFrame;
}

// ---- PROBE TEXEL GUARD: what a cube slot holds (the harvested slot-table snapshot) ----
// "slot 12 automatic, BC6H, complete, captured 3.2 s ago (first 41 s ago), flags RTU CDIRTY,
// key 0x..." -- or just the slot number when no snapshot came back.
std::string LLCleanRendererVK::litGuardSlotText(uint32_t s) const
{
    std::ostringstream os;
    os << "slot " << s;
    if (mLgSlotSnap.size() < (size_t)kPrbSlotCap * kPrbSlotBytes || s >= kPrbSlotCap) return os.str();
    struct SlotRec { uint32_t a[4]; int32_t cell[4]; float pos[4]; float t[4]; };   // clean_probe_gpu.comp PrbSlot
    static_assert(sizeof(SlotRec) == kPrbSlotBytes, "SlotRec = PrbSlot");
    SlotRec r;
    std::memcpy(&r, mLgSlotSnap.data() + (size_t)s * kPrbSlotBytes, sizeof(r));
    if (r.a[0] == 0u) { os << " (free now)"; return os.str(); }
    const uint32_t c = r.a[0] - 1u;
    const char* cls = s == 0u ? "default" : c < kPrbCandMan ? "default?" : c < kPrbCandGrid ? "manual"
                    : c < kPrbCandAuto ? "terrain-grid" : "automatic";
    const uint32_t f = r.a[3];
    const char* store = (mProbeFmt == 3 && s == 0u) ? "live cube 0 (RGBA16F)"
                      : (mProbeFmt == 3 && (f & 4u)) ? "live cube 1 (realtime RGBA16F) over BC6H"
                      : probeFmtDesc(mProbeFmt).name;
    const double tnow = std::chrono::duration<double>(std::chrono::steady_clock::now().time_since_epoch()).count()
                      - mPrbClock0;
    os << std::fixed;
    os.precision(1);
    os << " " << cls << ", " << store << ", " << ((f & 1u) ? "complete" : "INCOMPLETE");
    if (r.t[0] > -1e8f) os << ", captured " << (tnow - r.t[0]) << " s ago";
    else os << ", never captured";
    if (r.t[1] > -1e8f) os << " (first " << (tnow - r.t[1]) << " s ago)";
    if (r.t[2] > -1e8f) os << ", realtime " << (tnow - r.t[2]) << " s ago";
    os << ", radius " << r.pos[3] << " m, flags";
    static const char* const kSf[8] = {"COMPLETE", "STALE", "RTU", "CDIRTY", "EDIRTY", "EURGENT", "RTDIRTY", "DYNWAS"};
    for (uint32_t b = 0; b < 8; ++b) if (f & (1u << b)) os << " " << kSf[b];
    os << std::hex << ", key 0x" << r.a[2] << "_" << r.a[1] << std::dec;
    return os.str();
}

// ---- PROBE TEXEL GUARD -> SELF-HEAL (one harvested frame's words, w[kLgWords]) ----
void LLCleanRendererVK::litGuardProbeHeal(const uint32_t* w, uint64_t frame, double now)
{
    const uint32_t persist = w[kLgPt + 0] + w[kLgPt + 1] + w[kLgPt + 3];   // store, live 0, irradiance
    const uint32_t live1 = w[kLgPt + 2];
    if (persist == 0u && live1 == 0u) return;
    mLgSlotsUntil = now + 2.0;   // keep the slot-table snapshots coming while texels trip
    if (mLgHeal.size() != kPrbSlotCap) mLgHeal.assign(kPrbSlotCap, LgHeal{});
    float vmax = 0.f, vmin = 0.f;
    {
        const uint32_t mn = ~w[kLgPtMinInv];
        std::memcpy(&vmax, &w[kLgPtMax], 4);
        std::memcpy(&vmin, &mn, 4);
    }
    const uint32_t nonFinite = w[kLgPtNonFinite];
    // Filtered texels are <= 64512 (clean_probe_filter.comp), exact in RGBA16F / RGB9E5 /
    // R11G11B10 / the live cubes / irradiance: there, ANY texel over the guard is bad. Only
    // BC6H endpoint quantization can lift a clamp-level texel past it (<= 65504): finite
    // store-only trips in format 3 within that band are bright-but-legit data -- reported,
    // never healed. (Every finite trip is > 65000 and no store exceeds 65504: the band test
    // alone would excuse ALL finite trips, i.e. everything in RGB9E5.)
    const bool clampLevel = mProbeFmt == 3 && nonFinite == 0u && w[kLgPt + 1] == 0u && w[kLgPt + 3] == 0u
                         && w[kLgPtMinInv] != 0u && vmin >= 64512.f && vmax <= 65504.f;
    const uint32_t smp = w[kLgPtSample];
    std::ostringstream ctx;
    ctx << std::fixed;
    ctx.precision(0);
    ctx << "store " << w[kLgPt + 0] << " live0 " << w[kLgPt + 1] << " live1 " << w[kLgPt + 2] << " irr " << w[kLgPt + 3]
        << " px (non-finite " << nonFinite << "; finite bad values " << vmin << " .. " << vmax << "), bad inputs "
        << w[kLgPtBadIn];
    if (smp & 1u)
    {
        static const char* const kStore[4] = {"store", "live0", "live1", "irr"};
        static const char* const kCls[4] = {"default", "manual", "terrain-grid", "automatic"};
        ctx << "; sample: slot " << ((smp >> 1) & 255u) << " " << kStore[(smp >> 9) & 3u] << " class "
            << kCls[(smp >> 11) & 3u] << " lod " << ((smp >> 13) & 15u) << ((smp & (1u << 17)) ? " NON-FINITE" : "")
            << ((smp & (1u << 18)) ? " fading-in" : "") << ((smp & (1u << 20)) ? " box" : "");
    }
    // Live cube 1 is rewritten by every realtime capture: nothing persistent to heal. Bad
    // texels there come straight from this frame's capture -> filter path (loud, 10 s).
    if (live1 != 0u)
    {
        static double s_next = 0.0;
        if (now >= s_next)
        {
            s_next = now + 10.0;
            const uint32_t rs = w[kLgPtLive1];
            LL_WARNS("VKLitGuard") << "VK lit guard: REALTIME live cube 1 has bad texels ("
                                   << (rs ? litGuardSlotText(rs - 1u) : std::string("slot ?")) << "): the capture -> "
                                   << "filter path wrote them in the last frame (not healed: rewritten every frame); "
                                   << ctx.str() << LL_ENDL;
        }
    }
    if (persist == 0u) return;
    if (clampLevel)
    {
        static double s_next = 0.0;
        if (now >= s_next)
        {
            s_next = now + 30.0;
            LL_INFOS("VKLitGuard") << "VK lit guard: probe texels just over the guard are clamp-level bright data "
                                   << "(not healed): " << ctx.str() << LL_ENDL;
        }
        return;
    }
    // The probe key a slot holds in the harvested snapshot (false: no snapshot / free).
    auto snapKey = [&](uint32_t s, uint32_t k[2]) -> bool
    {
        if (mLgSlotSnap.size() < (size_t)kPrbSlotCap * kPrbSlotBytes) return false;
        uint32_t a[4];
        std::memcpy(a, mLgSlotSnap.data() + (size_t)s * kPrbSlotBytes, sizeof(a));
        k[0] = a[1]; k[1] = a[2];
        return a[0] != 0u;
    };
    // Per-slot sighting / heal lines: at most 6 per 10 s in all (the 10 s summary lists
    // every bad slot and the heal count anyway). RE-CORRUPTED lines are never throttled.
    auto logBudget = [&]() -> bool
    {
        static double s_win = 0.0;
        static uint32_t s_n = 0;
        if (now >= s_win) { s_win = now + 10.0; s_n = 0; }
        return s_n++ < 6u;
    };
    // Every slot with a bad persistent texel this frame.
    for (uint32_t s = 0; s < kPrbSlotCap; ++s)
    {
        if (!(w[kLgPtSlots + (s >> 5)] & (1u << (s & 31u)))) continue;
        LgHeal& h = mLgHeal[s];
        if (h.pending || (h.armed && frame < h.frame)) continue;   // shaded before the heal took effect
        if (h.armed && now - h.at < kLgHealRecorruptWindow)
        {
            // THE SMOKING GUN: cleared, recaptured from scratch, and bad again.
            ++h.recorrupt;
            uint32_t k[2] = {0, 0};
            const bool known = snapKey(s, k) && (h.key[0] | h.key[1]) != 0u;
            const bool same = known && k[0] == h.key[0] && k[1] == h.key[1];
            LL_WARNS("VKLitGuard") << "VK lit guard: probe " << litGuardSlotText(s) << " RE-CORRUPTED "
                                   << std::fixed << std::setprecision(1) << (now - h.at) << " s after heal #" << h.heals
                                   << " (re-corruption " << h.recorrupt << ", "
                                   << (!known ? "probe identity unknown" : same ? "SAME probe" : "slot now holds ANOTHER probe")
                                   << "): the slot was cleared and recaptured from scratch -- the WRITE side produced "
                                   << "this again; " << ctx.str() << LL_ENDL;
            h.armed = false;   // (counted once per heal)
            if (h.recorrupt >= kLgHealMaxRecorrupt)
            {
                h.backoffUntil = now + kLgHealBackoff;
                LL_WARNS("VKLitGuard") << "VK lit guard: slot " << s << " re-corrupted " << h.recorrupt
                                       << " times after heals: no more heals for it for " << kLgHealBackoff << " s"
                                       << LL_ENDL;
                h.recorrupt = 0;
            }
        }
        else if (now >= h.warnAt && logBudget())
        {
            h.warnAt = now + 30.0;
            LL_WARNS("VKLitGuard") << "VK lit guard: bad texels in probe " << litGuardSlotText(s) << "; " << ctx.str()
                                   << LL_ENDL;
        }
        // Heal it? One request at a time, kLgHealGap apart, a slot at most every
        // kLgHealSlotGap, none while backed off.
        if (mLgHealReq >= 0 || now < mLgHealNext || now < h.backoffUntil || now - h.at < kLgHealSlotGap) continue;
        mLgHealReq = (int32_t)s;
        mLgHealNext = now + kLgHealGap;
        h.pending = true;
        h.armed = false;
        if (!snapKey(s, h.key)) h.key[0] = h.key[1] = 0u;
        if (logBudget())
            LL_INFOS("VKLitGuard") << "VK lit guard: HEALING probe slot " << s << " (heal #" << (h.heals + 1)
                                   << " of this slot, " << (mLgHealsTotal + 1) << " total): clear its layers + recapture"
                                   << LL_ENDL;
    }
}

// The heal requested by litGuardProbeHeal, recorded at the top of recordPrbGpu (before the
// GPU probe passes mark the slot incomplete, clean_probe_gpu.comp chg_n.w): the slot's
// stored radiance (all mips; format 3: its BC6H blocks through the encoder's clear path,
// or live cube 0 for the default probe) and its irradiance are zeroed. Nothing samples
// them meanwhile -- the slot leaves this frame's shading list -- and its recapture
// overwrites every texel; the clear makes "it came back bad" a statement about the new
// capture alone. (Last frame's readers on graphics: the barrier below; on the async queue:
// joined before this frame's graphics, asyncBeginFrame. Format 3's encoder pipeline is
// left bound: recordPrbGpu binds its own next.)
void LLCleanRendererVK::recordProbeHealClear(VkCommandBuffer cmd, uint32_t slot)
{
    if (!mProbeRad.image || !mProbeIrr.image || slot >= mProbeSlotsN) return;
    VkMemoryBarrier2 mb{VK_STRUCTURE_TYPE_MEMORY_BARRIER_2};
    mb.srcStageMask = VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT | VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
    mb.srcAccessMask = VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    mb.dstStageMask = VK_PIPELINE_STAGE_2_CLEAR_BIT | VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
    mb.dstAccessMask = VK_ACCESS_2_TRANSFER_WRITE_BIT | VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    VkDependencyInfo d{VK_STRUCTURE_TYPE_DEPENDENCY_INFO}; d.memoryBarrierCount = 1; d.pMemoryBarriers = &mb;
    vkCmdPipelineBarrier2(cmd, &d);
    const VkClearColorValue black{};
    const VkImageSubresourceRange layers{VK_IMAGE_ASPECT_COLOR_BIT, 0, VK_REMAINING_MIP_LEVELS, slot * 6u, 6u};
    const bool split = mProbeFmt == 3;
    if (!split)
        vkCmdClearColorImage(cmd, mProbeRad.image, VK_IMAGE_LAYOUT_GENERAL, &black, 1, &layers);
    else if (slot == 0u)
    {
        if (mProbeLive.image)
        {
            const VkImageSubresourceRange l0{VK_IMAGE_ASPECT_COLOR_BIT, 0, VK_REMAINING_MIP_LEVELS, 0u, 6u};
            vkCmdClearColorImage(cmd, mProbeLive.image, VK_IMAGE_LAYOUT_GENERAL, &black, 1, &l0);
        }
    }
    else if (mProbeEncPipe && mDsetProbeEnc.size() >= mProbeMips)
    {
        // (a compressed image can't take vkCmdClearColorImage: the encoder's zero blocks)
        struct { uint32_t res, live_slots, clear, clear_base; uint32_t job[2]; } ep{};
        static_assert(sizeof(ep) == 24, "clean_probe_bc6h.comp Push");
        ep.live_slots = 1u; ep.clear = 1u; ep.clear_base = slot * 6u;
        vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mProbeEncPipe);
        for (uint32_t m = 0; m < mProbeMips; ++m)
        {
            ep.res = std::max(mProbeRes >> m, 1u);
            const uint32_t blocks = std::max(ep.res / 4u, 1u);
            vkCmdBindDescriptorSets(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mProbeEncLayout, 0, 1, &mDsetProbeEnc[m], 0, nullptr);
            VK_PUSH_BUDGET_CHECK(ep);
            vkCmdPushConstants(cmd, mProbeEncLayout, VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(ep), &ep);
            vkCmdDispatch(cmd, (blocks + 7) / 8, (blocks + 7) / 8, 6);
        }
    }
    vkCmdClearColorImage(cmd, mProbeIrr.image, VK_IMAGE_LAYOUT_GENERAL, &black, 1, &layers);
    // -> the recapture's filter / encode writes and every later sampler.
    mb.srcStageMask = VK_PIPELINE_STAGE_2_CLEAR_BIT | VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
    mb.srcAccessMask = VK_ACCESS_2_TRANSFER_WRITE_BIT | VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    mb.dstStageMask = VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT | VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
    mb.dstAccessMask = VK_ACCESS_2_SHADER_SAMPLED_READ_BIT | VK_ACCESS_2_SHADER_STORAGE_READ_BIT
                     | VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    vkCmdPipelineBarrier2(cmd, &d);
}

void LLCleanRendererVK::readLitGuardStats()
{
    const uint32_t slot = (uint32_t)(mLgFrame % 3u);
    if (!mLgRbValid[slot] || !mLgRb[slot].mapped) return;
    mLgRbValid[slot] = false;
    uint32_t w[kLgWords];
    std::memcpy(w, mLgRb[slot].mapped, sizeof(w));
    if (mLgSlotRbValid[slot] && mLgSlotRb[slot].mapped)
    {
        const size_t n = (size_t)kPrbSlotCap * kPrbSlotBytes;
        mLgSlotSnap.resize(n);
        std::memcpy(mLgSlotSnap.data(), mLgSlotRb[slot].mapped, n);
    }
    mLgSlotRbValid[slot] = false;
    ++mLgFrames;
    if (mLgRbScan[slot]) ++mLgScanFrames;   // (#831: words 6..12 come from scanning frames only)
    for (uint32_t i = 0; i < kLgWords; ++i)
    {
        const bool isMax = i == 7 || i == 11 || i == kLgPtMax || i == kLgPtMinInv || i == kLgPtLive1;
        const bool isOr = i >= kLgPtSlots && i < kLgRt;
        if (i == kLgPtSample) { if (w[i]) mLgAcc[i] = w[i]; }   // (the latest sample)
        else if (isOr) mLgAcc[i] |= w[i];
        else mLgAcc[i] = isMax ? std::max<uint64_t>(mLgAcc[i], w[i]) : mLgAcc[i] + w[i];
    }
    const double now = std::chrono::duration<double>(std::chrono::steady_clock::now().time_since_epoch()).count();
    litGuardProbeHeal(w, mLgRbFrame[slot], now);
    // First sighting of a defect kind: one WARN with this frame's numbers. (The cap
    // overflows 6 / 10 are routine in light- / probe-dense places: summary only.)
    static const char* const kNames[kLgWords] = {
        "local light term non-finite / > 65000", "probe blend non-finite / > 65000", "SSR hit non-finite / > 65000",
        "final lit colour non-finite / > 65000", "", "", "light clusters over CLUSTER_CAP", "",
        "clusters whose shadowed projectors overflowed CLUSTER_CAP (lit unshadowed there)",
        "light list entries past the light count", "probe clusters over PROBE_CLUSTER_CAP", "",
        "probe list entries past the probe count"};
    // (#1049) the RT reflection hang guard: first sighting of each kind, WARN (rare by design: the
    // first two budgets sit far above sane content: each count there is a pathological ray cut short)
    static const char* const kRtNames[3] = {"rays cut by the per-ray query budget (RTR_QUERY_BUDGET)",
        "rays refused by rtRaySane (non-finite / out-of-world origin, direction or interval)",
        "walks over the candidate budget (RT_CANDIDATE_BUDGET: dense alpha-tested content, or a pathological ray)"};
    for (uint32_t k = 0; k < 3; ++k)
        if (w[kLgRt + k] != 0u && (mLgSeen & (1ull << (kLgRt + k))) == 0u)
        {
            mLgSeen |= 1ull << (kLgRt + k);
            LL_WARNS("VKLitGuard") << "VK lit guard (first): RT reflections (#1049 hang guard): " << kRtNames[k] << ": "
                                   << w[kLgRt + k] << " this frame" << LL_ENDL;
        }
    for (uint32_t i : {0u, 1u, 2u, 3u, 8u, 9u, 12u})
        if (w[i] != 0u && (mLgSeen & (1u << i)) == 0u)
        {
            mLgSeen |= 1u << i;
            LL_WARNS("VKLitGuard") << "VK lit guard (first): " << kNames[i] << ": " << w[i] << " this frame"
                                   << " (light clusters over cap " << w[6] << ", max " << w[7] << " lights; probe clusters"
                                   << " over cap " << w[10] << ", max " << w[11] << ")" << LL_ENDL;
        }
    if (now < mLgNextLog) return;
    mLgNextLog = now + 10.0;
    bool any = false;
    for (uint64_t v : mLgAcc) any = any || v != 0u;
    if (any && mLgFrames > 0)
    {
        const double f = (double)mLgFrames;
        const double fs = (double)std::max<uint32_t>(mLgScanFrames, 1u);   // (#831: the cluster-scan words' frames)
        std::ostringstream os;
        os << std::fixed;
        os.precision(1);
        os << "VK lit guard (" << mLgFrames << " frames, " << mLgScanFrames << " cluster-scanned; per frame): light cluster"
           << " overflow: " << (double)mLgAcc[6] / fs
           << " clusters over cap " << CLUSTER_CAP << ", max count " << mLgAcc[7]
           << " | shadowed-projector overflow " << (double)mLgAcc[8] / fs
           << " | probe cluster overflow " << (double)mLgAcc[10] / fs << " over cap " << PROBE_CLUSTER_CAP
           << ", max " << mLgAcc[11]
           << " | invalid light index " << (double)mLgAcc[9] / fs << ", invalid probe index " << (double)mLgAcc[12] / fs
           << " | non-finite/huge px: local " << (double)mLgAcc[0] / f << " probe " << (double)mLgAcc[1] / f
           << " ssr " << (double)mLgAcc[2] / f << " out " << (double)mLgAcc[3] / f;
        // PROBE TEXEL GUARD: where the probe trips came from (per frame; the slots: any frame).
        const uint64_t pt = mLgAcc[kLgPt] + mLgAcc[kLgPt + 1] + mLgAcc[kLgPt + 2] + mLgAcc[kLgPt + 3];
        if (pt || mLgAcc[kLgPtBadIn])
        {
            float vmax = 0.f, vmin = 0.f;
            const uint32_t mx = (uint32_t)mLgAcc[kLgPtMax], mn = ~(uint32_t)mLgAcc[kLgPtMinInv];
            std::memcpy(&vmax, &mx, 4);
            std::memcpy(&vmin, &mn, 4);
            os << " | probe texels (fmt " << probeFmtDesc(mProbeFmt).name << "): store " << (double)mLgAcc[kLgPt] / f
               << " live0 " << (double)mLgAcc[kLgPt + 1] / f << " live1 " << (double)mLgAcc[kLgPt + 2] / f
               << " irr " << (double)mLgAcc[kLgPt + 3] / f << " (non-finite " << (double)mLgAcc[kLgPtNonFinite] / f;
            if (mLgAcc[kLgPtMinInv]) os << ", finite " << std::setprecision(0) << vmin << " .. " << vmax << std::setprecision(1);
            os << "), bad lookup inputs " << (double)mLgAcc[kLgPtBadIn] / f << ", slots";
            uint32_t listed = 0;
            for (uint32_t s = 0; s < kPrbSlotCap && listed < 16; ++s)
                if (mLgAcc[kLgPtSlots + (s >> 5)] & (1ull << (s & 31u))) { os << " " << s; ++listed; }
            if (!listed) os << " -";
            if (mLgAcc[kLgPtLive1]) os << ", live1 slot " << (mLgAcc[kLgPtLive1] - 1);
            os << ", heals " << mLgHealsTotal;
        }
        else if (mLgAcc[1])
            os << " | probe blend tripped with NO bad probe texel / input (the blend math, or a texel x ambiance product)";
        if (mLgAcc[kLgRt] || mLgAcc[kLgRt + 1] || mLgAcc[kLgRt + 2])   // (#1049)
            os << " | RT reflection hang guard (totals): query budget cut " << mLgAcc[kLgRt] << " rays, rtRaySane refused "
               << mLgAcc[kLgRt + 1] << " rays, candidate budget hit " << mLgAcc[kLgRt + 2] << " walks";
        LL_INFOS("VKLitGuard") << os.str() << LL_ENDL;
    }
    for (uint64_t& v : mLgAcc) v = 0;
    mLgFrames = 0;
    mLgScanFrames = 0;
}

// ---- SHADER CLOCK (RenderVKShaderClockLighting; clean_shader_clock.glsl) ----
// Init (inside the deferred lighting block, after mDsetDefer): the device-local counter
// buffer and set 2 binding 7. A refused buffer turns the feature off for the session (the
// production kernels are built then; binding 7 stays declared, never used).
void LLCleanRendererVK::initShaderClock()
{
    if (!mCtx || !mDsetDefer) { mClkOn = false; return; }
    {
        VkMemScope memcat(VKMEM_READBACK);   // #407 (diagnostic counters, as mOdCounter)
        mClkCounter = mCtx->createBuffer(kClkWords * sizeof(uint32_t), VK_BUFFER_USAGE_STORAGE_BUFFER_BIT |
                                         VK_BUFFER_USAGE_TRANSFER_SRC_BIT | VK_BUFFER_USAGE_TRANSFER_DST_BIT,
                                         VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);
    }
    if (!mClkCounter.buffer)
    {
        LL_WARNS("VKShaderClock") << "RenderVKShaderClockLighting: counter buffer refused -- off (production kernels)"
                                  << LL_ENDL;
        mClkOn = false;
        return;
    }
    mCtx->setObjectName(VK_OBJECT_TYPE_BUFFER, (uint64_t)mClkCounter.buffer, "shaderClockCounters");
    VkDescriptorBufferInfo bi{mClkCounter.buffer, 0, VK_WHOLE_SIZE};
    VkWriteDescriptorSet w{VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET};
    w.dstSet = mDsetDefer; w.dstBinding = 7; w.descriptorCount = 1;
    w.descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_BUFFER; w.pBufferInfo = &bi;
    vkUpdateDescriptorSets(mCtx->device(), 1, &w, 0, nullptr);
    LL_INFOS("VKShaderClock") << "RenderVKShaderClockLighting ON: the deferred lighting kernels (uber + split passes)"
                                 " are the shader-clock twins (slower, more registers than production); per-stage"
                                 " cycles logged every ~5 s as \"VK shader clock\"" << LL_ENDL;
}

// Before the lighting dispatches (both paths, after recordLitGuardBegin): harvest this ring
// slot (3 frames old), then zero the counters. Main view only, as the lit guards (offscreen
// renders would turn the ring faster than its latency; their counts are dropped).
void LLCleanRendererVK::recordShaderClockBegin(VkCommandBuffer cmd)
{
    mClkActive = false;
    if (!mClkOn || mOffscreen || !mClkCounter.buffer) return;
    readShaderClockStats();
    const uint32_t slot = (uint32_t)(mClkFrame % 3u);
    if (!mClkRb[slot].buffer)
    {
        VkMemScope memcat(VKMEM_READBACK);
        mClkRb[slot] = mCtx->createBuffer(kClkWords * sizeof(uint32_t), VK_BUFFER_USAGE_TRANSFER_DST_BIT,
                                          VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT |
                                          VK_MEMORY_PROPERTY_HOST_CACHED_BIT);
        if (!mClkRb[slot].mapped) return;
    }
    // WAR: an earlier frame's counter atomics + readback copy -> this zero fill.
    VkBufferMemoryBarrier2 b{VK_STRUCTURE_TYPE_BUFFER_MEMORY_BARRIER_2};
    b.srcStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT | VK_PIPELINE_STAGE_2_COPY_BIT;
    b.srcAccessMask = VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    b.dstStageMask = VK_PIPELINE_STAGE_2_CLEAR_BIT;
    b.dstAccessMask = VK_ACCESS_2_TRANSFER_WRITE_BIT;
    b.buffer = mClkCounter.buffer; b.offset = 0; b.size = VK_WHOLE_SIZE;
    VkDependencyInfo d{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
    d.bufferMemoryBarrierCount = 1; d.pBufferMemoryBarriers = &b;
    vkCmdPipelineBarrier2(cmd, &d);
    vkCmdFillBuffer(cmd, mClkCounter.buffer, 0, VK_WHOLE_SIZE, 0u);
    b.srcStageMask = VK_PIPELINE_STAGE_2_CLEAR_BIT; b.srcAccessMask = VK_ACCESS_2_TRANSFER_WRITE_BIT;
    b.dstStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
    b.dstAccessMask = VK_ACCESS_2_SHADER_STORAGE_READ_BIT | VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    vkCmdPipelineBarrier2(cmd, &d);
    mClkActive = true;
}

// After the last lighting dispatch: the counters -> this frame's ring slot (host-visible).
void LLCleanRendererVK::recordShaderClockEnd(VkCommandBuffer cmd)
{
    if (!mClkActive) return;
    mClkActive = false;
    const uint32_t slot = (uint32_t)(mClkFrame % 3u);
    if (!mClkRb[slot].buffer || !mClkRb[slot].mapped) return;
    VkBufferMemoryBarrier2 b{VK_STRUCTURE_TYPE_BUFFER_MEMORY_BARRIER_2};
    b.srcStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; b.srcAccessMask = VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    b.dstStageMask = VK_PIPELINE_STAGE_2_COPY_BIT; b.dstAccessMask = VK_ACCESS_2_TRANSFER_READ_BIT;
    b.buffer = mClkCounter.buffer; b.offset = 0; b.size = VK_WHOLE_SIZE;
    VkDependencyInfo d{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
    d.bufferMemoryBarrierCount = 1; d.pBufferMemoryBarriers = &b;
    vkCmdPipelineBarrier2(cmd, &d);
    const VkBufferCopy cp{0, 0, kClkWords * sizeof(uint32_t)};
    vkCmdCopyBuffer(cmd, mClkCounter.buffer, mClkRb[slot].buffer, 1, &cp);
    b.srcStageMask = VK_PIPELINE_STAGE_2_COPY_BIT; b.srcAccessMask = VK_ACCESS_2_TRANSFER_WRITE_BIT;
    b.dstStageMask = VK_PIPELINE_STAGE_2_HOST_BIT; b.dstAccessMask = VK_ACCESS_2_HOST_READ_BIT;
    b.buffer = mClkRb[slot].buffer;
    vkCmdPipelineBarrier2(cmd, &d);
    mClkRbValid[slot] = true;
    ++mClkFrame;
}

// Harvest one ring slot (its frame is >= 3 frames old: its fence has signalled) and, every
// ~5 s, log per kernel that ran: invocations per frame, the surface share, and each stage's
// mean subgroup-clock cycles per invocation (one invocation = one pixel; REFLECT HALF: one
// 2 x 2 block) with its share of the kernel's total. Raw per-SM shader cycles: compare
// stages within a kernel, not kernels across clocks; the instrumented build itself costs
// ~18 clock reads + 17 subgroup reductions per invocation (see clean_shader_clock.glsl).
void LLCleanRendererVK::readShaderClockStats()
{
    const uint32_t slot = (uint32_t)(mClkFrame % 3u);
    if (!mClkRbValid[slot] || !mClkRb[slot].mapped) return;
    mClkRbValid[slot] = false;
    const uint32_t* w = static_cast<const uint32_t*>(mClkRb[slot].mapped);
    for (uint32_t k = 0; k < kClkKernels; ++k)
    {
        uint64_t sum[kClkSlots] = {};
        for (uint32_t b = 0; b < kClkBuckets; ++b)
            for (uint32_t s = 0; s < kClkSlots; ++s)
            {
                const uint32_t i = ((b * kClkKernels + k) * kClkSlots + s) * 2u;
                sum[s] += ((uint64_t)w[i + 1] << 32) | (uint64_t)w[i];
            }
        if (sum[kClkSlotInv] == 0) continue;   // (the kernel did not run this frame)
        for (uint32_t s = 0; s < kClkSlots; ++s) mClkAcc[k][s] += sum[s];
        ++mClkKernelFrames[k];
    }
    ++mClkFrames;
    const double now = std::chrono::duration<double>(std::chrono::steady_clock::now().time_since_epoch()).count();
    if (now < mClkNextLog) return;
    mClkNextLog = now + 5.0;
    // = clean_shader_clock.glsl CLK_S_* / CLEAN_DEFER_PASS
    static const char* const kStage[kClkStages] = {"tail", "cluster_scan", "tile_depth", "tile_lights", "gbuf",
                                                   "sunvis", "proj", "atmos", "probe", "ssr", "mirror", "shade",
                                                   "local", "haze", "store", "grid", "froxel"};
    static const char* const kKernel[kClkKernels] = {"uber", "shadow", "reflect", "combine", "reflect_half",
                                                     "reflect_sharp", "light_grid", "base", "local", "tile_classify",
                                                     "shadow_classify"};   // (#831)
    for (uint32_t k = 0; k < kClkKernels; ++k)
    {
        if (!mClkKernelFrames[k]) continue;
        const double inv = (double)mClkAcc[k][kClkSlotInv];
        uint64_t total = 0;
        for (uint32_t s = 0; s < kClkStages; ++s) total += mClkAcc[k][s];
        std::ostringstream os;
        os << std::fixed;
        os.precision(0);
        os << "VK shader clock [" << kKernel[k] << "] " << mClkKernelFrames[k] << " frames, "
           << inv / mClkKernelFrames[k] << " inv/frame (";
        os.precision(1);
        os << 100.0 * (double)mClkAcc[k][kClkSlotSurf] / inv << "% surface): cyc/inv total=";
        os.precision(0);
        os << (double)total / inv << " (" << (double)total / std::max<double>(1.0, (double)mClkAcc[k][kClkSlotSurf])
           << " per surface px) |";
        for (uint32_t s = 0; s < kClkStages; ++s)
        {
            if (!mClkAcc[k][s]) continue;
            os.precision(0);
            os << " " << kStage[s] << "=" << (double)mClkAcc[k][s] / inv;
            os.precision(1);
            os << " (" << (total ? 100.0 * (double)mClkAcc[k][s] / (double)total : 0.0) << "%)";
        }
        LL_INFOS("VKShaderClock") << os.str() << LL_ENDL;
    }
    for (auto& row : mClkAcc) for (uint64_t& v : row) v = 0;
    for (uint32_t& f : mClkKernelFrames) f = 0;
    mClkFrames = 0;
}

void LLCleanRendererVK::bindDrawSets(VkCommandBuffer cmd, const VkDescriptorSet* dsets)
{
    // Ray-query frame: sets 0/1 + the RT consumer set through the RT layout (the set
    // was rewritten by this frame's recordBuild: selectLitVariant requires tlasValid()).
    // Plain frame: sets 0/1 only -- the RT set is never bound. Either way sets 0/1 stay
    // valid for the other layout's pipelines (compatible for sets 0/1).
    if (mLitRt && mRT && mDrawLayoutRt)
    {
        const VkDescriptorSet s3[3] = {dsets[0], dsets[1], mRT->consumerSet()};
        vkCmdBindDescriptorSets(cmd, VK_PIPELINE_BIND_POINT_GRAPHICS, mDrawLayoutRt, 0, 3, s3, 0, nullptr);
    }
    else
        vkCmdBindDescriptorSets(cmd, VK_PIPELINE_BIND_POINT_GRAPHICS, mDrawLayout, 0, 2, dsets, 0, nullptr);
}

VkPipeline* LLCleanRendererVK::litLive(LitPipe i)
{
    switch (i)
    {
    case LIT_DRAW:          return &mDrawPipe;
    case LIT_DRAW_DS:       return &mDrawDsPipe;
    case LIT_MASK:          return &mMaskPipe;
    case LIT_MASK_DS:       return &mMaskDsPipe;
    case LIT_ALPHA:         return &mAlphaPipe;
    case LIT_RIG:           return &mRiggedPipe;
    case LIT_RIG_DS:        return &mRiggedDsPipe;
    case LIT_RIG_ALPHA:     return &mRiggedAlphaPipe;
    case LIT_PROBE_DRAW:    return &mProbeDrawPipe;
    case LIT_PROBE_MASK:    return &mProbeMaskPipe;
    case LIT_PROBE_DRAW_DS: return &mProbeDrawDsPipe;
    case LIT_PROBE_MASK_DS: return &mProbeMaskDsPipe;
    case LIT_EQ:            return &mDrawEqPipe[0];
    case LIT_EQ_DS:         return &mDrawEqPipe[1];
    case LIT_RIG_EQ:        return &mRiggedEqPipe[0];
    case LIT_RIG_EQ_DS:     return &mRiggedEqPipe[1];
    case LIT_PROBE_MASK_EQ:    return &mProbeMaskEqPipe;
    case LIT_PROBE_MASK_DS_EQ: return &mProbeMaskDsEqPipe;
    case LIT_CAP_DRAW:       return &mCapDrawPipe;      // (#829 capture FS)
    case LIT_CAP_MASK:       return &mCapMaskPipe;
    case LIT_CAP_DRAW_DS:    return &mCapDrawDsPipe;
    case LIT_CAP_MASK_DS:    return &mCapMaskDsPipe;
    case LIT_CAP_MASK_EQ:    return &mCapMaskEqPipe;
    case LIT_CAP_MASK_DS_EQ: return &mCapMaskDsEqPipe;
    case LIT_CAP_ALPHA:      return &mCapAlphaPipe;
    case LIT_CAP_RIG:        return &mCapRigPipe;
    case LIT_CAP_RIG_DS:     return &mCapRigDsPipe;
    case LIT_CAP_RIG_ALPHA:  return &mCapRigAlphaPipe;
    default: break;
    }
    static VkPipeline s_dummy = VK_NULL_HANDLE;
    return &s_dummy;
}

// A TLAS consumer this frame: ray-traced projector shadows with at least one record
// (selectProjShadows ran in setLights, before recordWorld), or an RT debug view.
bool LLCleanRendererVK::rtConsumerActive() const
{
    if (!mRT) return false;
    if (mProjMode == 2u && mProjRecords > 0) return true;
    if (mProjMode == 2u && mRsMode != 0u && mRsSetN > 0u) return true;   // (#869 / #439 ReSTIR DI: point lights)
    if (mProjMode == 2u && rsEmLightWanted()) return true;                // (#91 the emissive lights)
    if (mGiModeSetting != 0u) return true;                                // (#87 ray-traced GI)
    if (mShadowOn && sunRtWanted()) return true;   // ray-traced sun / moon (#185)
    if (probeTraceWanted()) return true;            // ray-traced probe capture (detail 3)
    if (mAudioRT && !mOffscreen && mAudioRT->wanted()) return true;   // acoustics probe (#683, AudioAcoustics)
    if (rtReflWanted()) return true;                // hybrid RT reflections (#859, RenderVKRTReflections 1)
    if (rtaoWanted()) return true;                  // ray-traced AO (#86, RenderVKAOMethod 2)
#if defined(LL_HAS_CLEAN_PIPELINE)
    static LLCachedControl<U32> s_rtview(gSavedSettings, "RenderVKDebugView", 0);
    const U32 v = s_rtview;
    if (v == 13u || v == 14u || v == 15u || v == 18u) return true;
#endif
    return false;
}

// After the RT build: the ray-query lit variant only when a lit FS will actually trace
// (projector shadows mode 2 with records) AND this frame's TLAS + consumer set are valid.
// Everything else (RT off, no consumer, debug views only, TLAS skipped/failed) draws with
// the plain variant and never binds the RT set.
void LLCleanRendererVK::selectLitVariant()
{
    // Sun traced only once RT is warm (#268): a cold TLAS (first use, after the idle
    // release, after a forced eviction) traced an almost empty scene -- every pixel lit,
    // no shadow anywhere -- while the cascades were skipped. The build keeps running
    // (rtConsumerActive asks sunRtWanted only); the cascades cover the warm-up.
    // RT OVER ITS OWN MEMORY BUDGET (#227 replacement, #405): the working buffers alone
    // exceed 70% of it. Held 3 s first (not on the frame a build spike trips it; until then
    // sunRtWanted() is false and the cascades render), then ray-traced sun / projector
    // shadows use the shadow maps for mRtFallbackHold s -- TEMPORARY, settings untouched,
    // no popup (log + readout). The idle release then frees the RT working set, so
    // overBudget() clears at once; the hold (doubled when it trips again within 2 min of a
    // lift, up to 10 min; back to 60 s after 15 quiet minutes) keeps it from flapping.
    {
        const double now = std::chrono::duration<double>(std::chrono::steady_clock::now().time_since_epoch()).count();
        if (mRT && mRT->overBudget()) { if (mRtOverSince == 0.0) mRtOverSince = now; }
        else mRtOverSince = 0.0;
        if (!mRtFallback && mRtOverSince != 0.0 && now - mRtOverSince >= 3.0)
        {
            if (now - mRtFallbackLift < 120.0) mRtFallbackHold = std::min(mRtFallbackHold * 2.0, 600.0);
            mRtFallback = true;
            mRtFallbackSince = now;
            LL_WARNS("VKMem") << "RT over its memory budget (working buffers " << (mRT->workingBytes() >> 20) << " MB of "
                              << (mRT->budgetBytes() >> 20) << " MB): ray-traced shadows use the shadow maps for "
                              << (S32)mRtFallbackHold << " s (settings unchanged)" << LL_ENDL;
        }
        else if (mRtFallback && now - mRtFallbackSince >= mRtFallbackHold && !(mRT && mRT->overBudget()))
        {
            mRtFallback = false;
            mRtFallbackLift = now;
            LL_INFOS("VKMem") << "RT fallback hold over: ray-traced shadows may trace again" << LL_ENDL;
        }
        if (!mRtFallback && mRtFallbackHold > 60.0 && now - mRtFallbackLift > 900.0) mRtFallbackHold = 60.0;
    }
    // The VRAM pressure ladder dropped the avatars (rigged + worn attachments) from the TLAS (#1015:
    // the RT budget rule no longer does): temporary, back when the ladder lifts it, logged once per
    // session (no popup: a soft reduction, #405); the readout says so (fitNotesText).
    if (mRT && mRT->rigDropped() && !mRigNotified)
    {
        mRigNotified = true;
        LL_WARNS("VKMem") << "Video memory is full: avatars not on the cluster LOD path no longer cast ray-traced "
                             "shadows (scenery and cluster-path avatars still do) until memory frees up" << LL_ENDL;
    }
    const bool sun = mShadowOn && sunRtWanted() && mRT && mRT->sunReady();
    const bool want = mRT && mDrawLayoutRt && mLitVar[1][LIT_DRAW] && ((mProjMode == 2u && mProjRecords > 0) || sun);
    const bool rt = want && mRT->tlasValid();
    mLitRt = rt;
    mSunRtNow = rt && sun;
    // #600: the cascades are in use unless the sun is ray traced this frame.
    if (!mSunRtNow) mSunMapsUsedAt = std::chrono::duration<double>(std::chrono::steady_clock::now().time_since_epoch()).count();
    mShadowParams[3] = mShadowOn ? (mSunRtNow ? 2.f : 1.f) : 0.f;
    // SUN MODE LOG (#268): RenderVKSunShadows 2 only; every switch traced <-> maps, with
    // the reason, at most one line per 5 s (the count of switches in between is shown).
    {
        U32 sun_setting = 1;
#if defined(LL_HAS_CLEAN_PIPELINE)
        static LLCachedControl<U32> s_sun(gSavedSettings, "RenderVKSunShadows", 1);
        sun_setting = s_sun;
#endif
        const int mode = mSunRtNow ? 1 : 0;
        if (sun_setting == 2u && mShadowOn && mRT)
        {
            if (mode != mSunRtPrev) { ++mSunRtFlips; mSunRtPrev = mode; }
        }
        if (sun_setting == 2u && mShadowOn && mRT && mode != mSunRtLogged)
        {
            const double now = std::chrono::duration<double>(std::chrono::steady_clock::now().time_since_epoch()).count();
            if (now >= mSunRtLogNext)
            {
                mSunRtLogNext = now + 5.0;
                const uint32_t flips = mSunRtFlips;
                mSunRtFlips = 0;
                mSunRtLogged = mode;
                LL_WARNS("Vulkan") << "sun/moon shadows: " << (mode ? "ray traced (RT warm, TLAS valid)"
                                                                    : std::string("shadow maps (cascades) -- ") + sunRtOffReason())
                                   << (flips > 1 ? " [" + std::to_string(flips) + " switches since the last line]" : std::string())
                                   << LL_ENDL;
            }
        }
    }
    const int v = rt ? 1 : 0;
    // RT SHADOW MASK (#195): with the depth pre-pass, opaque receivers read the mask the
    // compute traces, so pass 1's opaque / mask / rigged / EQUAL slots take the PLAIN FS
    // (no ray queries: lighter, better occupancy); alpha and the captures keep the
    // ray-query variant (alpha traces its sun ray inline; its ray-traced projectors only
    // with RenderVKRTBlendProjShadows 1 -- clean_draw_common.glsl projectorVisibility).
    bool mask = false;
#if defined(LL_HAS_CLEAN_PIPELINE)
    {
        static LLCachedControl<bool> s_mask(gSavedSettings, "RenderVKRTShadowMask", true);
        static LLCachedControl<bool> s_prepass(gSavedSettings, "RenderVKDepthPrepass", true);
        static LLCachedControl<bool> s_od(gSavedSettings, "RenderVKOverdrawStats", false);
        mask = rt && s_mask && s_prepass && !s_od && mRtMaskPipe && mRtMaskTmpPipe && mRtMaskSpPipe && mDsetRtMask[0] && mRtMaskW > 1
            && mPreOpaquePipe[0] && mLitVar[0][LIT_EQ]
            && !(mOffscreen && mSnapAccFrames > 0);   // #417: supersampled snapshots trace inline
    }
#endif
    // MERGED RT SHADOWS (#195 + #85, RenderVKRTShadowMerge): when this frame is predicted to run
    // the merged pass (sun / moon AND projectors ray traced, the stochastic path, the denoiser's
    // sun images in place), the mask is held off -- nothing reads it then: the deferred SHADOW
    // kernel takes the denoised sun, the stochastic path the projectors, every forward surface
    // (alpha, water, particles, captures) traces inline -- and the opaque slots keep the ray-query
    // variant (a forward opaque draw must trace, not read a mask that is not there).
    // recordWorld settles the prediction after deferSplitFrame (the settle block in the code
    // there): a frame that cannot merge after all re-arms the mask exactly as today.
    mRtMaskWant = mask;
    shadowMergeSunState();
    mShadowMergeTry = rt && sun && shadowMergeWanted(true);
    mShadowMergeNow = false;
    mRtMaskOn = mask && !mShadowMergeTry;
    mLitSlotsV = v;
    installLitSlots(v, mRtMaskOn);
    if (mRT && v != mLitVariantLogged)
    {
        mLitVariantLogged = v;
        const char* why = rt   ? (sun ? "sun/moon (and projector) shadows ray traced, TLAS valid"
                                      : "projector shadows ray traced, TLAS valid")
                        : want ? "TLAS not valid this frame"
                               : "no ray-traced shadows this frame";
        LL_INFOS("Vulkan") << "lit FS variant: " << (rt ? "rayquery" : "plain") << " (" << why
                           << (want ? ", " + std::to_string(mProjRecords) + " projector records" : std::string())
                           << ")" << LL_ENDL;
    }
}

// The frame info's RT shadow mask word (rt_mask) and shadow_params, decided by selectLitVariant
// (TLAS state) -- and again (again = true) when recordWorld withdraws the merged RT shadow pass's
// prediction after deferSplitFrame (the mask re-armed: the readers below see its real state).
void LLCleanRendererVK::rtMaskFrameInfo(VkCommandBuffer cmd, bool again)
{
    if (!mSSRInfoSSBO.buffer) return;
    // x: 0 off, 1 read the mask, 2 read it with the denoiser's plane-aware upsample;
    // + 0.25 when this frame's ids / depth are history slot 1 (clean_shadow_mask_read).
    // -1 (#195 + #85): the MERGED RT shadow pass is predicted -- the mask is off for every
    // reader (rtMaskUsable needs > 0.5) and the deferred SHADOW kernel reads the merged sun
    // (clean_deferred_light.comp deferSunMerged, with DEFER_FLAG_PSTOCH). -2: the same with the
    // weak-sun gate closed (no sun / moon ray, the denoiser skips the sun channel: the SHADOW kernel
    // reads lit without it -- recordProjStoch's sun-channel skip).
    const float on = mShadowMergeTry ? (mShadowMergeSunW > 0.f ? -1.f : -2.f)
                   : mRtMaskOn ? (mRtMaskDenoise ? 2.f : 1.f) + ((mRtMaskSet & 1u) ? 0.25f : 0.f) : 0.f;
    const float rm[4] = {on, mRtMaskScale, (float)mRtMaskW, (float)mRtMaskH};
    // (Frame pipelining, 3b: the front end ran on the async queue; its frame-info upload
    // is published to everything below by the join semaphore, not by this barrier.)
    // PRECISE STAGES (F12 / B11). Was ALL_COMMANDS on both sides, which drained the
    // whole pipe here -- including the RT build just recorded (AS-build stage).
    // Before: WAW against this frame's full upload (c_lights, CLEAR / COPY). No frame-
    // info reader runs between that upload and this patch (its readers are the VS /
    // FS of the passes and the RT-mask / god-ray compute, all recorded below), and the
    // upload itself already waited for last frame's readers, so the chain covers WAR.
    // After: WHOLE buffer, to every reader stage -- the upload's own barrier reaches
    // VS / FS only, so this one also publishes the full frame info to the compute
    // readers (as the ALL_COMMANDS barrier did implicitly).
    // AGAIN (a withdrawn merge prediction, rare): compute work recorded since the first patch
    // may have read the frame info -- WAR from every shader read as well.
    VkBufferMemoryBarrier2 bb{VK_STRUCTURE_TYPE_BUFFER_MEMORY_BARRIER_2};
    bb.srcStageMask=VK_PIPELINE_STAGE_2_CLEAR_BIT|VK_PIPELINE_STAGE_2_COPY_BIT; bb.srcAccessMask=VK_ACCESS_2_TRANSFER_WRITE_BIT;
    if (again)
    {
        bb.srcStageMask |= VK_PIPELINE_STAGE_2_VERTEX_SHADER_BIT|VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT
                         |VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
        bb.srcAccessMask |= VK_ACCESS_2_SHADER_STORAGE_READ_BIT|VK_ACCESS_2_UNIFORM_READ_BIT;
    }
    bb.dstStageMask=VK_PIPELINE_STAGE_2_CLEAR_BIT|VK_PIPELINE_STAGE_2_COPY_BIT; bb.dstAccessMask=VK_ACCESS_2_TRANSFER_WRITE_BIT;
    bb.buffer=mSSRInfoSSBO.buffer; bb.offset=0; bb.size=VK_WHOLE_SIZE;
    VkDependencyInfo bd{VK_STRUCTURE_TYPE_DEPENDENCY_INFO}; bd.bufferMemoryBarrierCount=1; bd.pBufferMemoryBarriers=&bb;
    vkCmdPipelineBarrier2(cmd,&bd);
    vkCmdUpdateBuffer(cmd, mSSRInfoSSBO.buffer, offsetof(VKSSRInfo, rt_mask), sizeof(rm), rm);
    // shadow_params.w (#268): traced (2) vs cascades (1), decided only now (mSunRtNow).
    vkCmdUpdateBuffer(cmd, mSSRInfoSSBO.buffer, offsetof(VKSSRInfo, shadow_params), sizeof(mShadowParams), mShadowParams);
    bb.srcStageMask=VK_PIPELINE_STAGE_2_CLEAR_BIT|VK_PIPELINE_STAGE_2_COPY_BIT; bb.srcAccessMask=VK_ACCESS_2_TRANSFER_WRITE_BIT;
    bb.dstStageMask=VK_PIPELINE_STAGE_2_VERTEX_SHADER_BIT|VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT
                   |VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
    bb.dstAccessMask=VK_ACCESS_2_SHADER_STORAGE_READ_BIT|VK_ACCESS_2_UNIFORM_READ_BIT;
    vkCmdPipelineBarrier2(cmd,&bd);
}

// The lit FS slots for variant v (1 = ray-query): plainOpaque (the RT shadow mask runs) puts the
// opaque / mask / rigged / EQUAL slots on the plain FS; then the debug twins. selectLitVariant,
// and recordWorld when the merged RT shadow pass's prediction is withdrawn (the mask re-armed).
void LLCleanRendererVK::installLitSlots(int v, bool plainOpaque)
{
    // #672: a ray-query variant that failed to compile (out of memory: VK_NULL_HANDLE) falls
    // back to its plain twin (no RT shadows on those surfaces instead of nothing drawn).
    // (litVar: the bound setting-specialization set's pipeline, else the generic one.)
    for (int i = 0; i < LIT_COUNT; ++i) *litLive((LitPipe)i) = litVar(v, i) ? litVar(v, i) : litVar(0, i);
    if (plainOpaque)
        for (LitPipe i : {LIT_DRAW, LIT_DRAW_DS, LIT_MASK, LIT_MASK_DS, LIT_RIG, LIT_RIG_DS,
                          LIT_EQ, LIT_EQ_DS, LIT_RIG_EQ, LIT_RIG_EQ_DS})
            *litLive(i) = litVar(0, i);
    // DEBUG TWINS (kDebugViews): while a debug feature reads the lit FS, every live slot takes
    // the twin of the pipeline just installed (built on first use; none yet / failed: the
    // normal pipeline stays -- the debug output is missing that frame, nothing else).
    // The twins are GENERIC + debug (no setting constants): they read the frame-info fields,
    // which specApply keeps on the bound key, so they shade the same configuration.
    if (litDebugWanted())
    {
        ensureLitDebug(0);
        if (v == 1) ensureLitDebug(1);
        for (int i = 0; i < LIT_COUNT; ++i)
        {
            VkPipeline* live = litLive((LitPipe)i);
            for (int w = 0; w < 2; ++w)
                if (*live && (*live == litVar(w, i) || *live == mLitVar[w][i]) && mLitDbg[w][i]) { *live = mLitDbg[w][i]; break; }
        }
    }
}

// Any debug feature the lit FS / deferred lighting compute only carries in their kDebugViews
// twins (clean_draw_common.glsl): mirrors the frame-info fill (recordWorld) of the fields
// those paths read -- params1.z (RenderVKDebugView minus the non-FS overlays), lit_dbg.x
// bits 0-15 (RenderVKLitDebugMask) and 16 (RenderVKRTShadowDebug 8), ao_params2.z
// (Highlight Transparent) and blend_tol.w (RenderVKBlendDepthTolDebug).
bool LLCleanRendererVK::litDebugWanted() const
{
#if defined(LL_HAS_CLEAN_PIPELINE)
    static LLCachedControl<U32> s_dbgview(gSavedSettings, "RenderVKDebugView", 0);
    static LLCachedControl<U32> s_litdbg(gSavedSettings, "RenderVKLitDebugMask", 0);
    static LLCachedControl<U32> s_rtsdbg(gSavedSettings, "RenderVKRTShadowDebug", 0U);
    static LLCachedControl<bool> s_tol_on(gSavedSettings, "RenderVKBlendDepthTol", true);
    static LLCachedControl<bool> s_tol_dbg(gSavedSettings, "RenderVKBlendDepthTolDebug", false);
    const U32 dv = s_dbgview;
    const bool viewFs = dv != 0u && !((dv >= 13u && dv <= 15u) || dv == 18u || dv == 22u || dv == 28u);
    return viewFs || ((U32)s_litdbg & 0xFFFFu) != 0u || (U32)s_rtsdbg == 8u
        || LLPipeline::sShowDebugAlpha || (s_tol_on && s_tol_dbg);
#else
    return false;
#endif
}

// The kDebugViews twins of lit variant v (0 plain, 1 ray-query), from the descs recorded at
// init (litInto): queued on first use as ONE async pipeline batch (no hitch: the workers
// write mLitDbgStage, pollLitDebug installs them when the job is done -- until then the
// debug output is simply missing, logged), then kept until the lit pipelines go. The
// ray-query set waits until its own compile job installed mLitVar[1]. GENERIC + debug: no
// setting constants (they read the frame-info fields, which follow the bound spec key).
void LLCleanRendererVK::ensureLitDebug(int v)
{
    if (v < 0 || v > 1 || mLitDbgBuilt[v] || !mCtx) return;
    if (!mLitVar[v][LIT_DRAW]) return;   // (the variant itself is not in yet: try again later)
    if (v == 1 && !(mRT && mDrawLayoutRt)) return;
    mLitDbgBuilt[v] = true;
    VkDevice dev = mCtx->device();
    unsigned want = 0;
    {
        PipelineBatchScope batchScope(dev);   // queued here, compiled by the async job below
        VkShaderModule vs  = moduleFromSpv(dev, kWorldVertSpv, kWorldVertSpv_bytes, "kWorldVertSpv");
        VkShaderModule rvs = moduleFromSpv(dev, kWorldRiggedVertSpv, kWorldRiggedVertSpv_bytes, "kWorldRiggedVertSpv");
        VkShaderModule fsm[3];
        if (v == 0)
        {
            fsm[LITF_LIT]   = moduleFromSpv(dev, kWorldFragSpv, kWorldFragSpv_bytes, "kWorldFragSpv");
            fsm[LITF_BLEND] = moduleFromSpv(dev, kWorldFragBlendSpv, kWorldFragBlendSpv_bytes, "kWorldFragBlendSpv");
            fsm[LITF_EZ]    = moduleFromSpv(dev, kWorldFragEzSpv, kWorldFragEzSpv_bytes, "kWorldFragEzSpv");
        }
        else
        {
            fsm[LITF_LIT]   = moduleFromSpv(dev, kWorldFragRtSpv, kWorldFragRtSpv_bytes, "kWorldFragRtSpv");
            fsm[LITF_BLEND] = moduleFromSpv(dev, kWorldFragBlendRtSpv, kWorldFragBlendRtSpv_bytes, "kWorldFragBlendRtSpv");
            fsm[LITF_EZ]    = moduleFromSpv(dev, kWorldFragRtEzSpv, kWorldFragRtEzSpv_bytes, "kWorldFragRtEzSpv");
        }
        static const char* const kDbgNames[2] = {"lit debug twin (plain)", "lit debug twin (rayquery)"};
        for (int i = 0; i < LIT_COUNT; ++i)
        {
            mLitDbgStage[v][i] = VK_NULL_HANDLE;
            const LitDbgDesc& r = mLitDbgDesc[v][i];
            if (!r.valid || !mLitVar[v][i]) continue;   // (a slot that failed to compile has no twin either)
            if (r.frag == LITF_CAP) continue;           // (#829 capture FS: no debug terms to show)
            GraphicsPipelineDesc d = r.desc;
            d.vert = r.rigged ? rvs : vs;
            d.frag = fsm[r.frag];
            d.fragSpec = litDebugSpec(true);
            createGraphicsPipelineInto(dev, d, &mLitDbgStage[v][i], kDbgNames[v]);
            ++want;
        }
        for (VkShaderModule m : {vs, rvs, fsm[0], fsm[1], fsm[2]}) destroyShaderModuleDeferred(dev, m, nullptr);
        mLitDbgJob[v] = pipelineBatchFlushAsync(dev);   // (the scope's own flush then finds nothing)
    }
    mLitDbgSince[v] = std::chrono::duration<double>(std::chrono::steady_clock::now().time_since_epoch()).count();
    LL_INFOS("Vulkan") << "lit FS debug twins (" << (v ? "rayquery" : "plain") << "): " << want
                       << " compiling in the background (the debug view / RenderVKLitDebugMask / Highlight Transparent"
                          " / RT terminator view is not active until they land)" << LL_ENDL;
}

// Installs the finished debug twin jobs (every frame from specFrameTick; wait = shutdown).
void LLCleanRendererVK::pollLitDebug(bool wait)
{
    for (int v = 0; v < 2; ++v)
    {
        if (!mLitDbgJob[v] || (!wait && !pipelineJobDone(mLitDbgJob[v]))) continue;
        pipelineJobFinish(mLitDbgJob[v]);
        mLitDbgJob[v] = nullptr;
        unsigned made = 0;
        for (int i = 0; i < LIT_COUNT; ++i)
        {
            mLitDbg[v][i] = mLitDbgStage[v][i];
            mLitDbgStage[v][i] = VK_NULL_HANDLE;
            made += mLitDbg[v][i] ? 1u : 0u;
        }
        const double ms = (std::chrono::duration<double>(std::chrono::steady_clock::now().time_since_epoch()).count()
                           - mLitDbgSince[v]) * 1000.0;
        LL_INFOS("Vulkan") << "lit FS debug twins (" << (v ? "rayquery" : "plain") << "): " << made
                           << " built in " << (S32)ms << " ms (background); debug views / RenderVKLitDebugMask /"
                              " Highlight Transparent / RT terminator view bind them while on" << LL_ENDL;
    }
    if (mDeferDbgJob.valid() && (wait || mDeferDbgJob.wait_for(std::chrono::seconds(0)) == std::future_status::ready))
    {
        mDeferPipeDbg = mDeferDbgJob.get();
        if (mDeferDbgMod) { vkDestroyShaderModule(mCtx->device(), mDeferDbgMod, nullptr); mDeferDbgMod = VK_NULL_HANDLE; }
        LL_INFOS("Vulkan") << "deferred lighting debug twin " << (mDeferPipeDbg ? "built (background)"
                                                                                 : "FAILED (cost switches inactive in deferred frames)")
                           << LL_ENDL;
    }
}

// The deferred lighting compute's kDebugViews twin (RenderVKLitDebugMask cost switches in
// deferred frames): built on first use on a worker (std::async, as the split pipelines;
// litDebugSpec's info is static); false -- the normal kernel, switches inactive -- until it
// lands (pollLitDebug).
bool LLCleanRendererVK::ensureDeferDebug()
{
    if (mDeferPipeDbg) return true;
    if (mDeferDbgBuilt || !mCtx || !mDeferLayout) return false;
    mDeferDbgBuilt = true;
    VkDevice dev = mCtx->device();
    const VKDeferSpv ds = vkDeferLightingSpv(0, mDeferG11, mClkOn);
    mDeferDbgMod = moduleFromSpv(dev, ds.code, ds.bytes, ds.name);
    const VkShaderModule gm = mDeferDbgMod;
    const VkPipelineLayout layout = mDeferLayout;
    // Admitted (vk_pipeline.h): the worker waits for room under the compile memory budget.
    mDeferDbgJob = std::async(std::launch::async, [dev, gm, layout]()
                              { return createComputePipelineAdmitted(dev, gm, layout, 0, litDebugSpec(true),
                                                                     "mDeferPipeDbg", VKPIPE_PRIO_USER); });
    LL_INFOS("Vulkan") << "deferred lighting debug twin compiling in the background (cost switches inactive in"
                          " deferred frames until it lands)" << LL_ENDL;
    return false;
}

// ---- SPLIT DEFERRED LIGHTING (RenderVKDeferredSplit; clean_deferred_light.comp CLEAN_DEFER_PASS
// 1-3; see the header block at mDslDeferSplit) ----
static double dsClock()
{
    return std::chrono::duration<double>(std::chrono::steady_clock::now().time_since_epoch()).count();
}

// Init, inside the world PipelineBatchScope (after the uber kernel: mDeferLayout / mDslDefer /
// mDeferG11): set 3's layout + pool + set, the 4-set pipeline layout, and the three passes
// queued into the batch (the login shader gate). finalizePipelines sets mDeferSplitOk.
void LLCleanRendererVK::initDeferSplit()
{
    if (!mCtx || !mDeferLayout || !mDslDefer) return;
    VkDevice dev = mCtx->device();
    VkDescriptorSetLayoutBinding b[kDsBindings]{};
    for (uint32_t i = 0; i < kDsBindings; ++i)
    {
        b[i].binding = i; b[i].descriptorCount = 1; b[i].stageFlags = VK_SHADER_STAGE_COMPUTE_BIT;
        // (#827: binding 8 = the feature split's tile list, a storage buffer; the rest images)
        // (#827: binding 8 = the feature split's tile list; #859: 10 = the RT tile list -- buffers)
        // (#87: 22 / 23 the GI reservoirs / state -- buffers; 18-21 the GI denoiser's images)
        // (#1031: 25 the split GI stages' records, 26 the split shadow core's descriptors -- buffers)
        b[i].descriptorType = (i == kDsBindingTiles || i == kDsBindingRtTiles || i == kDsBindingRsRes
                               || i == kDsBindingGiRes || i == kDsBindingGiState || i == kDsBindingGiHit
                               || i == kDsBindingPdnSel || i == kDsBindingPdnVis)
                                  ? VK_DESCRIPTOR_TYPE_STORAGE_BUFFER : VK_DESCRIPTOR_TYPE_STORAGE_IMAGE;
    }
    VkDescriptorSetLayoutCreateInfo li{VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO};
    li.bindingCount = kDsBindings; li.pBindings = b;
    VK_CHECK(vkdCreateSetLayout(dev, &li, &mDslDeferSplit, "mDslDeferSplit"));
    VK_CHECK(mDeferSplitPool.create(dev, "deferred split", {{mDslDeferSplit, 1}}));
    VK_CHECK(mDeferSplitPool.allocate(mDslDeferSplit, &mDsetDeferSplit));
    // (#869 Phase 5b) binding 17's placeholder until the reservoirs exist
    if (!mRsResDummy.buffer)
        mRsResDummy = mCtx->createBuffer(16, VK_BUFFER_USAGE_STORAGE_BUFFER_BIT, VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);
    writeRsResBinding();
    writePdnSelBinding();   // (#1031: binding 26's placeholder until the descriptors exist)
    const VkDescriptorSetLayout dsl[4] = {mDslDraw0, mDslDraw1, mDslDefer, mDslDeferSplit};
    VkPushConstantRange pc{VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(VKDeferPush)};
    VkPipelineLayoutCreateInfo pli{VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO};
    pli.setLayoutCount = 4; pli.pSetLayouts = dsl;
    pli.pushConstantRangeCount = 1; pli.pPushConstantRanges = &pc;
    VK_CHECK(vkdCreatePipelineLayout(dev, &pli, &mDeferSplitLayout, "mDeferSplitLayout"));
    // Distinct module names: RenderVKPipelineStats logs each kernel's registers / spills.
    // (RenderVKShaderClockLighting: the clock twins, vkDeferLightingSpv; CLEAN_DEFER_PASS per slot.)
    // Half-resolution reflections (RenderVKDeferReflectHalfRes): per-block + sharp-pixel passes.
    VkShaderModule mods[DSP_COUNT];
    static const uint32_t kPass[DSP_COUNT] = {1u, 2u, 3u, 4u, 5u};   // DSP_* -> CLEAN_DEFER_PASS
    for (uint32_t i = 0; i < DSP_COUNT; ++i)
    {
        const VKDeferSpv sp = vkDeferLightingSpv(kPass[i], mDeferG11, mClkOn);
        mods[i] = moduleFromSpv(dev, sp.code, sp.bytes, sp.name);
    }
    static const char* const kName[DSP_COUNT] = {"mDeferSplitPipe (DeferShadow)", "mDeferSplitPipe (DeferReflect)",
                                                 "mDeferSplitPipe (DeferCombine)", "mDeferSplitPipe (DeferReflectHalf)",
                                                 "mDeferSplitPipe (DeferReflectSharp)"};
    // (no debug twins: RenderVKLitDebugMask frames take the uber kernel's)
    for (uint32_t i = 0; i < DSP_COUNT; ++i)
    {
        createComputePipelineInto(dev, mods[i], mDeferSplitLayout, 0, litDebugSpec(false), &mDeferSplitPipe[i], kName[i]);
        destroyShaderModuleDeferred(dev, mods[i], nullptr);
    }
    // The light grid build on the split layout (RenderVKLightCulling 1; [0] is the uber layout's).
    const VKDeferSpv ls = vkDeferLightingSpv(6, false, mClkOn);
    VkShaderModule lm = moduleFromSpv(dev, ls.code, ls.bytes, ls.name);
    createComputePipelineInto(dev, lm, mDeferSplitLayout, deferTileStageFlags(), litDebugSpec(false), &mLightGridPipe[1],
                              "mLightGridPipe (LightGrid, split)");
    destroyShaderModuleDeferred(dev, lm, nullptr);
    // FEATURE SPLIT (#827, RenderVKDeferredFeatureSplit): tile classify (the grid build + the tile
    // list; no settings specialization, as the grid build), BASE, LOCAL (the glow format as the
    // combine's; spec sets build their own BASE / LOCAL). Distinct names for RenderVKPipelineStats.
    // (#831) + SHADOW_CLS: the shadow resolve with the classification as its prologue
    // (RenderVKDeferClassifyFused; spec sets build their own, as for the shadow pass). The tile
    // builds (CLASSIFY, SHADOW_CLS) take the full-subgroups flag (deferTileStageFlags).
    static const uint32_t kFeatPass[DFP_COUNT] = {9u, 7u, 8u, 10u};   // DFP_* -> CLEAN_DEFER_PASS
    static const char* const kFeatName[DFP_COUNT] = {"mDeferFeatPipe (DeferTileClassify)", "mDeferFeatPipe (DeferBase)",
                                                     "mDeferFeatPipe (DeferLocal)", "mDeferFeatPipe (DeferShadowClassify)"};
    for (uint32_t i = 0; i < DFP_COUNT; ++i)
    {
        const bool tile = i == DFP_CLASSIFY || i == DFP_SHADOW_CLS;
        const VKDeferSpv sp = vkDeferLightingSpv(kFeatPass[i], !tile && mDeferG11, mClkOn);
        VkShaderModule fm = moduleFromSpv(dev, sp.code, sp.bytes, sp.name);
        createComputePipelineInto(dev, fm, mDeferSplitLayout, tile ? deferTileStageFlags() : 0u, litDebugSpec(false),
                                  &mDeferFeatPipe[i], kFeatName[i]);
        destroyShaderModuleDeferred(dev, fm, nullptr);
    }
    // HYBRID RT REFLECTIONS (#859): RT RESOLVE (13) on the split layout (no ray query); with RT up,
    // RT TRACE (11) + RT FORWARD (14) on the split's sets + the RT consumer set (set 4), and the uber
    // frames' RT PRE-TRACE (12) on the uber sets + the RT set (set 3), 96 B push. Generic pipelines
    // (their spec constants keep their run-time defaults, as the classification's), no clock twins.
    {
        VkShaderModule qm = moduleFromSpv(dev, kWorldDeferRtResolveSpv, kWorldDeferRtResolveSpv_bytes, "kWorldDeferRtResolveSpv");
        createComputePipelineInto(dev, qm, mDeferSplitLayout, 0u, litDebugSpec(false), &mRtResolvePipe,
                                  "mRtResolvePipe (DeferRtResolve)");
        destroyShaderModuleDeferred(dev, qm, nullptr);
    }
    if (mRT && mRT->consumerLayout())
    {
        VkPushConstantRange rpc{VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(VKRtReflPush)};
        const VkDescriptorSetLayout rsl[5] = {mDslDraw0, mDslDraw1, mDslDefer, mDslDeferSplit, mRT->consumerLayout()};
        VkPipelineLayoutCreateInfo rli{VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO};
        rli.setLayoutCount = 5; rli.pSetLayouts = rsl;
        rli.pushConstantRangeCount = 1; rli.pPushConstantRanges = &rpc;
        VK_CHECK(vkdCreatePipelineLayout(dev, &rli, &mRtReflLayout, "mRtReflLayout"));
        const VkDescriptorSetLayout usl[4] = {mDslDraw0, mDslDraw1, mDslDefer, mRT->consumerLayout()};
        VkPipelineLayoutCreateInfo uli = rli;
        uli.setLayoutCount = 4; uli.pSetLayouts = usl;
        VK_CHECK(vkdCreatePipelineLayout(dev, &uli, &mRtUberLayout, "mRtUberLayout"));
        VkShaderModule tm = moduleFromSpv(dev, kWorldDeferRtTraceSpv, kWorldDeferRtTraceSpv_bytes, "kWorldDeferRtTraceSpv");
        createComputePipelineInto(dev, tm, mRtReflLayout, 0u, litDebugSpec(false), &mRtTracePipe, "mRtTracePipe (DeferRtTrace)");
        destroyShaderModuleDeferred(dev, tm, nullptr);
        // RAY LIST (RenderVKRTReflectionsRayList): the per-tile selection (16) + the per-ray trace
        VkShaderModule sm = moduleFromSpv(dev, kWorldDeferRtSelectSpv, kWorldDeferRtSelectSpv_bytes, "kWorldDeferRtSelectSpv");
        createComputePipelineInto(dev, sm, mRtReflLayout, 0u, litDebugSpec(false), &mRtSelectPipe, "mRtSelectPipe (DeferRtSelect)");
        destroyShaderModuleDeferred(dev, sm, nullptr);
        VkShaderModule lm = moduleFromSpv(dev, kWorldDeferRtTraceListSpv, kWorldDeferRtTraceListSpv_bytes, "kWorldDeferRtTraceListSpv");
        createComputePipelineInto(dev, lm, mRtReflLayout, 0u, litDebugSpec(false), &mRtTraceListPipe,
                                  "mRtTraceListPipe (DeferRtTraceList)");
        destroyShaderModuleDeferred(dev, lm, nullptr);
        // (#1036, RenderVKRTReflectionsShadeSplit) the list trace's split stages (distinct module names:
        // RenderVKPipelineStats logs each one's registers)
        {
            struct Stage { const uint32_t* code; size_t bytes; const char* mod; const char* name; };
            const Stage st[RTS_COUNT] = {
                {kWorldDeferRtSplitTraceSpv, kWorldDeferRtSplitTraceSpv_bytes, "DeferRtSplitTrace", "mRtSplitPipe (DeferRtSplitTrace)"},
                {kWorldDeferRtSplitMatSpv, kWorldDeferRtSplitMatSpv_bytes, "DeferRtSplitMat", "mRtSplitPipe (DeferRtSplitMat)"},
                {kWorldDeferRtSplitLightSpv, kWorldDeferRtSplitLightSpv_bytes, "DeferRtSplitLight", "mRtSplitPipe (DeferRtSplitLight)"}};
            for (uint32_t i = 0; i < RTS_COUNT; ++i)
            {
                VkShaderModule xm = moduleFromSpv(dev, st[i].code, st[i].bytes, st[i].mod);
                createComputePipelineInto(dev, xm, mRtReflLayout, 0u, litDebugSpec(false), &mRtSplitPipe[i], st[i].name);
                destroyShaderModuleDeferred(dev, xm, nullptr);
            }
        }
        visQueueInit(dev, 0u);   // (#1039: the visibility queue's walk + the splits' producer / resolve variants)
        VkShaderModule fm = moduleFromSpv(dev, kWorldDeferRtFwdSpv, kWorldDeferRtFwdSpv_bytes, "kWorldDeferRtFwdSpv");
        createComputePipelineInto(dev, fm, mRtReflLayout, 0u, litDebugSpec(false), &mRtFwdPipe, "mRtFwdPipe (DeferRtFwd)");
        destroyShaderModuleDeferred(dev, fm, nullptr);
        VkShaderModule pm = moduleFromSpv(dev, kWorldDeferRtPreTraceSpv, kWorldDeferRtPreTraceSpv_bytes, "kWorldDeferRtPreTraceSpv");
        createComputePipelineInto(dev, pm, mRtUberLayout, 0u, litDebugSpec(false), &mRtPreTracePipe,
                                  "mRtPreTracePipe (DeferRtPreTrace)");
        destroyShaderModuleDeferred(dev, pm, nullptr);
        // (#860) RT MIRRORS: pass 12 -DCLEAN_RT_MIRROR on the pre-trace's sets + set 4 (the mirror
        // image, one storage binding: its own pool, rewritten with the target behind ensureMirror's
        // device wait).
        if (!mDslRtMirror)
        {
            VkDescriptorSetLayoutBinding mb{};
            mb.binding = 0; mb.descriptorCount = 1; mb.stageFlags = VK_SHADER_STAGE_COMPUTE_BIT;
            mb.descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_IMAGE;
            VkDescriptorSetLayoutCreateInfo ml{VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO};
            ml.bindingCount = 1; ml.pBindings = &mb;
            VK_CHECK(vkdCreateSetLayout(dev, &ml, &mDslRtMirror, "mDslRtMirror"));
            VK_CHECK(mRtMirrorPool.create(dev, "rt mirror", {{mDslRtMirror, 1}}));
            VK_CHECK(mRtMirrorPool.allocate(mDslRtMirror, &mDsetRtMirror));
        }
        const VkDescriptorSetLayout msl[5] = {mDslDraw0, mDslDraw1, mDslDefer, mRT->consumerLayout(), mDslRtMirror};
        VkPipelineLayoutCreateInfo mli = rli;
        mli.setLayoutCount = 5; mli.pSetLayouts = msl;
        VK_CHECK(vkdCreatePipelineLayout(dev, &mli, &mRtMirrorLayout, "mRtMirrorLayout"));
        VkShaderModule mm = moduleFromSpv(dev, kWorldDeferRtMirrorSpv, kWorldDeferRtMirrorSpv_bytes, "kWorldDeferRtMirrorSpv");
        createComputePipelineInto(dev, mm, mRtMirrorLayout, 0u, litDebugSpec(false), &mRtMirrorPipe,
                                  "mRtMirrorPipe (DeferRtMirror)");
        destroyShaderModuleDeferred(dev, mm, nullptr);
        writeRtMirrorDescriptor();   // (an RT target that already exists: the fresh set names it)
    }
    // (#85 phase 2) the diffuse / specular denoiser (set 3 bindings 13-16 name its images or its
    // placeholders in every split frame) + the projector stochastic sampler (pass 15, RT only).
    pdnInit(dev);
}

void LLCleanRendererVK::destroyDeferSplitProj()
{
    if (mDsVisProj.image) { mCtx->destroyImage(mDsVisProj); mDsVisProj = GpuImage{}; }
    mDsProjFull = mDsProjRgb = false;
}

void LLCleanRendererVK::destroyDeferSplitTargets()
{
    for (GpuImage& g : mDsImg)
        if (g.image) { mCtx->destroyImage(g); g = GpuImage{}; }   // (aliased: drops its block reference)
    mDsAliased = false;
    destroyDeferSplitProj();
    mDsW = mDsH = 0;
    mDsReflHalf = false;
    mDsVisReuse = false;
    // (#827 feature split: freed only here, with the rest -- every caller has waited for the device)
    if (mDsGain.image) { mCtx->destroyImage(mDsGain); mDsGain = GpuImage{}; }
    if (mDsTileList.buffer) { mCtx->destroyBuffer(mDsTileList); mDsTileList = GpuBuffer{}; }
    mDsFeatFull = false;
    // (#859) the RT targets; draw set 0 b45 back to the placeholder first (every caller has waited
    // for the device)
    mDsRtMarkFull = false;
    writeRtFwdBinding();
    if (mDsRtMark.image) { mCtx->destroyImage(mDsRtMark); mDsRtMark = GpuImage{}; }
    if (mDsRtTrace.image) { mCtx->destroyImage(mDsRtTrace); mDsRtTrace = GpuImage{}; }
    if (mDsRtFwd.image) { mCtx->destroyImage(mDsRtFwd); mDsRtFwd = GpuImage{}; }
    if (mDsRtHist.image) { mCtx->destroyImage(mDsRtHist); mDsRtHist = GpuImage{}; }
    mDsRtHistFull = mDsRtHistWant = false;
    if (mDsRtTiles.buffer) { mCtx->destroyBuffer(mDsRtTiles); mDsRtTiles = GpuBuffer{}; }
    mDsRtTileCount = 0;
    ++mDsRtEpoch;
    mRtFwdDirty = false;
}

// ensureDeferSplitTargets' early return ("nothing to re-create"), without touching anything.
bool LLCleanRendererVK::deferSplitTargetsMatch(uint32_t rw, uint32_t rh, bool projFull, bool projRgb, bool reflHalf,
                                               bool visReuse, bool feat, bool rtMark) const
{
    if (!mDsetDeferSplit) return false;
    projRgb = projRgb && projFull;
    const bool aliasWant = !mOffscreen && mAlias.enabled() && mScaled;
    const bool featFull = feat || mDsFeatFull;
    bool remake = mDsW != rw || mDsH != rh || aliasWant != mDsAliasWant || (aliasWant && aliasStale(mDsAliasEpoch))
               || reflHalf != mDsReflHalf || visReuse != mDsVisReuse || featFull != mDsFeatFull
               || !mDsGain.image || !mDsTileList.buffer;
    for (const GpuImage& g : mDsImg) remake = remake || !g.image;
    const bool markChange = !mDsRtMark.image || !mDsRtTrace.image || !mDsRtFwd.image || !mDsRtTiles.buffer
                         || mDsRtMarkFull != rtMark || (rtMark && mDsRtTileCount != ((rw + 7u) / 8u) * ((rh + 7u) / 8u))
                         || !mDsRtHist.image || (rtMark && mDsRtHistWant != mRtReflTemporal);
    return !remake && !markChange && mDsVisProj.image && mDsProjFull == projFull && mDsProjRgb == projRgb;
}

// The intermediates at the render extent (mDsVisProj: or the 1x1 placeholder), set 3
// pointed at them. A re-creation waits for the device first: the set and the images may be
// in use by frames in flight. False (VRAM refused, #697): uber until deferSplitFrame retries.
// #615: mDsImg on the alias arena (phase 0, beside the G-buffer) when it takes them; a set
// left on a retired block (or created before RenderVKAliasTargets moved) is re-created.
// feat (#827): the feature split's gain image + tile list at this extent. STICKY: once they are
// full size they stay so through every later call (feat false included) until the targets are
// destroyed -- a live RenderVKDeferredFeatureSplit toggle never frees or re-creates anything.
// rtMark (#859): the RT reflection targets (mark, trace, forward, tile list) at this extent (RT
// reflections wanted), else 1 x 1 / header-only placeholders -- NOT sticky: a stand-down frees them
// after its hold (one device wait per transition, like any re-creation here).
bool LLCleanRendererVK::ensureDeferSplitTargets(uint32_t rw, uint32_t rh, bool projFull, bool projRgb, bool reflHalf,
                                                bool visReuse, bool feat, bool rtMark)
{
    VkMemScope memcat(VKMEM_TARGET);   // #407
    if (!mDsetDeferSplit) return false;
    projRgb = projRgb && projFull;
    // Aliased only below render scale 1 (see the header block at mDslDeferSplit).
    const bool aliasWant = !mOffscreen && mAlias.enabled() && mScaled;
    const bool featFull = feat || mDsFeatFull;   // (sticky; taken before a remake drops mDsFeatFull)
    bool remake = mDsW != rw || mDsH != rh || aliasWant != mDsAliasWant || (aliasWant && aliasStale(mDsAliasEpoch))
               || reflHalf != mDsReflHalf || visReuse != mDsVisReuse || featFull != mDsFeatFull
               || !mDsGain.image || !mDsTileList.buffer;
    for (const GpuImage& g : mDsImg) remake = remake || !g.image;
    const bool markChange = !mDsRtMark.image || !mDsRtTrace.image || !mDsRtFwd.image || !mDsRtTiles.buffer
                         || mDsRtMarkFull != rtMark || (rtMark && mDsRtTileCount != ((rw + 7u) / 8u) * ((rh + 7u) / 8u))   // (#859)
                         || !mDsRtHist.image || (rtMark && mDsRtHistWant != mRtReflTemporal);   // (#859 noise: the history)
    if (!remake && !markChange && mDsVisProj.image && mDsProjFull == projFull && mDsProjRgb == projRgb) return true;
    // (deferSplitTargetsMatch is this early return's twin: keep the two in step)
    VkDevice dev = mCtx->device();
    vkDeviceWaitIdle(dev);
    const VkImageUsageFlags su = VK_IMAGE_USAGE_STORAGE_BIT;
    static const VkFormat kFmt[DS_ALIASED] = {VK_FORMAT_R8G8B8A8_UNORM, VK_FORMAT_R32_UINT, VK_FORMAT_R32_UINT,
                                              VK_FORMAT_R32_UINT, VK_FORMAT_R32G32B32A32_UINT, VK_FORMAT_R32_UINT};
    static const char* kName[DS_ALIASED] = {"deferSplitVisSun", "deferSplitReflIrr", "deferSplitReflSpec",
                                            "deferSplitReflEnv", "deferSplitReflHalf", "deferSplitVisDepth"};
    // Extents: half-resolution reflections keep DS_SPEC (the sharp pixels' word) full size,
    // DS_HALF at ceil(w/2) x ceil(h/2), and the unused DS_IRR / DS_ENV as 1 x 1 placeholders
    // (bound, never read); off, DS_HALF is the placeholder.
    uint32_t ew[DS_ALIASED], eh[DS_ALIASED];
    for (uint32_t i = 0; i < DS_ALIASED; ++i) { ew[i] = rw; eh[i] = rh; }
    if (reflHalf)
    {
        ew[DS_IRR] = eh[DS_IRR] = ew[DS_ENV] = eh[DS_ENV] = 1u;
        ew[DS_HALF] = (rw + 1u) / 2u; eh[DS_HALF] = (rh + 1u) / 2u;
    }
    else
        ew[DS_HALF] = eh[DS_HALF] = 1u;
    if (!visReuse) ew[DS_VDEPTH] = eh[DS_VDEPTH] = 1u;   // (visibility reuse off: placeholder)
    if (remake)
    {
        destroyDeferSplitTargets();
        mDsAliasWant = aliasWant;
        if (!aliasWant) mAlias.forget(AS_DSPLIT0, DS_ALIASED);   // (no region kept for them)
        else
        {
            VkAliasArena::Desc ad[DS_ALIASED];
            for (uint32_t i = 0; i < DS_ALIASED; ++i)
            {
                ad[i].slot = AS_DSPLIT0 + i; ad[i].w = ew[i]; ad[i].h = eh[i];
                ad[i].format = kFmt[i]; ad[i].usage = su; ad[i].aspect = VK_IMAGE_ASPECT_COLOR_BIT;
            }
            mDsAliased = mAlias.create(*mCtx, ad, DS_ALIASED, mDsImg);
            logAlias("split lighting intermediates", mDsAliased);
        }
        for (uint32_t i = 0; i < DS_ALIASED; ++i)
        {
            if (!mDsAliased) mDsImg[i] = mCtx->createImage2D(ew[i], eh[i], kFmt[i], su, VK_IMAGE_ASPECT_COLOR_BIT);
            if (!mDsImg[i].image) { destroyDeferSplitTargets(); return false; }
            mCtx->setObjectName(VK_OBJECT_TYPE_IMAGE, (uint64_t)mDsImg[i].image, kName[i]);
        }
        mDsAliasEpoch = mAlias.epoch();
        mDsW = rw; mDsH = rh;
        mDsReflHalf = reflHalf;
        mDsVisReuse = visReuse;
        // FEATURE SPLIT (#827): the local gain (R32F, render extent) and the tile list (dispatch
        // header + one uint per 16 px tile); placeholders (1 x 1, the 16 B header) until asked for.
        const uint32_t tiles = featFull ? ((rw + 15u) / 16u) * ((rh + 15u) / 16u) : 0u;
        mDsGain = mCtx->createImage2D(featFull ? rw : 1u, featFull ? rh : 1u, VK_FORMAT_R32_SFLOAT, su,
                                      VK_IMAGE_ASPECT_COLOR_BIT);
        mDsTileList = mCtx->createBuffer(16u + (VkDeviceSize)tiles * sizeof(uint32_t),
                                         VK_BUFFER_USAGE_STORAGE_BUFFER_BIT | VK_BUFFER_USAGE_INDIRECT_BUFFER_BIT
                                         | VK_BUFFER_USAGE_TRANSFER_DST_BIT, VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);
        if (!mDsGain.image || !mDsTileList.buffer) { destroyDeferSplitTargets(); return false; }
        mCtx->setObjectName(VK_OBJECT_TYPE_IMAGE, (uint64_t)mDsGain.image, "deferFeatLocalGain");
        mCtx->setObjectName(VK_OBJECT_TYPE_BUFFER, (uint64_t)mDsTileList.buffer, "deferFeatTileList");
        mDsFeatFull = featFull;
    }
    else
    {
        destroyDeferSplitProj();
    }
    // Projector slots: R32UI layers (0 ids, 1..3 R / G / B bytes; mono: 2 layers).
    const uint32_t layers = projFull ? (projRgb ? 4u : 2u) : 1u;
    mDsVisProj = mCtx->createImageLayers(projFull ? rw : 1u, projFull ? rh : 1u, layers, 1, VK_FORMAT_R32_UINT, su,
                                         VK_IMAGE_ASPECT_COLOR_BIT, false, VK_IMAGE_VIEW_TYPE_2D_ARRAY);
    if (!mDsVisProj.image)
    {
        destroyDeferSplitTargets();
        return false;
    }
    mCtx->setObjectName(VK_OBJECT_TYPE_IMAGE, (uint64_t)mDsVisProj.image, "deferSplitVisProj");
    mDsProjFull = projFull;
    mDsProjRgb = projRgb;
    // (#859) The RT reflection targets: render extent while RT reflections are wanted, else 1 x 1 /
    // header-only placeholders (bound, statically used by the reflect kernels, never read).
    if (markChange)
    {
        auto dropRt = [&]()
        {
            mDsRtMarkFull = false;
            writeRtFwdBinding();   // (draw set 0 b45 -> the placeholder before the image goes)
            if (mDsRtMark.image) { mCtx->destroyImage(mDsRtMark); mDsRtMark = GpuImage{}; }
            if (mDsRtTrace.image) { mCtx->destroyImage(mDsRtTrace); mDsRtTrace = GpuImage{}; }
            if (mDsRtFwd.image) { mCtx->destroyImage(mDsRtFwd); mDsRtFwd = GpuImage{}; }
            if (mDsRtHist.image) { mCtx->destroyImage(mDsRtHist); mDsRtHist = GpuImage{}; }
            mDsRtHistFull = mDsRtHistWant = false;
            if (mDsRtTiles.buffer) { mCtx->destroyBuffer(mDsRtTiles); mDsRtTiles = GpuBuffer{}; }
            mDsRtTileCount = 0;
            ++mDsRtEpoch;   // (#870: the RR guide set names them)
        };
        auto makeRt = [&](bool full) -> bool
        {
            const uint32_t w = full ? rw : 1u, h = full ? rh : 1u;
            const uint32_t fw = full ? (rw + 1u) / 2u : 1u, fh = full ? (rh + 1u) / 2u : 1u;
            const uint32_t tiles = full ? ((rw + 7u) / 8u) * ((rh + 7u) / 8u) : 1u;
            VkDeviceContext::SoftAllocScope soft(mCtx, full);   // (a refused full set: the placeholders)
            mDsRtMark = mCtx->createImage2D(w, h, VK_FORMAT_R32G32B32A32_UINT, su, VK_IMAGE_ASPECT_COLOR_BIT);
            if (mDsRtMark.image)
                mDsRtTrace = mCtx->createImage2D(w, h, VK_FORMAT_R16G16B16A16_SFLOAT, su, VK_IMAGE_ASPECT_COLOR_BIT);
            if (mDsRtTrace.image)
                mDsRtFwd = mCtx->createImage2D(fw, fh, VK_FORMAT_R16G16B16A16_SFLOAT,
                                               su | VK_IMAGE_USAGE_SAMPLED_BIT | VK_IMAGE_USAGE_TRANSFER_DST_BIT,
                                               VK_IMAGE_ASPECT_COLOR_BIT);
            // (#859 noise) the resolve's TEMPORAL history: two RGBA16F layers (ping-pong by the tile list
            // parity) at the render extent while RenderVKRTReflectionsTemporal, else 1 x 1 x 2. A refused
            // full history (#697: VRAM) takes the placeholder -- RT reflections without history, never
            // RT reflections off; mDsRtHistWant (what was asked) keeps it from re-asking every frame.
            bool histFull = full && mRtReflTemporal;
            mDsRtHistWant = histFull;
            if (mDsRtFwd.image)
            {
                mDsRtHist = mCtx->createImageLayers(histFull ? rw : 1u, histFull ? rh : 1u, 2, 1, VK_FORMAT_R16G16B16A16_SFLOAT,
                                                    su | VK_IMAGE_USAGE_TRANSFER_DST_BIT, VK_IMAGE_ASPECT_COLOR_BIT, false,
                                                    VK_IMAGE_VIEW_TYPE_2D_ARRAY);
                if (!mDsRtHist.image && histFull)
                {
                    LL_WARNS("Vulkan") << "RT reflections: temporal history " << rw << "x" << rh
                                       << " refused (VRAM); reflections without history" << LL_ENDL;
                    histFull = false;
                    mDsRtHist = mCtx->createImageLayers(1u, 1u, 2, 1, VK_FORMAT_R16G16B16A16_SFLOAT,
                                                        su | VK_IMAGE_USAGE_TRANSFER_DST_BIT, VK_IMAGE_ASPECT_COLOR_BIT, false,
                                                        VK_IMAGE_VIEW_TYPE_2D_ARRAY);
                }
            }
            if (mDsRtHist.image)
                // (the tile flags + list + the listed count, then the RAY LIST: 7 words of count /
                // dispatch / capacity / pad, 64 entries per tile -- clean_deferred_light.comp RAY LIST)
                mDsRtTiles = mCtx->createBuffer(kRtTilesHdrBytes + ((VkDeviceSize)tiles * 2u + 1u) * sizeof(uint32_t)
                                                + (7u + (VkDeviceSize)tiles * 64u) * sizeof(uint32_t),
                                                VK_BUFFER_USAGE_STORAGE_BUFFER_BIT | VK_BUFFER_USAGE_INDIRECT_BUFFER_BIT
                                                | VK_BUFFER_USAGE_TRANSFER_DST_BIT | VK_BUFFER_USAGE_TRANSFER_SRC_BIT,
                                                VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);
            if (!mDsRtTiles.buffer) { dropRt(); return false; }
            mDsRtTileCount = full ? tiles : 0u;
            ++mDsRtEpoch;
            mCtx->setObjectName(VK_OBJECT_TYPE_IMAGE, (uint64_t)mDsRtMark.image, "deferSplitRtReflMark");
            mCtx->setObjectName(VK_OBJECT_TYPE_IMAGE, (uint64_t)mDsRtTrace.image, "deferSplitRtReflTrace");
            mCtx->setObjectName(VK_OBJECT_TYPE_IMAGE, (uint64_t)mDsRtFwd.image, "deferSplitRtReflFwd");
            mCtx->setObjectName(VK_OBJECT_TYPE_IMAGE, (uint64_t)mDsRtHist.image, "deferSplitRtReflHist");
            mCtx->setObjectName(VK_OBJECT_TYPE_BUFFER, (uint64_t)mDsRtTiles.buffer, "deferSplitRtReflTiles");
            // Every image GENERAL (the descriptors' layout; the reflect kernels declare them all), the
            // forward reflections zero (the forward FS reads them every frame), the list header empty.
            mCtx->submitImmediate([&](VkCommandBuffer c){
                VkImageMemoryBarrier2 b[4]{};
                const VkImage im[4] = {mDsRtMark.image, mDsRtTrace.image, mDsRtFwd.image, mDsRtHist.image};
                for (int k = 0; k < 4; ++k)
                {
                    b[k].sType = VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER_2;
                    b[k].srcStageMask = VK_PIPELINE_STAGE_2_TOP_OF_PIPE_BIT;
                    b[k].dstStageMask = VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT;
                    b[k].dstAccessMask = VK_ACCESS_2_MEMORY_READ_BIT | VK_ACCESS_2_MEMORY_WRITE_BIT;
                    b[k].oldLayout = VK_IMAGE_LAYOUT_UNDEFINED; b[k].newLayout = VK_IMAGE_LAYOUT_GENERAL;
                    b[k].image = im[k];
                    b[k].subresourceRange = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, k == 3 ? 2u : 1u};
                }
                VkDependencyInfo d{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
                d.imageMemoryBarrierCount = 4; d.pImageMemoryBarriers = b;
                vkCmdPipelineBarrier2(c, &d);
                const VkClearColorValue zero{};
                const VkImageSubresourceRange rr{VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 1};
                vkCmdClearColorImage(c, mDsRtFwd.image, VK_IMAGE_LAYOUT_GENERAL, &zero, 1, &rr);
                // (the history: view depth 0 = no history anywhere)
                const VkImageSubresourceRange hr{VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 2};
                vkCmdClearColorImage(c, mDsRtHist.image, VK_IMAGE_LAYOUT_GENERAL, &zero, 1, &hr);
                const uint32_t hdr[4] = {0u, 0u, 1u, mDsRtTileCount};
                vkCmdUpdateBuffer(c, mDsRtTiles.buffer, 0, sizeof(hdr), hdr);
                vkCmdFillBuffer(c, mDsRtTiles.buffer, 16u, VK_WHOLE_SIZE, 0u);   // (+ the rest of the header)
            });
            mDsRtMarkFull = full;
            mDsRtHistFull = histFull;
            mRtFwdDirty = false;
            return true;
        };
        dropRt();
        bool ok = makeRt(rtMark);
        if (!ok && rtMark)
        {
            // VRAM refused (#697): the placeholders, RT reflections off until a retry (backoff: no
            // device wait per frame).
            mRtReflRetryAt = dsClock() + kDsRetryMaxSecs;
            LL_WARNS("Vulkan") << "RT reflections: targets " << rw << "x" << rh << " refused (VRAM); probe fallback, retry in "
                               << kDsRetryMaxSecs << " s" << LL_ENDL;
            ok = makeRt(false);
        }
        if (!ok)
        {
            destroyDeferSplitTargets();
            return false;
        }
        writeRtFwdBinding();
    }
    // set 3 bindings: 0 sun, 1 projector slots, 2..4 irradiance / radiance / env, 5 half-res reflections,
    // 6 visibility-reuse depth, 7 the #827 local gain (images); 8 the #827 tile list (buffer)
    VkDescriptorImageInfo ii[kDsBindings]{};
    VkWriteDescriptorSet wr[kDsBindings]{};
    const VkImageView views[kDsBindingGain + 1u] = {mDsImg[DS_SUN].view, mDsVisProj.view, mDsImg[DS_IRR].view,
                                                    mDsImg[DS_SPEC].view, mDsImg[DS_ENV].view, mDsImg[DS_HALF].view,
                                                    mDsImg[DS_VDEPTH].view, mDsGain.view};
    for (uint32_t i = 0; i <= kDsBindingGain; ++i)
    {
        ii[i].imageView = views[i];
        ii[i].imageLayout = VK_IMAGE_LAYOUT_GENERAL;
        wr[i].sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET; wr[i].dstSet = mDsetDeferSplit; wr[i].dstBinding = i;
        wr[i].descriptorCount = 1; wr[i].pImageInfo = &ii[i]; wr[i].descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_IMAGE;
    }
    const VkDescriptorBufferInfo tbi{mDsTileList.buffer, 0, VK_WHOLE_SIZE};
    wr[kDsBindingTiles].sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET; wr[kDsBindingTiles].dstSet = mDsetDeferSplit;
    wr[kDsBindingTiles].dstBinding = kDsBindingTiles; wr[kDsBindingTiles].descriptorCount = 1;
    wr[kDsBindingTiles].descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_BUFFER; wr[kDsBindingTiles].pBufferInfo = &tbi;
    // (#859) bindings 9-12: the RT reflection mark, tile list, trace, forward reflections
    const VkImageView rtViews[4] = {mDsRtMark.view, VK_NULL_HANDLE, mDsRtTrace.view, mDsRtFwd.view};
    for (uint32_t k = 0; k < 4; ++k)
    {
        const uint32_t bi = kDsBindingRtMark + k;
        wr[bi].sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET; wr[bi].dstSet = mDsetDeferSplit;
        wr[bi].dstBinding = bi; wr[bi].descriptorCount = 1;
        if (bi == kDsBindingRtTiles) continue;
        ii[bi].imageView = rtViews[k];
        ii[bi].imageLayout = VK_IMAGE_LAYOUT_GENERAL;
        wr[bi].pImageInfo = &ii[bi];
        wr[bi].descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_IMAGE;
    }
    const VkDescriptorBufferInfo rtbi{mDsRtTiles.buffer, 0, VK_WHOLE_SIZE};
    wr[kDsBindingRtTiles].descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_BUFFER; wr[kDsBindingRtTiles].pBufferInfo = &rtbi;
    vkUpdateDescriptorSets(dev, kDsBindingPdnIn, wr, 0, nullptr);
    {
        // (#859 noise) binding 24: the RT reflection temporal history (its 1 x 1 x 2 placeholder too)
        VkDescriptorImageInfo hi{VK_NULL_HANDLE, mDsRtHist.view, VK_IMAGE_LAYOUT_GENERAL};
        VkWriteDescriptorSet hw{VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET};
        hw.dstSet = mDsetDeferSplit; hw.dstBinding = kDsBindingRtHist; hw.descriptorCount = 1;
        hw.descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_IMAGE; hw.pImageInfo = &hi;
        if (mDsRtHist.view) vkUpdateDescriptorSets(dev, 1, &hw, 0, nullptr);
    }
    writePdnBindings();   // (#85 phase 2) 13-16: the denoiser's images / placeholders
    // ... and draw set 0 bindings 41-43 (visibility reuse: sun, projector slots, depth) to the
    // same images (the device is idle; PARTIALLY_BOUND, so a stale write while unused is fine).
    if (mDsetDraw0)
    {
        const uint32_t src[3] = {0u, 1u, 6u};   // views[] / set 3 binding of each
        VkWriteDescriptorSet dw[3]{};
        for (uint32_t i = 0; i < 3; ++i)
        {
            dw[i] = wr[src[i]];
            dw[i].dstSet = mDsetDraw0; dw[i].dstBinding = 41u + i;
        }
        vkUpdateDescriptorSets(dev, 3, dw, 0, nullptr);
    }
    const double px = (double)rw * rh;
    // sun 4 B + reflections (full: irr / spec / env 12 B; half: the sharp word 4 B + 16 B per block)
    const double reflB = mDsReflHalf ? px * 4.0 + (double)((rw + 1u) / 2u) * ((rh + 1u) / 2u) * 16.0 : px * 12.0;
    const double mb = (px * 4.0 + reflB + (mDsVisReuse ? px * 4.0 : 0.0) + (projFull ? px * 4.0 * layers : 0.0)
                       + (mDsFeatFull ? px * 4.0 : 0.0) + (mDsRtMarkFull ? px * 26.0 : 0.0) + (mDsRtHistFull ? px * 16.0 : 0.0)) / (1024.0 * 1024.0);
    LL_INFOS("Vulkan") << "VKDeferSplit: intermediates " << rw << "x" << rh << " (" << (S32)(mb + 0.5) << " MB"
                       << (mDsReflHalf ? "; half-resolution reflections" : "; full-resolution reflections")
                       << (mDsVisReuse ? "; visibility reuse depth" : "")
                       << (mDsFeatFull ? "; feature split gain + tile list" : "")
                       << (mDsRtMarkFull ? "; RT reflection mark / trace / forward targets" : "")
                       << (mDsRtHistFull ? " + temporal history" : "")
                       << (mDsAliased ? "; sun + reflection on the #615 alias arena" : "")
                       << (projFull ? (projRgb ? ", with colour projector slots" : ", with mono projector slots")
                                    : ", no projector slots") << ")" << LL_ENDL;
    return true;
}

void LLCleanRendererVK::destroyDeferSplit()
{
    if (!mCtx) return;
    VkDevice dev = mCtx->device();
    for (VkPipeline& q : mDeferSplitPipe)
        if (q) { vkDestroyPipeline(dev, q, nullptr); q = VK_NULL_HANDLE; }
    mDeferSplitOk = false;
    for (VkPipeline& q : mDeferFeatPipe)
        if (q) { vkDestroyPipeline(dev, q, nullptr); q = VK_NULL_HANDLE; }
    mDeferFeatOk = false;
    mDeferFeatNow = false;
    pdnDestroy();   // (#85 phase 2: pass 15 + the denoiser; before the RT layout goes)
    // (#859) the RT reflection kernels + their targets / placeholders
    for (VkPipeline* q : {&mRtTracePipe, &mRtSelectPipe, &mRtTraceListPipe, &mRtFwdPipe, &mRtResolvePipe, &mRtPreTracePipe})
        if (*q) { vkDestroyPipeline(dev, *q, nullptr); *q = VK_NULL_HANDLE; }
    for (VkPipeline& q : mRtSplitPipe)   // (#1036)
        if (q) { vkDestroyPipeline(dev, q, nullptr); q = VK_NULL_HANDLE; }
    visQueueDestroy();   // (#1039 M1)
    if (mRtRec.buffer) { mCtx->destroyBuffer(mRtRec); mRtRec = GpuBuffer{}; }
    mRtRecCap = 0;
    mRtSplitNow = false;
    if (mRtReflLayout) { vkDestroyPipelineLayout(dev, mRtReflLayout, nullptr); mRtReflLayout = VK_NULL_HANDLE; }
    if (mRtUberLayout) { vkDestroyPipelineLayout(dev, mRtUberLayout, nullptr); mRtUberLayout = VK_NULL_HANDLE; }
    // (#860) the RT mirror kernel + its set (the target is the mirror's: ensureMirror owns it). A mirror
    // target left in the RT mode keeps its last image; the next frame's mode falls back to planar.
    if (mRtMirrorPipe) { vkDestroyPipeline(dev, mRtMirrorPipe, nullptr); mRtMirrorPipe = VK_NULL_HANDLE; }
    if (mRtMirrorLayout) { vkDestroyPipelineLayout(dev, mRtMirrorLayout, nullptr); mRtMirrorLayout = VK_NULL_HANDLE; }
    mRtMirrorPool.destroy();
    mDsetRtMirror = VK_NULL_HANDLE;
    if (mDslRtMirror) { vkdDestroySetLayout(dev, mDslRtMirror); mDslRtMirror = VK_NULL_HANDLE; }
    mRtMirrorNow = false;
    mRtReflNow = mRtFwdNow = mRtUberNow = false;
    destroyDeferSplitTargets();
    if (mRtUber.image) { mCtx->destroyImage(mRtUber); mRtUber = GpuImage{}; }
    mRtUberFull = false;
    if (mRtFwdPlaceholder.image) { mCtx->destroyImage(mRtFwdPlaceholder); mRtFwdPlaceholder = GpuImage{}; }
    if (mDeferSplitLayout) { vkDestroyPipelineLayout(dev, mDeferSplitLayout, nullptr); mDeferSplitLayout = VK_NULL_HANDLE; }
    mDeferSplitPool.destroy();
    mDsetDeferSplit = VK_NULL_HANDLE;
    if (mDslDeferSplit) { vkdDestroySetLayout(dev, mDslDeferSplit); mDslDeferSplit = VK_NULL_HANDLE; }
    mDeferSplitNow = false;
    mDsRetryAt = 0.0;
    mDsAllocFails = 0;
    mDsReq = DsReq{};
}

// (#824) SPLIT VS UBER PER GPU CLASS. RenderVKDeferredSplit 2 (AUTO, the default) decides once
// per session from the device: the split (shadow / reflection resolves + combine, or the #827
// feature split) where the GPU has hardware ray tracing (Turing / RDNA2 / Arc and newer: the
// split was tuned on an RTX 5090, ~20-25 % under the uber kernel there, and the RT paths --
// merged RT shadows #195, projector stochastic #85, hybrid RT reflections #859 -- need it), the
// UBER kernel everywhere else (Pascal, Maxwell, Polaris / Vega / RDNA1, integrated without RT:
// on a GTX 1080 at 4K the uber kernel measured 0.7 ms faster at Firestorm-equivalent settings
// and 2.0 ms at high, because the split's extra passes re-decode the G-buffer and its combine
// runs at the uber kernel's ~126 registers anyway). 0 / 1 written by the user always win (the
// setting persists only when it differs from the AUTO default). The GPU class is the device
// tier llappviewer.cpp computes at Vulkan init (LLFeatureManager::setVulkanGPU); hardware RT is
// the deciding bit because the class conflates VRAM with architecture (a GTX 1080 and an RTX
// 2060 can share a class).
uint32_t LLCleanRendererVK::deferSplitMode() const
{
    U32 mode = 2;
#if defined(LL_HAS_CLEAN_PIPELINE)
    static LLCachedControl<U32> s_mode(gSavedSettings, "RenderVKDeferredSplit", 2);
    mode = s_mode;
#endif
    if (mode <= 1u) return mode;
    if (mDeferSplitAuto < 0)
    {
        bool hwRt = false;
        S32 cls = -1;
#if defined(LL_HAS_CLEAN_PIPELINE)
        cls = (S32)LLFeatureManager::getInstance()->getGPUClass();
#endif
        // (LLVulkanContext::supportsHardwareRayTracing's test: acceleration structures + ray query)
        if (mCtx && mCtx->physicalDevice() != VK_NULL_HANDLE)
        {
            uint32_t n = 0;
            vkEnumerateDeviceExtensionProperties(mCtx->physicalDevice(), nullptr, &n, nullptr);
            std::vector<VkExtensionProperties> exts(n);
            vkEnumerateDeviceExtensionProperties(mCtx->physicalDevice(), nullptr, &n, exts.data());
            bool accel = false, query = false;
            for (const VkExtensionProperties& e : exts)
            {
                if (std::strcmp(e.extensionName, VK_KHR_ACCELERATION_STRUCTURE_EXTENSION_NAME) == 0) accel = true;
                if (std::strcmp(e.extensionName, VK_KHR_RAY_QUERY_EXTENSION_NAME) == 0) query = true;
            }
            hwRt = accel && query;
        }
        mDeferSplitAuto = hwRt ? 1 : 0;
        LL_INFOS("Vulkan") << "VKDeferSplit: RenderVKDeferredSplit 2 (auto): GPU class " << cls << ", hardware RT "
                           << (hwRt ? "yes" : "no") << " -> " << (mDeferSplitAuto ? "SPLIT" : "UBER")
                           << " deferred lighting (set 0 / 1 to override)" << LL_ENDL;
    }
    return (uint32_t)mDeferSplitAuto;
}

void LLCleanRendererVK::deferSplitFrame(bool deferred, uint32_t rw, uint32_t rh)
{
    U32 mode = 1;
    bool lightingOn = true;
    bool reflHalf = true;
    F32 sharpRough = 0.25f;
    bool visReuse = true;
    bool featSplit = true;
#if defined(LL_HAS_CLEAN_PIPELINE)
    static LLCachedControl<bool> s_feat(gSavedSettings, "RenderVKDeferredFeatureSplit", true);   // #827
    static LLCachedControl<bool> s_defer(gSavedSettings, "RenderVKDeferredLighting", true);
    static LLCachedControl<bool> s_half(gSavedSettings, "RenderVKDeferReflectHalfRes", true);
    static LLCachedControl<F32>  s_sharp(gSavedSettings, "RenderVKDeferReflectSharpRough", 0.25f);
    static LLCachedControl<bool> s_visr(gSavedSettings, "RenderVKDeferVisReuse", true);
    lightingOn = s_defer;
    reflHalf = s_half;
    sharpRough = s_sharp;
    visReuse = s_visr;
    featSplit = s_feat;
#endif
    mode = deferSplitMode();   // (#824: 2 = auto, resolved per GPU class)
    const bool split = mode != 0u;
    // FEATURE SPLIT (#827): asked for with its kernels built; its targets then stay (sticky).
    const bool featWant = featSplit && mDeferFeatOk;
    const double now = dsClock();
    // HYBRID RT REFLECTIONS (#859): the targets exist while wanted (setting, deferred, RT up, no
    // stand-down); this frame marks + traces only with a valid, warm TLAS (a cold one would trace
    // an almost empty scene: every ray a miss -- harmless, the probe stays, but a pop).
    rtReflSettings();
    const float rtRough = mRtReflRough;
    const bool rtrWant = rtReflWanted() && now >= mRtReflRetryAt;
    // The mark stays allocated kRtReflHoldSecs past the last frame that wanted it: a stand-down
    // reason flickering at its threshold must not re-create it (a device wait) every frame.
    if (rtrWant) mRtReflLastWant = now;
    const bool rtrAlloc = rtrWant || (mDsRtMarkFull && now - mRtReflLastWant < kRtReflHoldSecs);
    mRtReflNow = false;
    // The intermediates: projector slots at full size while the frame has shadowed projector
    // records (+ kDsProjHoldSecs of hysteresis against projectors drifting in and out of view).
    const bool proj = mProjActive > 0u && mProjMode != 0u;   // (lights carry tex.z only then)
    if (proj) mDsLastProj = now;
    bool dsQueued = false;   // (a re-creation is requested for deferSplitPrestep: this frame changes nothing)
    if (split && deferred && mDeferSplitOk && now >= mDsRetryAt)
    {
        const bool projFull = proj || (mDsProjFull && now - mDsLastProj < kDsProjHoldSecs);
        // Colour planes only where the projector visibility can be coloured: RT-traced
        // projectors (the mask's rgb) or the #212 projector translucency layer; map
        // projectors without it are grey (2 layers, half the bytes). Held through the
        // hysteresis like projFull.
        const bool projRgb = proj ? (mProjMode == 2u || projTransOn()) : mDsProjRgb;
        // (2026-10-22, the Beta 5 DEVICE_LOST fix) A re-creation is only REQUESTED here: this runs
        // inside the recording, after draw set 0 was bound (volumetric clouds, weather passes), and the
        // re-creation rewrites set 0 b41-43 / b48 and set 3 behind a device wait that does not
        // cover this frame's recorded commands. deferSplitPrestep applies it before the next
        // recording begins; this frame lights with the uber kernel (the #697 refusal path).
        bool splitReady;
        if (resizeAtFrameStart()
            && !deferSplitTargetsMatch(rw, rh, projFull, projRgb, reflHalf, visReuse, featWant, rtrAlloc))
        {
            mDsReq = DsReq{};
            mDsReq.pending = true;
            mDsReq.rw = rw; mDsReq.rh = rh;
            mDsReq.projFull = projFull; mDsReq.projRgb = projRgb; mDsReq.reflHalf = reflHalf;
            mDsReq.visReuse = visReuse; mDsReq.feat = featWant; mDsReq.rtMark = rtrAlloc;
            dsQueued = true;
            splitReady = false;
        }
        else
            splitReady = deferSplitApply(rw, rh, projFull, projRgb, reflHalf, visReuse, featWant, rtrAlloc);
        if (splitReady)
        {
            mDeferSplitNow = true;
            mDeferFeatNow = featWant && mDsFeatFull;
            // (clean_deferred_light.comp DEFER_FLAG_PROJ / DEFER_FLAG_PROJ_RGB)
            mDeferSplitFlags = proj ? (1u | (mDsProjRgb ? 2u : 0u)) : 0u;
            // DEFER_FLAG_REFL_HALF + the sharp roughness byte. Floor 0.11: PBR SSR (roughness
            // <= 0.1) always stays in the per-pixel class. (#859) While the RT reflection mark
            // exists, at least its roughness threshold: every RT candidate is a per-pixel (sharp)
            // pixel of pass 5, which marks it (stable with the mark, not with this frame's TLAS).
            if (mDsRtMarkFull) sharpRough = std::max(sharpRough, rtRough);
            if (mDsReflHalf)
                mDeferSplitFlags |= 4u | ((U32)(llclamp(sharpRough, 0.11f, 1.f) * 255.f + 0.5f) << 8);
            // (#859) DEFER_FLAG_RT_MARK + the threshold byte: this frame traces.
            mRtReflNow = rtrWant && mDsRtMarkFull && mRtTracePipe && mRtResolvePipe && mRT && mRT->tlasValid()
                      && mRT->sunReady() && mRT->consumerSet() != VK_NULL_HANDLE;
            if (mRtReflNow)
                mDeferSplitFlags |= (1u << 16) | ((U32)(rtRough * 255.f + 0.5f) << 24);
            // RenderVKDebugView 28 (the RT reflection ray density): the combine draws it on every
            // pixel, so the plain split (LOCAL would add its lights over the heat map).
            if (mRtReflNow && mRtReflDebugView) mDeferFeatNow = false;
            // RT FORWARD (RenderVKRTReflectionsForward): the forward / water layer's reflections.
            bool rtrFwd = true;
#if defined(LL_HAS_CLEAN_PIPELINE)
            static LLCachedControl<bool> s_rtr_fwd(gSavedSettings, "RenderVKRTReflectionsForward", true);
            rtrFwd = s_rtr_fwd;
#endif
            mRtFwdNow = mRtReflNow && mRtFwdPipe && rtrFwd;
            // (#85 phase 2) PROJECTOR STOCHASTIC + DENOISED (RenderVKProjStochastic): the denoiser's
            // images and this frame's DEFER_FLAG_PSTOCH bits. A debug view keeps the plain split
            // (its combine shows it on every pixel; LOCAL only touches listed tiles).
            pdnFrame(rw, rh);
            if (mPdnNow)
            {
                mDeferSplitFlags |= mPdnFlags;
                if (mPdnDebug != 0u) mDeferFeatNow = false;
            }
            if (mGiNow && mGiDebug != 0u)
            {   // (#87 RenderVKGIDebug: the combine shows it on every pixel)
                mDeferFeatNow = false;
            }
            // Visibility reuse: the shadow pass writes DS_VDEPTH (DEFER_FLAG_VIS_REUSE), pass 2's
            // LIT_ALPHA FS reads it + the sun / projector buffers (VISR_ON / _PROJ / _PROJ_RGB).
            if (mDsVisReuse)
            {
                mDeferSplitFlags |= 8u;
                mVisReuseFlags = 1u | ((mDeferSplitFlags & 1u) ? 2u : 0u) | ((mDeferSplitFlags & 2u) ? 4u : 0u);
            }
        }
        // (not ready and not queued: refused -- deferSplitApply's #697 backoff; these frames light
        // with the uber kernel)
    }
    // Free the intermediates only when the split is switched off (RenderVKDeferredSplit 0)
    // or deferred lighting itself is (RenderVKDeferredLighting 0) -- and then their arena
    // slots are forgotten (the next block plan reserves nothing for them). Temporary uber /
    // forward frames (debug views, forward fallbacks) keep them. An unused set left on a
    // retired alias block goes at once too (it would hold that whole block; its slots stay
    // planned: it comes back at that size).
    // (A frame that queued a re-creation leaves all of this alone: deferSplitPrestep re-creates them
    // before the next recording, which decides again.)
    if (!mDeferSplitNow && !dsQueued)
    {
        const bool unused = !split || !lightingOn;
        // (#85 phase 2: nothing samples without the split; the images go after the hold.) #195 + #85:
        // a frame the merged RT shadow pass wants but cannot run yet (no denoiser sun images: the
        // first frame, a forward frame without a mask) allocates them, so the next one can merge.
        if (!unused && !mOffscreen && shadowMergeWanted(false)) pdnFrame(rw, rh, false);
        else pdnIdle();
        if (mDsImg[DS_SUN].image && (unused || (mDsAliased && aliasStale(mDsAliasEpoch))))
        {
            if (resizeAtFrameStart())
            {
                // (2026-10-22) freed before the next recording (deferSplitPrestep), not under this one:
                // set 0 b41-43 / b48 and set 3 name these images and set 0 is bound already
                mDsReq = DsReq{};
                mDsReq.pending = true;
                mDsReq.free = true;
                mDsReq.unused = unused;
            }
            else
            {
                vkDeviceWaitIdle(mCtx->device());
                destroyDeferSplitTargets();
                if (unused) LL_INFOS("Vulkan") << "VKDeferSplit: intermediates freed (split lighting off)" << LL_ENDL;
                if (unused) mAlias.forget(AS_DSPLIT0, DS_ALIASED);
            }
        }
        else if (unused) mAlias.forget(AS_DSPLIT0, DS_ALIASED);   // (idempotent; also after a stale drop)
    }
    rtSplitDecide(rw, rh, now);   // (#1036: after this frame's mRtReflNow)
    // (#859) UBER frames (deferred, not split -- RenderVKDeferredSplit 0, a retry backoff): the
    // pre-trace target at the render extent while wanted (held like the split's), else 1 x 1.
    // Not on a frame that queued the split's re-creation (it would allocate the uber target for
    // that one frame).
    if (!dsQueued)
    {
        const bool uberWant = rtrWant && deferred && !mDeferSplitNow && mRtPreTracePipe;
        const bool uberAlloc = uberWant || (mRtUberFull && now - mRtReflLastWant < kRtReflHoldSecs);
        mRtUberNow = false;
        if (rtUberAtFrameStart(rw, rh, uberAlloc) && uberWant && mRtUberFull && mRT && mRT->tlasValid() && mRT->sunReady()
            && mRT->consumerSet() != VK_NULL_HANDLE)
            mRtUberNow = true;
    }
    // Path change: one log line.
    static int s_logged = -1;
    const int path = mDeferSplitNow ? (mDeferFeatNow ? 2 : 1) : 0;
    if (deferred && path != s_logged && !dsQueued)   // (a queued re-creation's one uber frame: no line)
    {
        s_logged = path;
        LL_INFOS("Vulkan") << "VKDeferSplit: deferred lighting runs "
                           << (path == 2 ? "SPLIT + FEATURE SPLIT (tile classify + shadow + reflect -> base -> local lights"
                                           " over the lit tiles)"
                               : path == 1 ? "SPLIT (shadow + reflect + combine)" : "the UBER kernel")
                           << " (RenderVKDeferredSplit " << mode << ", RenderVKDeferredFeatureSplit " << (featSplit ? 1 : 0)
                           << (featSplit && !mDeferFeatOk ? ": its pipelines are missing" : "") << ")" << LL_ENDL;
    }
}

// ensureDeferSplitTargets + the allocation-failure policy (#697): VRAM refused -- never a crash,
// never a path switch for good. Those frames light with the uber kernel (it needs no
// intermediates); the allocation is retried with a backoff (each attempt waits for the device
// idle: kDsRetrySecs doubling up to kDsRetryMaxSecs).
bool LLCleanRendererVK::deferSplitApply(uint32_t rw, uint32_t rh, bool projFull, bool projRgb, bool reflHalf,
                                        bool visReuse, bool feat, bool rtMark)
{
    if (ensureDeferSplitTargets(rw, rh, projFull, projRgb, reflHalf, visReuse, feat, rtMark))
    {
        if (mDsAllocFails)
            LL_INFOS("Vulkan") << "VKDeferSplit: intermediates allocated after " << mDsAllocFails
                               << " refused attempt(s); split lighting resumed" << LL_ENDL;
        mDsAllocFails = 0;
        return true;
    }
    if (mDsAllocFails++ == 0)
        LL_WARNS("Vulkan") << "VKDeferSplit: intermediates " << rw << "x" << rh << " refused (VRAM); uber"
                              " lighting kernel until a retry succeeds" << LL_ENDL;
    const uint32_t shift = std::min<uint32_t>(mDsAllocFails - 1u, 5u);
    mDsRetryAt = dsClock() + std::min(kDsRetrySecs * (double)(1u << shift), kDsRetryMaxSecs);
    return false;
}

// syncFromStoresPrestep (before the frame's command buffer begins): what deferSplitFrame asked
// for under the last recording -- the intermediates re-created (ensureDeferSplitTargets waits
// for the device, then rewrites set 3 and draw set 0 b41-43 / b48) or freed. The recording that
// follows decides again from scratch (a changed want queues another request).
void LLCleanRendererVK::deferSplitPrestep()
{
    if (!mDsReq.pending) return;
    const DsReq r = mDsReq;
    mDsReq = DsReq{};
    if (!mCtx || !mDsetDeferSplit) return;
    if (r.free)
    {
        if (mDsImg[DS_SUN].image)
        {
            vkDeviceWaitIdle(mCtx->device());
            destroyDeferSplitTargets();
            if (r.unused) LL_INFOS("Vulkan") << "VKDeferSplit: intermediates freed (split lighting off)" << LL_ENDL;
        }
        if (r.unused) mAlias.forget(AS_DSPLIT0, DS_ALIASED);
        return;
    }
    deferSplitApply(r.rw, r.rh, r.projFull, r.projRgb, r.reflHalf, r.visReuse, r.feat, r.rtMark);
}

// ---- HYBRID RT REFLECTIONS (#859; clean_deferred_light.comp HYBRID RT REFLECTIONS) ----
// The RT build gate (rtConsumerActive, before this frame's build): RenderVKRTReflections 1,
// deferred lighting on (split: trace + resolve; uber: the pre-trace), on screen, RT up and no
// stand-down reason. (2 is reserved for full RT reflections: off until it exists.)
bool LLCleanRendererVK::rtReflWanted() const
{
    if (!mRT || mOffscreen || !mRtTracePipe || !mDeferSplitOk) return false;
#if defined(LL_HAS_CLEAN_PIPELINE)
    static LLCachedControl<U32>  s_mode(gSavedSettings, "RenderVKRTReflections", 1);
    static LLCachedControl<bool> s_defer(gSavedSettings, "RenderVKDeferredLighting", true);
    if ((U32)s_mode != 1u || !(bool)s_defer) return false;
    return optionalRtStandDownReason() == nullptr;
#else
    return false;
#endif
}

// This frame's settings (deferSplitFrame, once per on-screen recording) + the stand-down log
// (the acoustics probe's rule and pattern: the setting stays on).
void LLCleanRendererVK::rtReflSettings()
{
    mRtReflRough = 0.35f;
    mRtReflMaxDist = 64.f;
    mRtReflMaxRecv = 48.f;
    mRtReflSharp = 0.1f;
    mRtReflBudget = 0.25f;
    mRtReflFloor = 1u;
    mRtReflBlend = true;
    mRtReflHitShadows = 1u;
    mRtReflHWCull = true;
    mRtReflMaskTest = 0u;
    mRtReflHitOcc = true;
    mRtReflHitOccDbg = false;
    mRtReflSizeClasses = true;
    mRtReflSmallSize = 0.5f;
    mRtReflSmallPx = 1.f;
    mRtReflSmallDist = 16.f;
    mRtReflGradient = true;
    mRtReflDensityMin = 1.f / 64.f;
    mRtReflDensityCurve = 1.f;
    mRtReflStrength = true;
    mRtReflStrFull = 0.25f;
    mRtReflStrMin = 0.03f;
    mRtReflStrCut = 0.02f;
    mRtReflCurvRad = 12.f * (F_PI / 180.f);
    mRtReflLobe = true;
    mRtReflTemporal = true;
    mRtReflDebugView = false;
    mRtReflRayList = true;
    mRtSplitWant = true;
    U32 mode = 0;
#if defined(LL_HAS_CLEAN_PIPELINE)
    static LLCachedControl<U32>  s_mode(gSavedSettings, "RenderVKRTReflections", 1);
    static LLCachedControl<F32>  s_rough(gSavedSettings, "RenderVKRTReflectionsRough", 0.35f);
    static LLCachedControl<F32>  s_dist(gSavedSettings, "RenderVKRTReflectionsMaxDist", 64.f);
    static LLCachedControl<F32>  s_recv(gSavedSettings, "RenderVKRTReflectionsMaxRecvDist", 48.f);
    static LLCachedControl<F32>  s_sharp(gSavedSettings, "RenderVKRTReflectionsSharpRough", 0.1f);
    static LLCachedControl<F32>  s_budget(gSavedSettings, "RenderVKRTReflectionsRayBudget", 0.25f);
    static LLCachedControl<U32>  s_scale(gSavedSettings, "RenderVKRTReflectionsScale", 1);
    static LLCachedControl<bool> s_blend(gSavedSettings, "RenderVKRTReflectionsBlend", true);
    static LLCachedControl<U32>  s_hitsh(gSavedSettings, "RenderVKRTReflectionsHitShadowRays", 1);
    static LLCachedControl<bool> s_hwcull(gSavedSettings, "RenderVKRTReflectionsHWCull", true);
    static LLCachedControl<U32>  s_masktest(gSavedSettings, "RenderVKRTReflectionsMaskTest", 0);
    static LLCachedControl<bool> s_hitocc(gSavedSettings, "RenderVKRTReflectionsHitOcclusion", true);
    static LLCachedControl<bool> s_hitoccdbg(gSavedSettings, "RenderVKRTReflectionsHitOccDebug", false);
    static LLCachedControl<bool> s_hittermsdbg(gSavedSettings, "RenderVKRTReflectionsHitTermsDebug", false);
    static LLCachedControl<bool> s_hazeocc(gSavedSettings, "RenderVKRTReflectionsHazeOcclusion", true);
    static LLCachedControl<bool> s_backstop(gSavedSettings, "RenderVKRTReflectionsBackFaceStop", true);
    static LLCachedControl<bool> s_sizecls(gSavedSettings, "RenderVKRTReflectionsSizeClasses", true);
    static LLCachedControl<F32>  s_small(gSavedSettings, "RenderVKRTReflectionsSmallSize", 0.5f);
    static LLCachedControl<F32>  s_smallpx(gSavedSettings, "RenderVKRTReflectionsSizeFootprintPx", 1.f);
    static LLCachedControl<F32>  s_smalld(gSavedSettings, "RenderVKRTReflectionsSmallDist", 16.f);
    static LLCachedControl<bool> s_grad(gSavedSettings, "RenderVKRTReflectionsDensityGradient", true);
    static LLCachedControl<F32>  s_dmin(gSavedSettings, "RenderVKRTReflectionsDensityMin", 0.015625f);
    static LLCachedControl<F32>  s_dcurve(gSavedSettings, "RenderVKRTReflectionsDensityCurve", 1.f);
    static LLCachedControl<bool> s_str(gSavedSettings, "RenderVKRTReflectionsStrength", true);
    static LLCachedControl<F32>  s_sfull(gSavedSettings, "RenderVKRTReflectionsStrengthFull", 0.25f);
    static LLCachedControl<F32>  s_smin(gSavedSettings, "RenderVKRTReflectionsStrengthMin", 0.03f);
    static LLCachedControl<F32>  s_scut(gSavedSettings, "RenderVKRTReflectionsStrengthCut", 0.02f);
    static LLCachedControl<U32>  s_dbgview(gSavedSettings, "RenderVKDebugView", 0);
    static LLCachedControl<bool> s_raylist(gSavedSettings, "RenderVKRTReflectionsRayList", true);
    static LLCachedControl<bool> s_shsplit(gSavedSettings, "RenderVKRTReflectionsShadeSplit", false);
    static LLCachedControl<F32>  s_curv(gSavedSettings, "RenderVKRTReflectionsCurvatureDensity", 12.f);
    static LLCachedControl<bool> s_lobe(gSavedSettings, "RenderVKRTReflectionsLobeFilter", true);
    static LLCachedControl<bool> s_temporal(gSavedSettings, "RenderVKRTReflectionsTemporal", true);
    mode = s_mode;
    mRtReflRough = llclamp((F32)s_rough, 0.02f, 1.f);
    mRtReflMaxDist = llclamp((F32)s_dist, 1.f, 1024.f);
    mRtReflMaxRecv = llclamp((F32)s_recv, 1.f, 4096.f);
    mRtReflSharp = llclamp((F32)s_sharp, 0.f, mRtReflRough);   // (0: no block keeps full density)
    mRtReflBudget = std::max((F32)s_budget, 0.f);
    // RAY DENSITY floor (clean_deferred_light.comp RAY DENSITY): 0 = full density everywhere, 1 =
    // adaptive (sharp blocks full, the rest one ray per 2 x 2), 2+ = one ray per 2 x 2 everywhere.
    mRtReflFloor = std::min<U32>((U32)s_scale, 2u);
    mRtReflBlend = s_blend;
    // HIT SHADOW-RAY BUDGET (clean_rt_shade.glsl RT_SHADE_PROJ_K; 4 = the shader's RT_SHADE_PROJ_MAXK)
    mRtReflHitShadows = std::min<U32>((U32)s_hitsh, 4u);
    // HARDWARE BACK-FACE CULLING of the reflection rays (clean_deferred_light.comp rtrReflCullFlags)
    mRtReflHWCull = s_hwcull;
    // ALPHA-MASK TEST of the reflection rays (clean_deferred_light.comp rtrMaskCone): 0 raster
    // parity (pixel footprint + mip bias + coverage scale), 1 legacy cone LOD, 2 mip 0, 3 off (A/B)
    mRtReflMaskTest = std::min<U32>((U32)s_masktest, 3u);
    // (#87 x #859) HIT OCCLUSION under GI (clean_deferred_light.comp rtrHitEnv): a reflection hit's
    // probe / sky environment only where one ray along its own reflection escapes, else the GI cache
    mRtReflHitOcc = s_hitocc;
    mRtReflHitOccDbg = s_hitoccdbg;
    mRtReflHitTermsDbg = s_hittermsdbg;
    mRtReflHazeOcc = s_hazeocc;
    mRtReflBackStop = s_backstop;
    // SIZE-CLASS SEGMENTS (clean_deferred_light.comp rtrSmallDist). The bound is also pass A's
    // (LLCleanRTVK reads the same setting into clean_rt_instances.comp maskClassSized).
    mRtReflSizeClasses = s_sizecls;
    const F32 small = s_small;
    mRtReflSmallSize = (std::isfinite(small) && small > 0.f) ? std::min(small, 64.f) : 0.f;
    const F32 smallPx = s_smallpx;
    mRtReflSmallPx = std::isfinite(smallPx) ? llclamp(smallPx, 0.f, 64.f) : 1.f;
    const F32 smallD = s_smalld;
    mRtReflSmallDist = std::isfinite(smallD) ? llclamp(smallD, 0.f, 1024.f) : 16.f;
    // DENSITY GRADIENT (clean_deferred_light.comp rtrRho; the tile list header's rtt_param2)
    mRtReflGradient = s_grad;
    const F32 dmin = s_dmin;
    mRtReflDensityMin = std::isfinite(dmin) ? llclamp(dmin, 1.f / 256.f, 1.f) : 1.f / 64.f;
    const F32 dcurve = s_dcurve;
    mRtReflDensityCurve = std::isfinite(dcurve) ? llclamp(dcurve, 0.1f, 10.f) : 1.f;
    // STRENGTH DENSITY (clean_deferred_light.comp dsRtMark / rtrRho / rtrStrengthFade; rtt_param3):
    // 0 <= cut <= min < full <= 1 (the shader divides by full - min and fades over cut .. min)
    mRtReflStrength = s_str;
    const F32 scut = s_scut, smin = s_smin, sfull = s_sfull;
    mRtReflStrCut = std::isfinite(scut) ? llclamp(scut, 0.f, 1.f) : 0.02f;
    mRtReflStrMin = std::isfinite(smin) ? llclamp(smin, mRtReflStrCut, 1.f) : std::max(0.03f, mRtReflStrCut);
    mRtReflStrFull = std::isfinite(sfull) ? llclamp(sfull, mRtReflStrMin + 1e-3f, 1.001f) : std::max(0.25f, mRtReflStrMin + 1e-3f);
    // RenderVKDebugView 28: the ray density heat map (the combine; deferredWanted keeps the split)
    mRtReflDebugView = (U32)s_dbgview == 28u;
    // RAY LIST (clean_deferred_light.comp pass 16 + pass 11 -DCLEAN_RT_LIST): select, then trace one
    // lane per ray; off: the in-tile trace (A/B: the same rays and outputs)
    mRtReflRayList = s_raylist;
    // (#1036) the list trace as TRACE / MAT / LIGHT over per-ray records (rtSplitDecide)
    mRtSplitWant = s_shsplit;
    // (#859 noise) CURVATURE DENSITY (clean_deferred_light.comp rtrCurvQ / rtrRho; rtt_curv): degrees ->
    // rad, 0 / non-finite off; at least 1 degree (the density saturates at one ray per pixel anyway)
    const F32 curv = s_curv;
    mRtReflCurvRad = (std::isfinite(curv) && curv > 0.f) ? llclamp(curv, 1.f, 90.f) * (F_PI / 180.f) : 0.f;
    // LOBE FILTER (rtrTap's direction weight + specular AA, the trace's curvature cone; rtt_opts4 bit 0)
    mRtReflLobe = s_lobe;
    // TEMPORAL (clean_deferred_light.comp rtrTemporal; rtt_opts4 bit 1 while mDsRtHist is full size --
    // toggling it re-creates the RT targets: one device wait)
    mRtReflTemporal = s_temporal;
#endif
    if (mode == 1u && mRtReflHitShadows != mRtReflHitShadowsLogged)
    {
        mRtReflHitShadowsLogged = mRtReflHitShadows;
        LL_INFOS("Vulkan") << "RT reflections: hit shading budget = " << mRtReflHitShadows
                           << " projector shadow ray(s) per reflection hit (the brightest ray-traced projector shares;"
                              " the rest unshadowed), opaque casters only (alpha-blend beams / glow skipped);"
                              " lights in range at a hit are all shaded. Was one ray per covering projector"
                              " + an alpha walk: dozens per hit under a stage rig."
                              " RenderVKRTReflectionsHitShadowRays (0..4)" << LL_ENDL;
    }
    const char* why = (mode == 1u && mRT) ? optionalRtStandDownReason() : nullptr;
    if (why && !mRtReflStandDown)
    {
        mRtReflStandDown = true;
        LL_WARNS("Vulkan") << "RT reflections standing down (setting stays on; probe fallback): " << why << LL_ENDL;
        if (mRT && mBudgetCaps.rtLevel >= LLVramBudgetVK::RT_PROBE_TRACE_OFF) mRT->releaseSoon();   // may have been the last consumer
    }
    else if (!why && mRtReflStandDown)
    {
        mRtReflStandDown = false;
        LL_INFOS("Vulkan") << "RT reflections resuming (RT available again)" << LL_ENDL;
    }
}

VKRtReflPush LLCleanRendererVK::rtReflPush(const VKDeferPush& p) const
{
    VKRtReflPush rp{};
    rp.d = p;
    rp.d.flags = (p.flags & 0x00FFFFFFu) | ((U32)(mRtReflRough * 255.f + 0.5f) << 24);   // (the threshold byte)
    rp.rtr[0] = mRtReflMaxDist;
    // bit 0 blend layers, bits 1-3 the hit shadow-ray budget, bit 4 the light reservoir grid was
    // built this recording (#869; clean_deferred_light.comp rtrOpts / rtrRegirOn)
    // bit 5: hardware back-face culling of the reflection rays (RenderVKRTReflectionsHWCull);
    // bit 6: size-class segments (RenderVKRTReflectionsSizeClasses; rtr2);
    // bit 7: the trace-cost counters (rtt_cost; only read while GPU timers run);
    // bits 8-9: the alpha-mask test mode (RenderVKRTReflectionsMaskTest; rtrMaskMode)
    // bit 10: the hits' occlusion ray under GI (RenderVKRTReflectionsHitOcclusion; rtrHitEnv -- the
    //   kernels read it only on a GI frame; the planar RT mirror's pass 12 never does)
    // bit 11: its debug view (RenderVKRTReflectionsHitOccDebug; passes 11 / 14 only)
    // bit 12: the hit terms debug view (RenderVKRTReflectionsHitTermsDebug; passes 11 / 14 only)
    // bit 13: the hits' haze in-scatter x their occlusion ray (RenderVKRTReflectionsHazeOcclusion)
    // bit 14: the rays stop at a near single-sided back face -- they started inside a solid
    //   (RenderVKRTReflectionsBackFaceStop; rtrTraceRefl; passes 11 / 14 only)
    const bool sizeCls = mRtReflSizeClasses && mRtReflSmallSize > 0.f;
    rp.rtr[1] = (float)((mRtReflBlend ? 1u : 0u) | (mRtReflHitShadows << 1) | (mRegirNow && mRegirReflOn ? 16u : 0u)
                        | (mRtReflHWCull ? 32u : 0u) | (sizeCls ? 64u : 0u) | (mTsOn ? 128u : 0u)
                        | ((mRtReflMaskTest & 3u) << 8) | (mRtReflHitOcc ? 1024u : 0u)
                        | (mRtReflHitOccDbg ? 2048u : 0u) | (mRtReflHitTermsDbg ? 4096u : 0u)
                        | (mRtReflHazeOcc ? 8192u : 0u) | (mRtReflBackStop ? 16384u : 0u));
    rp.rtr[2] = mRtReflMaxRecv;   // (pass 12's receiver gate; the split kernels read the tile list header)
    rp.rtr[3] = std::max(mSamplerAniso, 1.f);   // (the raster sampler's: the hits' texture LOD rule)
    // SIZE-CLASS SEGMENTS (clean_deferred_light.comp rtrSmallDist / rtrInstSmall)
    rp.rtr2[0] = sizeCls ? mRtReflSmallSize : 0.f;
    rp.rtr2[1] = mRtReflSmallPx;
    rp.rtr2[2] = mRtReflSmallDist;
    rp.rtr2[3] = 0.f;
    return rp;
}

// (#1036) THE RT REFLECTION SPLIT (clean_deferred_light.comp; recordRtReflect): this recording traces the
// ray list as TRACE / MAT / LIGHT when the setting, the ray list, the three pipelines and the records are
// there. The records: kRtRecBytes per list entry for RenderVKRTReflectionsRayBudget x the render pixels
// (a quarter of them without a budget; at least 64 K entries, at most the list's capacity) -- the rays
// past them take the fused list kernel as a tail dispatch, so the capacity costs speed, never rays. No
// descriptor names them (device address in the push): a new size allocates the new buffer first and
// retires the old one (freed once no frame in flight reads it), no device wait. Refused (#697): the old
// records stay in use if there are any, else the fused trace; retried after 30 s.
void LLCleanRendererVK::rtSplitDecide(uint32_t rw, uint32_t rh, double now)
{
    mRtSplitNow = false;
    if (!mCtx) return;
    bool pipes = true;
    for (VkPipeline sp : mRtSplitPipe) pipes = pipes && sp != VK_NULL_HANDLE;
    const bool keep = mRtSplitWant && mRtReflRayList && mDsRtMarkFull && mDsRtTileCount != 0u && pipes;
    if (!keep)
    {
        if (mRtRec.buffer)
        {
            retireBuffer(mRtRec);
            mRtRec = GpuBuffer{};
            mRtRecCap = 0;
        }
        return;
    }
    const uint64_t listCap = (uint64_t)mDsRtTileCount * 64u;
    const double frac = mRtReflBudget > 0.f ? std::min((double)mRtReflBudget, 1.0) : 0.25;
    uint64_t cap = (uint64_t)std::ceil((double)rw * (double)rh * frac);
    cap = std::min<uint64_t>(std::max<uint64_t>(cap, 65536u), listCap);
    cap = std::min<uint64_t>((cap + 63u) & ~(uint64_t)63u, listCap);
    if ((!mRtRec.buffer || mRtRecCap != (uint32_t)cap) && now >= mRtRecRetryAt)
    {
        const VkDeviceSize bytes = (VkDeviceSize)cap * kRtRecBytes;
        GpuBuffer nb{};
        {
            VkMemScope memcat(VKMEM_TARGET);
            VkDeviceContext::SoftAllocScope soft(mCtx);
            nb = mCtx->createBuffer(bytes, VK_BUFFER_USAGE_STORAGE_BUFFER_BIT, VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT, true);
        }
        if (nb.buffer && nb.address)
        {
            if (mRtRec.buffer) retireBuffer(mRtRec);
            mRtRec = nb;
            mRtRecCap = (uint32_t)cap;
            mCtx->setObjectName(VK_OBJECT_TYPE_BUFFER, (uint64_t)mRtRec.buffer, "rtReflSplitRecords");
            LL_INFOS("Vulkan") << "RT reflections: split-trace records for " << cap << " rays ("
                               << ((bytes + (1u << 19)) >> 20) << " MB; RenderVKRTReflectionsShadeSplit)" << LL_ENDL;
        }
        else
        {
            if (nb.buffer) mCtx->destroyBuffer(nb);
            mRtRecRetryAt = now + 30.0;
            LL_WARNS("Vulkan") << "RT reflections: the split trace's records (" << ((bytes + (1u << 19)) >> 20)
                               << " MB) were refused (VRAM); "
                               << (mRtRec.buffer ? "the previous records stay in use" : "the fused trace instead")
                               << ", retry in 30 s" << LL_ENDL;
        }
    }
    mRtSplitNow = mRtReflNow && mRtSelectPipe && mRtTraceListPipe && mRtRec.buffer && mRtRec.address && mRtRecCap != 0u;
}

// Init (after the draw sets exist): the 1 x 1 zero forward-reflection placeholder (draw set 0
// b45 is read by every forward lit / water FS: it must always name an image) and the uber
// pre-trace placeholder (set 2 b11: the uber kernel declares it).
void LLCleanRendererVK::ensureRtPlaceholders()
{
    if (!mCtx) return;
    if (!mRtFwdPlaceholder.image)
    {
        mRtFwdPlaceholder = mCtx->createImage2D(1u, 1u, VK_FORMAT_R16G16B16A16_SFLOAT,
                                                VK_IMAGE_USAGE_STORAGE_BIT | VK_IMAGE_USAGE_SAMPLED_BIT
                                                | VK_IMAGE_USAGE_TRANSFER_DST_BIT, VK_IMAGE_ASPECT_COLOR_BIT);
        if (mRtFwdPlaceholder.image)
        {
            mCtx->setObjectName(VK_OBJECT_TYPE_IMAGE, (uint64_t)mRtFwdPlaceholder.image, "rtReflFwdPlaceholder");
            mCtx->submitImmediate([&](VkCommandBuffer c){
                VkImageMemoryBarrier2 b{VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER_2};
                b.srcStageMask = VK_PIPELINE_STAGE_2_TOP_OF_PIPE_BIT;
                b.dstStageMask = VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT;
                b.dstAccessMask = VK_ACCESS_2_MEMORY_READ_BIT | VK_ACCESS_2_MEMORY_WRITE_BIT;
                b.oldLayout = VK_IMAGE_LAYOUT_UNDEFINED; b.newLayout = VK_IMAGE_LAYOUT_GENERAL;
                b.image = mRtFwdPlaceholder.image; b.subresourceRange = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 1};
                VkDependencyInfo d{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
                d.imageMemoryBarrierCount = 1; d.pImageMemoryBarriers = &b;
                vkCmdPipelineBarrier2(c, &d);
                const VkClearColorValue zero{};
                const VkImageSubresourceRange rr{VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 1};
                vkCmdClearColorImage(c, mRtFwdPlaceholder.image, VK_IMAGE_LAYOUT_GENERAL, &zero, 1, &rr);
            });
        }
    }
    writeRtFwdBinding();
    if (!mRtUber.image && mDsetDefer) ensureRtUber(1u, 1u, false);
}

// Draw set 0 binding 48 (clean_draw_common.glsl uRtFwd): mDsRtFwd while the RT targets are full
// size, else the zero placeholder. Callers make sure no frame in flight reads the set (init, or
// behind ensureDeferSplitTargets' / destroyDeferSplitTargets' device wait).
void LLCleanRendererVK::writeRtFwdBinding()
{
    if (!mDsetDraw0 || !mDepthSampler) return;
    const VkImageView v = (mDsRtMarkFull && mDsRtFwd.view) ? mDsRtFwd.view : mRtFwdPlaceholder.view;
    if (!v) return;
    VkDescriptorImageInfo ii{mDepthSampler, v, VK_IMAGE_LAYOUT_GENERAL};   // (nearest; the FS texelFetch-es)
    VkWriteDescriptorSet w{VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET};
    w.dstSet = mDsetDraw0; w.dstBinding = 48; w.descriptorCount = 1;
    w.descriptorType = VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER; w.pImageInfo = &ii;
    vkUpdateDescriptorSets(mCtx->device(), 1, &w, 0, nullptr);
}

// deferSplitFrame's uber pre-trace target (2026-10-22, the pdnPrestep rule): ensureRtUber waits for
// the device, re-creates the image, runs a submitImmediate and rewrites set 2 binding 11 -- inside
// the recording deferSplitFrame runs in (after draw set 0 is bound). A target that differs is now
// REQUESTED (mRtUberReq) and frameStartResizePrestep re-creates it before the next command buffer
// begins; this frame takes no pre-trace (false: the probe fallback, as after a refusal).
// RenderVKResizeAtFrameStart 0: ensureRtUber here, as before.
bool LLCleanRendererVK::rtUberAtFrameStart(uint32_t rw, uint32_t rh, bool full)
{
    if (!resizeAtFrameStart()) return ensureRtUber(rw, rh, full);
    if (!mDsetDefer) return false;
    const uint32_t w = full ? rw : 1u, h = full ? rh : 1u;
    if (mRtUber.image && mRtUberFull == full && (!full || (mRtUber.extent.width == w && mRtUber.extent.height == h)))
        return true;   // (= ensureRtUber)
    if (full && mRtUber.image && dsClock() < mRtReflRetryAt) return false;   // (refused earlier: the backoff)
    mRtUberReq.pending = true;
    mRtUberReq.w = rw; mRtUberReq.h = rh; mRtUberReq.full = full;
    return false;
}

// The uber pre-trace target (set 2 binding 11): render extent (full) or 1 x 1. A change waits for
// the device (set 2 is in every lighting recording). False: refused (#697) -- the placeholder
// stays, no pre-trace, retry after the backoff.
bool LLCleanRendererVK::ensureRtUber(uint32_t rw, uint32_t rh, bool full)
{
    if (!mDsetDefer) return false;
    const uint32_t w = full ? rw : 1u, h = full ? rh : 1u;
    if (mRtUber.image && mRtUberFull == full && (!full || (mRtUber.extent.width == w && mRtUber.extent.height == h))) return true;
    if (full && mRtUber.image && dsClock() < mRtReflRetryAt) return false;   // (refused earlier: wait out the backoff)
    VkMemScope memcat(VKMEM_TARGET);
    vkDeviceWaitIdle(mCtx->device());
    if (mRtUber.image) { mCtx->destroyImage(mRtUber); mRtUber = GpuImage{}; }
    mRtUberFull = false;
    {
        VkDeviceContext::SoftAllocScope soft(mCtx, full);
        mRtUber = mCtx->createImage2D(w, h, VK_FORMAT_R16G16B16A16_SFLOAT, VK_IMAGE_USAGE_STORAGE_BIT, VK_IMAGE_ASPECT_COLOR_BIT);
    }
    bool ok = true;
    if (!mRtUber.image && full)
    {
        mRtReflRetryAt = dsClock() + kDsRetryMaxSecs;
        LL_WARNS("Vulkan") << "RT reflections: uber pre-trace target " << w << "x" << h << " refused (VRAM); probe fallback, retry in "
                           << kDsRetryMaxSecs << " s" << LL_ENDL;
        mRtUber = mCtx->createImage2D(1u, 1u, VK_FORMAT_R16G16B16A16_SFLOAT, VK_IMAGE_USAGE_STORAGE_BIT, VK_IMAGE_ASPECT_COLOR_BIT);
        ok = false;
    }
    if (!mRtUber.image) return false;
    mRtUberFull = ok && full;
    mCtx->setObjectName(VK_OBJECT_TYPE_IMAGE, (uint64_t)mRtUber.image, "rtReflUberPreTrace");
    mCtx->submitImmediate([&](VkCommandBuffer c){
        VkImageMemoryBarrier2 b{VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER_2};
        b.srcStageMask = VK_PIPELINE_STAGE_2_TOP_OF_PIPE_BIT;
        b.dstStageMask = VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT;
        b.dstAccessMask = VK_ACCESS_2_MEMORY_READ_BIT | VK_ACCESS_2_MEMORY_WRITE_BIT;
        b.oldLayout = VK_IMAGE_LAYOUT_UNDEFINED; b.newLayout = VK_IMAGE_LAYOUT_GENERAL;
        b.image = mRtUber.image; b.subresourceRange = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 1};
        VkDependencyInfo d{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
        d.imageMemoryBarrierCount = 1; d.pImageMemoryBarriers = &b;
        vkCmdPipelineBarrier2(c, &d);
    });
    VkDescriptorImageInfo ii{VK_NULL_HANDLE, mRtUber.view, VK_IMAGE_LAYOUT_GENERAL};
    VkWriteDescriptorSet wr{VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET};
    wr.dstSet = mDsetDefer; wr.dstBinding = 11; wr.descriptorCount = 1;
    wr.descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_IMAGE; wr.pImageInfo = &ii;
    vkUpdateDescriptorSets(mCtx->device(), 1, &wr, 0, nullptr);
    if (mRtUberFull) LL_INFOS("Vulkan") << "RT reflections: uber pre-trace target " << w << "x" << h << LL_ENDL;
    return ok;
}

// Every split frame, before the reflect passes: the RT tile list emptied (header (0, 1, 1, tiles),
// tile flags 0), the mark / trace images to GENERAL with their contents discarded (written per
// listed tile before any read); the forward reflections cleared once when tracing them stopped
// (the forward FS reads them every frame). The previous frame's RT kernels / forward FS read
// these (WAR: execution dependencies).
void LLCleanRendererVK::recordRtMarkInit(VkCommandBuffer cmd)
{
    if (!mDsRtMark.image || !mDsRtTiles.buffer) return;
    if (mRtFwdDirty && !mRtFwdNow && mDsRtFwd.image)
    {
        VkImageMemoryBarrier2 b{VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER_2};
        b.srcStageMask = VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT | VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
        b.dstStageMask = VK_PIPELINE_STAGE_2_CLEAR_BIT; b.dstAccessMask = VK_ACCESS_2_TRANSFER_WRITE_BIT;
        b.oldLayout = VK_IMAGE_LAYOUT_GENERAL; b.newLayout = VK_IMAGE_LAYOUT_GENERAL;
        b.image = mDsRtFwd.image; b.subresourceRange = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 1};
        VkDependencyInfo d{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
        d.imageMemoryBarrierCount = 1; d.pImageMemoryBarriers = &b;
        vkCmdPipelineBarrier2(cmd, &d);
        const VkClearColorValue zero{};
        const VkImageSubresourceRange rr{VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 1};
        vkCmdClearColorImage(cmd, mDsRtFwd.image, VK_IMAGE_LAYOUT_GENERAL, &zero, 1, &rr);
        b.srcStageMask = VK_PIPELINE_STAGE_2_CLEAR_BIT; b.srcAccessMask = VK_ACCESS_2_TRANSFER_WRITE_BIT;
        b.dstStageMask = VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT; b.dstAccessMask = VK_ACCESS_2_SHADER_SAMPLED_READ_BIT;
        vkCmdPipelineBarrier2(cmd, &d);
        mRtFwdDirty = false;
    }
    if (!mRtReflNow) return;
    VkImageMemoryBarrier2 b[3]{};
    const VkImage im[2] = {mDsRtMark.image, mDsRtTrace.image};
    for (int k = 0; k < 2; ++k)
    {
        b[k].sType = VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER_2;
        b[k].srcStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
        b[k].dstStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
        b[k].dstAccessMask = VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
        b[k].oldLayout = VK_IMAGE_LAYOUT_UNDEFINED; b[k].newLayout = VK_IMAGE_LAYOUT_GENERAL;
        b[k].image = im[k]; b[k].subresourceRange = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 1};
    }
    // (#859 noise) the temporal history: last frame's resolve wrote the layer this frame's reads and
    // read the one it writes (RAW + WAR; contents kept: GENERAL -> GENERAL)
    b[2].sType = VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER_2;
    b[2].srcStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; b[2].srcAccessMask = VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    b[2].dstStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
    b[2].dstAccessMask = VK_ACCESS_2_SHADER_STORAGE_READ_BIT | VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    b[2].oldLayout = VK_IMAGE_LAYOUT_GENERAL; b[2].newLayout = VK_IMAGE_LAYOUT_GENERAL;
    b[2].image = mDsRtHist.image; b[2].subresourceRange = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 2};
    // The tile list: last frame's RT kernels read it as indirect arguments / storage, the stats
    // ring copied its header (WAR).
    VkMemoryBarrier2 tw{VK_STRUCTURE_TYPE_MEMORY_BARRIER_2};
    tw.srcStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT | VK_PIPELINE_STAGE_2_DRAW_INDIRECT_BIT
                    | VK_PIPELINE_STAGE_2_ALL_TRANSFER_BIT;
    tw.dstStageMask = VK_PIPELINE_STAGE_2_ALL_TRANSFER_BIT; tw.dstAccessMask = VK_ACCESS_2_TRANSFER_WRITE_BIT;
    VkDependencyInfo d{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
    d.memoryBarrierCount = 1; d.pMemoryBarriers = &tw;
    d.imageMemoryBarrierCount = mDsRtHist.image ? 3u : 2u; d.pImageMemoryBarriers = b;
    vkCmdPipelineBarrier2(cmd, &d);
    // (clean_deferred_light.comp RT TILE LIST: header (x, y, z, n) = (0, 0, 1, n), the ray density
    // counters zero, the params; the level ping-pong words (9, 10) are the GPU's -- untouched; the
    // n flags and the listed count -- at word 2n of rtt_words -- zero)
    const uint32_t hdr[9] = {0u, 0u, 1u, mDsRtTileCount, 0u, 0u, 0u, 0u, 0u};
    vkCmdUpdateBuffer(cmd, mDsRtTiles.buffer, 0, sizeof(hdr), hdr);
    // (words 11-15: pass 11's hit-shading counters, rtt_hit; words 9 / 10 stay the GPU's)
    const uint32_t hitz[5] = {0u, 0u, 0u, 0u, 0u};
    vkCmdUpdateBuffer(cmd, mDsRtTiles.buffer, 11u * sizeof(uint32_t), sizeof(hitz), hitz);
    // (words 26-51: the gradient's ray / density sums and pass 11's trace-cost counters; words
    // 24 / 25 -- the gradient's scale ping-pong -- stay the GPU's)
    vkCmdFillBuffer(cmd, mDsRtTiles.buffer, 26u * sizeof(uint32_t), (2u + kRtCostWords) * sizeof(uint32_t), 0u);
    // RenderVKRTReflectionsRayBudget: rays per render pixel -> rays (0: no budget).
    const double px = (double)mDsRtMark.extent.width * (double)mDsRtMark.extent.height;
    const double budget = mRtReflBudget > 0.f ? std::min(px * (double)mRtReflBudget, 4.0e9) : -1.0;
    mRtReflParity ^= 1u;
    uint32_t param[4];
    std::memcpy(&param[0], &mRtReflMaxRecv, 4);
    std::memcpy(&param[1], &mRtReflSharp, 4);
    param[2] = budget < 0.0 ? 0xFFFFFFFFu : (uint32_t)budget;
    param[3] = mRtReflFloor | (mRtReflParity << 8);
    vkCmdUpdateBuffer(cmd, mDsRtTiles.buffer, 16u * sizeof(uint32_t), sizeof(param), param);
    // (words 20-23, rtt_param2: the DENSITY GRADIENT -- x on, y rho_min, z the curve, w the
    // roughness cutoff; clean_deferred_light.comp rtrRho)
    uint32_t param2[4];
    param2[0] = mRtReflGradient ? 1u : 0u;
    std::memcpy(&param2[1], &mRtReflDensityMin, 4);
    std::memcpy(&param2[2], &mRtReflDensityCurve, 4);
    std::memcpy(&param2[3], &mRtReflRough, 4);
    vkCmdUpdateBuffer(cmd, mDsRtTiles.buffer, 20u * sizeof(uint32_t), sizeof(param2), param2);
    // (words 52-55, rtt_param3: the STRENGTH DENSITY -- x on | RenderVKDebugView 28 << 1, y the
    // full-density strength, z the minimum-density strength, w the cutoff; clean_deferred_light.comp
    // rtrRho / dsRtMark / rtrDebugColor -- then words 56-63: its per-type candidate / strength
    // sums and the cut count, zero)
    uint32_t param3[16] = {};   // (+ words 64-67: the tiles listed, the ray list overflow, rtt_curv, rtt_opts4)
    param3[0] = (mRtReflStrength ? 1u : 0u) | (mRtReflDebugView ? 2u : 0u)
              | (rrRawSignal(kRrRawRefl, mRenderW, mRenderH) ? 4u : 0u);   // (#870 raw routing: the resolve keeps own rays)
    std::memcpy(&param3[1], &mRtReflStrFull, 4);
    std::memcpy(&param3[2], &mRtReflStrMin, 4);
    std::memcpy(&param3[3], &mRtReflStrCut, 4);
    // (words 66 / 67: rtt_curv -- the CURVATURE DENSITY limit, rad -- and rtt_opts4 -- bit 0 the LOBE FILTER)
    std::memcpy(&param3[14], &mRtReflCurvRad, 4);
    // (temporal: only while the frame keeps a previous camera -- taa_prev_vp is this frame's otherwise)
    param3[15] = (mRtReflLobe ? 1u : 0u) | (mRtReflTemporal && mDsRtHistFull && mTemporalOn ? 2u : 0u);
    static_assert(kRtTilesHdrWords == 68u, "rtt_param3 + the strength / tile stats end the header");
    vkCmdUpdateBuffer(cmd, mDsRtTiles.buffer, 52u * sizeof(uint32_t), sizeof(param3), param3);
    vkCmdFillBuffer(cmd, mDsRtTiles.buffer, kRtTilesHdrBytes, (VkDeviceSize)mDsRtTileCount * sizeof(uint32_t), 0u);
    // (rtt_words[2n]: the listed count; [2n + 1 .. 2n + 5]: the RAY LIST's count, the list trace's
    // dispatch (0, 0, 1) and the capacity -- 64 rays per tile, the buffer's whole list)
    const uint32_t rayl[6] = {0u, 0u, 0u, 0u, 1u, mDsRtTileCount * 64u};
    vkCmdUpdateBuffer(cmd, mDsRtTiles.buffer, kRtTilesHdrBytes + (VkDeviceSize)mDsRtTileCount * 2u * sizeof(uint32_t),
                      sizeof(rayl), rayl);
    VkMemoryBarrier2 tr{VK_STRUCTURE_TYPE_MEMORY_BARRIER_2};
    tr.srcStageMask = VK_PIPELINE_STAGE_2_ALL_TRANSFER_BIT; tr.srcAccessMask = VK_ACCESS_2_TRANSFER_WRITE_BIT;
    tr.dstStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
    tr.dstAccessMask = VK_ACCESS_2_SHADER_STORAGE_READ_BIT | VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    VkDependencyInfo td{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
    td.memoryBarrierCount = 1; td.pMemoryBarriers = &tr;
    vkCmdPipelineBarrier2(cmd, &td);
}

// After the reflect pass(es), before BASE / COMBINE (the split layout's sets + push are bound
// again when it returns):
//   RT TRACE (indirect over the tile list; RT layout) -- or, RenderVKRTReflectionsRayList, RT RAY
//   SELECT (indirect over the tile list) -> barrier -> RT TRACE over the ray list (indirect, one
//   lane per ray) -- + RT FORWARD (half-res grid; RT layout, independent of the trace) -> barrier
//   -> RT RESOLVE (indirect; the split layout) -> the spliced words. Empty screen: indirect
//   dispatches of 0 groups + the forward pass (its camera rays over the blend / water classes,
//   when RenderVKRTReflectionsForward is on).
// GPU timers (c_ on the async queue): g_defer_rtrefl_wait (the reflect passes' drain),
// g_defer_rtrefl_sel (the ray list's selection), g_defer_rtrefl_trace (the trace; #1036
// RenderVKRTReflectionsShadeSplit: its walk, then g_defer_rtrefl_mat / _tail / _light),
// g_defer_rtrefl_fwd (forward / water layer), g_defer_rtrefl (the resolve). (The trace and forward
// dispatches have no barrier between them: on a GPU that overlaps them the two marks split one window.)
void LLCleanRendererVK::recordRtReflect(VkCommandBuffer cmd, const VKDeferPush& p, uint32_t viewOff, bool onAsync)
{
    if (!mRtReflNow || !mRtTracePipe || !mRtResolvePipe || !mRtReflLayout || !mRT) return;
    const VkDescriptorSet rtSet = mRT->consumerSet();
    if (rtSet == VK_NULL_HANDLE) return;
    VkMemoryBarrier2 m{VK_STRUCTURE_TYPE_MEMORY_BARRIER_2};
    m.srcStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; m.srcAccessMask = VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    m.dstStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT | VK_PIPELINE_STAGE_2_DRAW_INDIRECT_BIT;
    m.dstAccessMask = VK_ACCESS_2_SHADER_STORAGE_READ_BIT | VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT
                    | VK_ACCESS_2_INDIRECT_COMMAND_READ_BIT;
    VkDependencyInfo d{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
    d.memoryBarrierCount = 1; d.pMemoryBarriers = &m;
    // RT FORWARD writes mDsRtFwd, which the previous frame's forward FS sampled (WAR).
    VkImageMemoryBarrier2 fb{VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER_2};
    fb.srcStageMask = VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT;
    fb.dstStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; fb.dstAccessMask = VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    fb.oldLayout = VK_IMAGE_LAYOUT_GENERAL; fb.newLayout = VK_IMAGE_LAYOUT_GENERAL;
    fb.image = mDsRtFwd.image; fb.subresourceRange = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 1};
    if (mRtFwdNow && mDsRtFwd.image) { d.imageMemoryBarrierCount = 1; d.pImageMemoryBarriers = &fb; }
    vkCmdPipelineBarrier2(cmd, &d);
    gpuSubMark(cmd, onAsync ? "c_defer_rtrefl_wait" : "g_defer_rtrefl_wait");   // (the reflect passes' tail)
    const VKRtReflPush rp = rtReflPush(p);
    const VkDescriptorSet sets[5] = {mDsetDraw0, mDsetDraw1, mDsetDefer, mDsetDeferSplit, rtSet};
    vkCmdBindDescriptorSets(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mRtReflLayout, 0, 5, sets, 1, &viewOff);
    VK_PUSH_BUDGET_CHECK(rp);
    vkCmdPushConstants(cmd, mRtReflLayout, VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(rp), &rp);
    if (mRtReflRayList && mRtSelectPipe && mRtTraceListPipe)
    {
        // RAY LIST (RenderVKRTReflectionsRayList): SELECT (one 8x8 workgroup per listed tile: the
        // same rays, appended) -> barrier -> TRACE (indirect, 64 rays per workgroup). The in-tile
        // trace ran the heavy per-ray tail in warps holding the tile's few rays (~1-3 of 64 lanes
        // at a weak-reflector scene): its cost followed the listed tiles, not the rays.
        vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mRtSelectPipe);
        vkCmdDispatchIndirect(cmd, mDsRtTiles.buffer, 0);
        VkMemoryBarrier2 sm{VK_STRUCTURE_TYPE_MEMORY_BARRIER_2};
        sm.srcStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; sm.srcAccessMask = VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
        sm.dstStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT | VK_PIPELINE_STAGE_2_DRAW_INDIRECT_BIT;
        sm.dstAccessMask = VK_ACCESS_2_SHADER_STORAGE_READ_BIT | VK_ACCESS_2_INDIRECT_COMMAND_READ_BIT;
        VkDependencyInfo sd{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
        sd.memoryBarrierCount = 1; sd.pMemoryBarriers = &sm;
        vkCmdPipelineBarrier2(cmd, &sd);
        gpuSubMark(cmd, onAsync ? "c_defer_rtrefl_sel" : "g_defer_rtrefl_sel");
        // (clean_deferred_light.comp RAY LIST: the dispatch at rtt_words[2n + 2])
        const VkDeviceSize argOff = kRtTilesHdrBytes + ((VkDeviceSize)mDsRtTileCount * 2u + 2u) * sizeof(uint32_t);
        if (mRtSplitNow && mRtRec.buffer && mRtRec.address)
        {
            // (#1036) THE RT REFLECTION SPLIT (clean_deferred_light.comp): TRACE -> MAT -> LIGHT over the
            // records (lane = list entry, below the capacity), the fused list kernel as the TAIL over the
            // entries past it -- all four indirect over the list's dispatch; each stage reads what the one
            // before it wrote (compute -> compute RAW). The push: rtr3.x the capacity, rtr3.zw the address.
            VKRtReflPush sp = rp;
            sp.rtr3[0] = mRtRecCap;
            sp.rtr3[2] = (uint32_t)(mRtRec.address & 0xFFFFFFFFull);
            sp.rtr3[3] = (uint32_t)(mRtRec.address >> 32);
            vkCmdPushConstants(cmd, mRtReflLayout, VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(sp), &sp);
            VkMemoryBarrier2 rm{VK_STRUCTURE_TYPE_MEMORY_BARRIER_2};
            rm.srcStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; rm.srcAccessMask = VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
            rm.dstStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
            rm.dstAccessMask = VK_ACCESS_2_SHADER_STORAGE_READ_BIT | VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
            VkDependencyInfo rd{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
            rd.memoryBarrierCount = 1; rd.pMemoryBarriers = &rm;
            // (#1039 M1, RenderVKVisQueue) THE VISIBILITY QUEUE: MAT queues the hits' sun rays (its producer
            // variant), the walk traces them, LIGHT resolves (no sun walk in it); the entries past the region's
            // capacity take the fused LIGHT as a tail (push rtr3.y = the first). The queue's stages find the
            // records through the region header (their push rtr3.zw names the region).
            // (#1039 M2, bit 2: pipeline set 1) MAT also queues the hits' occlusion ray and the budget's light
            // rays, a LAYERS stage beside the walk gathers the blend layers, LIGHT holds no ray query.
            const uint32_t vs = mVqSet;
            const bool vq = mVqRtNow && mVq.buffer && mVisWalkPipe && mRtVqPipe[vs][VQS_MAT] && mRtVqPipe[vs][VQS_LIGHT]
                         && (vs == 0u || mRtVqPipe[vs][VQS_LAYERS]);
            VKRtReflPush vp = sp;
            if (vq)
            {
                visQueueBegin(cmd, VQR_RT, mRtRec.address, mRtRecCap);
                const VkDeviceAddress qa = visQueueAddr(VQR_RT);
                vp.rtr3[0] = 0u;
                vp.rtr3[1] = 0u;
                vp.rtr3[2] = (uint32_t)(qa & 0xFFFFFFFFull);
                vp.rtr3[3] = (uint32_t)(qa >> 32);
            }
            vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mRtSplitPipe[RTS_TRACE]);
            vkCmdDispatchIndirect(cmd, mDsRtTiles.buffer, argOff);
            gpuSubMark(cmd, onAsync ? "c_defer_rtrefl_trace" : "g_defer_rtrefl_trace");
            vkCmdPipelineBarrier2(cmd, &rd);
            if (vq) vkCmdPushConstants(cmd, mRtReflLayout, VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(vp), &vp);
            vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, vq ? mRtVqPipe[vs][VQS_MAT] : mRtSplitPipe[RTS_MAT]);
            vkCmdDispatchIndirect(cmd, mDsRtTiles.buffer, argOff);
            gpuSubMark(cmd, onAsync ? "c_defer_rtrefl_mat" : "g_defer_rtrefl_mat");
            // (the tail's rays are its own: no barrier against MAT; mostly workgroups that find no entry)
            if (vq) vkCmdPushConstants(cmd, mRtReflLayout, VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(sp), &sp);
            vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mRtTraceListPipe);
            vkCmdDispatchIndirect(cmd, mDsRtTiles.buffer, argOff);
            gpuSubMark(cmd, onAsync ? "c_defer_rtrefl_tail" : "g_defer_rtrefl_tail");
            if (vq)
            {
                // MAT's requests + its raised dispatch -> the walk (storage + indirect); the walk's results ->
                // LIGHT (storage)
                VkMemoryBarrier2 im = rm;
                im.dstStageMask |= VK_PIPELINE_STAGE_2_DRAW_INDIRECT_BIT;
                im.dstAccessMask |= VK_ACCESS_2_INDIRECT_COMMAND_READ_BIT;
                VkDependencyInfo id{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
                id.memoryBarrierCount = 1; id.pMemoryBarriers = &im;
                vkCmdPipelineBarrier2(cmd, &id);
                visQueueWalk(cmd, VQR_RT, sp);
                gpuSubMark(cmd, onAsync ? "c_defer_rtrefl_walk" : "g_defer_rtrefl_walk");
                if (vs == 1u && mRtReflBlend)
                {
                    // (set 1) the blend layers of every queued entry -> its layer slot: MAT's records and flags
                    // only (no barrier against the walk -- disjoint slots)
                    vkCmdPushConstants(cmd, mRtReflLayout, VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(vp), &vp);
                    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mRtVqPipe[vs][VQS_LAYERS]);
                    vkCmdDispatchIndirect(cmd, mDsRtTiles.buffer, argOff);
                    gpuSubMark(cmd, onAsync ? "c_defer_rtrefl_layers" : "g_defer_rtrefl_layers");
                }
                vkCmdPipelineBarrier2(cmd, &rd);
                vkCmdPushConstants(cmd, mRtReflLayout, VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(vp), &vp);
                vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mRtVqPipe[vs][VQS_LIGHT]);
                vkCmdDispatchIndirect(cmd, mDsRtTiles.buffer, argOff);
                if (mVqRegion[VQR_RT].entries < mRtRecCap)
                {
                    // the entries past the region: the fused LIGHT from the first of them (independent entries:
                    // no barrier against the resolve)
                    VKRtReflPush tp = sp;
                    tp.rtr3[1] = mVqRegion[VQR_RT].entries;
                    vkCmdPushConstants(cmd, mRtReflLayout, VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(tp), &tp);
                    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mRtSplitPipe[RTS_LIGHT]);
                    vkCmdDispatchIndirect(cmd, mDsRtTiles.buffer, argOff);
                }
                gpuSubMark(cmd, onAsync ? "c_defer_rtrefl_light" : "g_defer_rtrefl_light");
                visQueueStats(cmd, VQR_RT);
            }
            else
            {
                vkCmdPipelineBarrier2(cmd, &rd);
                vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mRtSplitPipe[RTS_LIGHT]);
                vkCmdDispatchIndirect(cmd, mDsRtTiles.buffer, argOff);
                gpuSubMark(cmd, onAsync ? "c_defer_rtrefl_light" : "g_defer_rtrefl_light");
            }
            vkCmdPushConstants(cmd, mRtReflLayout, VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(rp), &rp);
        }
        else
        {
            vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mRtTraceListPipe);
            vkCmdDispatchIndirect(cmd, mDsRtTiles.buffer, argOff);
            gpuSubMark(cmd, onAsync ? "c_defer_rtrefl_trace" : "g_defer_rtrefl_trace");
        }
    }
    else
    {
        vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mRtTracePipe);
        vkCmdDispatchIndirect(cmd, mDsRtTiles.buffer, 0);   // one 8x8 workgroup per listed tile
        gpuSubMark(cmd, onAsync ? "c_defer_rtrefl_trace" : "g_defer_rtrefl_trace");
    }
    if (mRtFwdNow && mDsRtFwd.image)
    {
        const uint32_t hw = (p.width + 1u) / 2u, hh = (p.height + 1u) / 2u;
        vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mRtFwdPipe);
        vkCmdDispatch(cmd, (hw + 7u) / 8u, (hh + 7u) / 8u, 1);   // 8x8 over the half-resolution grid
        mRtFwdDirty = true;
        gpuSubMark(cmd, onAsync ? "c_defer_rtrefl_fwd" : "g_defer_rtrefl_fwd");   // (the empty-screen floor)
    }
    // trace -> resolve; forward -> the forward / water FS (sampled; the async join covers it there)
    m.dstStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT | VK_PIPELINE_STAGE_2_FRAGMENT_SHADER_BIT;
    m.dstAccessMask = VK_ACCESS_2_SHADER_STORAGE_READ_BIT | VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT
                    | VK_ACCESS_2_SHADER_SAMPLED_READ_BIT;
    d.imageMemoryBarrierCount = 0; d.pImageMemoryBarriers = nullptr;
    vkCmdPipelineBarrier2(cmd, &d);
    // RT RESOLVE on the split layout (incompatible push range: every set re-bound) -- which the
    // passes after it keep.
    const VkDescriptorSet ssets[4] = {mDsetDraw0, mDsetDraw1, mDsetDefer, mDsetDeferSplit};
    vkCmdBindDescriptorSets(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mDeferSplitLayout, 0, 4, ssets, 1, &viewOff);
    vkCmdPushConstants(cmd, mDeferSplitLayout, VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(p), &p);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mRtResolvePipe);
    vkCmdDispatchIndirect(cmd, mDsRtTiles.buffer, 0);
    gpuSubMark(cmd, onAsync ? "c_defer_rtrefl" : "g_defer_rtrefl");
    rtReflStatsRecord(cmd);
}

// RAY DENSITY stats (#859; GPU timers on): harvest the ring slot written 3 RT frames ago (frames in
// flight <= 2), then copy this frame's tile list header into it (after the trace's atomics). No
// wait anywhere: a slot is only read once its copy is three submissions old.
void LLCleanRendererVK::rtReflStatsRecord(VkCommandBuffer cmd)
{
    VkMemScope memcat(VKMEM_READBACK);   // #407
    if (!mTsOn || !mDsRtTiles.buffer) return;
    if (!mRtrStatRb.buffer)
    {
        mRtrStatRb = mCtx->createBuffer(3u * kRtTilesHdrBytes, VK_BUFFER_USAGE_TRANSFER_DST_BIT,
                                        VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT);
        for (bool& u : mRtrStatUsed) u = false;
        if (!mRtrStatRb.buffer) return;
    }
    const uint32_t slot = ++mRtrStatFrame % 3u;
    if (mRtrStatUsed[slot] && mRtrStatRb.mapped)
    {
        const uint32_t* h = reinterpret_cast<const uint32_t*>(mRtrStatRb.mapped) + slot * kRtTilesHdrWords;
        RtrStatAcc& a = mRtrStatAcc;
        // (clean_deferred_light.comp RtReflTiles: words 4-6 rays per level, 7 cand, 8 cast, 9 / 10 the
        // level ping-pong, 18 the budget, 19 floor | parity << 8)
        for (int L = 0; L < 3; ++L) a.rays[L] += h[4 + L];
        a.cand += h[7];
        a.cast += h[8];
        for (int k = 0; k < 5; ++k) a.hit[k] += h[11 + k];
        // (words 26-51: the gradient's sums, pass 11's trace-cost counters; 24 / 25 the gradient's
        // scale ping-pong, 20 its options)
        bool anyCost = false;
        for (uint32_t k = 0; k < kRtCostWords; ++k) { a.cost[k] += h[28 + k]; anyCost |= h[28 + k] != 0u; }
        if (anyCost) ++a.costFrames;
        if ((h[20] & 1u) != 0u && h[8] != 0u)
        {
            a.grays += h[26];
            a.rhosum += h[27];
            a.gcand += h[7];
            float sc = 1.f;
            std::memcpy(&sc, &h[24 + ((h[19] >> 8) & 1u)], 4);
            a.scale += std::isfinite(sc) ? (double)sc : 0.0;
            ++a.gradFrames;
        }
        // (words 56-62: the strength density's candidates / strength sums by type, the cut count)
        for (int t = 0; t < 3; ++t) { a.scand[t] += h[56 + t]; a.ssum[t] += h[59 + t]; }
        a.scut += h[62];
        a.amresc += h[63];   // (rtt_amresc: pass 11's avatar alpha-mask hits the coverage rule kept)
        a.tiles += h[64];    // (rtt_tiles: tiles listed -- the in-tile trace's workgroups)
        a.ovf += h[65];      // (rtt_ovf: ray list overflow; 0 with the tiles x 64 capacity)
        a.budget += h[18] == 0xFFFFFFFFu ? 0.0 : (double)h[18];
        const uint32_t lvl = h[9 + ((h[19] >> 8) & 1u)];
        if (h[8] != 0u) ++a.level[std::min<uint32_t>(lvl, 2u)];   // (frames that cast rays)
        ++a.frames;
    }
    VkMemoryBarrier2 m{VK_STRUCTURE_TYPE_MEMORY_BARRIER_2};
    m.srcStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; m.srcAccessMask = VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    m.dstStageMask = VK_PIPELINE_STAGE_2_COPY_BIT; m.dstAccessMask = VK_ACCESS_2_TRANSFER_READ_BIT;
    VkDependencyInfo d{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
    d.memoryBarrierCount = 1; d.pMemoryBarriers = &m;
    vkCmdPipelineBarrier2(cmd, &d);
    const VkBufferCopy r{0, (VkDeviceSize)slot * kRtTilesHdrBytes, kRtTilesHdrBytes};
    vkCmdCopyBuffer(cmd, mDsRtTiles.buffer, mRtrStatRb.buffer, 1, &r);
    mRtrStatUsed[slot] = true;
    // (#869) LIGHT RESERVOIR GRID: its header (the build's + the trace's counters, the reach mask)
    // into the same slot of its own ring, with the host's changed-light mask of this frame. The
    // slot is harvested above's way: three RT frames later, or dropped (a frame without the grid).
    if (mRegirStatUsed[slot] && mRegirStatRb.mapped)
    {
        const RegirHeader* g = reinterpret_cast<const RegirHeader*>(
            static_cast<const uint8_t*>(mRegirStatRb.mapped) + (size_t)slot * sizeof(RegirHeader));
        RegirStatAcc& a = mRegirStatAcc;
        for (int k = 0; k < 12; ++k) a.stat[k] += g->stat[k];
        uint32_t reach = 0, changedReach = 0;
        for (int w = 0; w < 8; ++w)
        {
            reach += (uint32_t)__builtin_popcount(g->reach[w]);
            changedReach += (uint32_t)__builtin_popcount(g->reach[w] & mRegirStatChanged[slot][w]);
        }
        a.reach += reach;
        a.changedReach += changedReach;
        a.changedAll += mRegirStatChangedN[slot];
        a.lights += mRegirStatLights[slot];
        ++a.frames;
    }
    mRegirStatUsed[slot] = false;
    if (mRegirNow && mRegir.buffer)
    {
        if (!mRegirStatRb.buffer)
            mRegirStatRb = mCtx->createBuffer(3u * sizeof(RegirHeader), VK_BUFFER_USAGE_TRANSFER_DST_BIT,
                                              VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT);
        if (mRegirStatRb.buffer)
        {
            const VkBufferCopy gr{0, (VkDeviceSize)slot * sizeof(RegirHeader), sizeof(RegirHeader)};
            vkCmdCopyBuffer(cmd, mRegir.buffer, mRegirStatRb.buffer, 1, &gr);
            std::memcpy(mRegirStatChanged[slot], mRegirChanged, sizeof(mRegirChanged));
            mRegirStatChangedN[slot] = mRegirChangedN;
            mRegirStatLights[slot] = (uint32_t)std::min<size_t>(mLightsCPU.size(), MAX_VK_LIGHTS);
            mRegirStatUsed[slot] = true;
        }
    }
}

// "RT reflections over N frames: ..." (per-frame averages) for the VKGpu timer log; resets.
std::string LLCleanRendererVK::rtReflStatsText()
{
    RtrStatAcc& a = mRtrStatAcc;
    if (!a.frames) return std::string();
    const double k = 1.0 / a.frames;
    std::ostringstream os;
    os << std::fixed << std::setprecision(0) << "RT reflections over " << a.frames << " frames (per frame): cand="
       << a.cand * k << " rays@level0/1/2=" << a.rays[0] * k << "/" << a.rays[1] * k << "/" << a.rays[2] * k
       << " cast=" << a.cast * k << " tiles=" << a.tiles * k << " (rays/tile "
       << std::setprecision(2) << (a.tiles > 0.0 ? a.cast / a.tiles : 0.0) << std::setprecision(0) << ", ray list "
       << (mRtReflRayList && mRtSelectPipe && mRtTraceListPipe ? "on" : "off");
    if (mRtSplitNow) os << ", split trace: " << mRtRecCap << " ray records";   // (#1036: the cast past them took the tail)
    if (a.ovf > 0.0) os << ", overflow " << a.ovf * k;
    os << ") budget=";
    if (a.budget > 0.0) os << a.budget * k; else os << "none";
    os << " level frames 0/1/2=" << a.level[0] << "/" << a.level[1] << "/" << a.level[2]
       << " (floor " << mRtReflFloor << ", recv " << std::setprecision(1) << mRtReflMaxRecv << " m, sharp "
       << std::setprecision(2) << mRtReflSharp << ", curvature density "
       << std::setprecision(1) << mRtReflCurvRad * (180.f / F_PI) << " deg, lobe filter " << (mRtReflLobe ? "on" : "off")
       << ", temporal " << (mRtReflTemporal && mDsRtHistFull ? "on" : "off") << ")";
    // STRENGTH DENSITY (the mark passes' rtt_scand / rtt_ssum / rtt_scut): which content spends the
    // rays -- candidates and their mean reflection strength per type, and what the cutoff removed.
    {
        static const char* kType[3] = {"pbr", "legacy-env", "legacy-glossenv"};
        os << " | candidates by type:";
        for (int t = 0; t < 3; ++t)
            os << " " << kType[t] << "=" << std::setprecision(0) << a.scand[t] * k << " (mean strength "
               << std::setprecision(3) << (a.scand[t] > 0.0 ? a.ssum[t] / 256.0 / a.scand[t] : 0.0) << ")";
        os << " strength-cut=" << std::setprecision(0) << a.scut * k;
        if (mRtReflStrength)
            os << " (RenderVKRTReflectionsStrength: full " << std::setprecision(3) << mRtReflStrFull << ", min "
               << mRtReflStrMin << ", cut " << mRtReflStrCut << ")";
        else
            os << " (RenderVKRTReflectionsStrength off)";
    }
    // HIT SHADING (pass 11's counters): what each reflection ray paid after its closest hit -- the
    // part of the trace's GPU time the ray budget above does not see.
    if (a.cast > 0.0)
    {
        const double hits = a.hit[4];
        const double ph = hits > 0.0 ? 1.0 / hits : 0.0;
        os << " | hit shading: hits/ray=" << std::setprecision(2) << hits / a.cast
           << " lights/hit=" << a.hit[0] * ph << " proj-shadow wanted/hit=" << a.hit[1] * ph
           << " cast/hit=" << a.hit[2] * ph << " (budget " << mRtReflHitShadows
           << ", RenderVKRTReflectionsHitShadowRays) blend cand/ray=" << a.hit[3] / a.cast;
        // (#869) LIGHT RESERVOIR GRID (clean_regir.glsl stat words; RenderVKLightGrid*)
        RegirStatAcc& g = mRegirStatAcc;
        if (!mRegirNow && g.frames == 0u)
            os << " grid=off (RenderVKLightGrid)";
        else if (g.frames > 0u && hits > 0.0)
        {
            const double gk = 1.0 / g.frames;
            // hit fractions: the grid frames' hits only (a.hit[4] spans every frame of the window)
            const double gh = g.stat[3] + g.stat[4] + g.stat[5] + g.stat[6];
            const double gp = gh > 0.0 ? 1.0 / gh : 0.0;
            const double cells = g.stat[0] * gk;
            const double liveB = (double)sizeof(RegirHeader)
                               + (double)mRegirLevels * kRegirCellsPerLevel * (mRegirRes + 1u) * 8.0;
            os << " grid=" << (mRegirNow ? "on" : "off(last frames on)")
               << " hits grid/exact=" << (g.stat[3] + g.stat[4]) * gp << "/" << (g.stat[5] + g.stat[6]) * gp
               << " (sampled " << g.stat[3] * gp << ", exact-list cell " << g.stat[4] * gp
               << ", footprint < " << std::setprecision(1) << mRegirFootCm << " cm " << std::setprecision(2)
               << g.stat[5] * gp << ", outside grid " << g.stat[6] * gp << ")"
               << " cand/cell=" << (g.stat[0] > 0.0 ? g.stat[1] / g.stat[0] : 0.0)
               << " (max " << std::setprecision(0) << g.stat[2] * gk << std::setprecision(2)
               << ", at sampled hits " << (g.stat[3] > 0.0 ? g.stat[8] / g.stat[3] : 0.0) << ")"
               << " picks/sampled-hit=" << (g.stat[3] > 0.0 ? g.stat[7] / g.stat[3] : 0.0)
               << " (" << mRegirPicks << " of " << mRegirRes << " reservoirs, RenderVKLightGridPicks / _Reservoirs)"
               << " changed lights: evaluated/hit=" << (gh > 0.0 ? g.stat[9] / gh : 0.0)
               << " reaching the grid " << std::setprecision(1) << g.changedReach * gk << " of " << g.reach * gk
               << " (all lights: " << g.changedAll * gk << " of " << g.lights * gk << ")"
               << " grid mem live/cap=" << liveB / 1048576.0 << "/" << (double)kRegirBytes / 1048576.0
               << " MB (cells with lights " << std::setprecision(0) << cells << " of "
               << mRegirLevels * kRegirCellsPerLevel << ")";
        }
    }
    // TRACE COST (pass 11's rtt_cost counters, frames with GPU timers on): where each reflection
    // ray's traversal goes -- hit distances, the closest-hit walk's passes and shader candidates.
    if (a.costFrames > 0u)
    {
        const double* c = a.cost;
        double rays = c[6];
        for (int b = 0; b < 6; ++b) rays += c[b];
        if (rays > 0.0)
        {
            const double r = 1.0 / rays;
            os << " | trace cost (" << std::setprecision(0) << rays / a.costFrames
               << std::setprecision(3) << " rays/frame): hit dist 0-2/2-4/4-8/8-16/16-32/32+ m="
               << c[0] * r << "/" << c[1] * r << "/" << c[2] * r << "/" << c[3] * r << "/" << c[4] * r << "/" << c[5] * r
               << " miss=" << c[6] * r
               << " traversals/ray=" << c[7] * r << " backface retraces/ray=" << c[8] * r
               << " (hw cull " << (mRtReflHWCull ? "on" : "off") << ", RenderVKRTReflectionsHWCull)"
               << " retraced>=1=" << c[9] * r << " shader cand/ray=" << c[10] * r << " at cand budget=" << c[11] * r;
            if (c[12] > 0.0)
            {
                const double sg = 1.0 / c[12];
                os << " size segments: segmented=" << c[12] * r << " far segment ran=" << c[13] * sg
                   << " hits near/far=" << c[14] * sg << "/" << c[15] * sg
                   << " mean boundary=" << std::setprecision(1) << c[16] * 0.25 * sg << " m" << std::setprecision(3);
            }
            else os << " size segments=off";
            os << " (RenderVKRTReflectionsSizeClasses " << (mRtReflSizeClasses ? 1 : 0) << ", bound "
               << std::setprecision(2) << mRtReflSmallSize << " m, " << mRtReflSmallPx << " px / fixed "
               << std::setprecision(1) << mRtReflSmallDist << " m)" << std::setprecision(3);
            // AVATAR ALPHA-MASK candidates (rigged / worn / own avatar; clean_deferred_light.comp
            // rtrClosest): alpha-tested in the shader, rejected below the cutoff, and kept only by
            // the coverage rule (maskTestAlpha). tested 0 while the avatar is in a reflection = its
            // cut-out faces never reach the test (class / culling / geometry), not an alpha problem.
            os << " avatar mask cand: tested/ray=" << c[22] * r << " rejected="
               << (c[22] > 0.0 ? c[23] / c[22] : 0.0) << " rescued by coverage="
               << (c[22] > 0.0 ? a.amresc / c[22] : 0.0) << std::setprecision(0) << " (" << c[22] << "/"
               << c[23] << "/" << a.amresc << " over " << a.costFrames << " frames; RenderVKRTReflectionsMaskTest "
               << mRtReflMaskTest << " = " << (mRtReflMaskTest == 0u ? "raster parity" : mRtReflMaskTest == 1u ? "legacy cone LOD"
                                               : mRtReflMaskTest == 2u ? "mip 0" : "off: every mask candidate solid")
               << ")" << std::setprecision(3);
            const double bands = c[17] + c[18] + c[19] + c[20];
            if (bands > 0.0)
            {
                const double bk = 1.0 / bands;
                os << " ray density bands >=1/2, 1/8-1/2, 1/32-1/8, <1/32=" << c[17] * bk << "/" << c[18] * bk
                   << "/" << c[19] * bk << "/" << c[20] * bk << " mean rho/ray=" << c[21] / 256.0 * bk;
            }
        }
    }
    if (a.gradFrames > 0u)
    {
        const double gk = 1.0 / a.gradFrames;
        os << std::setprecision(0) << " | density gradient (" << a.gradFrames << " frames): rays@scale1="
           << a.grays * gk << std::setprecision(3)
           << " mean rho/cand=" << (a.gcand > 0.0 ? a.rhosum / 256.0 / a.gcand : 0.0)
           << " budget scale=" << a.scale * gk << " (RenderVKRTReflectionsDensityGradient, min "
           << mRtReflDensityMin << ", curve " << std::setprecision(2) << mRtReflDensityCurve
           << "; the levels' rays@ counts read 0 while it is on)";
    }
    mRegirStatAcc = RegirStatAcc{};
    a = RtrStatAcc{};
    return os.str();
}

// Uber frames (#859): the pre-trace into mRtUber before the uber kernel (which binds its own
// pipeline, sets and push right after). GPU timer: g_defer_rtrefl_pre (c_ on the async queue).
void LLCleanRendererVK::recordRtPreTrace(VkCommandBuffer cmd, const VKDeferPush& p, uint32_t viewOff)
{
    if (!mRtUberNow || !mRtPreTracePipe || !mRtUberLayout || !mRT || !mRtUber.image) return;
    const VkDescriptorSet rtSet = mRT->consumerSet();
    if (rtSet == VK_NULL_HANDLE) return;
    const bool onAsync = mAsyncAvail && vkAsyncIsAsyncCmd(cmd);
    // last frame's uber kernel read mRtUber (WAR)
    VkImageMemoryBarrier2 b{VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER_2};
    b.srcStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
    b.dstStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; b.dstAccessMask = VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    b.oldLayout = VK_IMAGE_LAYOUT_UNDEFINED; b.newLayout = VK_IMAGE_LAYOUT_GENERAL;
    b.image = mRtUber.image; b.subresourceRange = {VK_IMAGE_ASPECT_COLOR_BIT, 0, 1, 0, 1};
    VkDependencyInfo d{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
    d.imageMemoryBarrierCount = 1; d.pImageMemoryBarriers = &b;
    vkCmdPipelineBarrier2(cmd, &d);
    const VKRtReflPush rp = rtReflPush(p);
    const VkDescriptorSet sets[4] = {mDsetDraw0, mDsetDraw1, mDsetDefer, rtSet};
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mRtPreTracePipe);
    vkCmdBindDescriptorSets(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, mRtUberLayout, 0, 4, sets, 1, &viewOff);
    VK_PUSH_BUDGET_CHECK(rp);
    vkCmdPushConstants(cmd, mRtUberLayout, VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(rp), &rp);
    vkCmdDispatch(cmd, (p.width + 7u) / 8u, (p.height + 7u) / 8u, 1);
    VkMemoryBarrier2 m{VK_STRUCTURE_TYPE_MEMORY_BARRIER_2};
    m.srcStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; m.srcAccessMask = VK_ACCESS_2_SHADER_STORAGE_WRITE_BIT;
    m.dstStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT; m.dstAccessMask = VK_ACCESS_2_SHADER_STORAGE_READ_BIT;
    VkDependencyInfo md{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
    md.memoryBarrierCount = 1; md.pMemoryBarriers = &m;
    vkCmdPipelineBarrier2(cmd, &md);
    gpuSubMark(cmd, onAsync ? "c_defer_rtrefl_pre" : "g_defer_rtrefl_pre");
}

const char* LLCleanRendererVK::sunRtOffReason() const
{
    if (!mRT) return "ray tracing unavailable";
    if (!mLitVar[1][LIT_DRAW]) return "no ray-query lit pipeline";
    if (mRT->overBudget()) return "RT over its memory budget";
    if (!mRT->sunReady()) return "RT warming up (BLAS rebuilding)";
    if (!mRT->tlasValid()) return "TLAS not valid this frame";
    return "no ray-traced shadows this frame";
}

// ---- GPU pass timers (RenderVKGpuTimers): timestamp per pass boundary, read back a
// frame later WITHOUT waiting (VK_NOT_READY -> skip), averaged + logged every ~5 s. ----
void LLCleanRendererVK::gpuTimersBegin(VkCommandBuffer cmd)
{
    rigGpuTimeBegin(cmd);   // #613: the rigged perf trigger's own sampled timestamps (always on)
    bool ts_log = true;     // #422: the VKGpu log lines (RenderVKGpuTimers itself on)
#if defined(LL_HAS_CLEAN_PIPELINE)
    static LLCachedControl<bool> s_on(gSavedSettings, "RenderVKGpuTimers", false);
    // #422: also while the auto-tuner wants the per-pass breakdown (Performance window
    // open, Tune once measuring) -- without the VKGpu log lines unless the setting is on.
    mTsOn = s_on || LLVKAutoTune::wantPassTimers();
    ts_log = s_on;
#endif
    // #790: timers unusable on this device (no timestamps on the graphics family, or the
    // pools could not be made): stay off for the session, said once in the log.
    if (mTsUnavailable) mTsOn = false;
    if (!mTsOn) { mClGpuSubLine.clear(); mPrbGpuSubLine.clear(); return; }   // (the CLOD gpu sub line says "off", never stale)
    VkDevice dev = mCtx->device();
    if (!mTsPoolR[0])
    {
        // #790: the graphics family must write timestamps (timestampValidBits > 0; the
        // rigged timer and the cluster stream check the same). Pools are made soft: a
        // failure turns the timers off instead of aborting (VK_CHECK).
        uint32_t nf = 0;
        vkGetPhysicalDeviceQueueFamilyProperties(mCtx->physicalDevice(), &nf, nullptr);
        std::vector<VkQueueFamilyProperties> qf(nf);
        if (nf) vkGetPhysicalDeviceQueueFamilyProperties(mCtx->physicalDevice(), &nf, qf.data());
        const uint32_t fam = mCtx->queueFamily();
        const uint32_t bits = fam < nf ? qf[fam].timestampValidBits : 0u;
        VkPhysicalDeviceProperties pp{};
        vkGetPhysicalDeviceProperties(mCtx->physicalDevice(), &pp);
        bool ok = bits != 0u && pp.limits.timestampPeriod > 0.f;
        VkQueryPoolCreateInfo qi{VK_STRUCTURE_TYPE_QUERY_POOL_CREATE_INFO};
        qi.queryType = VK_QUERY_TYPE_TIMESTAMP;
        for (uint32_t r = 0; r < TS_RING && ok; ++r)
        {
            // (a failed create leaves its handle undefined: zero it for the cleanup below)
            auto make = [&](uint32_t n, VkQueryPool& out)
            {
                qi.queryCount = n;
                if (vkCreateQueryPool(dev, &qi, nullptr, &out) == VK_SUCCESS) return true;
                out = VK_NULL_HANDLE;
                return false;
            };
            ok = make(TS_COUNT, mTsPoolR[r]);
            ok = ok && make(SUB_TS, mSubPoolR[r]);
            ok = ok && make(kFeTs, mFePoolR[r]);
            mFeCountR[r] = 0;
            mTsPendingR[r] = false;
        }
        if (!ok)
        {
            for (uint32_t r = 0; r < TS_RING; ++r)
            {
                if (mTsPoolR[r]) vkDestroyQueryPool(dev, mTsPoolR[r], nullptr);
                if (mSubPoolR[r]) vkDestroyQueryPool(dev, mSubPoolR[r], nullptr);
                if (mFePoolR[r]) vkDestroyQueryPool(dev, mFePoolR[r], nullptr);
                mTsPoolR[r] = mSubPoolR[r] = mFePoolR[r] = VK_NULL_HANDLE;
            }
            mTsPool = mSubPool = mFePool = VK_NULL_HANDLE;
            mTsUnavailable = true;
            mTsOn = false;
            LL_WARNS("VKGpu") << "GPU timers unavailable: "
                              << (bits == 0u ? "the graphics queue family has no timestamps (timestampValidBits 0)"
                                             : pp.limits.timestampPeriod > 0.f ? "query pools could not be created"
                                                                              : "timestampPeriod is 0")
                              << "; RenderVKGpuTimers stays off this session" << LL_ENDL;
            mClGpuSubLine.clear(); mPrbGpuSubLine.clear();
            return;
        }
        mTsMask = bits >= 64u ? ~0ull : ((1ull << bits) - 1ull);
        mTsPeriodNs = pp.limits.timestampPeriod;
        mTsSlot = 0;
        mSubCount = 0;
        mFeCount = 0;
        LL_INFOS("VKGpu") << "GPU timers on: " << TS_RING << " x (" << TS_COUNT << " + " << SUB_TS << " + " << kFeTs
                          << ") timestamp queries, " << bits << " valid bits, period " << mTsPeriodNs << " ns" << LL_ENDL;
    }
    else
    {
        // Close the slot the previous frame recorded into.
        mSubCountR[mTsSlot] = mSubCount;
        mFeCountR[mTsSlot] = mFeCount;
        mTsLeanR[mTsSlot] = mTsLeanRec;
        mTsJobR[mTsSlot] = mFrameJobs;
        mFrameJobs = 0u;
    }
    // Harvest the OLDEST slot (recorded TS_RING-1 frames ago -- complete by now), then
    // reuse it for this frame.
    const uint32_t h = (mTsSlot + 1u) % TS_RING;
    if (mTsPendingR[h])
    {
        const bool lean = mTsLeanR[h];
        uint64_t t[TS_COUNT] = {};
        // Lean frames (RenderVKGpuSubMarks off) wrote only the first and last timestamp:
        // read those two (a range read over unwritten queries is NOT_READY as a whole).
        bool got = false;
        if (lean)
            got = vkGetQueryPoolResults(dev, mTsPoolR[h], 0, 1, sizeof(uint64_t), &t[0], sizeof(uint64_t),
                                        VK_QUERY_RESULT_64_BIT) == VK_SUCCESS
               && vkGetQueryPoolResults(dev, mTsPoolR[h], TS_COUNT - 1, 1, sizeof(uint64_t), &t[TS_COUNT - 1],
                                        sizeof(uint64_t), VK_QUERY_RESULT_64_BIT) == VK_SUCCESS;
        else
            got = vkGetQueryPoolResults(dev, mTsPoolR[h], 0, TS_COUNT, sizeof(t), t, sizeof(uint64_t),
                                        VK_QUERY_RESULT_64_BIT) == VK_SUCCESS;
        if (got)
        {
            double f[TS_COUNT];
            for (int i = 1; i < TS_COUNT; ++i)
                f[i] = lean ? 0.0 : (double)((t[i] - t[i - 1]) & mTsMask) * mTsPeriodNs * 1e-6;
            f[0] = (double)((t[TS_COUNT - 1] - t[0]) & mTsMask) * mTsPeriodNs * 1e-6;
            for (int i = 0; i < TS_COUNT; ++i) mTsAccum[i] += f[i];
            if (f[0] > mTsWorst[0]) std::memcpy(mTsWorst, f, sizeof(mTsWorst));
            // GPU time of a recent frame into the hitch recorder (now TS_RING-1 frames late).
            LLVKHitch::add("gpu_prev_frame", f[0]);
            LLVKHitch::timelineGpu(f[0]);   // (the HITCH timeline line's gpu column)
            {
                // #946 the same frame's prologue (top -> timestamp 0) and the queue's gap before it
                // (the previous harvested frame's last timestamp -> top). Same queue, same clock;
                // an overlap (a negative span, wrapped) or a span over a second is no sample.
                uint64_t top = 0;
                const bool haveTop = mTsTopR[h] && mTsTopPool
                    && vkGetQueryPoolResults(dev, mTsTopPool, h, 1, sizeof(uint64_t), &top, sizeof(uint64_t),
                                             VK_QUERY_RESULT_64_BIT) == VK_SUCCESS;
                if (haveTop)
                {
                    const double pre = (double)((t[0] - top) & mTsMask) * mTsPeriodNs * 1e-6;
                    if (pre < 1000.0)
                    {
                        mTsPreAccum += pre;
                        ++mTsPreN;
                        LLVKHitch::add("gpu_prologue_prev", pre);
                    }
                    if (mTsPrevEndValid)
                    {
                        const double gap = (double)((top - mTsPrevEnd) & mTsMask) * mTsPeriodNs * 1e-6;
                        if (gap < 1000.0)
                        {
                            mTsGapAccum += gap;
                            mTsGapWorst = std::max(mTsGapWorst, gap);
                            ++mTsGapN;
                            LLVKHitch::add("gpu_gap_prev", gap);
                        }
                    }
                }
                mTsPrevEnd = t[TS_COUNT - 1];
                mTsPrevEndValid = true;
            }
#if defined(LL_HAS_CLEAN_PIPELINE)
            // PER-FRAME JOB LOG (measurement): the frame's GPU total next to the staggered jobs
            // it carried (bits 0-3 sun cascades re-rendered, 4-7 overlay cascades, 8-11
            // projector tiles re-rendered, 12 realtime probe, 13-15 scheduled probe face slot,
            // #825: 16 a far cascade re-render deferred, 17 a projector tile held behind one).
            static LLCachedControl<bool> s_jobLog(gSavedSettings, "RenderVKFrameJobLog", false);
            if (s_jobLog)
                LL_INFOS("VKFrameJob") << "FRAMEJOB gpu=" << f[0] << " jobs=0x" << std::hex << mTsJobR[h] << std::dec << LL_ENDL;
#endif
            ++mTsFrames;
            // Sub-marks of the same frame (only when the pass timers were read, so the
            // averages share one frame count).
            uint64_t st[SUB_TS] = {};
            const uint32_t n = lean ? 0u : std::min(mSubCountR[h], SUB_TS);
            if (n >= 2 && vkGetQueryPoolResults(dev, mSubPoolR[h], 0, n, sizeof(st), st, sizeof(uint64_t),
                                                VK_QUERY_RESULT_64_BIT) == VK_SUCCESS)
            {
                const char* const* names = mSubNamesR[h];
                const uint8_t* qs = mSubQueueR[h];
                auto addSub = [&](const char* name, double ms, bool async)
                {
                    SubAcc* acc = nullptr;
                    for (SubAcc& a : mSubAcc)
                        if (a.async == async && (a.name == name || std::strcmp(a.name, name) == 0)) { acc = &a; break; }
                    if (!acc) { mSubAcc.push_back({name, 0.0, 0.0, async}); acc = &mSubAcc.back(); }
                    acc->ms += ms;
                    acc->worst = std::max(acc->worst, ms);
                    LLVKBench::subSample(name, ms, async);
                };
                // Deltas PER QUEUE (async compute, phase 3a): timestamps of two queues are
                // not comparable. Graphics marks (tag 0) as before: from the previous
                // graphics mark (index 0 = "begin"). Async marks: from the previous async
                // mark; a segment's begin (2) has no delta, its end (3) reports the whole
                // segment as q_*. q_async_busy = sum of the segments, q_async_span = first
                // async begin -> last async end (both on the async queue's clock).
                const double k = mTsPeriodNs * 1e-6;
                uint32_t prevG = 0;
                int prevA = -1;
                uint64_t segBegin = 0, firstA = 0, lastA = 0;
                double busy = 0.0;
                double feWait = -1.0;   // frame pipelining: g_fe_wait (graphics clock)
                // (#978) GI EARLY TRACE: the graphics marks after g_gi_fork up to g_gi_window (the work
                // recorded beside the chain), g_join_gi (the wait), q_defer_light (the segment, async clock).
                bool giWin = false;
                double giBeside = 0.0, giJoin = -1.0, giSeg = -1.0;
                // (#978 phase 2) ONE-FRAME-LATENCY GI: q_gi_lag (its segment, async clock), g_join_gi_lag
                // (the graphics queue's wait for it after the HUD)
                double lagJoin = -1.0, lagSeg = -1.0;
                for (uint32_t i = 1; i < n; ++i)
                {
                    switch (qs[i])
                    {
                    case 0:
                    {
                        const double d = (double)((st[i] - st[prevG]) & mTsMask) * k;
                        addSub(names[i], d, false);
                        if (!std::strcmp(names[i], "g_fe_wait")) feWait = d;
                        if (giWin) giBeside += d;
                        if (!std::strcmp(names[i], "g_gi_fork")) { giWin = true; giBeside = 0.0; }
                        else if (!std::strcmp(names[i], "g_gi_window")) giWin = false;
                        else if (!std::strcmp(names[i], "g_join_gi")) giJoin = d;
                        else if (!std::strcmp(names[i], "g_join_gi_lag")) lagJoin = d;
                        prevG = i;
                        break;
                    }
                    case 1:
                        if (prevA >= 0) addSub(names[i], (double)(st[i] - st[prevA]) * k, true);
                        prevA = (int)i;
                        break;
                    case 2:
                        prevA = (int)i;
                        segBegin = st[i];
                        if (!firstA) firstA = st[i];
                        break;
                    default:
                        if (segBegin)
                        {
                            const double ms = (double)(st[i] - segBegin) * k;
                            addSub(names[i], ms, true);
                            busy += ms;
                            lastA = st[i];
                            if (!std::strcmp(names[i], "q_defer_light")) giSeg = ms;
                            else if (!std::strcmp(names[i], "q_gi_lag")) lagSeg = ms;
                        }
                        prevA = (int)i;
                        segBegin = 0;
                        break;
                    }
                }
                if (firstA && lastA > firstA)
                {
                    addSub("q_async_busy", busy, true);
                    addSub("q_async_span", (double)(lastA - firstA) * k, true);
                }
                // (#978 phase 2) q_gi_lag_hidden = q_gi_lag - g_join_gi_lag: the GI segment's time the
                // graphics queue did not wait for (all of it when scope 2 .. HUD covered it)
                if (lagSeg >= 0.0 && lagJoin >= 0.0)
                    addSub("q_gi_lag_hidden", std::max(0.0, lagSeg - lagJoin), true);
                // (#978) q_gi_beside = the graphics work recorded beside the lighting chain (g_gi_fork ..
                // g_gi_window), q_gi_hidden = q_defer_light - g_join_gi: the part of the chain graphics did
                // not wait for (q_defer_light starts at its own begin mark: queueing behind q_mask_ao is outside it).
                if (giSeg >= 0.0 && giJoin >= 0.0 && !giWin)
                {
                    addSub("q_gi_beside", giBeside, true);
                    addSub("q_gi_hidden", std::max(0.0, giSeg - giJoin), true);
                }
                // FRAME PIPELINING (phase 3b): the front-end segment's own pool (async
                // queue clock): its sub-marks (c_stream_inst .. c_preskin, deltas from the
                // previous front-end mark), q_frontend = the whole segment, and q_fe_hidden
                // = q_frontend minus g_fe_wait -- the graphics queue's wait at the join (the
                // gap between the end of the work before the front end and the work after
                // it), i.e. the part of the front end that ran beside other graphics work
                // (the previous frame's tail, this frame's uploads) instead of in line.
                const uint32_t nf = std::min(mFeCountR[h], kFeTs);
                uint64_t ft[kFeTs] = {};
                if (nf >= 2 && vkGetQueryPoolResults(dev, mFePoolR[h], 0, nf, nf * sizeof(uint64_t), ft,
                                                     sizeof(uint64_t), VK_QUERY_RESULT_64_BIT) == VK_SUCCESS)
                {
                    const char* const* fn = mFeNamesR[h];
                    for (uint32_t i = 1; i + 1 < nf; ++i) addSub(fn[i], (double)(ft[i] - ft[i - 1]) * k, true);
                    const double feMs = (double)(ft[nf - 1] - ft[0]) * k;
                    addSub(fn[nf - 1], feMs, true);   // q_frontend
                    if (feWait >= 0.0) addSub("q_fe_hidden", std::max(0.0, feMs - feWait), true);
                }
            }
            LLVKBench::gpuFrame(f[0]);
        }
        else
        {
            LLVKHitch::count("gpuTimerMiss", 1);
            mTsPrevEndValid = false;   // (#946: the next gap would span a missing frame)
        }
        mTsPendingR[h] = false;
    }
    else
        mTsPrevEndValid = false;
    // #946: whether this recording's top (gpuTimersTop) went into the slot it now takes.
    mTsTopR[h] = mTsTopPending == (int32_t)h;
    mTsTopPending = -1;
    mTsSlot = h;
    mTsPool = mTsPoolR[h];
    mSubPool = mSubPoolR[h];
    mSubNames = mSubNamesR[h];
    mSubQueue = mSubQueueR[h];
    mFePool = mFePoolR[h];
    mFeNames = mFeNamesR[h];
    mFeCount = 0;
    mFeCountR[h] = 0;
    const double now = std::chrono::duration<double>(std::chrono::steady_clock::now().time_since_epoch()).count();
    if (mTsFrames > 0 && now > mTsNextLog)
    {
        mTsNextLog = now + 5.0;
        const double k = 1.0 / mTsFrames;
        // The CPU side of the same window (LLVKAutoTune's per-frame sample): wall frame time and the
        // main thread's share (wall minus the GPU / present / pacing waits). cpu > total: the frame
        // is CPU-paced and GPU savings do not move FPS; frame ~ total > cpu: GPU-bound.
        double win_frame = 0.0, win_cpu = 0.0;
        const uint32_t win_n = LLVKAutoTune::instance().takeFrameWindow(win_frame, win_cpu);
        if (ts_log) LL_INFOS("VKGpu") << "GPU ms/frame over " << mTsFrames << " frames: total=" << mTsAccum[0] * k
            << " compute=" << mTsAccum[1] * k << " pass1=" << mTsAccum[2] * k
            << " pass2=" << mTsAccum[3] * k << " resolve=" << mTsAccum[4] * k
            << " tonemap=" << mTsAccum[5] * k << " glow=" << mTsAccum[6] * k
            << " sel+hud=" << mTsAccum[7] * k << " probe=" << mTsAccum[8] * k
            // projector-shadow A/B tag (state at log time): technique + shadowed projectors
            << " projshadow=" << (mProjMode == 2u ? "rt" : (mProjMode == 1u ? "map" : "off"))
            << " proj_n=" << mProjActive
            << " | worst=" << mTsWorst[0] << " (compute=" << mTsWorst[1] << " pass1=" << mTsWorst[2]
            << " pass2=" << mTsWorst[3] << " probe=" << mTsWorst[8] << ")"
            << overdrawStatsText()   // empty unless RenderVKOverdrawStats
            // Phase 2: work now overlaps on the queue, so a pass / sub-mark delta can
            // include (or hide) neighbouring work; only total -- first to last timestamp
            // of the world recording, the GPU critical path -- is the truth. With the
            // probe faces early, "compute" holds them and "probe" only the filters.
            << ((mOv.maskAo || mOv.godRays || mOv.tlas || mOv.particles || mOv.probeEarly)
                    ? " [overlap on: per-pass/sub deltas unreliable, total=critical path]" : "")
            << (mOv.probeEarly ? " [probe faces in compute/c_mirror window: pr_early]" : "")
            // Async compute (phase 3a): total = the GRAPHICS queue's first -> last
            // timestamp (incl. its waits on async joins) = the frame's critical path; the
            // async queue's work is in the q_* sub-marks (its own clock).
            << (mAsyncNow.on ? " [async compute: graphics total; async in q_* (q_async_busy / q_async_span)]" : "")
            << (mAsyncNow.pipe ? " [frame pipelining: front end in q_frontend (own clock), hidden ~ q_fe_hidden]" : "")
            << (mTsLeanRec ? " [lean: sub-marks off]" : "")
            // #946: GPU time OUTSIDE total -- the recording's prologue (texture uploads, the
            // weather's prepare, ...) and the queue's gap between our frames
            << " | outside total: prologue=" << (mTsPreN ? mTsPreAccum / mTsPreN : 0.0)
            << " gap=" << (mTsGapN ? mTsGapAccum / mTsGapN : 0.0) << " (worst " << mTsGapWorst << ")"
            << " | CPU ms/frame over " << win_n << " frames: frame=" << win_frame << " cpu=" << win_cpu << LL_ENDL;
        mTsPreAccum = mTsGapAccum = mTsGapWorst = 0.0;
        mTsPreN = mTsGapN = 0;
        if (ts_log && !mSubAcc.empty())
        {
            std::ostringstream os;
            // Graphics marks first, then the async queue's (own clock): a mark recorded on
            // the async queue (segment B's g_ssao / c_rtmask*, the RT build, god rays) is
            // NOT graphics time -- a single mixed list read that way (F3 follow-up).
            os << "GPU sub ms/frame:";
            for (const SubAcc& a : mSubAcc) if (!a.async) os << " " << a.name << "=" << a.ms * k;
            bool anyAsync = false;
            for (const SubAcc& a : mSubAcc) anyAsync |= a.async;
            if (anyAsync)
            {
                os << " | async queue:";
                for (const SubAcc& a : mSubAcc) if (a.async) os << " " << a.name << "=" << a.ms * k;
            }
            // Spiky sections: probe capture sub-steps carry their worst frame too; so do the
            // cluster LOD stages (#748 static pass: c_cl_* RT cut / CLAS / BLAS builds, the
            // cluster draws and pre-skin, the RT build and the async queue they ride on).
            os << " | worst:";
            for (const SubAcc& a : mSubAcc)
                if (!std::strncmp(a.name, "pr_", 3) || !std::strcmp(a.name, "p_probe") || !std::strncmp(a.name, "c_cl", 4)
                    || !std::strncmp(a.name, "c_cluster", 9) || !std::strncmp(a.name, "g_gbuf_cluster", 14)
                    || !std::strncmp(a.name, "g_pre_cl", 8) || !std::strcmp(a.name, "c_blas_build")
                    || !std::strcmp(a.name, "q_rt_build") || !std::strcmp(a.name, "q_async_busy")
                    || !std::strcmp(a.name, "c_shadow_rigcull"))
                    os << " " << a.name << "=" << a.worst;
            LL_INFOS("VKGpu") << os.str() << LL_ENDL;
        }
        // #772: the probe passes for the probe recapture log (prbIdleLog): avg ms/frame of
        // the last window, pr_* summed (scheduled + realtime capture, filter, encode).
        if (!mSubAcc.empty())
        {
            std::ostringstream ps;
            ps.setf(std::ios::fixed);
            ps.precision(3);
            double tot = 0.0;
            for (const SubAcc& a : mSubAcc)
            {
                const bool pr = !std::strncmp(a.name, "pr_", 3);
                if (pr || !std::strncmp(a.name, "c_prb_", 6) || !std::strcmp(a.name, "p_probe"))
                {
                    ps << " " << a.name << "=" << a.ms * k;
                    if (pr) tot += a.ms * k;
                }
            }
            std::ostringstream hs;
            hs.setf(std::ios::fixed);
            hs.precision(3);
            hs << "pr_* total=" << tot << " |" << ps.str();
            mPrbGpuSubLine = hs.str();
        }
        // (the cluster LOD module's 10 s CLOD gpu sub line: its stages + the legacy stages they
        // replace, for an LOD on / off A/B at one camera; q_* = the async queue's clock)
        // (also when only the auto-tuner runs the timers: no VKGpu line, the CLOD line still reads it)
        if (mCluster && !mSubAcc.empty())
        {
            std::ostringstream cs;
            cs.setf(std::ios::fixed);
            cs.precision(2);
            static const char* const kCmp[] = {"c_preskin", "c_rigweld", "c_blas_build", "c_blas_refit", "g_prepass",
                                               "g_pre_static", "g_pre_rigged",
                                               "q_rt_build", "c_shadow_rigcull", "pr_rigcull", "pr_cull", "pr_face",
                                               "pr_rt_face", "pr_rt_alpha", "pr_gbuf", "pr_light",
                                               "pr_rt_gbuf", "pr_rt_light"};   // (#833 deferred faces)
            // (#1011: the cluster RT cut and the rigged CLAS step are split into sub-marks; their
            // sums keep the old c_cl_rt_select / c_cl_rig_clas figures comparable -- avg only)
            double rt_sel = 0.0, rig_clas = 0.0;
            bool rt_any = false;
            for (const SubAcc& a : mSubAcc)
            {
                bool want = !std::strncmp(a.name, "c_cl", 4) || !std::strncmp(a.name, "c_cluster", 9)
                         || !std::strncmp(a.name, "g_gbuf_cluster", 14) || !std::strncmp(a.name, "g_pre_cl", 8)
                         || !std::strncmp(a.name, "g_cl_", 5) || !std::strncmp(a.name, "q_cluster", 9);
                for (const char* c : kCmp) want = want || !std::strcmp(a.name, c);
                if (want) cs << " " << a.name << "=" << a.ms * k << "/" << a.worst;
                if (!std::strncmp(a.name, "c_cl_rts_", 9) || !std::strcmp(a.name, "c_cl_rt_select")) { rt_sel += a.ms * k; rt_any = true; }
                if (!std::strcmp(a.name, "c_cl_rig_skin") || !std::strcmp(a.name, "c_cl_rig_clas")) { rig_clas += a.ms * k; rt_any = true; }
            }
            if (rt_any) cs << " c_cl_rt_select_sum=" << rt_sel << " c_cl_rig_sum=" << rig_clas;
            mClGpuSubLine = cs.str();
        }
        // #771: the RT shadow mask's per-frame GPU ms for the cache's own log line.
        {
            double cls = -1.0, tr = -1.0, ts = -1.0;
            for (const SubAcc& a : mSubAcc)
            {
                if (!std::strcmp(a.name, "c_rtmask_cls")) cls = std::max(cls, 0.0) + a.ms * k;
                else if (!std::strcmp(a.name, "c_rtmask")) tr = std::max(tr, 0.0) + a.ms * k;
                else if (!std::strcmp(a.name, "c_rtmask_tmp") || !std::strcmp(a.name, "c_rtmask_sp"))
                    ts = std::max(ts, 0.0) + a.ms * k;
            }
            mRtCacheMs[0] = cls; mRtCacheMs[1] = tr; mRtCacheMs[2] = ts;
        }
        sunCertGpuWindow(k);   // #771 Phase 2: c_sxc + c_defer_shadowmerge for the VKSunCert line
        if (ts_log) { const std::string pr = probeStatsText(); if (!pr.empty()) LL_INFOS("VKGpu") << pr << LL_ENDL; }
        if (ts_log) { const std::string p2 = p2StatsText(); if (!p2.empty()) LL_INFOS("VKGpu") << p2 << LL_ENDL; }
        if (ts_log) { const std::string rr = rtReflStatsText(); if (!rr.empty()) LL_INFOS("VKGpu") << rr << LL_ENDL; }
        if (ts_log) { const std::string rs = rsStatsText(); if (!rs.empty()) LL_INFOS("VKGpu") << rs << LL_ENDL; }
        if (ts_log) { const std::string gs = giStatsText(); if (!gs.empty()) LL_INFOS("VKGpu") << gs << LL_ENDL; }
        for (double& a : mTsAccum) a = 0.0;
        for (double& a : mTsWorst) a = 0.0;
        for (SubAcc& a : mSubAcc) a.ms = a.worst = 0.0;
        mTsFrames = 0;
    }
    // RenderVKGpuSubMarks off: only timestamps 0 and TS_COUNT-1 (the frame total). The
    // ~60 ALL_COMMANDS timestamps per frame may themselves drain the pipe on some
    // drivers, which would hide exactly the overlap phase 2 adds.
    {
        bool sub = true;
#if defined(LL_HAS_CLEAN_PIPELINE)
        static LLCachedControl<bool> s_sub(gSavedSettings, "RenderVKGpuSubMarks", true);
        sub = s_sub;
#endif
        mTsLean = !sub;
        mTsLeanRec = mTsLean;
    }
    vkCmdResetQueryPool(cmd, mTsPool, 0, TS_COUNT);
    vkCmdResetQueryPool(cmd, mSubPool, 0, SUB_TS);
    vkCmdWriteTimestamp2(cmd, VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT, mTsPool, 0);
    mSubCount = 0;
    gpuSubMark(cmd, "begin");
    mTsPendingR[mTsSlot] = true;
}

// #946: the top of the world recording (mTsTopPool; see the header). Uses the slot
// gpuTimersBegin will take this recording ((mTsSlot + 1) % TS_RING) and the last recording's
// mTsOn (gpuTimersBegin refreshes it after the prologue: the first frame with the timers on has
// no top -- no sample, nothing wrong). Outside any rendering scope (a query reset must be).
void LLCleanRendererVK::gpuTimersTop(VkCommandBuffer cmd)
{
    mTsTopPending = -1;
    if (!mTsOn || mTsUnavailable || !mTsPoolR[0] || !mCtx) return;
    if (!mTsTopPool)
    {
        VkQueryPoolCreateInfo qi{VK_STRUCTURE_TYPE_QUERY_POOL_CREATE_INFO};
        qi.queryType = VK_QUERY_TYPE_TIMESTAMP;
        qi.queryCount = TS_RING;
        if (vkCreateQueryPool(mCtx->device(), &qi, nullptr, &mTsTopPool) != VK_SUCCESS)
        {
            mTsTopPool = VK_NULL_HANDLE;
            return;
        }
        for (bool& b : mTsTopR) b = false;
    }
    const uint32_t slot = (mTsSlot + 1u) % TS_RING;
    vkCmdResetQueryPool(cmd, mTsTopPool, slot, 1);
    vkCmdWriteTimestamp2(cmd, VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT, mTsTopPool, slot);
    mTsTopPending = (int32_t)slot;
}

void LLCleanRendererVK::gpuSubMark(VkCommandBuffer cmd, const char* name)
{
    vkBreadcrumb(cmd, name);   // device-lost diagnostics (always, when supported)
    if (mRigTsRec) rigGpuTimeMark(cmd, name);   // #613 rigged GPU time (sampled frames)
    if (!mTsOn || mTsLean) return;
    if (mFeCmd && cmd == mFeCmd)
    {
        // Frame pipelining (3b): the front-end segment's own pool (async queue clock).
        if (!mAsyncTs || !mFePool || mFeCount >= kFeTs) return;
        vkCmdWriteTimestamp2(cmd, VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT, mFePool, mFeCount);
        mFeNames[mFeCount++] = name;
        return;
    }
    if (!mSubPool || mSubCount >= SUB_TS) return;
    // Async compute (phase 3a): tag the queue; the harvest takes deltas per queue.
    uint8_t q = 0;
    if (mAsyncAvail && vkAsyncIsAsyncCmd(cmd))
    {
        if (!mAsyncTs) return;   // the async family has no timestamps
        q = mAsyncSegStart ? 2u : (mAsyncSegEnd ? 3u : 1u);
    }
    vkCmdWriteTimestamp2(cmd, VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT, mSubPool, mSubCount);
    mSubQueue[mSubCount] = q;
    mSubNames[mSubCount++] = name;
}

void LLCleanRendererVK::gpuTimerMark(VkCommandBuffer cmd, uint32_t idx)
{
    static const char* const kStageCrumb[] = {"stage0", "stage1", "stage2", "stage3", "stage4", "stage5",
                                              "stage6", "stage7", "stage8", "stage9", "stage10", "stage11",
                                              "stage12", "stage13", "stage14", "stage15"};
    if (idx < sizeof(kStageCrumb) / sizeof(kStageCrumb[0])) vkBreadcrumb(cmd, kStageCrumb[idx]);
    if (idx == TS_COUNT - 1 && mRigTsRec) rigGpuTimeMark(cmd, nullptr, 1);   // #613: the frame's GPU span ends
    if (!mTsOn || !mTsPool || idx >= TS_COUNT) return;
    if (mTsLean && idx != 0 && idx != TS_COUNT - 1) return;   // lean: the frame total only
    vkCmdWriteTimestamp2(cmd, VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT, mTsPool, idx);
}

// ---- #613 RIGGED GPU TIME (always on, sampled; independent of RenderVKGpuTimers) ----
// The rigged controller's perf trigger (rigPressure) needs the GPU time of the rigged work
// and whether the frame is GPU-bound, cheaply, with the pass timers off. Every
// kRigTsEvery-th recording writes a few timestamps into an own ring (read kRigTsRing-1
// frames later WITHOUT waiting; VK_NOT_READY skips the sample): the frame's first and last
// (here and at the last pass mark: its GPU span) and both ends of each rigged span, i.e.
// the graphics sub-marks bracketing it -- c_skin_pal -> c_preskin (pre-skin), c_preskin ->
// c_rigweld (#574 weld), g_gbuf_static -> g_gbuf_rigged, g_lit_static -> g_lit_rigged and
// g_p2_{pre,post}_static -> g_p2_{pre,post}_rig (rigged raster). A span counts only when
// its two marks are ADJACENT graphics marks (the gpuSubMark sequence), so a frame without
// rigged draws measures nothing for it. Marks on the async queue are not measured (frame
// pipelining records the pre-skin there: then the rigged RASTER time only). Rigged shadow
// / probe / mirror casters are not in it. ALL_COMMANDS timestamps can drain the pipe:
// ~12 on every 8th frame is noise next to the pass timers' ~60 per frame.
void LLCleanRendererVK::rigGpuTimeBegin(VkCommandBuffer cmd)
{
    mRigTsRec = false;
    VkDevice dev = mCtx->device();
    if (!mRigTsInit)
    {
        mRigTsInit = true;
        uint32_t nf = 0;
        vkGetPhysicalDeviceQueueFamilyProperties(mCtx->physicalDevice(), &nf, nullptr);
        std::vector<VkQueueFamilyProperties> qf(nf);
        if (nf) vkGetPhysicalDeviceQueueFamilyProperties(mCtx->physicalDevice(), &nf, qf.data());
        const uint32_t fam = mCtx->queueFamily();
        if (fam < nf && qf[fam].timestampValidBits != 0u)
        {
            VkPhysicalDeviceProperties pp{};
            vkGetPhysicalDeviceProperties(mCtx->physicalDevice(), &pp);
            mRigTsPeriodNs = pp.limits.timestampPeriod;
            mRigTsBits = qf[fam].timestampValidBits;
            VkQueryPoolCreateInfo qi{VK_STRUCTURE_TYPE_QUERY_POOL_CREATE_INFO};
            qi.queryType = VK_QUERY_TYPE_TIMESTAMP;
            qi.queryCount = kRigTs;
            mRigTsOk = true;
            for (uint32_t r = 0; r < kRigTsRing && mRigTsOk; ++r)
                mRigTsOk = vkCreateQueryPool(dev, &qi, nullptr, &mRigTsPool[r]) == VK_SUCCESS;
            if (!mRigTsOk) rigGpuTimeDestroy();
        }
        if (!mRigTsOk)
            LL_INFOS("VKMem") << "rigged GPU time: no timestamps on the graphics queue; the rigged perf trigger "
                                 "(RenderVKRiggedGpuBudgetMs) stays off" << LL_ENDL;
    }
    if (!mRigTsOk) return;
    // Harvest the OLDEST slot (written kRigTsRing-1 recordings ago), then reuse it.
    const uint32_t h = (mRigTsSlot + 1u) % kRigTsRing;
    if (mRigTsPend[h])
    {
        mRigTsPend[h] = false;
        const uint32_t n = std::min(mRigTsN[h], kRigTs);
        uint64_t t[kRigTs] = {};
        if (n >= 2u && vkGetQueryPoolResults(dev, mRigTsPool[h], 0, n, n * sizeof(uint64_t), t, sizeof(uint64_t),
                                             VK_QUERY_RESULT_64_BIT) == VK_SUCCESS)
        {
            const uint64_t mask = mRigTsBits >= 64u ? ~0ull : ((1ull << mRigTsBits) - 1ull);
            const double k = (double)mRigTsPeriodNs * 1e-6;
            auto ms = [&](uint64_t a, uint64_t b) { return (double)((b - a) & mask) * k; };
            const uint8_t* kind = mRigTsKind[h];
            const uint8_t* cls = mRigTsCls[h];
            const uint32_t* seq = mRigTsSeqAt[h];
            double frame_ms = -1.0, rig_ms = 0.0;
            double cl_ms[4] = {0.0, 0.0, 0.0, 0.0};   // #749 cluster spans (class 1..4)
            bool cl_seen[4] = {false, false, false, false};
            for (uint32_t i = 1; i < n; ++i)
            {
                if (kind[i] == 1u && kind[0] == 0u) frame_ms = ms(t[0], t[i]);
                if ((kind[i] == 3u || kind[i] == 4u) && (kind[i - 1] == 2u || kind[i - 1] == 4u)
                    && seq[i - 1] + 1u == seq[i] && cls[i - 1] == cls[i])
                {
                    if (cls[i] == 0u) rig_ms += ms(t[i - 1], t[i]);
                    else if (cls[i] <= 4u) { cl_ms[cls[i] - 1u] += ms(t[i - 1], t[i]); cl_seen[cls[i] - 1u] = true; }
                }
            }
            if (frame_ms > 0.0 && frame_ms < 1000.0 && rig_ms <= frame_ms)
            {
                const bool first = mRigGpuAt <= 0.0;
                mRigGpuFrameMs = first ? (float)frame_ms : mRigGpuFrameMs * 0.7f + (float)frame_ms * 0.3f;
                mRigGpuMs = first ? (float)rig_ms : mRigGpuMs * 0.7f + (float)rig_ms * 0.3f;
                mRigGpuAt = LLFrameTimer::getTotalSeconds();
                // #749: a sample without a cluster span measured 0 for it (the path drew nothing).
                for (int c = 0; c < 4; ++c)
                {
                    const float v = cl_seen[c] && cl_ms[c] <= frame_ms ? (float)cl_ms[c] : 0.f;
                    mClGpuMs[c] = mClGpuMs[c] < 0.f ? v : mClGpuMs[c] * 0.7f + v * 0.3f;
                }
            }
        }
    }
    mRigTsSlot = h;
    if ((++mRigTsFrame % kRigTsEvery) != 0u) return;
    vkCmdResetQueryPool(cmd, mRigTsPool[h], 0, kRigTs);
    mRigTsN[h] = 0;
    mRigTsRec = true;
    mRigTsPend[h] = true;
    rigGpuTimeMark(cmd, nullptr, 0);
}

// One rigged-time timestamp (sampled recordings only). name: a graphics sub-mark (kind
// from the span tables below; others only advance the sequence); kind >= 0: the frame's
// begin (0) / end (1).
void LLCleanRendererVK::rigGpuTimeMark(VkCommandBuffer cmd, const char* name, int kind)
{
    if (!mRigTsRec) return;
    if (kind < 0)
    {
        // graphics queue only (timestamps of two queues are not comparable)
        if ((mFeCmd && cmd == mFeCmd) || (mAsyncAvail && vkAsyncIsAsyncCmd(cmd))) return;
        const uint32_t sq = ++mRigTsSeq;
        static const char* const kBegin[] = {"c_skin_pal", "g_gbuf_static", "g_lit_static", "g_p2_pre_static",
                                             "g_p2_post_static"};
        static const char* const kEnd[] = {"c_rigweld", "g_gbuf_rigged", "g_lit_rigged", "g_p2_pre_rig", "g_p2_post_rig"};
        if (!std::strcmp(name, "c_preskin")) kind = 4;   // ends the pre-skin, begins the weld
        for (const char* b : kBegin) if (kind < 0 && !std::strcmp(name, b)) kind = 2;
        for (const char* e : kEnd) if (kind < 0 && !std::strcmp(name, e)) kind = 3;
        // #749 cluster spans (class 1 selection, 2 pre-pass, 3 G-buffer, 4 the #747 cluster
        // pre-skin): their marks exist only while the cluster path records (c_cull begins a
        // selection span only when a c_cluster_t* mark follows it directly; a span needs both
        // ends of one class).
        uint8_t cls = 0;
        if (kind < 0 && mCluster)   // (module off: not one more timestamp, #749)
        {
            if (!std::strcmp(name, "c_cull")) { kind = 2; cls = 1; }
            else if (!std::strncmp(name, "c_cluster_t", 11)) { kind = 3; cls = 1; }
            else if (!std::strcmp(name, "g_pre_cl_begin")) { kind = 2; cls = 2; }
            else if (!std::strcmp(name, "g_pre_cl_end")) { kind = 3; cls = 2; }
            else if (!std::strcmp(name, "g_cl_begin")) { kind = 2; cls = 3; }
            else if (!std::strncmp(name, "g_gbuf_cluster", 14)) { kind = 3; cls = 3; }
            else if (!std::strcmp(name, "c_cl_preskin_begin")) { kind = 2; cls = 4; }
            else if (!std::strcmp(name, "c_cluster_preskin")) { kind = 3; cls = 4; }
            // (2026-10-14 step 0: the cluster pre-skin window's sub-marks -- links of the class-4
            // chain (end one segment, begin the next), so the span stays adjacent and complete)
            else if (!std::strncmp(name, "c_cl_sk_", 8)) { kind = 4; cls = 4; }
        }
        if (kind < 0) return;
        const uint32_t h = mRigTsSlot;
        if (mRigTsN[h] >= kRigTs - 1u) return;   // (the last query is kept for the frame end)
        mRigTsKind[h][mRigTsN[h]] = (uint8_t)kind;
        mRigTsCls[h][mRigTsN[h]] = cls;
        mRigTsSeqAt[h][mRigTsN[h]] = sq;
    }
    else
    {
        const uint32_t h = mRigTsSlot;
        if (mRigTsN[h] >= kRigTs) return;
        mRigTsKind[h][mRigTsN[h]] = (uint8_t)kind;
        mRigTsCls[h][mRigTsN[h]] = 0u;
        mRigTsSeqAt[h][mRigTsN[h]] = 0u;
        if (kind == 1) mRigTsRec = false;   // (a later snapshot recording of this frame writes nothing)
    }
    vkCmdWriteTimestamp2(cmd, VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT, mRigTsPool[mRigTsSlot], mRigTsN[mRigTsSlot]++);
}

void LLCleanRendererVK::rigGpuTimeDestroy()
{
    for (uint32_t r = 0; r < kRigTsRing; ++r)
    {
        if (mRigTsPool[r] && mCtx) vkDestroyQueryPool(mCtx->device(), mRigTsPool[r], nullptr);
        mRigTsPool[r] = VK_NULL_HANDLE;
        mRigTsPend[r] = false;
    }
    mRigTsOk = false;
    mRigTsRec = false;
}

// ---- OVERDRAW DIAGNOSTIC (RenderVKOverdrawStats) ----
// Two independent counts of pass-1 lit-FS work, on alternating frames so neither
// perturbs the other:
//   * ATOMIC frames: the lit pipelines are swapped for kOverdrawStats-specialized
//     twins that subgroup-atomicAdd their non-helper invocations into mOdCounter.
//     Exact with the pre-pass on (EarlyFragmentTests). With the pre-pass OFF the
//     storage write forces late depth testing, so it reads as the no-early-Z upper
//     bound -- which is why the query below exists.
//   * QUERY frames: the UNMODIFIED pipelines inside a FRAGMENT_SHADER_INVOCATIONS
//     pipeline-statistics query -- what the hardware really shaded (drivers may
//     include helper lanes).
// Both land in a 3-deep ring read 3 frames later (frames in flight <= 2), no waits.
bool LLCleanRendererVK::buildOverdrawPipes()
{
    VkMemScope memcat(VKMEM_READBACK);   // #407
    if (mOdPipesBuilt) return true;
    if ((!mOdAtomicOk && !mOdQueryOk) || !mDrawLayout || !mOdCounter.buffer) return false;
    VkDevice dev = mCtx->device();
    for (GpuBuffer& rb : mOdRb)
    {
        if (rb.buffer) continue;
        rb = mCtx->createBuffer(16, VK_BUFFER_USAGE_TRANSFER_DST_BIT,
                                VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT |
                                VK_MEMORY_PROPERTY_HOST_CACHED_BIT);
        if (rb.mapped) std::memset(rb.mapped, 0, 16);
    }
    if (mOdQueryOk && !mOdQueryPool)
    {
        VkQueryPoolCreateInfo qi{VK_STRUCTURE_TYPE_QUERY_POOL_CREATE_INFO};
        qi.queryType = VK_QUERY_TYPE_PIPELINE_STATISTICS; qi.queryCount = 3;
        qi.pipelineStatistics = VK_QUERY_PIPELINE_STATISTIC_FRAGMENT_SHADER_INVOCATIONS_BIT;
        if (vkCreateQueryPool(dev, &qi, nullptr, &mOdQueryPool) != VK_SUCCESS)
        {
            mOdQueryPool = VK_NULL_HANDLE; mOdQueryOk = false;
        }
    }
    if (mOdAtomicOk)
    {
        VkShaderModule vs  = moduleFromSpv(dev, kWorldVertSpv, kWorldVertSpv_bytes, "kWorldVertSpv");
        VkShaderModule rvs = moduleFromSpv(dev, kWorldRiggedVertSpv, kWorldRiggedVertSpv_bytes, "kWorldRiggedVertSpv");
        // Plain FS always: the stats twins use mDrawLayout (sets 0/1, no RT set); they
        // count shading invocations, which the ray-query variant doesn't change.
        VkShaderModule fs  = moduleFromSpv(dev, kWorldFragSpv, kWorldFragSpv_bytes, "kWorldFragSpv");
        VkShaderModule ezf = moduleFromSpv(dev, kWorldFragEzSpv, kWorldFragEzSpv_bytes, "kWorldFragEzSpv");
        const VkBool32 on = VK_TRUE;
        const VkSpecializationMapEntry me{0, 0, sizeof(VkBool32)};   // constant_id 0 = kOverdrawStats
        const VkSpecializationInfo si{1, &me, sizeof(on), &on};
        const VkCullModeFlags cm[2] = {VK_CULL_MODE_BACK_BIT, VK_CULL_MODE_NONE};
        GraphicsPipelineDesc d = mLitDesc;
        d.fragSpec = &si;
        for (int mode = 0; mode < 2; ++mode)   // 0 = no pre-pass (LEQUAL + write), 1 = after pre-pass
        {
            d.frag = mode ? ezf : fs;
            d.depthWrite = mode == 0;
            d.depthCompare = mode ? VK_COMPARE_OP_EQUAL : VK_COMPARE_OP_LESS_OR_EQUAL;
            for (int i = 0; i < 2; ++i)
            {
                d.cullMode = cm[i];
                d.vert = vs; vkWorldStaticVI(d);  mOdPipe[mode][i]     = createGraphicsPipeline(dev, d);
                d.vert = rvs; vkWorldRiggedVI(d); mOdPipe[mode][2 + i] = createGraphicsPipeline(dev, d);
            }
        }
        for (VkShaderModule m : {vs, rvs, fs, ezf}) vkDestroyShaderModule(dev, m, nullptr);
    }
    mOdPipesBuilt = true;
    LL_INFOS("VKGpu") << "overdraw stats: atomic " << (mOdAtomicOk ? "on" : "unsupported")
                      << ", fs-invocation query " << (mOdQueryOk ? "on" : "unsupported") << LL_ENDL;
    return true;
}

// Harvest the ring entry about to be reused (written 3 frames ago).
void LLCleanRendererVK::readOverdrawStats()
{
    const uint32_t slot = (uint32_t)(mOdFrame % 3u);
    if (mOdRbValid[slot] && mOdRb[slot].mapped)
    {
        mOdShadedAcc += (double)reinterpret_cast<const uint32_t*>(mOdRb[slot].mapped)[0];
        mOdPxAcc += (double)mOdPx[slot];
        ++mOdFrames;
    }
    if (mOdQueryIssued[slot] && mOdQueryPool)
    {
        uint64_t v = 0;
        if (vkGetQueryPoolResults(mCtx->device(), mOdQueryPool, slot, 1, sizeof(v), &v, sizeof(v),
                                  VK_QUERY_RESULT_64_BIT) == VK_SUCCESS)
        {
            mOdStatAcc += (double)v;
            mOdPxStatAcc += (double)mOdPx[slot];
            ++mOdStatFrames;
        }
    }
    mOdRbValid[slot] = false;
    mOdQueryIssued[slot] = false;
    // With the GPU timers off there is no VKGpu line to ride on: log on our own ~5 s.
    if (!mTsOn && (mOdFrames > 0 || mOdStatFrames > 0))
    {
        const double now = std::chrono::duration<double>(std::chrono::steady_clock::now().time_since_epoch()).count();
        if (now > mOdNextLog)
        {
            mOdNextLog = now + 5.0;
            LL_INFOS("VKGpu") << "GPU pass1" << overdrawStatsText() << LL_ENDL;
        }
    }
}

// " overdraw[prepass=on] fs_atomic=<per frame> px=<per frame> factor=<x>
//   fs_query=<per frame> factor_q=<x>" -- factor = lit-FS invocations / screen pixels.
std::string LLCleanRendererVK::overdrawStatsText()
{
    std::ostringstream os;
    if (mOdFrames == 0 && mOdStatFrames == 0) return std::string();
    os << std::fixed;
    os.precision(2);
    os << " overdraw[prepass=" << (mOdLastPrepass ? "on" : "off") << "]";
    if (mOdFrames > 0)
    {
        const double sh = mOdShadedAcc / mOdFrames, px = mOdPxAcc / mOdFrames;
        os << " fs_atomic=" << (uint64_t)sh << " px=" << (uint64_t)px
           << " factor=" << (px > 0.0 ? sh / px : 0.0);
    }
    if (mOdStatFrames > 0)
    {
        const double sq = mOdStatAcc / mOdStatFrames, px = mOdPxStatAcc / mOdStatFrames;
        os << " fs_query=" << (uint64_t)sq << " factor_q=" << (px > 0.0 ? sq / px : 0.0);
    }
    mOdShadedAcc = mOdStatAcc = mOdPxAcc = mOdPxStatAcc = 0.0;
    mOdFrames = mOdStatFrames = 0;
    return os.str();
}

// ---- #422 AUTO-TUNE ("Improve graphics speed", LLVKAutoTune) ----
// The continuous mode's caps ride the VRAM ladder's clamp points: merged into the effective
// mBudgetCaps, most restrictive wins. The ladder's own logic (mBudget: rung usefulness,
// pacing, recovery, readouts, mGeomTrim) keeps seeing only its own caps.
LLVramBudgetVK::Caps LLCleanRendererVK::budgetCapsWithPerf() const
{
    LLVramBudgetVK::Caps c = mBudget.caps();
    const LLVKPerfCaps& p = mPerfCaps;
    c.renderScaleMax = std::min(c.renderScaleMax, p.renderScaleMax);
    c.probeResShift = std::max(c.probeResShift, p.probeResShift);
    c.probeCountShift = std::max(c.probeCountShift, p.probeCountShift);
    c.farShadowsOff = c.farShadowsOff || p.farShadowsOff;
    c.mirrorsOff = c.mirrorsOff || p.mirrorsOff;
    c.projShadowsOff = c.projShadowsOff || p.projShadowsOff;
    c.meshLodScale = std::min(c.meshLodScale, p.meshLodScale);
    c.avatarLodScale = std::min(c.avatarLodScale, p.avatarLodScale);
    c.drawDistScale = std::min(c.drawDistScale, p.drawDistScale);
    return c;
}

void LLCleanRendererVK::setPerfCaps(const LLVKPerfCaps& caps)
{
    if (caps == mPerfCaps) return;
    mPerfCaps = caps;
    mPerfCapsDirty = true;   // applied by the next budgetTick (the texture pass), like a ladder move
}

void LLCleanRendererVK::autoTuneSample(LLVKAutoTuneSample& out) const
{
    out.valid = true;
    const double now = LLFrameTimer::getTotalSeconds();
    out.gpuAgeSec = (mRigTsOk && mRigGpuAt > 0.0) ? now - mRigGpuAt : 1.0e9;
    out.gpuFrameMs = mRigGpuFrameMs;
    out.rigGpuMs = mRigGpuMs;
    out.rigSlod = mRigSlodPerf;
    out.rigSlodMax = kRigSlodMax;
    out.rigPerfP = mRigPerfP;
    out.rigPerfPMax = rigPerfCreatorOn() ? kRigPerfPMax : 0u;   // (#734: the reachable top; 0 = creator LODs off)
    const LLVramBudgetVK::Caps& v = mBudget.caps();
    out.vram.renderScaleMax = v.renderScaleMax;
    out.vram.probeResShift = v.probeResShift;
    out.vram.probeCountShift = v.probeCountShift;
    out.vram.farShadowsOff = v.farShadowsOff;
    out.vram.mirrorsOff = v.mirrorsOff;
    out.vram.projShadowsOff = v.projShadowsOff;
    out.vram.meshLodScale = v.meshLodScale;
    out.vram.avatarLodScale = v.avatarLodScale;
    out.vram.drawDistScale = v.drawDistScale;
    out.vramMode = mBudget.mode();
    out.vramRungs = mBudget.engaged();
    out.vramUsage = mVramStatus.usage;
    out.vramBudget = mVramStatus.budget;
    // #966: the internal render extent and the upscaler the last main-view frame ran.
    out.renderW = mRenderW;
    out.renderH = mRenderH;
    out.upscalerRan = mRrRanLast ? (mDlssRanKind == LLVKNeuralRecon::F_SR ? LLVKAutoTuneSample::UPS_DLSS_SR
                                                                          : LLVKAutoTuneSample::UPS_DLSS_RR)
                    : mFsrRanLast ? LLVKAutoTuneSample::UPS_FSR : LLVKAutoTuneSample::UPS_NONE;
    out.avVerts.clear();
#if defined(LL_HAS_CLEAN_PIPELINE)
    static std::vector<std::pair<LLUUID, U32>> slots;   // main thread only
    LLCleanSkinStore::instance().copyAvatarSlots(slots);
    const size_t n = sizeof(mRigAvVerts) / sizeof(mRigAvVerts[0]);
    for (const auto& sl : slots)
        if (sl.second < n && mRigAvVerts[sl.second]) out.avVerts.emplace_back(sl.first, mRigAvVerts[sl.second]);
#endif
}

// ---- CLUSTER LOD hooks (#642 / #743) -------------------------------------------------------
// RenderVKClusterLOD (default off). Off: the module never exists and these are no-ops, so
// every existing path is unchanged. The module (llcleanclustervk.h) owns everything else.
bool LLCleanRendererVK::clusterLodOn() const
{
#if defined(LL_HAS_CLEAN_PIPELINE)
    static LLCachedControl<bool> s_on(gSavedSettings, "RenderVKClusterLOD", false);
    return s_on && mCluster && mCluster->ready();
#else
    return false;
#endif
}

// CLUSTER LOD MODE FLIP SUMMARY (2026-10-14, LOD-off vanishing avatars): one line ~3 s after a
// flip (readback lag, repack, re-scan and the capacity grow all done by then) -- what came back to
// the legacy path (routed slots / meshes uploaded again, rigged rows the CPU scan admits, the rigged
// buffers' re-sizes) or what left it, and whether the cull still drops rigged draws for capacity
// (it must not: the ceiling follows the measured demand) and how many rows have neither path. A
// WARNING while capacity drops remain, so a regression of the flip is visible in the log.
void LLCleanRendererVK::rigFlipReport()
{
    if (!mRigFlipFrame || (uint32_t)gFrameCount - mRigFlipFrame < 180u) return;
    mRigFlipFrame = 0;
    uint64_t dem = 0;
    for (uint32_t t = 0; t < kRigTiers; ++t) dem += mRigDemTier[t];
    const uint64_t rs = mGeomRoutedSlots.load(std::memory_order_relaxed), rg = mGeomRoutedGroups.load(std::memory_order_relaxed);
    // (rows with neither path include meshes still loading: reported, not a failure by themselves)
    const bool bad = mRigDropItems != 0u;
    std::ostringstream q;
    q << "Cluster LOD flip " << (mRigFlipTo ? "to the cluster path" : "back to the legacy path") << " settled: "
      << "cluster-routed legacy slots not uploaded " << mRigFlipRoutedSlotsBefore << " -> " << rs << " (meshes "
      << mRigFlipRoutedGroupsBefore << " -> " << rg << "; "
      << (mRigFlipRoutedSlotsBefore > rs ? mRigFlipRoutedSlotsBefore - rs : 0u) << " slots re-uploaded from the mirror)"
      << " | legacy rigged rows admitted " << mRigFlipItemsBefore << " -> " << mRigUbItems
      << " | rigged buffers re-sized " << mRigFlipResizes << "x: skinned verts " << mRigFlipDynBefore << " -> " << mSkinDynCap
      << ", cache " << mRigFlipCacheBefore << " -> " << mSkinCacheCap << ", work " << mRigFlipWorkBefore << " -> " << mWorkCap
      << " | GPU visible demand " << dem << " verts, capacity drops " << mRigDropItems << " draws (" << mRigDropVerts
      << " verts) | rows with neither path " << mRowsNoPath << " (rigged " << mRowsNoPathRigged << ")";
    if (bad)
        LL_WARNS("Vulkan") << q.str() << " -- NOT COMPLETE (the cull still drops rigged draws for capacity)" << LL_ENDL;
    else
        LL_INFOS("Vulkan") << q.str() << LL_ENDL;
}

// The cluster LOD module (RenderVKClusterLOD): made on the first clusterTick, or earlier by
// warmFirstUse -- at login, behind the progress screen -- so its init (compute pipelines,
// ~1.3 s cold in a frame) and its draw-pipeline batch (background, part of the login gate)
// are not paid by a world frame. false: not available (yet / retry later).
bool LLCleanRendererVK::ensureClusterModule()
{
#if !defined(LL_HAS_CLEAN_PIPELINE)
    return false;
#else
    if (mCluster) return true;
    {
        if ((uint64_t)gFrameCount < mClusterRetryFrame) return false;
        LLClusterRenderEnv env;
        env.drawSet0 = mDslDraw0;
        env.drawSet1 = mDslDraw1;
        env.drawPushBytes = (uint32_t)sizeof(VKDrawViewPush);
        env.gbufDesc = mGbufDesc;
        env.gbufValid = mGbufDescValid;
        env.reverseZ = kReverseZ;
        for (int i = 0; i < 4; ++i) env.preDesc[i] = mPreDescCl[i];   // #749 pre-pass templates (+ [3] motion only)
        env.preValid = mPreDescClValid;
        // #702 integration: the secondary passes' templates (sun cascades, projector tiles, captures).
        env.shadowDesc = mShadowDescCl;   env.shadowValid = mShadowDescClValid;
        env.projDesc = mProjDescCl;       env.projValid = mProjDescClValid;
        env.captureDesc = mCaptureDescCl; env.captureValid = mCaptureDescClValid;
        // rigged alpha-blend on the cluster path (the alpha lists' pipelines)
        env.alphaDesc = mAlphaDescCl;               env.alphaValid = mAlphaDescClValid;
        env.alphaDepthDesc = mAlphaDepthDescCl;     env.alphaDepthValid = mAlphaDepthDescClValid;
        env.transDesc[0] = mTransDescCl[0];         env.transDesc[1] = mTransDescCl[1];
        env.transValid = mTransDescClValid;
        env.captureAlphaDesc = mCaptureAlphaDescCl; env.captureAlphaValid = mCaptureAlphaDescClValid;
        env.forwardDesc = mFwdDescCl;               env.forwardValid = mFwdDescClValid;
        // (legacy-skin skip: the captures' ray-query lit variant, when RT exists)
        env.rtSetLayout = (mRT && mDrawLayoutRt) ? mRT->consumerLayout() : VK_NULL_HANDLE;
        mCluster = new LLCleanClusterVK();
        if (!mCluster->init(*mCtx, env))
        {   // (init cleaned up after itself) the legacy path keeps drawing; retry later
            delete mCluster;
            mCluster = nullptr;
            mClusterRetryFrame = (uint64_t)gFrameCount + 600;
            return false;
        }
    }
    return true;
#endif
}

// CLUSTER-OWNED MIRROR RELEASE (2026-10-16, header "CLUSTER-ROUTED GEOMETRY"). Render thread,
// after the fill join: the fill's bookkeeping (mGrp*Refs, mSlotGrp, mCpuSlots, mRematAsk) is
// stable and nothing reads the store. The store applies queued releases at its ingest sync
// point (pumpMirrorReleases), re-checking each slot.
void LLCleanRendererVK::clusterMirrorTick(bool own)
{
#if defined(LL_HAS_CLEAN_PIPELINE)
    LLCleanMeshAsset& ms = LLCleanMeshAsset::instance();
    // 1. Legacy needs slots whose mirror was freed: bring them back (async; not drawn meanwhile).
    if (!mRematAsk.empty())
    {
        std::sort(mRematAsk.begin(), mRematAsk.end());
        mRematAsk.erase(std::unique(mRematAsk.begin(), mRematAsk.end()), mRematAsk.end());
        for (const uint32_t sl : mRematAsk) ms.requestMirror(sl, "legacy geometry");
        mRematAsk.clear();
        if (mRematAsk.capacity() > 4096) std::vector<uint32_t>().swap(mRematAsk);
    }
    // 2. Releases: only while the cluster path owns rigged meshes AND the pack is laid out so.
    if (!own)
    {
        if (mMirrorOwnLast) ms.cancelMirrorReleases();   // (a release queued in the last owned frame)
        mMirrorOwnLast = false;
        if (mCluster) mCluster->stream().takeMirrorCandidates(mMirrorCand);
        mMirrorCand.clear();
        return;
    }
    mMirrorOwnLast = true;
    if (!mCluster) return;
    mCluster->stream().takeMirrorCandidates(mMirrorCand);
    if (mMirrorCand.empty()) return;
    static LLCachedControl<bool> s_free(gSavedSettings, "RenderVKClusterFreeMirrors", true);
    if (!s_free || !mGeomRoutedMode)
    {
        mMirrorCand.clear();   // (offered again in kMirrorRecheckFrames)
        return;
    }
    // A group only cluster-routed rows reference: no legacy GPU geometry (fillFromCleanStores).
    auto routedOnly = [this](uint32_t g) -> bool
    {
        return g < mGrpLegacyRefs.size() && g < mGrpRoutedRefs.size() && mGrpLegacyRefs[g] == 0u && mGrpRoutedRefs[g] != 0u;
    };
    const SlotInfo* packed = reinterpret_cast<const SlotInfo*>(mCpuSlots.data());
    const size_t pack_rows = mCpuSlots.size() / sizeof(SlotInfo);
    for (const LLClusterKey& k : mMirrorCand)
    {
        const uint32_t gid = ms.getLodGroupId(k.mesh_id, k.face);
        if (gid == LOD_SENTINEL || !routedOnly(gid)) continue;
        for (S32 L = 0; L < LLCleanMeshAsset::NUM_LOD; ++L)
        {
            // Every resident level of the face: the durable DAG (from the highest creator LOD)
            // supersedes all of them as the cluster path's source.
            const uint32_t sl = ms.groupSlotAt(k.mesh_id, k.face, L);
            if (sl == LOD_SENTINEL) continue;
            if (sl < pack_rows && packed[sl].index_count) continue;          // placed: legacy holds it
            if (sl >= mSlotGrp.size() || mSlotGrp[sl] != gid) continue;      // (the pack's mapping not settled)
            ms.slotPublishers(sl, mMirrorPubs);
            bool ok = !mMirrorPubs.empty();
            for (const uint32_t g : mMirrorPubs) ok = ok && routedOnly(g);
            if (!ok) continue;                                                // another group still draws it on legacy
            // (the store verifies the slot is (mesh, L, face)'s own -- not a fallback publish)
            ms.queueClusterMirrorRelease(sl, k.mesh_id, L, k.face);
        }
    }
    mMirrorCand.clear();
#else
    (void)own;
#endif
}

void LLCleanRendererVK::clusterTick(VkCommandBuffer cmd, const VKCullPush& cullIn, uint32_t height)
{
    mClusterTicked = false;
    mClSnapPass = 0;   // (this recording's cluster material pass: set where it draws)
#if defined(LL_HAS_CLEAN_PIPELINE)
    static LLCachedControl<bool> s_on(gSavedSettings, "RenderVKClusterLOD", false);
    // THE SESSION MODE (2026-10-14, the cluster path REPLACES the legacy one): cluster LOD on, the
    // module working, rigged meshes on the cluster path (RenderVKClusterRigged) and the deferred
    // G-buffer path (a forward-lit frame draws the cluster path in its forward pass 1 --
    // CLPASS_FORWARD, 2026-10-14 snapshot fix -- once those pipelines exist; until then it draws
    // no cluster-path mesh). Not per-frame readiness: pipelines still compiling or a mesh
    // still loading draw nothing for those frames (pop-in), never a legacy copy.
    {
        static LLCachedControl<bool> s_defer(gSavedSettings, "RenderVKDeferredLighting", true);
        // (deferred: the setting AND the path the frames actually take -- TAA / SSAO / the RT mask
        // off makes every frame forward; a debug view for a few frames does not flip the mode)
        const bool own = s_on && s_defer && mForwardStreak < kForwardStreakLegacy && mCluster && mCluster->ready()
                      && mCluster->skin().riggedWanted();
        if (own != mClOwnsRigged.load(std::memory_order_relaxed))
        {
            LL_INFOS("Vulkan") << "Cluster LOD: " << (own ? "the cluster path owns every eligible rigged mesh (no legacy "
                                                          "geometry, skinning, draws or RT for them)"
                                                        : "rigged meshes on the legacy path")
                               << LL_ENDL;
            mClOwnsRigged.store(own, std::memory_order_release);
            // the rigged sizing restarts from the new mode (buildRiggedFrame, next frame) and one
            // summary line reports what came back once the flip settled (rigFlipReport)
            mRigFlipPending = true;
            mRigFlipTo = own;
            mRigFlipFrame = std::max<uint32_t>((uint32_t)gFrameCount, 1u);
            mRigFlipDynBefore = mSkinDynCap;
            mRigFlipCacheBefore = mSkinCacheCap;
            mRigFlipWorkBefore = mWorkCap;
            mRigFlipItemsBefore = mRigUbItems;
            mRigFlipRoutedSlotsBefore = mGeomRoutedSlots.load(std::memory_order_relaxed);
            mRigFlipRoutedGroupsBefore = mGeomRoutedGroups.load(std::memory_order_relaxed);
            mRigFlipResizes = 0;
        }
        // #798 THE CLUSTER DAG SOURCE: while the cluster path owns rigged meshes, every rigged volume
        // loads the highest creator LOD (LLVOVolume::calcLOD) whatever its screen size -- the DAG
        // built from it supplies the coarser levels, and creators match the seams between meshes
        // (body parts, clothing) on that LOD only: a DAG built from LOD 2 left the leg / rump seam
        // without weld partners. Pressure acts through the cut's tolerance (2c), not the source;
        // the legacy path keeps LL's screen-size LOD + the #559 / #734 pressure caps.
        static LLCachedControl<U32> s_src_lod(gSavedSettings, "RenderVKClusterRiggedSourceLOD", 3U);
        LLVOAvatar::setVKClusterRiggedLOD(own ? (S32)std::min<U32>((U32)s_src_lod, 3u) : -1);
    }
    rigFlipReport();
    clusterMirrorTick(mClOwnsRigged.load(std::memory_order_relaxed));
    if (!s_on)
    {   // Turned off at runtime: the module winds down, then goes away (frees on liveness).
        if (mCluster && mCluster->idleRelease((uint64_t)gFrameCount))
        {
            mCluster->destroy();
            delete mCluster;
            mCluster = nullptr;
            LL_INFOS("Vulkan") << "Cluster LOD: off, module released" << LL_ENDL;
        }
        return;
    }
    if (!mCluster && !ensureClusterModule()) return;
    LLClusterFrameIn in;
    in.cmd = cmd;   // (the GPU half is recorded by clusterFrameStart, #749)
    in.owns_rigged = mClOwnsRigged.load(std::memory_order_relaxed);
    in.slot = mFrameSlot % kTexDescSets;
    in.frame = (uint64_t)gFrameCount;
    {
        const VramRoom vr = vramRoom(0);
        in.vram_avail = vr.avail;
        in.vram_budget = vr.budget;
    }
    in.vram_ladder = mBudget.engaged();
    in.offscreen = mOffscreen && mOffscreenFrame > 0;   // a snapshot holds still
    in.snapshot = mOffscreen;   // #749: every snapshot recording at the base tolerance
    // Hi-Z import for CLV_OCCLUSION (#745): LAST frame's main-view pyramid (built after its
    // pre-pass by the single- or two-phase occlusion cull, mHizBuiltFrame), never on an
    // offscreen recording. The module pairs it with the main view it recorded last frame.
    // (Not when the depth size changed: ensureHiz would re-create the pyramid later in this
    // frame, after the selection dispatch that samples it was recorded.)
    if (mHiz.image && mHiz.view && !mHizFresh && mDepthSampler && !mOffscreen
        && mHizBuiltFrame + 1 == (uint64_t)gFrameCount
        && mHizW == (mDepthW + 1) / 2 && mHizH == (mDepthH + 1) / 2)
    {
        in.hiz_view = mHiz.view;
        in.hiz_sampler = mDepthSampler;
        in.hiz_w = mHizW;
        in.hiz_h = mHizH;
        in.hiz_gen = mHizImageGen;
    }
    // #749 THE TOLERANCE CONTROLLER's inputs: the #613 GPU-time measurement (sampled rigged
    // ring: legacy rigged spans + the cluster raster spans) against the same budget and frame
    // target as the old controller -- "Keep my FPS" hands its target over through
    // LLVKAutoTune::rigTargetFps -- and the VRAM ladder. Snapshots (any offscreen recording)
    // run at the base tolerance (the controller ignores pressure there).
    {
        static LLCachedControl<bool> s_slod(gSavedSettings, "RenderVKRiggedScreenLOD", true);
        static LLCachedControl<F32>  s_fps(gSavedSettings, "RenderVKRiggedLodTargetFPS", 60.f);
        static LLCachedControl<F32>  s_gpu_ms(gSavedSettings, "RenderVKRiggedGpuBudgetMs", 0.f);
        const double now = LLFrameTimer::getTotalSeconds();
        const bool gpu_ok = mRigTsOk && mRigGpuAt > 0.0 && now - mRigGpuAt < 3.0;
        const float target_ms = 1000.f / llclamp(LLVKAutoTune::rigTargetFps((F32)s_fps), 10.f, 500.f);
        LLClusterPressureIn& p = in.pressure;
        p.gpu_ok = gpu_ok;
        p.frame_ms = mRigFrameMs;
        p.gpu_frame_ms = mRigGpuFrameMs;
        p.rig_gpu_ms = gpu_ok ? mRigGpuMs : 0.f;
        // (+ the #747 cluster pre-skin: its cost follows the cut, so the tolerance moves it too)
        p.cluster_gpu_ms = gpu_ok ? std::max(mClGpuMs[1], 0.f) + std::max(mClGpuMs[2], 0.f) + std::max(mClGpuMs[3], 0.f)
                                  : 0.f;
        p.target_ms = target_ms;
        p.budget_ms = (F32)s_gpu_ms > 0.f ? (F32)s_gpu_ms : target_ms * 0.3f;
        p.perf_on = s_slod;
        p.vram_ladder = mBudget.engaged();
        p.vram_rungs = LLVramBudgetVK::rungCount();
        p.vram_avail = in.vram_avail;
        in.now = now;
        LLClusterDiagIn& d = in.diag;
        d.skinned_verts = (uint64_t)mRigDemTier[0] + mRigDemTier[1] + mRigDemTier[2] + mRigDemTier[3];
        // (the legacy pre-skin's actual work: mRigDemTier excludes the skipped rows)
        d.skip_insts = mClSkipInst;
        d.skip_verts = mClSkipVerts;
        d.skip_av = mClSkipAv;
        d.switched_av = mClSwitchedAv;
        static_assert(kClNeedCount == 8, "LLClusterDiagIn::keep_why");
        for (uint32_t k = 0; k < kClNeedCount; ++k) d.keep_why[k] = mClKeepWhy[k];
        d.rt_role = mClRtNotConsumer;
        d.rig_gpu_ms = gpu_ok ? mRigGpuMs : -1.f;
        d.select_ms = gpu_ok ? mClGpuMs[0] : -1.f;
        d.prepass_ms = gpu_ok ? mClGpuMs[1] : -1.f;
        d.draw_ms = gpu_ok ? mClGpuMs[2] : -1.f;
        d.preskin_ms = gpu_ok ? mClGpuMs[3] : -1.f;   // #747 cluster pre-skin (graphics queue only)
        // fixed-cost audit: the cluster RT bytes / pools and the cluster sub-timers (CLOD mem / gpu sub)
        // (only on the frames the 10 s summary logs: no per-frame string building)
        if (mCluster->summaryDue(now))
        {
            d.rt_bytes = mRT ? mRT->clusterRtBytes() : 0;
            d.rt_mem = mRT ? mRT->clusterRtMemLine() : std::string();
            d.gpu_sub = mClGpuSubLine;
        }
        d.rig_slod = mRigSlod;
        d.rig_perf_p = mRigPerfP;
        d.rig_pressure = mRigPressure;
        d.rig_ladder = mRigLadderLvl;
        // rigged alpha-blend draws still on the legacy path (main cull, pre + post water; read back)
        if (mCounterReadback.mapped)
        {
            const uint32_t* c = reinterpret_cast<const uint32_t*>(mCounterReadback.mapped);
            d.legacy_alpha_faces = (int64_t)c[5] + (int64_t)c[7];
        }
    }
    // The main view (protection is measured from it): the CULLING camera (lod_cam_pos, the
    // frustum's camera -- frozen with "Freeze culling camera", #479), px_scale = 0.5 x the
    // display height x |P[1][1]| (= clusterCullMain's), the near clip.
    for (int k = 0; k < 3; ++k) in.main_cam[k] = cullIn.lod_cam_pos[k];
    in.main_px_scale = std::fabs(mCurProj[5]) * (float)height * 0.5f;
    in.main_h = (float)height;
    in.znear = mCamNear;
    // CLUSTER SKINNING (#747, 2a): this frame's rigged state (buildRiggedFrame ran above). The
    // palettes are computed later in the frame (c_skin_pal); the module reads them only after.
    {
        LLClusterSkinIn si;
        si.palette = &mSkinPaletteSSBO;
        si.meta = &mSkinMetaSSBO;
        si.joints = &jointTable();
        si.work = &mWorkSSBO;
        si.rig_alloc = &mRigAlloc;
        si.skin_count = std::min<uint32_t>(mSkinCount, mSkinPaletteCap);
        // (= the palette compute's avatar_count)
        si.avatar_count = std::min<uint32_t>(mAvatarJointCount,
            (mAnimPipe && mAnimJointsOut.buffer) ? (uint32_t)LLCleanSkinStore::MAX_AVATARS
                                                 : (uint32_t)(mAvatarJointsCap / kAvatarJointsBytes));
        si.work_cap = mWorkCap;
        si.eye[0] = mPalEye[0]; si.eye[1] = mPalEye[1]; si.eye[2] = mPalEye[2];
        si.meta_cpu = mCpuSkinMeta.data();
        si.meta_cpu_bytes = mCpuSkinMeta.size();
        si.hide_self = mHideSelf;
        si.prepass_readers = mTemporalOn || mAoThisFrame || mRtMaskOn || mShadowMergeNow;   // (last frame's: decided later)
        mCluster->skin().setFrameInputs(si);
    }
    mCluster->tick(in);
    mClusterTicked = true;
#else
    (void)cmd; (void)cullIn; (void)height;
#endif
}

// #749 FRAME PIPELINING ORDER + ASYNC PAGE COPIES. Called at the start of the front-end
// section, with the command buffer the main cluster selection is about to be recorded into:
//  - pipelined (in_fe): cmd is the front-end segment F, which waits only the previous
//    recording's P. The module's frame-start writes (stats readback + zero, 1c's page table /
//    directory / group writes and page copies, 1b's counter zeroing) are recorded INTO F, so
//    they are ordered before this frame's selection on the same queue, and after the previous
//    frame's last cluster reader (every cluster pass records before P). Page copies stay in F
//    (already off the graphics queue).
//  - otherwise (graphics): exactly the old order, one hook later. With async compute on and
//    page copies planned, the copies go to a forked async segment (they target pool slots no
//    frame references until their fence-gated flip, kFrameSlots frames later, so nothing joins
//    it before the selection; the frame tail's wait on mAsyncOutstanding orders it before the
//    fence). The stream keeps a pool growth frame's copies on graphics, and holds a growth
//    until copies of forked segments are kFrameSlots frames old.
void LLCleanRendererVK::clusterFrameStart(VkCommandBuffer& cmd, bool in_fe)
{
#if defined(LL_HAS_CLEAN_PIPELINE)
    if (!mClusterTicked || !mCluster) return;
    mClusterTicked = false;
    VkCommandBuffer cc = VK_NULL_HANDLE;
    if (!in_fe && mCluster->uploadsPlanned())
        cc = asyncFork(cmd, "q_cluster_up");   // (null: async off / not opted in / no buffer -- all on graphics)
    mCluster->stream().setUploadCmd(cc);
    mCluster->recordFrameStart(cmd, in_fe);
    if (cc) asyncEndCompute(cc, "q_cluster_up");
#else
    (void)cmd; (void)in_fe;
#endif
}

uint32_t LLCleanRendererVK::clusterCullMain(VkCommandBuffer cmd, const VKCullPush& push, const VKDrawPush& dp,
                                            uint32_t rw, uint32_t rh)
{
#if defined(LL_HAS_CLEAN_PIPELINE)
    using namespace LLClusterFmt;
    LLClusterViewIn v;
    v.flags = CLV_MAIN | CLV_REQUESTS;
    // Mouselook: our own avatar stays admitted (shadows, captures, RT) and only the main view
    // hides it (clean_cluster_select.comp / clean_cluster_pick.comp, CLI_SELF).
    if (mHideSelf) v.flags |= CLV_HIDE_SELF;
    // <GMDX> The avatars render type (Develop > Render Types, the region map capture) also covers
    // the avatars on the cluster path: the legacy cull's bit 4 never reaches them.
    if (!gPipeline.hasRenderType(LLPipeline::RENDER_TYPE_AVATAR)) v.flags |= CLV_NO_RIGGED;
    if (mOrtho) v.flags |= CLV_ORTHO;   // <GMDX> region map capture: px_scale is px per metre
    v.role = CLROLE_MAIN;
    std::memcpy(v.view_proj, dp.view_proj, sizeof(v.view_proj));
    std::memcpy(v.planes, push.frustum_planes, sizeof(v.planes));
    // #749: the CULLING camera (lod_cam_pos), consistent with the frustum planes (both frozen
    // under "Freeze culling camera", #479); cam_pos is the live shading eye.
    for (int k = 0; k < 3; ++k) { v.cam_pos[k] = push.lod_cam_pos[k]; v.origin[k] = dp.origin[k]; }
    v.znear = mCamNear;                    // #749: the camera's near clip
    v.px_scale = push.lod_cam_pos[3];      // 0.5 * height * |P[1][1]| (display height; a snapshot's own)
    v.tol_px = 1.f;                        // (#749: the core fills it from the controller)
    v.viewport_px[0] = (float)rw;
    v.viewport_px[1] = (float)rh;
    return mCluster->recordCull(cmd, v);
#else
    (void)cmd; (void)push; (void)dp; (void)rw; (void)rh;
    return LLClusterFmt::kNone;
#endif
}

bool LLCleanRendererVK::clusterViewWanted(uint32_t bit) const
{
#if defined(LL_HAS_CLEAN_PIPELINE)
    static LLCachedControl<U32> s_views(gSavedSettings, "RenderVKClusterViews", 7);
    return mCluster && clusterLodOn() && ((U32)s_views & bit) != 0u;
#else
    (void)bit;
    return false;
#endif
}

// #749: one cluster view of another pass (outside any rendering scope). Perspective views:
// px_scale = 0.5 x the target height x |P[1][1]|; orthographic (CLV_ORTHO): px per metre. The
// core fills the tolerance (role scale x the controller) and the LOD camera. #702 integration:
// returns the view (the pass draws its statics when clusterStaticExclusion agrees).
uint32_t LLCleanRendererVK::clusterCullView(VkCommandBuffer cmd, uint32_t role, uint32_t sub, uint32_t flags,
                                            const float view_proj[16], const float origin[3], const float planes[6][4],
                                            const float cam[3], float px_scale, uint32_t vw, uint32_t vh, bool skip_dyn)
{
#if defined(LL_HAS_CLEAN_PIPELINE)
    if (!mCluster || !(px_scale > 0.f) || !std::isfinite(px_scale)) return LLClusterFmt::kNone;
    LLClusterViewIn v;
    v.flags = flags;
    v.role = role;
    v.sub = sub;
    std::memcpy(v.view_proj, view_proj, sizeof(v.view_proj));
    std::memcpy(v.planes, planes, sizeof(v.planes));
    for (int k = 0; k < 3; ++k) { v.cam_pos[k] = cam[k]; v.origin[k] = origin ? origin[k] : 0.f; }
    v.znear = mCamNear;
    v.px_scale = px_scale;
    v.viewport_px[0] = (float)vw;
    v.viewport_px[1] = (float)vh;
    v.skip_dyn = skip_dyn;
    const uint32_t idx = mCluster->recordCull(cmd, v);
    if (idx != LLClusterFmt::kNone)
        gpuSubMark(cmd, "c_cluster_view");
    return idx;
#else
    (void)cmd; (void)role; (void)sub; (void)flags; (void)view_proj; (void)origin; (void)planes; (void)cam;
    (void)px_scale; (void)vw; (void)vh; (void)skip_dyn;
    return LLClusterFmt::kNone;
#endif
}

// ---- #702 INTEGRATION: the cluster path in the secondary passes ------------------------------
// (CLUSTER_LOD_CONTRACT.md §9 "secondary views"; llcleanclusterselectvk.h.) Statics: per-view
// selections (sun cascades, mirror) drawn in that pass, its legacy cull skipping them through
// the exclusion bitset -- only when that view's selection and pipelines exist this frame.
// Rigged (switched avatars): ONE skinned cut -- the main view's un-culled cut of every avatar a
// secondary pass draws -- in two shared rig lists, drawn by the passes whose legacy rigged
// draws then drop the owned instances (u_sky_zenith.w = 1). Everything else stays legacy.
bool LLCleanRendererVK::clusterViewDrawWanted(uint32_t bit) const
{
#if defined(LL_HAS_CLEAN_PIPELINE)
    static LLCachedControl<U32> s_draw(gSavedSettings, "RenderVKClusterViewDraw", 31);
    return mCluster && clusterLodOn() && ((U32)s_draw & bit) != 0u;
#else
    (void)bit;
    return false;
#endif
}

// Before the main view's selection: which avatars each rig list carries this frame, from the
// per-pass avatar visibility (computeAvatarVis, the legacy rigged passes' own rule): shadow
// casters = on screen or casting into the sun cascades / a projector, not a no-shadow
// (reduced) avatar; captures = on screen, in the dynamic mirror, or a realtime probe candidate.
// A list whose passes cannot draw clusters this frame stays empty: no un-culled skinning for it.
void LLCleanRendererVK::clusterSetRigLists(bool do_rigged)
{
#if defined(LL_HAS_CLEAN_PIPELINE)
    if (!mCluster || !clusterLodOn()) return;
    uint32_t bits[2][kAvatarSlotWords] = {};
    const bool want_shadow = do_rigged && (clusterViewDrawWanted(1u) || clusterViewDrawWanted(2u))
                          && (mCluster->select().passReady(CLPASS_SHADOW) || mCluster->select().passReady(CLPASS_PROJ));
    // (not gated on this frame's lit variant: selectLitVariant runs later; a ray-query frame
    // then draws the captures legacy -- clusterRigDraw -- and only the skinning was spent)
    const bool want_capture = do_rigged && (clusterViewDrawWanted(4u) || clusterViewDrawWanted(8u))
                           && mCluster->select().passReady(CLPASS_PROBE);
    // WELDED RT (2026-10-14): every avatar the cluster RT traces (RT candidacy: some pass or a
    // traced capture, not a no-shadow one) is in list 0's un-culled cut too, so its RT cut is
    // derived from the shared, WELDED skinned arena (llcleanclusterrtvk.h "DERIVED RT CUT"): the
    // RT arena's own skinning (mode 9, no weld) is left for the arena overflow and tier 0 only --
    // ray-traced seams match the raster's. Records follow `emit` as before (none unless a shadow
    // map draws rigged casters), so this costs the skinning of off-screen casters only, which the
    // RT arena did anyway.
    const bool want_rt = do_rigged && mRT && rtConsumerActive() && mRT->clusterTracesSwitched();
    bool any = false;
    for (uint32_t a = 0; a < kAvVisSlots; ++a)
    {
        const uint32_t v = mAvVis[a];
        if ((v & kAvVisAny) == 0u && (v & kAvVisProbeOk) == 0u) continue;
        if (want_shadow && (v & (kAvVisMain | kAvVisSun | kAvVisProj)) != 0u && (v & kAvVisNoShadow) == 0u)
        {
            bits[0][a >> 5] |= 1u << (a & 31u);
            any = true;
        }
        if (want_capture && (v & (kAvVisMain | kAvVisMirror | kAvVisProbeOk)) != 0u)
        {
            bits[1][a >> 5] |= 1u << (a & 31u);
            any = true;
        }
        if (want_rt && (v & (kAvVisAny | kAvVisRtProbe)) != 0u && (v & kAvVisNoShadow) == 0u)
        {
            bits[0][a >> 5] |= 1u << (a & 31u);
            any = true;
        }
    }
    // #748 perf pass: the shadow list's RECORDS only while a shadow map draws rigged casters this
    // frame (sun cascades not ray traced, or projector shadow maps) -- with RT sun / projector
    // shadows nothing draws them (16958 records emitted for nothing in a 39-avatar region). Its
    // avatars keep their un-culled cut (the shared skinning the RT cut takes over).
    const uint32_t emit = (clusterShadowMapsRig() ? 1u : 0u) | 2u;
    mCluster->setRigLists(bits, any, emit);
#else
    (void)do_rigged;
#endif
}

// #748 perf pass: a shadow map draws rigged casters this frame (= buildRiggedFrame's
// shadow_maps_rig): sun cascades not ray traced, or projector shadow maps.
bool LLCleanRendererVK::clusterShadowMapsRig() const
{
    return (mShadowOn && !mSunRtNow) || mProjMode == 1u;
}

bool LLCleanRendererVK::clusterRigDraw(uint32_t bit, uint32_t pass) const
{
#if defined(LL_HAS_CLEAN_PIPELINE)
    if (!clusterViewDrawWanted(bit)) return false;
    // (captures in a ray-query lit frame: the RT variant -- passReady requires both variants
    // when RT exists; the mClCapCommit guard covers a device without the RT capture layout)
    if (pass == CLPASS_PROBE && mLitRt && !(mRT && mDrawLayoutRt) && !mClCapCommit) return false;
    return mCluster->rigListReady((LLClusterDrawPass)pass);
#else
    (void)bit; (void)pass;
    return false;
#endif
}

// ---- CLUSTER LOD LEGACY-SKIN SKIP (CLUSTER_LOD_CONTRACT.md §11) ------------------------------
// Inside recordMainCull: after the main view's cluster selection (the shared rig cut of this
// frame exists or not), before the legacy main cull. Per avatar 2a switched to the cluster path,
// the NEED MASK: every consumer that would read its LEGACY pre-skinned vertices this frame. The
// passes' own gates are evaluated here with what they will see (rigListWillDraw = rigListReady
// before the pre-skin is recorded; the pick's cluster pick armed now), so a pass whose rig list
// covers an avatar here draws it later -- the commit is exact, not a prediction. RT is the one
// GPU-decided consumer: an avatar needs no legacy rigged BLAS only once its switched groups took
// their cluster records in pass B for a run of frames (LLCleanRTVK::clusterRigCovered, read back
// kFrameSlots frames late); a group that falls back afterwards traces nothing for at most those
// frames, then the mask re-arms its legacy BLAS. An empty mask: kAvVisClSkip.
void LLCleanRendererVK::clusterLegacySkipPlan(VkCommandBuffer cmd, bool do_rigged, uint32_t main_view)
{
#if defined(LL_HAS_CLEAN_PIPELINE)
    mClSkipAv = mClSwitchedAv = 0;
    mClRtNotConsumer = 0;
    std::memset(mClKeepWhy, 0, sizeof(mClKeepWhy));
    mClCapCommit = false;
    if (!mCluster || !clusterLodOn() || !mAvVisSSBO.buffer || mAvVis[kAvVisSlots] == 0u) return;
    const LLCleanClusterSkinVK& sk = mCluster->skin();
    uint32_t sw[kAvVisSlots / 32] = {};
    for (uint32_t a = 0; a < kAvVisSlots; ++a)
        if (sk.avatarSwitched(a)) { sw[a >> 5] |= 1u << (a & 31u); ++mClSwitchedAv; }
    // 2026-10-14 (the cluster path REPLACES the legacy one): in the cluster-owns-rigged mode
    // EVERY avatar is skipped -- its cluster-owned rows have no legacy geometry, draw, pre-skin,
    // weld or RT BLAS whatever a pass can do; the need mask below only COUNTS the passes that
    // draw nothing for a drawn avatar this frame (the "keep" reasons of the CLOD A/B line become
    // holes: e.g. "sel" = no selection outline, "prb" = a probe face without the capture list).
    const bool owned = clusterOwnsRigged();
    if (!mClSwitchedAv && !owned) return;
    static LLCachedControl<bool> s_skip(gSavedSettings, "RenderVKClusterLegacySkinSkip", true);
    extern bool gUseWireframe;
    // Reasons that keep every switched avatar legacy this frame.
    uint32_t global = 0;
    if (!s_skip || !do_rigged || main_view == LLClusterFmt::kNone || !sk.preskinWillRecord(main_view))
        global |= 1u << kClNeedGlobal;
    if (gUseWireframe || mSelRigAvAll) global |= 1u << kClNeedSel;   // (wireframe: every rigged bucket)
    // Per pass: its rig list will be drawn this frame (= clusterRigDraw / clusterPickOn later).
    // (#748 perf pass: no shadow map drawing rigged casters this frame -- RT sun / projector
    // shadows -- reads no legacy skinned vertex either)
    const bool sun_cov = !(mShadowOn && !mSunRtNow)
                      || (clusterViewDrawWanted(1u) && mCluster->rigListWillDraw(CLPASS_SHADOW));
    const bool proj_cov = mProjMode != 1u || (clusterViewDrawWanted(2u) && mCluster->rigListWillDraw(CLPASS_PROJ));
    const bool cap_ready = mCluster->rigListWillDraw(CLPASS_PROBE);
    const bool mir_cov = clusterViewDrawWanted(4u) && cap_ready;
    // (CPU- and GPU-scheduled probe faces alike: a GPU job's capture rig list is clipped away on
    // the GPU when its job draws no avatars, clean_probe_patch.comp kind 3)
    const bool prb_cov = clusterViewDrawWanted(8u) && cap_ready;
    // (a snapshot recording records no pick; a pick between frames answers from the last LIVE
    // frame, whose own mask covered it)
    const bool pick_cov = mOffscreen || !mPick || mPick->clusterPickArmed();
    const bool rt_on = mRT && rtConsumerActive();
    // (cluster-owns-rigged mode: RT never reads a cluster-path mesh's legacy vertices -- it has none)
    const bool rt_legacy_sw = mRT && !owned && mRT->rigSwitchedLegacyAllowed();
    mClRtNotConsumer = !rt_on ? 1u : !rt_legacy_sw ? 2u : 0u;
    for (uint32_t a = 0; a < kAvVisSlots; ++a)
    {
        const bool switched = ((sw[a >> 5] >> (a & 31u)) & 1u) != 0u;
        if (owned && !switched)
        {   // (nothing of it drawn yet: its owned rows still leave every legacy pass; a zero word
            // -- an avatar no pass draws -- stays zero: the cull drops it whole)
            if (mAvVis[a] != 0u)
            {
                mAvVis[a] |= kAvVisClSkip;
                ++mClSkipAv;
            }
            continue;
        }
        if (!switched) continue;
        const uint32_t v = mAvVis[a];
        uint32_t need = global;
        const bool caster = (v & kAvVisNoShadow) == 0u;
        if (caster && (v & (kAvVisMain | kAvVisSun)) && !sun_cov) need |= 1u << kClNeedSun;
        if (caster && (v & (kAvVisMain | kAvVisProj)) && !proj_cov) need |= 1u << kClNeedProj;
        if ((v & (kAvVisMain | kAvVisMirror)) && !mir_cov) need |= 1u << kClNeedMirror;
        if ((v & (kAvVisMain | kAvVisProbeOk)) && !prb_cov) need |= 1u << kClNeedProbe;
        if ((v & kAvVisMain) && !pick_cov) need |= 1u << kClNeedPick;
        // RT traces the avatar (= the rigged plan's candidacy: some pass or a traced capture,
        // not a no-shadow one) from its LEGACY BLAS: only when the cluster RT does not trace
        // switched avatars at all (RenderVKClusterRT 0 / RenderVKClusterRTRigged 0 / module
        // inactive) and the legacy avatar class is in RT. 2026-10-13 ("never fall back"): with
        // the cluster RT tracing them, switched groups are cluster-only in RT from the first
        // frame (no legacy fallback BLAS, no 8-frame confirmation -- that wait is what kept
        // "keep rt" avatars skinning twice while the drop meant RT never confirmed); RT dropped
        // the legacy class or traces nothing: RT is no consumer ("not needed", not "not
        // confirmed"). (A switch of this state lands in recordBuild after this plan: the frame
        // in between traces cluster-only or nothing, never stale vertices.)
        if (rt_on && rt_legacy_sw && caster && (v & (kAvVisAny | kAvVisRtProbe)))
            need |= 1u << kClNeedRt;
        if ((mSelRigAv[a >> 5] >> (a & 31u)) & 1u) need |= 1u << kClNeedSel;
        if (need)
        {
            for (uint32_t k = 0; k < kClNeedCount; ++k)
                if ((need >> k) & 1u) ++mClKeepWhy[k];
            if (!owned) continue;
        }
        mAvVis[a] |= kAvVisClSkip;
        ++mClSkipAv;
        if (v & (kAvVisMain | kAvVisMirror | kAvVisProbeOk)) mClCapCommit = true;
    }
    if (!mClSkipAv) return;
    // av_vis was uploaded (and barriered to compute) before the probe scheduler; rewrite its
    // per-avatar words with the skip bits for the main cull (same command buffer). WAR: the
    // probe scheduler's / earlier reads; then the cull's reads.
    VkBufferMemoryBarrier2 b{VK_STRUCTURE_TYPE_BUFFER_MEMORY_BARRIER_2};
    b.srcStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT | VK_PIPELINE_STAGE_2_CLEAR_BIT | VK_PIPELINE_STAGE_2_COPY_BIT;
    b.srcAccessMask = VK_ACCESS_2_TRANSFER_WRITE_BIT;
    b.dstStageMask = VK_PIPELINE_STAGE_2_CLEAR_BIT;
    b.dstAccessMask = VK_ACCESS_2_TRANSFER_WRITE_BIT;
    b.buffer = mAvVisSSBO.buffer;
    b.offset = 0;
    b.size = (VkDeviceSize)kAvVisSlots * sizeof(uint32_t);
    VkDependencyInfo d{VK_STRUCTURE_TYPE_DEPENDENCY_INFO};
    d.bufferMemoryBarrierCount = 1;
    d.pBufferMemoryBarriers = &b;
    vkCmdPipelineBarrier2(cmd, &d);
    vkCmdUpdateBuffer(cmd, mAvVisSSBO.buffer, 0, (VkDeviceSize)kAvVisSlots * sizeof(uint32_t), mAvVis);
    b.srcStageMask = VK_PIPELINE_STAGE_2_CLEAR_BIT;
    b.srcAccessMask = VK_ACCESS_2_TRANSFER_WRITE_BIT;
    b.dstStageMask = VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT;
    b.dstAccessMask = VK_ACCESS_2_SHADER_STORAGE_READ_BIT;
    vkCmdPipelineBarrier2(cmd, &d);
#else
    (void)cmd; (void)do_rigged; (void)main_view;
#endif
}

bool LLCleanRendererVK::clusterStaticExclusion(uint32_t view, uint32_t pass, VKCullPush& cp, uint32_t& mode) const
{
#if defined(LL_HAS_CLEAN_PIPELINE)
    if (!mCluster || view == LLClusterFmt::kNone || !clusterLodOn()) return false;
    if (pass == CLPASS_PROBE && mLitRt && !(mRT && mDrawLayoutRt)) return false;   // (RT variant: passReady)
    if (!mCluster->viewDrawReady(view, (LLClusterDrawPass)pass)) return false;
    uint64_t addr = 0;
    uint32_t words = 0;
    if (!mCluster->select().legacyExclusion(addr, words)) return false;   // (no bitset: nothing excluded, nothing drawn)
    cp.cluster_owned_lo = (uint32_t)addr;
    cp.cluster_owned_hi = (uint32_t)(addr >> 32);
    cp.cluster_owned_words = words;
    mode |= kCullModeCluster;
    return true;
#else
    (void)view; (void)pass; (void)cp; (void)mode;
    return false;
#endif
}

// #748 perf pass, MDI tiers: the rig-list cull of rig list `list` (CLLIST_RIG_*) for ONE secondary
// view, against draw view `view_idx` of the param ring (its device address), recorded OUTSIDE a
// rendering scope right before the scope that draws the list (one culled region: the next view's
// cull reuses it). True = that scope passes rig_culled to clusterDrawSecondary(Idx). The mesh
// tier culls in its task stage (false here, nothing recorded).
bool LLCleanRendererVK::clusterRigCullView(VkCommandBuffer cmd, uint32_t list, uint32_t view_idx)
{
#if defined(LL_HAS_CLEAN_PIPELINE)
    if (!mCluster || !mParamRing.buffer || list < CLLIST_RIG_SHADOW || list > CLLIST_RIG_CAPTURE) return false;
    VkBufferDeviceAddressInfo ai{VK_STRUCTURE_TYPE_BUFFER_DEVICE_ADDRESS_INFO};
    ai.buffer = mParamRing.buffer;
    const VkDeviceAddress base = vkGetBufferDeviceAddress(mCtx->device(), &ai);
    if (!base) return false;
    return mCluster->select().recordRigCull(cmd, list - CLLIST_RIG_SHADOW,
                                            base + mViewRgn.offset + (VkDeviceAddress)view_idx * mViewRgn.stride);
#else
    (void)cmd; (void)list; (void)view_idx;
    return false;
#endif
}

bool LLCleanRendererVK::clusterDrawSecondary(VkCommandBuffer cmd, uint32_t pass, uint32_t view, uint32_t list,
                                             const VKDrawPush& vp, uint32_t restore_view, bool rig_culled, bool alpha)
{
#if defined(LL_HAS_CLEAN_PIPELINE)
    if (!mCluster) return false;
    const uint32_t idx = pushDrawView(cmd, mDrawLayout, vp);
    return clusterDrawSecondaryIdx(cmd, pass, view, list, idx, restore_view, rig_culled, alpha);
#else
    (void)cmd; (void)pass; (void)view; (void)list; (void)vp; (void)restore_view; (void)rig_culled; (void)alpha;
    return false;
#endif
}

// RIGGED ALPHA-BLEND on the cluster path: a main-view alpha list (pass CLPASS_ALPHA: pass 2's
// blend, alpha_list 0 pre-water / 1 post-water; CLPASS_ALPHA_DEPTH: the alpha-blend depth
// pre-pass) inside the open scope, under the WORLD draw view `view` (cluster vertices are placed
// by the world view, not the rigged eye-relative one). Restores the pass's sets and the static
// streams; the caller re-pushes its own view when it draws more.
bool LLCleanRendererVK::clusterDrawAlpha(VkCommandBuffer cmd, uint32_t pass, uint32_t alpha_list, const VKDrawPush& view)
{
#if defined(LL_HAS_CLEAN_PIPELINE)
    if (!mCluster || !clusterLodOn() || !mCluster->alphaReady((LLClusterDrawPass)pass)) return false;
    const uint32_t idx = pushDrawView(cmd, mDrawLayout, view);
    LLClusterDrawIn ci;
    ci.cmd = cmd;
    ci.view = mCluster->select().mainView();
    ci.pass = (LLClusterDrawPass)pass;
    ci.draw_view = idx;
    ci.draw_sets[0] = mDsetDraw0;
    ci.draw_sets[1] = mDsetDraw1;
    ci.list = CLLIST_VIEW;
    ci.alpha = true;
    ci.alpha_list = alpha_list;
    // (pass 2 in a ray-query lit frame: the ray-query blend FS, as LIT_RIG_ALPHA's variant)
    if (pass == CLPASS_ALPHA && mLitRt && mRT && mDrawLayoutRt) ci.rt_set = mRT->consumerSet();
    const bool drawn = mCluster->recordDraw(ci);
    const VkDescriptorSet dsets[2] = {mDsetDraw0, mDsetDraw1};
    bindDrawSets(cmd, dsets);
    const VkDeviceSize off = 0;
    vkCmdBindVertexBuffers(cmd, 0, 1, &mVbo.buffer, &off);
    vkCmdBindIndexBuffer(cmd, mIbo.buffer, 0, VK_INDEX_TYPE_UINT16);
    return drawn;
#else
    (void)cmd; (void)pass; (void)alpha_list; (void)view;
    return false;
#endif
}

// CLPASS_FORWARD (2026-10-14, snapshots lost every cluster-owned rigged mesh): the lit FS variant
// the forward pass 1's opaque / rigged slots use this frame -- ray-query when the frame traces and
// no RT mask feeds the plain FS (selectLitVariant), else plain -- and whether the module has it.
bool LLCleanRendererVK::clusterForwardReady() const
{
#if defined(LL_HAS_CLEAN_PIPELINE)
    if (!mCluster || !clusterLodOn()) return false;
    const bool rt = mLitRt && !mRtMaskOn;
    if (rt && !(mRT && mDrawLayoutRt)) return false;
    return mCluster->select().forwardReady(rt);
#else
    return false;
#endif
}

bool LLCleanRendererVK::clusterDrawForward(VkCommandBuffer cmd, uint32_t main_view, uint32_t view_idx)
{
#if defined(LL_HAS_CLEAN_PIPELINE)
    if (!mCluster || main_view == LLClusterFmt::kNone || !clusterForwardReady()) return false;
    LLClusterDrawIn ci;
    ci.cmd = cmd;
    ci.view = main_view;
    ci.pass = CLPASS_FORWARD;
    ci.draw_view = view_idx;
    ci.draw_sets[0] = mDsetDraw0;
    ci.draw_sets[1] = mDsetDraw1;
    ci.list = CLLIST_VIEW;
    if (mLitRt && !mRtMaskOn && mRT && mDrawLayoutRt) ci.rt_set = mRT->consumerSet();
    pushDrawViewIndex(cmd, mDrawLayout, view_idx);
    const bool drawn = mCluster->recordDraw(ci);
    // The pass's state: its sets (+ the RT set of a ray-query frame: the cluster set took set 2
    // or 3), the static streams (the indexed tier bound the page pool).
    const VkDescriptorSet dsets[2] = {mDsetDraw0, mDsetDraw1};
    bindDrawSets(cmd, dsets);
    const VkDeviceSize off = 0;
    vkCmdBindVertexBuffers(cmd, 0, 1, &mVbo.buffer, &off);
    vkCmdBindIndexBuffer(cmd, mIbo.buffer, 0, VK_INDEX_TYPE_UINT16);
    return drawn;
#else
    (void)cmd; (void)main_view; (void)view_idx;
    return false;
#endif
}

bool LLCleanRendererVK::clusterDrawSecondaryIdx(VkCommandBuffer cmd, uint32_t pass, uint32_t view, uint32_t list,
                                                uint32_t view_idx, uint32_t restore_view, bool rig_culled, bool alpha)
{
#if defined(LL_HAS_CLEAN_PIPELINE)
    if (!mCluster || view == LLClusterFmt::kNone) return false;
    if (alpha && !mCluster->alphaReady((LLClusterDrawPass)pass)) return false;
    pushDrawViewIndex(cmd, mDrawLayout, view_idx);
    LLClusterDrawIn ci;
    ci.cmd = cmd;
    ci.view = view;
    ci.pass = (LLClusterDrawPass)pass;
    ci.draw_view = view_idx;
    ci.draw_sets[0] = mDsetDraw0;
    ci.draw_sets[1] = mDsetDraw1;
    ci.list = list;
    ci.rig_culled = rig_culled && !alpha;   // (the alpha lists are never rig-culled on the MDI tiers)
    ci.alpha = alpha;
    // A ray-query lit frame's captures: the RT variant (its set is this frame's; bindDrawSets
    // below rebinds it for the pass's own pipelines).
    if (pass == CLPASS_PROBE && mLitRt && mRT && mDrawLayoutRt) ci.rt_set = mRT->consumerSet();
    const bool drawn = mCluster->recordDraw(ci);
    // The pass's state: its sets (+ the RT set of a ray-query frame: the cluster set took set
    // 2), the static streams (the indexed tier bound the page pool), its draw view.
    const VkDescriptorSet dsets[2] = {mDsetDraw0, mDsetDraw1};
    bindDrawSets(cmd, dsets);
    const VkDeviceSize off = 0;
    vkCmdBindVertexBuffers(cmd, 0, 1, &mVbo.buffer, &off);
    vkCmdBindIndexBuffer(cmd, mIbo.buffer, 0, VK_INDEX_TYPE_UINT16);
    if (restore_view != LLClusterFmt::kNone) pushDrawViewIndex(cmd, mDrawLayout, restore_view);
    return drawn;
#else
    (void)cmd; (void)pass; (void)view; (void)list; (void)view_idx; (void)restore_view; (void)rig_culled; (void)alpha;
    return false;
#endif
}
